INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'Certificate in Home-Based Care Support ? Level 3 – GoCare Training Institute', 'certificate-in-home-based-care-support-level-3', NULL, 'A foundational program preparing learners for home-based care assistant, HCA, and caregiver roles.', '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Home-Based Care Support &ndash; Level 3</strong> is a foundational, competency-based program that prepares learners to become Home-Based Care Assistants, Health Care Assistants (HCA), Caregivers, Patient Attendants, and Nursing Assistants capable of delivering safe, compassionate, and supportive care in homes, hospitals, clinics, nursing facilities, and community health environments.</p>\r\n            <p>Learners acquire essential skills in patient hygiene, feeding, mobility assistance, repositioning, communication, safety, and supportive care procedures. The course also trains students to observe and report patient concerns to nurses and other healthcare professionals, ensuring continuity of care and patient safety.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized Level 3 qualification provides a strong entry point into the healthcare profession and serves as a direct pathway to advanced programs such as Caregiving Level 4 and subsequently the Kenya Health Professions Oversight Authority (KHPOA) licensed Healthcare Support Services - Level 5 (CNA).</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national home-based care and healthcare support standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training with real patient exposure in hospitals, clinics, and home-based care environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">International certification options (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Clear progression pathway to Certificate in Caregiving &ndash; Level 4 and Healthcare Support Services &ndash; Level 5 (CNA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified nurses, clinicians, and professional caregivers.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for hygiene care, feeding, mobility assistance, vital signs, and home-based care procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">11</div>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and private home-based care.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCPE or KCSE Certificate (Any Grade)</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Healthcare Housekeeping &amp; Hygiene</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Client Dietary Support &amp; Nutrition Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Support for Clients</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Pre-Departure &amp; Patient Transfer Procedures</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <h3 style=\"color: var(--dark); margin-top: 30px; margin-bottom: 20px; font-size: 20px;\">Additional Institutional Competencies (GoCare Enhanced Training)</h3>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); padding: 25px; border-radius: 8px; border-left: 4px solid var(--o);\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Introduction to Caregiving and the Fundamental Skills of Caregiving</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Alzheimer&#8217;s, Dementia and Other Common Mental Health Disorders Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Infection Prevention and Control</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Home-Based Care Skills and Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communicable and Non-Communicable Diseases and Common Health Conditions</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Introduction to the Hospital Layout and Procedures</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"special-offer\" style=\"margin-top: 50px; background: linear-gradient(135deg, var(--dark), #2d184a); color: #F5F0E8; padding: 40px; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.15); position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -50px; right: -50px; width: 200px; height: 200px; background: var(--o); opacity: 0.2; border-radius: 50%;\"></div>\r\n            <h2 style=\"color: #F5F0E8; font-size: 28px; margin-bottom: 15px; position: relative; z-index: 2; display: flex; align-items: center; gap: 15px;\"><i data-lucide=\"gift\" style=\"color: var(--o); width: 32px; height: 32px;\"></i> Second Course Sponsorship (Special Offer)</h2>\r\n            <p style=\"font-size: 16px; line-height: 1.6; position: relative; z-index: 2; margin-bottom: 15px;\">Enrol for this Home-Based Care Support &ndash; Level 3 course and receive a fully sponsored international training and certification in an additional program.</p>\r\n            <p style=\"font-size: 16px; line-height: 1.6; position: relative; z-index: 2; margin-bottom: 15px;\">This offer includes a second free course, giving every student access to internationally accredited training and certification for either the HealthCare Assistant (HCA) or Certified Nursing Assistant (CNA) program, depending on your preference.</p>\r\n            <div style=\"background: rgba(255,255,255,0.1); padding: 20px; border-radius: 8px; border-left: 4px solid var(--o); margin-top: 20px; position: relative; z-index: 2;\">\r\n              <p style=\"margin: 0; font-weight: 500; font-size: 16px; color: #F5F0E8;\">You pay for one course, and GoCare sponsors and trains you in the second complimentary course at no extra cost &ndash; enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability.</p>\r\n            </div>\r\n            <div style=\"margin-top: 25px; position: relative; z-index: 2;\">\r\n              <a href=\"second-course-sponsorship.html\" class=\"btn btn-primary\" style=\"background: var(--o); border-color: var(--o); color: #F5F0E8; text-transform: uppercase; font-size: 14px; font-weight: bold; letter-spacing: 1px; padding: 12px 24px;\"><i data-lucide=\"arrow-right\"></i> Learn More About Sponsorship</a>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a two (2) month attachment in:</p>\r\n            <ul style=\"list-style: none; padding: 0; margin-top: 15px; display: flex; flex-wrap: wrap; gap: 20px;\">\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o);\"></i> Hospitals</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"activity\" style=\"color: var(--o);\"></i> Clinics</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o);\"></i> Nursing homes</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"home\" style=\"color: var(--o);\"></i> Home-based care agencies</li>\r\n            </ul>\r\n            <p style=\"margin-top: 15px;\">GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Home-Based Care Support &ndash; Level 3 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Care Assistant (HCA)</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Professional Caregiver</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Care Technician</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Medical Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Home-Based Care Provider</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Support Worker in diverse healthcare settings</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to a wide range of healthcare support roles locally and internationally.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts<br>TVET CDACC Certificate<br>GoCare Completion Certificate<br>SDC Canada Int\'l Cert (HCA or CNA)</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a certified and globally recognized HCA / Caregiver.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Home-Based Care Support – Level 3 is a foundational, competency-based program that prepares learners to become Home-Based Care Assistants, Health Care Assistants (HCA), Caregivers, Patient Attendants, and Nursing Assistants capable of delivering safe, compassionate, and supportive care in homes, hospitals, clinics, nursing facilities, and community health environments. Learners acquire essential skills in patient hygiene, feeding, mobility assistance, repositioning, communication, safety, and supportive care procedures. The course also trains students to observe and report patient concerns to nurses and other healthcare professionals, ensuring continuity of care and patient safety. This nationally recognized Level 3 qualification provides a strong entry point into the healthcare profession and serves as a direct pathway to advanced programs such as Caregiving Level 4 and subsequently the Kenya Health Professions Oversight Authority (KHPOA) licensed Healthcare Support Services - Level 5 (CNA).\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national home-based care and healthcare support standards. 3 Hands-on practical training with real patient exposure in hospitals, clinics, and home-based care environments. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 International certification options (SDC Canada, AMCA USA). 7 Clear progression pathway to Certificate in Caregiving – Level 4 and Healthcare Support Services – Level 5 (CNA). 8 Training delivered by qualified nurses, clinicians, and professional caregivers. 9 Modern skills-lab and simulation-based training for hygiene care, feeding, mobility assistance, vital signs, and home-based care procedures. 10 Flexible study modes (Day, Online, Evening, Saturday). 11 High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and private home-based care.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCPE or KCSE Certificate (Any Grade)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Healthcare Housekeeping & Hygiene Client Dietary Support & Nutrition Care Psychosocial Support for Clients Pre-Departure & Patient Transfer Procedures\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"Introduction to Caregiving and the Fundamental Skills of Caregiving Alzheimer’s, Dementia and Other Common Mental Health Disorders Care Infection Prevention and Control Home-Based Care Skills and Procedures Communicable and Non-Communicable Diseases and Common Health Conditions Introduction to the Hospital Layout and Procedures\", \"heading\": \"Additional Institutional Competencies (GoCare Enhanced Training)\"}, {\"body\": \"Enrol for this Home-Based Care Support – Level 3 course and receive a fully sponsored international training and certification in an additional program. This offer includes a second free course, giving every student access to internationally accredited training and certification for either the HealthCare Assistant (HCA) or Certified Nursing Assistant (CNA) program, depending on your preference. You pay for one course, and GoCare sponsors and trains you in the second complimentary course at no extra cost – enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability. Learn More About Sponsorship\", \"heading\": \"Second Course Sponsorship (Special Offer)\"}, {\"body\": \"All learners undertake a two (2) month attachment in: Hospitals Clinics Nursing homes Home-based care agencies GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Home-Based Care Support – Level 3 can work as: Health Care Assistant (HCA) Professional Caregiver Patient Attendant Patient Care Technician Medical Receptionist Home-Based Care Provider Support Worker in diverse healthcare settings This qualification opens doors to a wide range of healthcare support roles locally and internationally. Total Duration 3 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic TranscriptsTVET CDACC CertificateGoCare Completion CertificateSDC Canada Int\'l Cert (HCA or CNA)\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a certified and globally recognized HCA / Caregiver. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', 'images/new-images/HBCS.jpeg', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(2, 'Advanced Cardiac Life Support (ACLS) - American Heart Association · GoCare Training Institute', 'advanced-cardiac-life-support-acls', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Advanced Cardiac Life Support (ACLS) course provides advanced training in the management of adult cardiac arrest, peri-arrest conditions, arrhythmias and cardiovascular emergencies. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response &mdash; skills required in hospitals, clinics, emergency units, workplaces and community settings.</p>\r\n            <p>This AHA-aligned program emphasizes clinical decision-making, ECG interpretation, emergency pharmacology and team leadership. Training is delivered through hands-on simulations, megacode practice and case-based learning at GoCare&rsquo;s Nairobi CBD and Thika Road (Ruiru) campuses.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study ACLS at GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Internationally recognized AHA certification.</li>\r\n              <li>Hands-on, simulation-based emergency care training.</li>\r\n              <li>Training delivered by certified emergency care instructors.</li>\r\n              <li>Modern skills-lab with CPR manikins, AED trainers and emergency equipment.</li>\r\n              <li>Affordable, accessible pricing for healthcare professionals.</li>\r\n              <li>Flexible study modes (Day, Evening, Weekend).</li>\r\n              <li>Ideal for hospital staff, emergency teams and critical care providers.</li>\r\n              <li>High employability in Kenya and abroad.</li>\r\n              <li>Strong add-on qualification for all GoCare medical and health sciences programs.</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #f0f4f8; padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Healthcare Background</strong>\r\n                  <p style=\"margin: 0;\">Student or qualified healthcare professional.</p>\r\n                </div>\r\n              </div>\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Recommended</strong>\r\n                  <p style=\"margin: 0;\">BLS knowledge recommended.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Course Duration</h2>\r\n            <p style=\"font-size:1.05rem;\"><strong style=\"color:var(--o);\">Two (2) Days</strong></p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>ACLS algorithms for cardiac arrest and arrhythmias</li>\r\n              <li>ECG rhythm recognition</li>\r\n              <li>Airway management</li>\r\n              <li>Emergency pharmacology</li>\r\n              <li>Team leadership and communication</li>\r\n              <li>Megacode simulations</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Ideal For</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Nurses</li>\r\n              <li>Doctors</li>\r\n              <li>Clinical officers</li>\r\n              <li>Critical care and emergency nurses</li>\r\n              <li>Paramedics</li>\r\n              <li>Senior health sciences students</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Certifications Awarded</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>AHA ACLS Provider eCard Certification</li>\r\n              <li>GoCare Completion Certificate</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>ACLS-certified graduates qualify for roles in:</p>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Emergency departments</li>\r\n              <li>Critical care units</li>\r\n              <li>High dependency units</li>\r\n              <li>Ambulance and rescue services</li>\r\n              <li>Hospitals and clinics</li>\r\n              <li>International healthcare facilities</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 12px;\">\r\n            <p style=\"font-style: italic; color: var(--dark);\">ACLS certification is a mandatory or preferred requirement in many advanced care settings worldwide.</p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li><strong>Option 1:</strong> Apply Online via the <a href=\"../apply.html\" style=\"color:var(--o);font-weight:600;\">application form</a>.</li>\r\n              <li><strong>Option 2:</strong> Visit Any GoCare Campus &mdash; Nairobi CBD or Thika Road (Ruiru).</li>\r\n              <li><strong>Admissions Line:</strong> 0703 115 502</li>\r\n            </ul>\r\n            <p style=\"margin-top: 20px;\">Begin your Advanced Cardiac Life Support (ACLS) certification today and advance your emergency care skills with GoCare Training Institute.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">2 Days</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply for Certification</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Us</a>\r\n            </div>\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Accreditation</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA (USA)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Certification</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA ACLS eCard</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n                <span style=\"color: var(--gray);\">Entry</span>\r\n                <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">Healthcare Background</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Advanced Cardiac Life Support (ACLS) course provides advanced training in the management of adult cardiac arrest, peri-arrest conditions, arrhythmias and cardiovascular emergencies. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response — skills required in hospitals, clinics, emergency units, workplaces and community settings. This AHA-aligned program emphasizes clinical decision-making, ECG interpretation, emergency pharmacology and team leadership. Training is delivered through hands-on simulations, megacode practice and case-based learning at GoCare’s Nairobi CBD and Thika Road (Ruiru) campuses.\", \"heading\": \"Course Overview\"}, {\"body\": \"Internationally recognized AHA certification. Hands-on, simulation-based emergency care training. Training delivered by certified emergency care instructors. Modern skills-lab with CPR manikins, AED trainers and emergency equipment. Affordable, accessible pricing for healthcare professionals. Flexible study modes (Day, Evening, Weekend). Ideal for hospital staff, emergency teams and critical care providers. High employability in Kenya and abroad. Strong add-on qualification for all GoCare medical and health sciences programs.\", \"heading\": \"Why Study ACLS at GoCare?\"}, {\"body\": \"Healthcare Background Student or qualified healthcare professional. Recommended BLS knowledge recommended.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Two (2) Days\", \"heading\": \"Course Duration\"}, {\"body\": \"ACLS algorithms for cardiac arrest and arrhythmias ECG rhythm recognition Airway management Emergency pharmacology Team leadership and communication Megacode simulations\", \"heading\": \"What You Will Learn\"}, {\"body\": \"Nurses Doctors Clinical officers Critical care and emergency nurses Paramedics Senior health sciences students\", \"heading\": \"Ideal For\"}, {\"body\": \"AHA ACLS Provider eCard Certification GoCare Completion Certificate\", \"heading\": \"Certifications Awarded\"}, {\"body\": \"ACLS-certified graduates qualify for roles in: Emergency departments Critical care units High dependency units Ambulance and rescue services Hospitals and clinics International healthcare facilities ACLS certification is a mandatory or preferred requirement in many advanced care settings worldwide.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Option 1: Apply Online via the application form. Option 2: Visit Any GoCare Campus — Nairobi CBD or Thika Road (Ruiru). Admissions Line: 0703 115 502 Begin your Advanced Cardiac Life Support (ACLS) certification today and advance your emergency care skills with GoCare Training Institute. Total Duration 2 Days Apply for Certification Contact Us Accreditation AHA (USA) Certification AHA ACLS eCard Entry Healthcare Background\", \"heading\": \"How to Apply\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(3, 'American Heart Association (AHA) Emergency Care Programs – GoCare Training Institute', 'aha-emergency-care-programs', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Overview</h2>\r\n            <p>The American Heart Association (AHA) Emergency Care Programs offered at GoCare Training Institute provide internationally recognized training in lifesaving skills for healthcare professionals, students, corporates and community responders. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response &ndash; skills required in hospitals, clinics, emergency units, workplaces and community settings.</p>\r\n            <p>These programs follow global AHA standards and include official AHA certification valid worldwide. Training is delivered through hands-on simulations, skills practice and scenario-based learning at GoCare&#8217;s Nairobi CBD and Thika Road (Ruiru) campuses.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study AHA Courses at GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Internationally recognized AHA certification.</li>\r\n              <li>Hands-on, simulation-based emergency care training.</li>\r\n              <li>Training delivered by certified emergency care instructors.</li>\r\n              <li>Modern skills-lab with CPR manikins, AED trainers and emergency equipment.</li>\r\n              <li>Flexible study modes (Day, Evening, Weekend).</li>\r\n              <li>Accessible to both medical and non-medical learners.</li>\r\n              <li>Ideal for hospital staff, students, corporates, caregivers and community responders.</li>\r\n              <li>High employability in Kenya and abroad.</li>\r\n              <li>Strong add-on qualification for all GoCare medical and health sciences programs.</li>\r\n            </ul>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" id=\"aha-courses\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">AHA Courses Offered</h2>\r\n            <p>Learners may pursue any of the following internationally certified AHA programs:</p>\r\n\r\n            <a href=\"basic-life-support-bls.html\" class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee; text-decoration:none; color:inherit;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">01</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0 0 6px; font-size: 18px; color: var(--dark);\">Basic Life Support (BLS) <i data-lucide=\"arrow-up-right\" style=\"width:16px;height:16px;color:var(--o)\"></i></h4>\r\n                <p style=\"margin:0;color:#555;\">CPR, AED use, choking management and early recognition of cardiac arrest for adults, children and infants. Open to KCPE / KCSE graduates and the general public.</p>\r\n              </div>\r\n            </a>\r\n\r\n            <a href=\"advanced-cardiac-life-support-acls.html\" class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee; text-decoration:none; color:inherit;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">02</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0 0 6px; font-size: 18px; color: var(--dark);\">Advanced Cardiac Life Support (ACLS) <i data-lucide=\"arrow-up-right\" style=\"width:16px;height:16px;color:var(--o)\"></i></h4>\r\n                <p style=\"margin:0;color:#555;\">Cardiac arrest algorithms, ECG interpretation, emergency pharmacology, airway management and megacode simulations. For healthcare professionals and senior health sciences students.</p>\r\n              </div>\r\n            </a>\r\n\r\n            <a href=\"pediatric-advanced-life-support-pals.html\" class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee; text-decoration:none; color:inherit;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">03</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0 0 6px; font-size: 18px; color: var(--dark);\">Pediatric Advanced Life Support (PALS) <i data-lucide=\"arrow-up-right\" style=\"width:16px;height:16px;color:var(--o)\"></i></h4>\r\n                <p style=\"margin:0;color:#555;\">Assessment, respiratory distress, shock management, pediatric cardiac arrest and emergency teamwork. For pediatric, maternity, emergency and ICU providers.</p>\r\n              </div>\r\n            </a>\r\n\r\n            <a href=\"heartsaver-first-aid.html\" class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 0; padding-bottom: 0; text-decoration:none; color:inherit;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">04</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0 0 6px; font-size: 18px; color: var(--dark);\">Heartsaver First Aid <i data-lucide=\"arrow-up-right\" style=\"width:16px;height:16px;color:var(--o)\"></i></h4>\r\n                <p style=\"margin:0;color:#555;\">Bleeding control, burns, fractures, allergic reactions, seizures, diabetic emergencies, stroke and heart attack recognition. Open to KCPE / KCSE graduates, corporates, schools, caregivers and the general public.</p>\r\n              </div>\r\n            </a>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #f0f4f8; padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Open Entry (No Medical Background Required)</strong>\r\n                  <p style=\"margin: 0;\">Basic Life Support (BLS) and Heartsaver First Aid &ndash; open to KCPE / KCSE graduates and the general public.</p>\r\n                </div>\r\n              </div>\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Healthcare Background Required</strong>\r\n                  <p style=\"margin: 0;\">Advanced Cardiac Life Support (ACLS) and Pediatric Advanced Life Support (PALS). BLS knowledge recommended.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Course Duration</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Basic Life Support (BLS): One (1) Day</li>\r\n              <li>Advanced Cardiac Life Support (ACLS): Two (2) Days</li>\r\n              <li>Pediatric Advanced Life Support (PALS): Two (2) Days</li>\r\n              <li>Heartsaver First Aid: One (1) Day</li>\r\n            </ul>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Ideal For</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Healthcare workers and students</li>\r\n              <li>Corporates, schools and factories</li>\r\n              <li>Caregivers and home-based care providers</li>\r\n              <li>Security personnel</li>\r\n              <li>Community responders</li>\r\n              <li>KCPE / KCSE graduates and the general public</li>\r\n            </ul>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Certifications Awarded</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Official AHA eCard Certification (valid 2 years)</li>\r\n              <li>GoCare Completion Certificate</li>\r\n            </ul>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>AHA-certified graduates qualify for roles in:</p>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Hospitals and clinics</li>\r\n              <li>Emergency departments</li>\r\n              <li>Critical care units</li>\r\n              <li>Ambulance and rescue services</li>\r\n              <li>Schools, corporates and NGOs</li>\r\n              <li>Community health programs</li>\r\n              <li>International healthcare markets</li>\r\n            </ul>\r\n            <p style=\"margin-top: 20px; font-style: italic;\">AHA certification is a mandatory or preferred requirement in many healthcare and emergency settings worldwide.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li><strong>Option 1:</strong> Apply Online via the <a href=\"../apply.html\" style=\"color:var(--o);font-weight:600;\">application form</a>.</li>\r\n              <li><strong>Option 2:</strong> Visit Any GoCare Campus &ndash; Nairobi CBD or Thika Road (Ruiru).</li>\r\n              <li><strong>Admissions Line:</strong> 0703 115 502</li>\r\n            </ul>\r\n            <p style=\"margin-top: 20px;\">Begin your AHA Emergency Care Certification today and gain internationally recognized lifesaving skills with GoCare Training Institute.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply for Certification</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Us</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Accreditation</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA (USA)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Certification</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA eCard (2 yrs)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n                <span style=\"color: var(--gray);\">Global Reach</span>\r\n                <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">Recognised Worldwide</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The American Heart Association (AHA) Emergency Care Programs offered at GoCare Training Institute provide internationally recognized training in lifesaving skills for healthcare professionals, students, corporates and community responders. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response – skills required in hospitals, clinics, emergency units, workplaces and community settings. These programs follow global AHA standards and include official AHA certification valid worldwide. Training is delivered through hands-on simulations, skills practice and scenario-based learning at GoCare’s Nairobi CBD and Thika Road (Ruiru) campuses.\", \"heading\": \"Overview\"}, {\"body\": \"Internationally recognized AHA certification. Hands-on, simulation-based emergency care training. Training delivered by certified emergency care instructors. Modern skills-lab with CPR manikins, AED trainers and emergency equipment. Flexible study modes (Day, Evening, Weekend). Accessible to both medical and non-medical learners. Ideal for hospital staff, students, corporates, caregivers and community responders. High employability in Kenya and abroad. Strong add-on qualification for all GoCare medical and health sciences programs.\", \"heading\": \"Why Study AHA Courses at GoCare?\"}, {\"body\": \"Learners may pursue any of the following internationally certified AHA programs: 01\", \"heading\": \"AHA Courses Offered\"}, {\"body\": \"CPR, AED use, choking management and early recognition of cardiac arrest for adults, children and infants. Open to KCPE / KCSE graduates and the general public. 02\", \"heading\": \"Basic Life Support (BLS)\"}, {\"body\": \"Cardiac arrest algorithms, ECG interpretation, emergency pharmacology, airway management and megacode simulations. For healthcare professionals and senior health sciences students. 03\", \"heading\": \"Advanced Cardiac Life Support (ACLS)\"}, {\"body\": \"Assessment, respiratory distress, shock management, pediatric cardiac arrest and emergency teamwork. For pediatric, maternity, emergency and ICU providers. 04\", \"heading\": \"Pediatric Advanced Life Support (PALS)\"}, {\"body\": \"Bleeding control, burns, fractures, allergic reactions, seizures, diabetic emergencies, stroke and heart attack recognition. Open to KCPE / KCSE graduates, corporates, schools, caregivers and the general public.\", \"heading\": \"Heartsaver First Aid\"}, {\"body\": \"Open Entry (No Medical Background Required) Basic Life Support (BLS) and Heartsaver First Aid – open to KCPE / KCSE graduates and the general public. Healthcare Background Required Advanced Cardiac Life Support (ACLS) and Pediatric Advanced Life Support (PALS). BLS knowledge recommended.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Basic Life Support (BLS): One (1) Day Advanced Cardiac Life Support (ACLS): Two (2) Days Pediatric Advanced Life Support (PALS): Two (2) Days Heartsaver First Aid: One (1) Day\", \"heading\": \"Course Duration\"}, {\"body\": \"Healthcare workers and students Corporates, schools and factories Caregivers and home-based care providers Security personnel Community responders KCPE / KCSE graduates and the general public\", \"heading\": \"Ideal For\"}, {\"body\": \"Official AHA eCard Certification (valid 2 years) GoCare Completion Certificate\", \"heading\": \"Certifications Awarded\"}, {\"body\": \"AHA-certified graduates qualify for roles in: Hospitals and clinics Emergency departments Critical care units Ambulance and rescue services Schools, corporates and NGOs Community health programs International healthcare markets AHA certification is a mandatory or preferred requirement in many healthcare and emergency settings worldwide.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Option 1: Apply Online via the application form. Option 2: Visit Any GoCare Campus – Nairobi CBD or Thika Road (Ruiru). Admissions Line: 0703 115 502 Begin your AHA Emergency Care Certification today and gain internationally recognized lifesaving skills with GoCare Training Institute. Apply for Certification Contact Us Accreditation AHA (USA) Certification AHA eCard (2 yrs) Global Reach Recognised Worldwide\", \"heading\": \"How to Apply\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(4, 'AMCA (USA) Certification – GoCare Training Institute', 'amca-usa-certification', NULL, NULL, '<!-- COOKIE CONSENT -->\r\n  <div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\r\n    <div class=\"ck-inner\">\r\n      <div class=\"ck-left\">\r\n        <div class=\"ck-icon-wrap\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n            <path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/>\r\n            <path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/>\r\n          </svg>\r\n        </div>\r\n        <div class=\"ck-copy\">\r\n          <strong>We use cookies</strong>\r\n          <p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"ck-actions\">\r\n        <button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button>\r\n        <button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button>\r\n        <button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- -- NAVBAR ---------------------------------------- -->\r\n\r\n\r\n  <!-- -- SUB BAR --------------------------------------- -->\r\n  <div class=\"subbar\">\r\n    <div class=\"wrap subbar-inner\">\r\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\r\n      <div class=\"subbar-portals\">\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n\r\n  \r\n\r\n  \r\n\r\n\r\n\r\n<!-- -- HERO -- -->\r\n<section class=\"icp-hero\">\r\n  <img loading=\"lazy\" decoding=\"async\" class=\"icp-hero-img\" src=\"../images/new-images/DSC00707.jpg.jpeg\" alt=\"International Certification Pathways\">\r\n  <div class=\"icp-hero-overlay\"></div>\r\n  <div class=\"icp-hero-inner\">\r\n    <div class=\"icp-hero-left\">\r\n      <h1>International <span>Certification Pathways</span></h1>\r\n      <p>Gain globally recognized qualifications through <strong>AMCA USA</strong>, <strong>SDC Canada</strong>, and <strong>ICDL Global</strong>.</p>\r\n      <div class=\"icp-hero-btns\">\r\n        <a href=\"../admissions.html#how-to-apply\" class=\"icp-btn-blue\">Learn About Certifications</a>\r\n        <a href=\"../courses.html\" class=\"icp-btn-orange\">View Accredited Courses</a>\r\n      </div>\r\n      <div class=\"icp-hero-flags\">\r\n        <span class=\"icp-flag-badge\"><i data-lucide=\"map-pin\"></i> USA</span>\r\n        <span class=\"icp-flag-badge\"><i data-lucide=\"map-pin\"></i> Canada</span>\r\n        <span class=\"icp-flag-badge\"><i data-lucide=\"map-pin\"></i> Europe</span>\r\n        <span class=\"icp-flag-badge\"><i data-lucide=\"map-pin\"></i> Germany</span>\r\n      </div>\r\n    </div>\r\n    <div></div>\r\n  </div>\r\n</section>\r\n\r\n<!-- -- GLOBAL ACCREDITATION PARTNERS -- -->\r\n<div class=\"icp-partners\">\r\n  <div class=\"icp-partners-inner\">\r\n    <h2>Global Accreditation Partners</h2>\r\n    <div class=\"icp-partners-logos\">\r\n      <div class=\"icp-partner-logo\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"../images/partners/amca.png\" alt=\"AMCA USA\">\r\n      </div>\r\n      <div class=\"icp-partner-logo\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"../images/partners/SDCC.png\" alt=\"SDC Canada\">\r\n      </div>\r\n      <div class=\"icp-partner-logo\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"../images/partners/ICDL.png\" alt=\"ICDL Global\">\r\n      </div>\r\n      <div class=\"icp-partner-logo\">\r\n        <img loading=\"eager\" decoding=\"async\" src=\"../images/partners/American_Heart_Association_Logo.svg\" alt=\"American Heart Association\">\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- -- AHA EMERGENCY CARE COURSES -- -->\r\n<section class=\"aha-section\">\r\n  <div class=\"aha-inner\">\r\n    <div class=\"aha-head\">\r\n      <img loading=\"eager\" decoding=\"async\" src=\"../images/partners/American_Heart_Association_Logo.svg\" alt=\"American Heart Association\">\r\n      <h2>AHA <span>Emergency Care Courses</span></h2>\r\n    </div>\r\n    <p class=\"aha-sub\">Globally recognized American Heart Association certifications delivered at GoCare &ndash; giving you life-saving skills and an international edge.</p>\r\n    <div class=\"aha-grid\">\r\n\r\n      <a href=\"aha-emergency-care-programs.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"shield-check\"></i></div>\r\n          <span class=\"aha-dur\">Varies</span>\r\n        </div>\r\n        <h3>AHA Emergency Care Programs</h3>\r\n        <p>American Heart Association&ndash;certified emergency care training including BLS, ACLS, PALS and Heartsaver.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"basic-life-support-bls.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"heart-pulse\"></i></div>\r\n          <span class=\"aha-dur\">1 Day</span>\r\n        </div>\r\n        <h3>Basic Life Support (BLS)</h3>\r\n        <p>AHA-accredited BLS training for healthcare professionals and first responders.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"advanced-cardiac-life-support-acls.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"activity\"></i></div>\r\n          <span class=\"aha-dur\">2 Days</span>\r\n        </div>\r\n        <h3>Advanced Cardiac Life Support (ACLS)</h3>\r\n        <p>AHA-certified ACLS for managing cardiac emergencies and advanced resuscitation.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"pediatric-advanced-life-support-pals.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"baby\"></i></div>\r\n          <span class=\"aha-dur\">3 Days</span>\r\n        </div>\r\n        <h3>Pediatric Advanced Life Support (PALS)</h3>\r\n        <p>AHA-certified PALS covering paediatric emergencies and resuscitation protocols.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"heartsaver-first-aid.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"shield-plus\"></i></div>\r\n          <span class=\"aha-dur\">1 Day</span>\r\n        </div>\r\n        <h3>Heartsaver First Aid CPR &amp; AED</h3>\r\n        <p>AHA Heartsaver certification for first aid, CPR and AED use in any setting.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- -- SDC CANADA CERTIFICATION COURSES -- -->\r\n<section class=\"aha-section\">\r\n  <div class=\"aha-inner\">\r\n    <div class=\"aha-head\">\r\n      <img loading=\"eager\" decoding=\"async\" src=\"../images/partners/SDCC.png\" alt=\"Skill Development Council Canada\">\r\n      <h2>SDC Canada <span>Certification Courses</span></h2>\r\n    </div>\r\n    <p class=\"aha-sub\">Globally recognized Skill Development Council (SDC) Canada certifications delivered at GoCare &ndash; validating your professional competence for healthcare roles worldwide.</p>\r\n    <div class=\"aha-grid\">\r\n\r\n      <a href=\"sdc-canada-certification.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"stethoscope\"></i></div>\r\n          <span class=\"aha-dur\">Certificate</span>\r\n        </div>\r\n        <h3>Certificate in Nursing Assistant</h3>\r\n        <p>Canada-aligned training, examination and certification for nursing assistants in clinical settings.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"sdc-canada-certification.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"heart-pulse\"></i></div>\r\n          <span class=\"aha-dur\">Certificate</span>\r\n        </div>\r\n        <h3>Certificate in Health Care Assistant</h3>\r\n        <p>SDC Canada certification validating essential healthcare support and patient-care skills.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"sdc-canada-certification.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"heart-handshake\"></i></div>\r\n          <span class=\"aha-dur\">Certificate</span>\r\n        </div>\r\n        <h3>Certificate in Professional Caregiver</h3>\r\n        <p>Internationally recognized caregiver certification for professional home and facility-based care.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n      <a href=\"sdc-canada-certification.html\" class=\"aha-card\">\r\n        <div class=\"aha-card-top\">\r\n          <div class=\"aha-icon\"><i data-lucide=\"award\"></i></div>\r\n          <span class=\"aha-dur\">Adv. Certificate</span>\r\n        </div>\r\n        <h3>Advanced Certificate in Health Care Assistant</h3>\r\n        <p>Advanced SDC Canada credential for healthcare assistants seeking senior support roles abroad.</p>\r\n        <span class=\"aha-cta\">Learn More <i data-lucide=\"arrow-right\"></i></span>\r\n      </a>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- -- AMCA USA CERTIFICATION DETAIL -- -->\r\n<section class=\"amca-section\">\r\n  <div class=\"amca-inner\">\r\n    <div class=\"amca-layout\">\r\n      <div class=\"amca-main\">\r\n        <div class=\"amca-head\">\r\n          <img loading=\"lazy\" decoding=\"async\" class=\"amca-head-logo\" src=\"../images/partners/amca.png\" alt=\"AMCA USA\">\r\n          <div>\r\n            <span class=\"amca-eyebrow\">USA-Based Accredited Curriculum, Examination &amp; Certification</span>\r\n            <h2>The American Medical Certification Association <span>(AMCA) &ndash; USA</span></h2>\r\n          </div>\r\n        </div>\r\n        <p class=\"amca-intro\">GoCare Training Institute offers USA&#8209;aligned curriculum training, examination, and certification through the American Medical Certification Association (AMCA) &mdash; a globally recognized U.S. credentialing body for healthcare support professionals. This pathway provides career, professional, and global recognition, enabling graduates to qualify for international healthcare roles across the USA, Canada, Europe, the Middle East, and Asia.</p>\r\n\r\n        <div class=\"amca-grid\">\r\n\r\n          <div class=\"icp-card\">\r\n            <h3><i data-lucide=\"badge-check\"></i> Certification Options</h3>\r\n            <ul class=\"icp-checklist\">\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                Patient Care Technician (PCT)\r\n              </li>\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                Nursing Assistant (CNA)\r\n              </li>\r\n            </ul>\r\n            <p class=\"amca-note\">These certifications validate clinical competence and align with U.S. healthcare support standards.</p>\r\n          </div>\r\n\r\n          <div class=\"icp-card\">\r\n            <h3><i data-lucide=\"user-check\"></i> Who Qualifies?</h3>\r\n            <div class=\"amca-qual-row\">\r\n              <span class=\"amca-qual-label\">Qualification</span>\r\n              <strong>Medical and healthcare professionals</strong>\r\n            </div>\r\n            <div class=\"amca-qual-row\">\r\n              <span class=\"amca-qual-label\">Requirements</span>\r\n              <strong>A relevant Certificate, Diploma, or Degree qualification in a medical or healthcare field</strong>\r\n            </div>\r\n            <p class=\"amca-note\">This ensures that only trained professionals pursue AMCA&rsquo;s internationally recognized credentials.</p>\r\n          </div>\r\n\r\n          <div class=\"icp-card\">\r\n            <h3><i data-lucide=\"star\"></i> Why Choose AMCA at GoCare?</h3>\r\n            <ul class=\"icp-checklist\">\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                USA-based curriculum &amp; assessment standards\r\n              </li>\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                Internationally recognized certification\r\n              </li>\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                Strengthens global employability\r\n              </li>\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                Ideal for migration-linked healthcare opportunities\r\n              </li>\r\n              <li>\r\n                <div class=\"icp-check\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\r\n                Complements GoCare&rsquo;s accredited medical &amp; health sciences programs\r\n              </li>\r\n            </ul>\r\n          </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"amca-careers\">\r\n          <h3><i data-lucide=\"briefcase\"></i> Career Opportunities with AMCA Certification</h3>\r\n          <p class=\"amca-careers-sub\">AMCA-certified graduates qualify for roles such as:</p>\r\n          <div class=\"amca-career-grid\">\r\n            <span class=\"amca-career-pill\">Certified Nursing Assistant (CNA)</span>\r\n            <span class=\"amca-career-pill\">Patient Care Technician (PCT)</span>\r\n            <span class=\"amca-career-pill\">Home Health Aide</span>\r\n            <span class=\"amca-career-pill\">Long-Term Care Assistant</span>\r\n            <span class=\"amca-career-pill\">Hospital Support Staff</span>\r\n            <span class=\"amca-career-pill\">International Caregiver</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <aside class=\"course-sidebar amca-sidebar\">\r\n        <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n          <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n            <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Training Duration</span>\r\n            <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1 Month</div>\r\n            <p style=\"margin: 8px 0 0; color: var(--o); font-weight: 700; font-size: 13px;\">4 Weeks Intensive Training</p>\r\n          </div>\r\n          <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n            <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply Now</a>\r\n            <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n          </div>\r\n\r\n          <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n            <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n              <span style=\"color: var(--gray);\">Accreditation</span>\r\n              <strong style=\"color: var(--dark); text-align: right;\">AMCA (USA)</strong>\r\n            </div>\r\n            <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n              <span style=\"color: var(--gray);\">Global Reach</span>\r\n              <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">USA, Canada, Europe, Middle East, Asia</strong>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n          <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n          <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n          <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n        </div>\r\n      </aside>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- -- BOTTOM TAGLINE BAR -- -->\r\n<div class=\"icp-tagline-bar\">Your Gateway to <em>International Certification and Career Mobility</em></div>\r\n  \r\n  \r\n  <!-- BACK TO TOP -->\r\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\r\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\r\n  </button>', '[{\"body\": \"Gain globally recognized qualifications through AMCA USA, SDC Canada, and ICDL Global. Learn About Certifications View Accredited Courses USA Canada Europe Germany\", \"heading\": \"International Certification Pathways\"}, {\"body\": \"\", \"heading\": \"Global Accreditation Partners\"}, {\"body\": \"Globally recognized American Heart Association certifications delivered at GoCare – giving you life-saving skills and an international edge. Varies\", \"heading\": \"AHA Emergency Care Courses\"}, {\"body\": \"American Heart Association–certified emergency care training including BLS, ACLS, PALS and Heartsaver. Learn More 1 Day\", \"heading\": \"AHA Emergency Care Programs\"}, {\"body\": \"AHA-accredited BLS training for healthcare professionals and first responders. Learn More 2 Days\", \"heading\": \"Basic Life Support (BLS)\"}, {\"body\": \"AHA-certified ACLS for managing cardiac emergencies and advanced resuscitation. Learn More 3 Days\", \"heading\": \"Advanced Cardiac Life Support (ACLS)\"}, {\"body\": \"AHA-certified PALS covering paediatric emergencies and resuscitation protocols. Learn More 1 Day\", \"heading\": \"Pediatric Advanced Life Support (PALS)\"}, {\"body\": \"AHA Heartsaver certification for first aid, CPR and AED use in any setting. Learn More\", \"heading\": \"Heartsaver First Aid CPR & AED\"}, {\"body\": \"Globally recognized Skill Development Council (SDC) Canada certifications delivered at GoCare – validating your professional competence for healthcare roles worldwide. Certificate\", \"heading\": \"SDC Canada Certification Courses\"}, {\"body\": \"Canada-aligned training, examination and certification for nursing assistants in clinical settings. Learn More Certificate\", \"heading\": \"Certificate in Nursing Assistant\"}, {\"body\": \"SDC Canada certification validating essential healthcare support and patient-care skills. Learn More Certificate\", \"heading\": \"Certificate in Health Care Assistant\"}, {\"body\": \"Internationally recognized caregiver certification for professional home and facility-based care. Learn More Adv. Certificate\", \"heading\": \"Certificate in Professional Caregiver\"}, {\"body\": \"Advanced SDC Canada credential for healthcare assistants seeking senior support roles abroad. Learn More USA-Based Accredited Curriculum, Examination & Certification\", \"heading\": \"Advanced Certificate in Health Care Assistant\"}, {\"body\": \"GoCare Training Institute offers USA‑aligned curriculum training, examination, and certification through the American Medical Certification Association (AMCA) — a globally recognized U.S. credentialing body for healthcare support professionals. This pathway provides career, professional, and global recognition, enabling graduates to qualify for international healthcare roles across the USA, Canada, Europe, the Middle East, and Asia.\", \"heading\": \"The American Medical Certification Association (AMCA) – USA\"}, {\"body\": \"Patient Care Technician (PCT) Nursing Assistant (CNA) These certifications validate clinical competence and align with U.S. healthcare support standards.\", \"heading\": \"Certification Options\"}, {\"body\": \"Qualification Medical and healthcare professionals Requirements A relevant Certificate, Diploma, or Degree qualification in a medical or healthcare field This ensures that only trained professionals pursue AMCA’s internationally recognized credentials.\", \"heading\": \"Who Qualifies?\"}, {\"body\": \"USA-based curriculum & assessment standards Internationally recognized certification Strengthens global employability Ideal for migration-linked healthcare opportunities Complements GoCare’s accredited medical & health sciences programs\", \"heading\": \"Why Choose AMCA at GoCare?\"}, {\"body\": \"AMCA-certified graduates qualify for roles such as: Certified Nursing Assistant (CNA) Patient Care Technician (PCT) Home Health Aide Long-Term Care Assistant Hospital Support Staff International Caregiver Training Duration 1 Month 4 Weeks Intensive Training Apply Now Contact Admissions Accreditation AMCA (USA) Global Reach USA, Canada, Europe, Middle East, Asia\", \"heading\": \"Career Opportunities with AMCA Certification\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502 Your Gateway to International Certification and Career Mobility\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(5, 'Basic Life Support (BLS) - American Heart Association · GoCare Training Institute', 'basic-life-support-bls', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Basic Life Support (BLS) course equips learners with essential lifesaving skills in CPR, AED use and emergency response for adults, children and infants. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response &mdash; skills required in hospitals, clinics, emergency units, workplaces and community settings.</p>\r\n            <p>This AHA-aligned program focuses on high-quality CPR, early recognition of cardiac arrest and effective team dynamics during resuscitation. Training is delivered through hands-on simulations, skills practice and scenario-based learning at GoCare&rsquo;s Nairobi CBD and Thika Road (Ruiru) campuses.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study BLS at GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Internationally recognized AHA certification.</li>\r\n              <li>Hands-on, simulation-based CPR and AED training.</li>\r\n              <li>Training delivered by certified emergency care instructors.</li>\r\n              <li>Modern skills-lab with CPR manikins, AED trainers and emergency equipment.</li>\r\n              <li>Affordable, accessible pricing for students, corporates and the general public.</li>\r\n              <li>Flexible study modes (Day, Evening, Weekend).</li>\r\n              <li>Ideal for hospital staff, students, corporates, caregivers and community responders.</li>\r\n              <li>High employability in Kenya and abroad.</li>\r\n              <li>Strong add-on qualification for all GoCare medical and health sciences programs.</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #f0f4f8; padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Open Entry</strong>\r\n                  <p style=\"margin: 0;\">No medical background required.</p>\r\n                </div>\r\n              </div>\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Eligibility</strong>\r\n                  <p style=\"margin: 0;\">KCPE or KCSE graduates and the general public.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Course Duration</h2>\r\n            <p style=\"font-size:1.05rem;\"><strong style=\"color:var(--o);\">One (1) Day</strong></p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>High-quality CPR for adults, children and infants</li>\r\n              <li>AED use and operation</li>\r\n              <li>Choking management</li>\r\n              <li>Team roles during resuscitation</li>\r\n              <li>Early recognition of cardiac arrest</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Ideal For</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>KCPE and KCSE graduates</li>\r\n              <li>General public</li>\r\n              <li>Healthcare workers and students</li>\r\n              <li>Corporates, schools and factories</li>\r\n              <li>Emergency responders and safety teams</li>\r\n              <li>Caregivers and home-based care providers</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Certifications Awarded</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>AHA BLS Provider eCard Certification</li>\r\n              <li>GoCare Completion Certificate</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>BLS-certified graduates qualify for roles in:</p>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Hospitals and clinics</li>\r\n              <li>Emergency departments</li>\r\n              <li>Critical care units</li>\r\n              <li>Ambulance and rescue services</li>\r\n              <li>Schools, corporates and NGOs</li>\r\n              <li>Community health programs</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 12px;\">\r\n            <p style=\"font-style: italic; color: var(--dark);\">BLS certification is a mandatory or preferred requirement in many healthcare and emergency settings worldwide.</p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li><strong>Option 1:</strong> Apply Online via the <a href=\"../apply.html\" style=\"color:var(--o);font-weight:600;\">application form</a>.</li>\r\n              <li><strong>Option 2:</strong> Visit Any GoCare Campus &mdash; Nairobi CBD or Thika Road (Ruiru).</li>\r\n              <li><strong>Admissions Line:</strong> 0703 115 502</li>\r\n            </ul>\r\n            <p style=\"margin-top: 20px;\">Begin your Basic Life Support (BLS) certification today and gain essential lifesaving skills with GoCare Training Institute.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1 Day</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply for Certification</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Us</a>\r\n            </div>\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Accreditation</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA (USA)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Certification</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA BLS eCard</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n                <span style=\"color: var(--gray);\">Entry</span>\r\n                <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">Open Entry</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Basic Life Support (BLS) course equips learners with essential lifesaving skills in CPR, AED use and emergency response for adults, children and infants. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response — skills required in hospitals, clinics, emergency units, workplaces and community settings. This AHA-aligned program focuses on high-quality CPR, early recognition of cardiac arrest and effective team dynamics during resuscitation. Training is delivered through hands-on simulations, skills practice and scenario-based learning at GoCare’s Nairobi CBD and Thika Road (Ruiru) campuses.\", \"heading\": \"Course Overview\"}, {\"body\": \"Internationally recognized AHA certification. Hands-on, simulation-based CPR and AED training. Training delivered by certified emergency care instructors. Modern skills-lab with CPR manikins, AED trainers and emergency equipment. Affordable, accessible pricing for students, corporates and the general public. Flexible study modes (Day, Evening, Weekend). Ideal for hospital staff, students, corporates, caregivers and community responders. High employability in Kenya and abroad. Strong add-on qualification for all GoCare medical and health sciences programs.\", \"heading\": \"Why Study BLS at GoCare?\"}, {\"body\": \"Open Entry No medical background required. Eligibility KCPE or KCSE graduates and the general public.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"One (1) Day\", \"heading\": \"Course Duration\"}, {\"body\": \"High-quality CPR for adults, children and infants AED use and operation Choking management Team roles during resuscitation Early recognition of cardiac arrest\", \"heading\": \"What You Will Learn\"}, {\"body\": \"KCPE and KCSE graduates General public Healthcare workers and students Corporates, schools and factories Emergency responders and safety teams Caregivers and home-based care providers\", \"heading\": \"Ideal For\"}, {\"body\": \"AHA BLS Provider eCard Certification GoCare Completion Certificate\", \"heading\": \"Certifications Awarded\"}, {\"body\": \"BLS-certified graduates qualify for roles in: Hospitals and clinics Emergency departments Critical care units Ambulance and rescue services Schools, corporates and NGOs Community health programs BLS certification is a mandatory or preferred requirement in many healthcare and emergency settings worldwide.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Option 1: Apply Online via the application form. Option 2: Visit Any GoCare Campus — Nairobi CBD or Thika Road (Ruiru). Admissions Line: 0703 115 502 Begin your Basic Life Support (BLS) certification today and gain essential lifesaving skills with GoCare Training Institute. Total Duration 1 Day Apply for Certification Contact Us Accreditation AHA (USA) Certification AHA BLS eCard Entry Open Entry\", \"heading\": \"How to Apply\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(6, 'Caregiver Course Level II (NITA) | GoCare Training Institute', 'caregiver-course-level-ii', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\">\r\n        <div class=\"course-body\">\r\n\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Caregiver Course &ndash; Level II is a comprehensive, NITA-accredited program that prepares learners to become professional caregivers and patient attendants capable of delivering safe, compassionate, and high-quality support in hospitals, clinics, nursing homes, hospices, and home-based care environments.</p>\r\n            <p>Learners gain essential skills in patient hygiene, feeding, mobility assistance, repositioning, communication, and basic supportive nursing procedures. The course also trains students to observe and report patient concerns to nurses and other healthcare professionals, ensuring continuity of care and patient safety.</p>\r\n            <p>This approved Caregiver Level II program offers standardized, nationally recognized training and certification. Graduates qualify for multiple professional roles, including Patient Attendant, Patient Care Technician, Nursing Assistant, Health Care Assistant, and Professional Caregiver.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top:50px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display:grid;gap:16px;margin-top:20px;\">\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">1</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">2</div>\r\n                <p style=\"margin:0;line-height:1.6;\">NITA-approved Caregiver Level II curriculum aligned with national occupational standards.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">3</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Hands-on practical training with real patient exposure in hospitals, clinics, nursing homes, and home-based care settings.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">4</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Guaranteed attachment placement by the college in accredited healthcare and homecare facilities.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">5</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Government and regulator-recognized qualifications and certification.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">6</div>\r\n                <p style=\"margin:0;line-height:1.6;\">International certification options (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">7</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Training delivered by qualified nurses, clinicians, and professional caregivers.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">8</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Modern skills-lab and simulation-based training for hygiene care, feeding, mobility assistance, repositioning, communication, and supportive nursing procedures.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">9</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Strong emphasis on patient safety, compassion, ethics, and professional conduct.</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">10</div>\r\n                <p style=\"margin:0;line-height:1.6;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n                <div style=\"background:var(--o);color:#F5F0E8;min-width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;\">11</div>\r\n                <p style=\"margin:0;line-height:1.6;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, hospices, and private home-based care.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top:50px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div style=\"display:flex;align-items:center;gap:14px;background:#f9fafb;padding:18px 24px;border-radius:12px;border:1px solid #e5e7eb;margin-top:16px;\">\r\n              <i data-lucide=\"file-text\" style=\"color:var(--o);width:28px;height:28px;flex-shrink:0;\"></i>\r\n              <p style=\"margin:0;font-weight:600;font-size:1rem;color:var(--dark);\">KCSE Mean Grade D- (Minus) and above</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top:50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <h3 style=\"font-size:1.1rem;color:var(--dark);margin-bottom:16px;font-weight:700;\">Units of Competence</h3>\r\n            <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px;\">\r\n              <ul style=\"list-style:none;padding:0;\">\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Introduction to Caregiving</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Life Skills for Caregivers</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Patient &amp; Environmental Safety</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Infection Prevention &amp; Control (IPC)</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Use and Care of Tools &amp; Equipment</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Professional Conduct in Caregiving</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Patient and Healthcare Workers\' Rights</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Introduction to Business Skills</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Introduction to ICT for Caregivers</li>\r\n              </ul>\r\n              <ul style=\"list-style:none;padding:0;\">\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Communication Skills for Caregivers</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Basic First Aid</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Nutrition &amp; Feeding Support</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Patient Bed-Making &amp; Repositioning</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Bathing &amp; Grooming Assistance</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> General Toileting Support</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Moving &amp; Handling Patients</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Basic Care &amp; Management of Patient Conditions</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check-circle\" style=\"color:var(--o);flex-shrink:0;width:20px;\"></i> Psychosocial &amp; Spiritual Support</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- SECOND COURSE SPONSORSHIP BANNER -->\r\n          <section style=\"margin-top:50px;background:linear-gradient(135deg,var(--dark) 0%,#3a1a5e 100%);border-radius:16px;padding:40px 50px !important;position:relative;overflow:hidden;\">\r\n            <div style=\"position:absolute;top:-40px;right:-40px;width:200px;height:200px;background:var(--o);opacity:0.08;border-radius:50%;\"></div>\r\n            <div style=\"position:absolute;bottom:-30px;left:-30px;width:150px;height:150px;background:var(--o);opacity:0.06;border-radius:50%;\"></div>\r\n            <span style=\"display:inline-block;background:var(--o);color:#F5F0E8;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:1.5px;padding:6px 16px;border-radius:20px;margin-bottom:16px;position:relative;z-index:2;\"><i data-lucide=\"gift\" style=\"width:14px;height:14px;vertical-align:-2px;margin-right:4px;\"></i> Special Offer</span>\r\n            <h3 style=\"color:#F5F0E8;font-size:1.5rem;margin-bottom:12px;position:relative;z-index:2;\">Second Course Sponsorship</h3>\r\n            <p style=\"color:rgba(255,255,255,0.85);line-height:1.7;font-size:0.95rem;position:relative;z-index:2;\">Enrol for this Caregiver Course &ndash; Level II and receive a fully sponsored international training and certification in an additional program.</p>\r\n            <p style=\"color:rgba(255,255,255,0.85);line-height:1.7;font-size:0.95rem;position:relative;z-index:2;\">This offer includes a second free course, giving every student access to internationally accredited training and certification for either the <strong style=\"color:var(--o);\">Professional Caregiver</strong> or <strong style=\"color:var(--o);\">Certified Nursing Assistant (CNA)</strong> program, depending on your preference.</p>\r\n            <div style=\"background:rgba(255,255,255,0.1);padding:20px;border-radius:8px;border-left:4px solid var(--o);margin-top:20px;position:relative;z-index:2;\">\r\n              <p style=\"margin:0;font-weight:500;font-size:16px;color:#F5F0E8;\">You pay for one course, and GoCare Training Institute sponsors and trains you in the second complimentary course at no extra cost &mdash; enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability.</p>\r\n            </div>\r\n            <div style=\"margin-top:25px;position:relative;z-index:2;\">\r\n              <a href=\"second-course-sponsorship.html\" class=\"btn btn-primary\" style=\"background:var(--o);border-color:var(--o);color:#F5F0E8;text-transform:uppercase;font-size:14px;font-weight:bold;letter-spacing:1px;padding:12px 24px;\"><i data-lucide=\"arrow-right\"></i> Learn More About Sponsorship</a>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top:50px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a <strong>Two (2) month</strong> hospital attachment in:</p>\r\n            <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px;\">\r\n              <div style=\"display:flex;gap:10px;align-items:center;\"><i data-lucide=\"hospital\" style=\"color:var(--o);width:20px;\"></i> Hospitals</div>\r\n              <div style=\"display:flex;gap:10px;align-items:center;\"><i data-lucide=\"building\" style=\"color:var(--o);width:20px;\"></i> Clinics</div>\r\n              <div style=\"display:flex;gap:10px;align-items:center;\"><i data-lucide=\"home\" style=\"color:var(--o);width:20px;\"></i> Nursing homes</div>\r\n              <div style=\"display:flex;gap:10px;align-items:center;\"><i data-lucide=\"heart\" style=\"color:var(--o);width:20px;\"></i> Home-based care agencies</div>\r\n            </div>\r\n            <p style=\"margin-top:16px;\">GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top:40px;border-top:1px solid #e2e8f0;padding-top:30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates can work as:</p>\r\n            <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:20px;\">\r\n              <ul style=\"list-style:none;padding:0;\">\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Professional Caregiver</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Nursing Assistant</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Patient Attendant</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Patient Care Technician</li>\r\n              </ul>\r\n              <ul style=\"list-style:none;padding:0;\">\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Health Care Assistant</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Medical Receptionist</li>\r\n                <li style=\"margin-bottom:10px;display:flex;gap:10px;\"><i data-lucide=\"check\" style=\"color:var(--o);flex-shrink:0;\"></i> Support Worker in diverse healthcare settings</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top:15px;font-weight:500;color:var(--dark);\">This qualification opens doors to a wide range of healthcare support roles locally and internationally.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top:40px;border-top:1px solid #e2e8f0;padding-top:30px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px;\">\r\n              <div style=\"background:#f9fafb;padding:24px;border-radius:12px;border:1px solid #e5e7eb;\">\r\n                <h4 style=\"color:var(--o);margin-bottom:8px;\">Option 1: Apply Online</h4>\r\n                <p style=\"margin:0;font-size:0.95rem;\">Submit your application through the official <a href=\"../apply.html\" style=\"color:var(--o);font-weight:600;\">GoCare Online Application Form</a>.</p>\r\n              </div>\r\n              <div style=\"background:#f9fafb;padding:24px;border-radius:12px;border:1px solid #e5e7eb;\">\r\n                <h4 style=\"color:var(--o);margin-bottom:8px;\">Option 2: Visit Any Campus</h4>\r\n                <p style=\"margin:0;font-size:0.95rem;\">Our admissions team will guide you. Call: <a href=\"tel:+254703115502\" style=\"color:var(--o);font-weight:600;\">0703 115 502</a></p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background:#fcfcfc;padding:30px;border-radius:12px;box-shadow:0 4px 20px rgba(0,0,0,0.05);margin-bottom:30px;border-top:5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">6 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display:grid;gap:15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align:center;background:var(--o);border-color:var(--o);color:#F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align:center;border-color:var(--o);color:var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n            <div class=\"sidebar-info-list\" style=\"margin-top:30px;\">\r\n              <div class=\"side-info-item\" style=\"padding:12px 0;border-bottom:1px dashed #e2e8f0;\">\r\n                <span style=\"color:var(--gray);font-size:13px;display:block;margin-bottom:4px;\">Entry Requirements</span>\r\n                <strong style=\"color:var(--dark);display:block;\">KCSE D- (Minus) and above</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding:12px 0;border-bottom:1px dashed #e2e8f0;\">\r\n                <span style=\"color:var(--gray);font-size:13px;display:block;margin-bottom:4px;\">Study Mode</span>\r\n                <strong style=\"color:var(--dark);display:block;\">Day / Online / Evening / Saturday</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding:12px 0;border-bottom:1px dashed #e2e8f0;\">\r\n                <span style=\"color:var(--gray);font-size:13px;display:block;margin-bottom:4px;\">Internal Assessment</span>\r\n                <strong style=\"color:var(--dark);display:block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding:12px 0;border-bottom:1px dashed #e2e8f0;\">\r\n                <span style=\"color:var(--gray);font-size:13px;display:block;margin-bottom:4px;\">External Assessment</span>\r\n                <strong style=\"color:var(--dark);display:block;\">NITA (National Industrial Training Authority)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding:12px 0;\">\r\n                <span style=\"color:var(--gray);font-size:13px;display:block;margin-bottom:4px;\">Certificates Awarded</span>\r\n                <strong style=\"color:var(--dark);display:block;font-size:14px;line-height:1.5;\">NITA Certification<br>Academic Transcripts<br>GoCare Completion Certificate<br>SDC Canada Int\'l Cert<br><span style=\"font-size:12px;color:var(--gray);\">(Professional Caregiver or CNA &mdash; your choice)</span></strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background:var(--dark);color:#F5F0E8;padding:30px;border-radius:12px;text-align:center;position:relative;overflow:hidden;\">\r\n            <div style=\"position:absolute;top:-20px;right:-20px;width:100px;height:100px;background:var(--o);opacity:0.1;border-radius:50%;\"></div>\r\n            <h4 style=\"color:#F5F0E8;margin-bottom:10px;position:relative;z-index:2;\">Begin Your Career Today</h4>\r\n            <p style=\"color:rgba(255,255,255,0.8);margin-bottom:20px;font-size:14px;position:relative;z-index:2;\">Start your journey toward becoming a certified and globally recognized Professional Caregiver / Nursing Assistant.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display:inline-flex;align-items:center;gap:10px;font-size:20px;font-weight:bold;color:var(--o);background:rgba(255,255,255,0.1);padding:10px 20px;border-radius:8px;position:relative;z-index:2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Caregiver Course – Level II is a comprehensive, NITA-accredited program that prepares learners to become professional caregivers and patient attendants capable of delivering safe, compassionate, and high-quality support in hospitals, clinics, nursing homes, hospices, and home-based care environments. Learners gain essential skills in patient hygiene, feeding, mobility assistance, repositioning, communication, and basic supportive nursing procedures. The course also trains students to observe and report patient concerns to nurses and other healthcare professionals, ensuring continuity of care and patient safety. This approved Caregiver Level II program offers standardized, nationally recognized training and certification. Graduates qualify for multiple professional roles, including Patient Attendant, Patient Care Technician, Nursing Assistant, Health Care Assistant, and Professional Caregiver.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 NITA-approved Caregiver Level II curriculum aligned with national occupational standards. 3 Hands-on practical training with real patient exposure in hospitals, clinics, nursing homes, and home-based care settings. 4 Guaranteed attachment placement by the college in accredited healthcare and homecare facilities. 5 Government and regulator-recognized qualifications and certification. 6 International certification options (SDC Canada, AMCA USA). 7 Training delivered by qualified nurses, clinicians, and professional caregivers. 8 Modern skills-lab and simulation-based training for hygiene care, feeding, mobility assistance, repositioning, communication, and supportive nursing procedures. 9 Strong emphasis on patient safety, compassion, ethics, and professional conduct. 10 Flexible study modes (Day, Online, Evening, Saturday). 11 High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, hospices, and private home-based care.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade D- (Minus) and above\", \"heading\": \"Entry Requirements\"}, {\"body\": \"\", \"heading\": \"What You Will Learn\"}, {\"body\": \"Introduction to Caregiving Life Skills for Caregivers Patient & Environmental Safety Infection Prevention & Control (IPC) Use and Care of Tools & Equipment Professional Conduct in Caregiving Patient and Healthcare Workers\' Rights Introduction to Business Skills Introduction to ICT for Caregivers Communication Skills for Caregivers Basic First Aid Nutrition & Feeding Support Patient Bed-Making & Repositioning Bathing & Grooming Assistance General Toileting Support Moving & Handling Patients Basic Care & Management of Patient Conditions Psychosocial & Spiritual Support Special Offer\", \"heading\": \"Units of Competence\"}, {\"body\": \"Enrol for this Caregiver Course – Level II and receive a fully sponsored international training and certification in an additional program. This offer includes a second free course, giving every student access to internationally accredited training and certification for either the Professional Caregiver or Certified Nursing Assistant (CNA) program, depending on your preference. You pay for one course, and GoCare Training Institute sponsors and trains you in the second complimentary course at no extra cost — enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability. Learn More About Sponsorship\", \"heading\": \"Second Course Sponsorship\"}, {\"body\": \"All learners undertake a Two (2) month hospital attachment in: Hospitals Clinics Nursing homes Home-based care agencies GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates can work as: Professional Caregiver Nursing Assistant Patient Attendant Patient Care Technician Health Care Assistant Medical Receptionist Support Worker in diverse healthcare settings This qualification opens doors to a wide range of healthcare support roles locally and internationally.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"\", \"heading\": \"How to Apply\"}, {\"body\": \"Submit your application through the official GoCare Online Application Form.\", \"heading\": \"Option 1: Apply Online\"}, {\"body\": \"Our admissions team will guide you. Call: 0703 115 502 Total Duration 6 Months Apply Online Contact Admissions Entry Requirements KCSE D- (Minus) and above Study Mode Day / Online / Evening / Saturday Internal Assessment GoCare Training Institute External Assessment NITA (National Industrial Training Authority) Certificates Awarded NITA CertificationAcademic TranscriptsGoCare Completion CertificateSDC Canada Int\'l Cert(Professional Caregiver or CNA — your choice)\", \"heading\": \"Option 2: Visit Any Campus\"}, {\"body\": \"Start your journey toward becoming a certified and globally recognized Professional Caregiver / Nursing Assistant. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(7, 'Certificate in Caregiving Level 4 | GoCare Training Institute', 'certificate-in-caregiving-level-4', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\">\r\n        <div class=\"course-body\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Certificate in Caregiving &ndash; Level 4 is a comprehensive, competency-based program that prepares learners to become advanced healthcare assistants and professional caregivers capable of delivering safe, compassionate, and supportive patient care across hospitals, clinics, nursing homes, hospices, and home-based care environments.</p>\r\n            <p>Learners acquire essential caregiving skills, patient-handling techniques, infection-control practices, communication competencies, and supportive nursing procedures required in modern healthcare settings. Students are trained to work under and alongside nurses, doctors, and allied health professionals, ensuring comfort, dignity, and quality service delivery for patients.</p>\r\n            <p>Graduates emerge as confident, job-ready healthcare support professionals with strong employability both locally and internationally.</p>\r\n            <div style=\"background: linear-gradient(135deg, #fff7ed, #fff1e3); border-left: 4px solid var(--o); padding: 20px 24px; border-radius: 8px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-weight: 600; color: var(--dark); line-height: 1.7; font-size: 0.95rem;\">This nationally recognized Level 4 qualification provides a strong entry point into more advanced healthcare professions and serves as a direct pathway to the <strong style=\"color: var(--o);\">Kenya Health Professions Oversight Authority (KHPOA)</strong> licensed Healthcare Support Services &ndash; Level 5 (CNA).</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 16px; margin-top: 20px;\">\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">1</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">2</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Competency-based TVET CDACC curriculum aligned with national caregiving and healthcare support standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">3</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Hands-on clinical training with real patient exposure in hospitals, clinics, nursing homes, and home-based care settings.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">4</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">5</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">6</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">International certification options (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">7</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Clear progression pathway to the KHPOA licensed Certificate in Healthcare Support Services &ndash; Level 5 (CNA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">8</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Training delivered by qualified nurses, clinicians, and professional caregivers.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">9</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Modern skills-lab and simulation-based training for patient care, vital signs, mobility assistance, infection control, and homecare procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">10</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">11</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, hospices, and community health programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div style=\"display: flex; align-items: center; gap: 14px; background: #f9fafb; padding: 18px 24px; border-radius: 12px; border: 1px solid #e5e7eb; margin-top: 16px;\">\r\n              <i data-lucide=\"file-text\" style=\"color: var(--o); width: 28px; height: 28px; flex-shrink: 0;\"></i>\r\n              <p style=\"margin: 0; font-weight: 600; font-size: 1rem; color: var(--dark);\">KCSE Certificate (Any Grade)</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <h3 style=\"font-size: 1.1rem; color: var(--dark); margin-bottom: 16px; font-weight: 700;\">Units of Competence</h3>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> First Aid &amp; Emergency Response</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Healthcare Housekeeping &amp; Hygiene</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Client Dietary Support &amp; Nutrition Care</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Psychosocial Support for Patients</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Pre-Departure &amp; Patient Transfer Procedures</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Caregiving Catering &amp; Meal Support</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Special Needs Care Support</li>\r\n              </ul>\r\n            </div>\r\n\r\n            <h3 style=\"font-size: 1.1rem; color: var(--dark); margin: 30px 0 16px; font-weight: 700;\">Additional Institutional Competencies (GoCare Enhanced Training)</h3>\r\n            <div style=\"background: #fff7ed; padding: 24px; border-radius: 12px; border: 1px solid #fed7aa;\">\r\n              <ul style=\"list-style: none; padding: 0; margin: 0; display: grid; gap: 12px;\">\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Introduction to Caregiving and the Fundamental Skills of Caregiving</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Alzheimer&rsquo;s, Dementia and Other Common Mental Health Disorders Care</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Infection Prevention and Control</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Home-Based Care Skills and Procedures</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Communicable and Non-Communicable Diseases and Common Health Conditions</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Introduction to the Hospital Layout and Procedures</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- SECOND COURSE SPONSORSHIP BANNER -->\r\n          <section style=\"margin-top: 50px; background: linear-gradient(135deg, var(--dark) 0%, #3a1a5e 100%); border-radius: 16px; padding: 40px 50px !important; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -40px; right: -40px; width: 200px; height: 200px; background: var(--o); opacity: 0.08; border-radius: 50%;\"></div>\r\n            <div style=\"position: absolute; bottom: -30px; left: -30px; width: 150px; height: 150px; background: var(--o); opacity: 0.06; border-radius: 50%;\"></div>\r\n            <span style=\"display: inline-block; background: var(--o); color: #F5F0E8; font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: 1.5px; padding: 6px 16px; border-radius: 20px; margin-bottom: 16px; position: relative; z-index: 2;\"><i data-lucide=\"gift\" style=\"width: 14px; height: 14px; vertical-align: -2px; margin-right: 4px;\"></i> Special Offer</span>\r\n            <h3 style=\"color: #F5F0E8; font-size: 1.5rem; margin-bottom: 12px; position: relative; z-index: 2;\">Second Course Sponsorship</h3>\r\n            <p style=\"color: rgba(255,255,255,0.85); line-height: 1.7; font-size: 0.95rem; position: relative; z-index: 2;\">Enrol for this Certificate in Caregiving &ndash; Level 4 course and receive a fully sponsored international training and certification in an additional program.</p>\r\n            <p style=\"color: rgba(255,255,255,0.85); line-height: 1.7; font-size: 0.95rem; position: relative; z-index: 2;\">This offer includes a second free course, giving every student access to internationally accredited training and certification for either the <strong style=\"color: var(--o);\">Advanced Health Care Assistant</strong> or <strong style=\"color: var(--o);\">Certified Nursing Assistant (CNA)</strong> program, depending on your preference.</p>\r\n            <div style=\"background: rgba(255,255,255,0.1); padding: 20px; border-radius: 8px; border-left: 4px solid var(--o); margin-top: 20px; position: relative; z-index: 2;\">\r\n              <p style=\"margin: 0; font-weight: 500; font-size: 16px; color: #F5F0E8;\">You pay for one course, and GoCare Training Institute sponsors and trains you in the second complimentary course at no extra cost &mdash; enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability.</p>\r\n            </div>\r\n            <div style=\"margin-top: 25px; position: relative; z-index: 2;\">\r\n              <a href=\"second-course-sponsorship.html\" class=\"btn btn-primary\" style=\"background: var(--o); border-color: var(--o); color: #F5F0E8; text-transform: uppercase; font-size: 14px; font-weight: bold; letter-spacing: 1px; padding: 12px 24px;\"><i data-lucide=\"arrow-right\"></i> Learn More About Sponsorship</a>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a <strong>Two (2) month</strong> hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Professional Caregiver</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Care Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Care Technician</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Nursing Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Home-Based Care Provider</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Medical Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Support Worker in diverse healthcare settings</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to a wide range of healthcare support roles locally and internationally.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 20px;\">\r\n              <div style=\"background: #f9fafb; padding: 24px; border-radius: 12px; border: 1px solid #e5e7eb;\">\r\n                <h4 style=\"color: var(--o); margin-bottom: 8px;\">Option 1: Apply Online</h4>\r\n                <p style=\"margin: 0; font-size: 0.95rem;\">Submit your application through the official <a href=\"../apply.html\" style=\"color: var(--o); font-weight: 600;\">GoCare Online Application Form</a>.</p>\r\n              </div>\r\n              <div style=\"background: #f9fafb; padding: 24px; border-radius: 12px; border: 1px solid #e5e7eb;\">\r\n                <h4 style=\"color: var(--o); margin-bottom: 8px;\">Option 2: Visit Any Campus</h4>\r\n                <p style=\"margin: 0; font-size: 0.95rem;\">Our admissions team will guide you. Call: <a href=\"tel:+254703115502\" style=\"color: var(--o); font-weight: 600;\">0703 115 502</a></p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">8 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Entry Requirements</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KCSE Certificate (Any Grade)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Study Mode</span>\r\n                <strong style=\"color: var(--dark); display: block;\">Day / Online / Evening / Saturday</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.5;\">Academic Transcripts<br>TVET CDACC Certificate<br>GoCare Completion Certificate<br>SDC Canada Int\'l Cert<br><span style=\"font-size: 12px; color: var(--gray);\">(Adv. HCA or CNA &mdash; your choice)</span></strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a certified and globally recognized Caregiver / Advanced Health Care Assistant / CNA.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Caregiving – Level 4 is a comprehensive, competency-based program that prepares learners to become advanced healthcare assistants and professional caregivers capable of delivering safe, compassionate, and supportive patient care across hospitals, clinics, nursing homes, hospices, and home-based care environments. Learners acquire essential caregiving skills, patient-handling techniques, infection-control practices, communication competencies, and supportive nursing procedures required in modern healthcare settings. Students are trained to work under and alongside nurses, doctors, and allied health professionals, ensuring comfort, dignity, and quality service delivery for patients. Graduates emerge as confident, job-ready healthcare support professionals with strong employability both locally and internationally. This nationally recognized Level 4 qualification provides a strong entry point into more advanced healthcare professions and serves as a direct pathway to the Kenya Health Professions Oversight Authority (KHPOA) licensed Healthcare Support Services – Level 5 (CNA).\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national caregiving and healthcare support standards. 3 Hands-on clinical training with real patient exposure in hospitals, clinics, nursing homes, and home-based care settings. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 International certification options (SDC Canada, AMCA USA). 7 Clear progression pathway to the KHPOA licensed Certificate in Healthcare Support Services – Level 5 (CNA). 8 Training delivered by qualified nurses, clinicians, and professional caregivers. 9 Modern skills-lab and simulation-based training for patient care, vital signs, mobility assistance, infection control, and homecare procedures. 10 Flexible study modes (Day, Online, Evening, Saturday). 11 High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, hospices, and community health programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Certificate (Any Grade)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"\", \"heading\": \"What You Will Learn\"}, {\"body\": \"First Aid & Emergency Response Healthcare Housekeeping & Hygiene Client Dietary Support & Nutrition Care Psychosocial Support for Patients Pre-Departure & Patient Transfer Procedures Caregiving Catering & Meal Support Special Needs Care Support\", \"heading\": \"Units of Competence\"}, {\"body\": \"Introduction to Caregiving and the Fundamental Skills of Caregiving Alzheimer’s, Dementia and Other Common Mental Health Disorders Care Infection Prevention and Control Home-Based Care Skills and Procedures Communicable and Non-Communicable Diseases and Common Health Conditions Introduction to the Hospital Layout and Procedures Special Offer\", \"heading\": \"Additional Institutional Competencies (GoCare Enhanced Training)\"}, {\"body\": \"Enrol for this Certificate in Caregiving – Level 4 course and receive a fully sponsored international training and certification in an additional program. This offer includes a second free course, giving every student access to internationally accredited training and certification for either the Advanced Health Care Assistant or Certified Nursing Assistant (CNA) program, depending on your preference. You pay for one course, and GoCare Training Institute sponsors and trains you in the second complimentary course at no extra cost — enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability. Learn More About Sponsorship\", \"heading\": \"Second Course Sponsorship\"}, {\"body\": \"All learners undertake a Two (2) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates can work as: Professional Caregiver Health Care Assistant Patient Attendant Patient Care Technician Nursing Assistant Home-Based Care Provider Medical Receptionist Support Worker in diverse healthcare settings This qualification opens doors to a wide range of healthcare support roles locally and internationally.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"\", \"heading\": \"How to Apply\"}, {\"body\": \"Submit your application through the official GoCare Online Application Form.\", \"heading\": \"Option 1: Apply Online\"}, {\"body\": \"Our admissions team will guide you. Call: 0703 115 502 Total Duration 8 Months Apply Online Contact Admissions Entry Requirements KCSE Certificate (Any Grade) Study Mode Day / Online / Evening / Saturday Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic TranscriptsTVET CDACC CertificateGoCare Completion CertificateSDC Canada Int\'l Cert(Adv. HCA or CNA — your choice)\", \"heading\": \"Option 2: Visit Any Campus\"}, {\"body\": \"Start your journey toward becoming a certified and globally recognized Caregiver / Advanced Health Care Assistant / CNA. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(8, 'Certificate in Community-Based Services Level 4 | GoCare Training Institute', 'certificate-in-community-based-services-level-4', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\">\r\n        <div class=\"course-body\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Certificate in Community-Based Services &ndash; Level 4 is a comprehensive, competency-based program that prepares learners to deliver safe, compassionate, and supportive community-based services across various environments.</p>\r\n            <p>Learners acquire essential skills in community health, communication competencies, and supportive procedures required in modern community settings. Graduates emerge as confident, job-ready professionals with strong employability both locally and internationally.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 16px; margin-top: 20px;\">\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">1</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">2</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Competency-based TVET CDACC curriculum aligned with national caregiving and healthcare support standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">3</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Hands-on clinical training with real patient exposure in hospitals, clinics, nursing homes, and home-based care settings.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">4</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">5</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">6</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">International certification options (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">7</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Clear progression pathway to the KHPOA licensed Certificate in Healthcare Support Services &ndash; Level 5 (CNA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">8</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Training delivered by qualified nurses, clinicians, and professional caregivers.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">9</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Modern skills-lab and simulation-based training for patient care, vital signs, mobility assistance, infection control, and homecare procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">10</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 16px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; min-width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px;\">11</div>\r\n                <p style=\"margin: 0; line-height: 1.6;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, hospices, and community health programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div style=\"display: flex; align-items: center; gap: 14px; background: #f9fafb; padding: 18px 24px; border-radius: 12px; border: 1px solid #e5e7eb; margin-top: 16px;\">\r\n              <i data-lucide=\"file-text\" style=\"color: var(--o); width: 28px; height: 28px; flex-shrink: 0;\"></i>\r\n              <p style=\"margin: 0; font-weight: 600; font-size: 1rem; color: var(--dark);\">KCSE Certificate (Any Grade)</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <h3 style=\"font-size: 1.1rem; color: var(--dark); margin-bottom: 16px; font-weight: 700;\">Units of Competence</h3>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> First Aid &amp; Emergency Response</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Healthcare Housekeeping &amp; Hygiene</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Client Dietary Support &amp; Nutrition Care</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Psychosocial Support for Patients</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Pre-Departure &amp; Patient Transfer Procedures</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Caregiving Catering &amp; Meal Support</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Special Needs Care Support</li>\r\n              </ul>\r\n            </div>\r\n\r\n            <h3 style=\"font-size: 1.1rem; color: var(--dark); margin: 30px 0 16px; font-weight: 700;\">Additional Institutional Competencies (GoCare Enhanced Training)</h3>\r\n            <div style=\"background: #fff7ed; padding: 24px; border-radius: 12px; border: 1px solid #fed7aa;\">\r\n              <ul style=\"list-style: none; padding: 0; margin: 0; display: grid; gap: 12px;\">\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Introduction to Caregiving and the Fundamental Skills of Caregiving</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Alzheimer&rsquo;s, Dementia and Other Common Mental Health Disorders Care</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Infection Prevention and Control</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Home-Based Care Skills and Procedures</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Communicable and Non-Communicable Diseases and Common Health Conditions</li>\r\n                <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 20px;\"></i> Introduction to the Hospital Layout and Procedures</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          \r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a <strong>Two (2) month</strong> hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Service Worker</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Outreach Coordinator</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Social Services Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Promotor</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to a wide range of community and social support roles.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 20px;\">\r\n              <div style=\"background: #f9fafb; padding: 24px; border-radius: 12px; border: 1px solid #e5e7eb;\">\r\n                <h4 style=\"color: var(--o); margin-bottom: 8px;\">Option 1: Apply Online</h4>\r\n                <p style=\"margin: 0; font-size: 0.95rem;\">Submit your application through the official <a href=\"../apply.html\" style=\"color: var(--o); font-weight: 600;\">GoCare Online Application Form</a>.</p>\r\n              </div>\r\n              <div style=\"background: #f9fafb; padding: 24px; border-radius: 12px; border: 1px solid #e5e7eb;\">\r\n                <h4 style=\"color: var(--o); margin-bottom: 8px;\">Option 2: Visit Any Campus</h4>\r\n                <p style=\"margin: 0; font-size: 0.95rem;\">Our admissions team will guide you. Call: <a href=\"tel:+254703115502\" style=\"color: var(--o); font-weight: 600;\">0703 115 502</a></p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">8 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            \r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Entry Requirements</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KCSE Certificate (Any Grade)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Duration</span>\r\n                <strong style=\"color: var(--dark); display: block;\">Eight (8) Months (2 Terms) Tuition Duration and Two (2) Months Hospital Attachment</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Intakes</span>\r\n                <strong style=\"color: var(--dark); display: block;\">January, May, September</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Examination Body</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">Kenya Health Professions Oversight Authority (KHPOA)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.5;\">&bull; Academic Transcripts<br>&bull; TVET CDACC Certificate<br>&bull; GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a certified and globally recognized Caregiver / Advanced Health Care Assistant / CNA.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Community-Based Services – Level 4 is a comprehensive, competency-based program that prepares learners to deliver safe, compassionate, and supportive community-based services across various environments. Learners acquire essential skills in community health, communication competencies, and supportive procedures required in modern community settings. Graduates emerge as confident, job-ready professionals with strong employability both locally and internationally.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national caregiving and healthcare support standards. 3 Hands-on clinical training with real patient exposure in hospitals, clinics, nursing homes, and home-based care settings. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 International certification options (SDC Canada, AMCA USA). 7 Clear progression pathway to the KHPOA licensed Certificate in Healthcare Support Services – Level 5 (CNA). 8 Training delivered by qualified nurses, clinicians, and professional caregivers. 9 Modern skills-lab and simulation-based training for patient care, vital signs, mobility assistance, infection control, and homecare procedures. 10 Flexible study modes (Day, Online, Evening, Saturday). 11 High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, hospices, and community health programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Certificate (Any Grade)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"\", \"heading\": \"What You Will Learn\"}, {\"body\": \"First Aid & Emergency Response Healthcare Housekeeping & Hygiene Client Dietary Support & Nutrition Care Psychosocial Support for Patients Pre-Departure & Patient Transfer Procedures Caregiving Catering & Meal Support Special Needs Care Support\", \"heading\": \"Units of Competence\"}, {\"body\": \"Introduction to Caregiving and the Fundamental Skills of Caregiving Alzheimer’s, Dementia and Other Common Mental Health Disorders Care Infection Prevention and Control Home-Based Care Skills and Procedures Communicable and Non-Communicable Diseases and Common Health Conditions Introduction to the Hospital Layout and Procedures\", \"heading\": \"Additional Institutional Competencies (GoCare Enhanced Training)\"}, {\"body\": \"All learners undertake a Two (2) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates can work as: Community Service Worker Outreach Coordinator Social Services Assistant Community Health Promotor This qualification opens doors to a wide range of community and social support roles.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"\", \"heading\": \"How to Apply\"}, {\"body\": \"Submit your application through the official GoCare Online Application Form.\", \"heading\": \"Option 1: Apply Online\"}, {\"body\": \"Our admissions team will guide you. Call: 0703 115 502 Total Duration 8 Months Apply Online Contact Admissions Entry Requirements KCSE Certificate (Any Grade) Duration Eight (8) Months (2 Terms) Tuition Duration and Two (2) Months Hospital Attachment Intakes January, May, September Examination Body TVET CDACC Practicing License Kenya Health Professions Oversight Authority (KHPOA) Certificates Awarded • Academic Transcripts• TVET CDACC Certificate• GoCare Completion Certificate\", \"heading\": \"Option 2: Visit Any Campus\"}, {\"body\": \"Start your journey toward becoming a certified and globally recognized Caregiver / Advanced Health Care Assistant / CNA. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(9, 'Certificate in Community Health Assistant ? Level 5 – GoCare Training Institute', 'certificate-in-community-health-assistant-level-5', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Community Health Assistant &ndash; Level 5</strong> is a foundational, competency-based program designed to equip learners with essential knowledge and practical skills for supporting community health initiatives across diverse settings.</p>\r\n            <p>The program prepares trainees to work directly with communities, households, and health facilities in promoting preventive healthcare, health education, disease prevention, maternal and child health support, and community-based health interventions.</p>\r\n            <p>Learners gain hands-on experience through structured practical sessions and supervised hospital/community attachments, enabling them to confidently support public health programs, community health units, NGOs, and government health departments.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This KHPOA-licensed Level 5 qualification also provides a direct progression pathway to the Diploma in Community Health Assistant &ndash; Level 6.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national community health standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on clinical and community-based training with real field exposure in households, facilities, and community units.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed attachment placement in accredited hospitals, health centres, NGOs, and community health programs.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified community health, public health, and primary healthcare professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for health promotion, disease prevention, community diagnosis, and household health support.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">High employability across hospitals, NGOs, community health programs, public health projects, and primary healthcare facilities.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade D+ (Plus) and above <span style=\"font-weight:normal; color: var(--gray);\">or</span></p>\r\n                  <p style=\"margin: 5px 0 0 0; font-size: 16px; color: var(--dark); font-weight: 600;\">Related Level 4 Certificate</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurship Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Nutrition in Community Health</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Microbiology and Parasitology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Epidemiology in Community Health</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Information Systems</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Maternal, Newborn and Child Health Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Promotion Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Strategies</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Linkages</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community-Based Health Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Gender, Disability and Vulnerable Groups</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Diagnosis and Partnership</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a 3-month hospital or community health attachment in accredited facilities. GoCare provides full placement support to ensure every student gains real-world practical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate In Community Health Assistant &ndash; Level 5 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"heart\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community health programs</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"landmark\" style=\"color: var(--o); flex-shrink: 0;\"></i> Government and county health departments</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"globe\" style=\"color: var(--o); flex-shrink: 0;\"></i> NGOs and international development agencies</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals and medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"map\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public health outreach programs</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"users\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community health units and CHV programs</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Educator</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public Health Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Volunteer</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Maternal &amp; Child Health Worker</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Promotion Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Outreach Support Worker</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts<br>TVET CDACC Certificate<br>GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts and become a licensed Community Health Assistant.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Community Health Assistant – Level 5 is a foundational, competency-based program designed to equip learners with essential knowledge and practical skills for supporting community health initiatives across diverse settings. The program prepares trainees to work directly with communities, households, and health facilities in promoting preventive healthcare, health education, disease prevention, maternal and child health support, and community-based health interventions. Learners gain hands-on experience through structured practical sessions and supervised hospital/community attachments, enabling them to confidently support public health programs, community health units, NGOs, and government health departments. This KHPOA-licensed Level 5 qualification also provides a direct progression pathway to the Diploma in Community Health Assistant – Level 6.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national community health standards. 3 Hands-on clinical and community-based training with real field exposure in households, facilities, and community units. 4 Guaranteed attachment placement in accredited hospitals, health centres, NGOs, and community health programs. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Training delivered by qualified community health, public health, and primary healthcare professionals. 8 Modern skills-lab and simulation-based training for health promotion, disease prevention, community diagnosis, and household health support. 9 Flexible study modes. 10 High employability across hospitals, NGOs, community health programs, public health projects, and primary healthcare facilities.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade D+ (Plus) and above or Related Level 4 Certificate\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics and Professional Conduct Entrepreneurship Skills Nutrition in Community Health Microbiology and Parasitology Human Anatomy and Physiology Epidemiology in Community Health Community Health Information Systems Maternal, Newborn and Child Health Care Community Health Promotion Services Community Health Strategies Community Health Linkages Community-Based Health Care Gender, Disability and Vulnerable Groups Community Health Diagnosis and Partnership\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a 3-month hospital or community health attachment in accredited facilities. GoCare provides full placement support to ensure every student gains real-world practical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate In Community Health Assistant – Level 5 can work in: Community health programs Government and county health departments NGOs and international development agencies Hospitals and medical centres Public health outreach programs Community health units and CHV programs Job roles include: Community Health Assistant Community Health Educator Public Health Assistant Community Health Volunteer Maternal & Child Health Worker Health Promotion Assistant Community Outreach Support Worker Total Duration 1½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic TranscriptsTVET CDACC CertificateGoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts and become a licensed Community Health Assistant. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(10, 'Certificate in Food and Beverage Production (Culinary Arts) ? Level 3 – GoCare Training Institute', 'certificate-in-food-and-beverage-production-culinary-arts-level-3', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Food &amp; Beverage Production (Culinary Arts) &ndash; Level 3</strong> is a practical, competency-based program designed to equip learners with foundational culinary skills for professional kitchen environments.</p>\r\n            <p>The course prepares trainees to work confidently in hotels, restaurants, catering establishments, bakeries, food production facilities, and hospitality institutions.</p>\r\n            <p>Learners gain hands-on experience in food preparation, cooking techniques, kitchen safety, hygiene, workstation organization, and production of starters, main dishes, and desserts.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This Level 3 qualification provides a strong entry point into the hospitality industry and serves as a pathway to advanced culinary programs.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed hospitality training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with industry standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training in real kitchen environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed industrial attachment placement.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Highly employable skills for local and international hospitality markets.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Strong progression pathway to higher-level culinary and hospitality programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCPE or KCSE Certificate (Any Grade)</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            \r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h3 style=\"color: var(--dark); font-size: 18px; margin-bottom: 15px; display: flex; align-items: center; gap: 10px;\"><span style=\"background: var(--o); color: #F5F0E8; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 14px;\">1</span> Starters &amp; Accompaniments Preparation</h3>\r\n              <div style=\"background: #f8fafc; padding: 20px; border-radius: 8px;\">\r\n                <ul style=\"list-style: none; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Cold starters</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Hot starters</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Starter accompaniments</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Kitchen tools, equipment &amp; hygiene</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Food safety and HACCP principles</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n\r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h3 style=\"color: var(--dark); font-size: 18px; margin-bottom: 15px; display: flex; align-items: center; gap: 10px;\"><span style=\"background: var(--o); color: #F5F0E8; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 14px;\">2</span> Main Meal Preparation</h3>\r\n              <div style=\"background: #f8fafc; padding: 20px; border-radius: 8px;\">\r\n                <ul style=\"list-style: none; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Protein dishes</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Starch dishes</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Vegetable dishes</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Breakfast items</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Standard recipes, portioning &amp; presentation</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n\r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h3 style=\"color: var(--dark); font-size: 18px; margin-bottom: 15px; display: flex; align-items: center; gap: 10px;\"><span style=\"background: var(--o); color: #F5F0E8; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 14px;\">3</span> Desserts Preparation</h3>\r\n              <div style=\"background: #f8fafc; padding: 20px; border-radius: 8px;\">\r\n                <ul style=\"list-style: none; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Hot and cold desserts</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Pastry basics</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Dessert sauces</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Plating and garnishing techniques</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a two (2) month attachment in:</p>\r\n            <ul style=\"list-style: none; padding: 0; margin-top: 15px; display: flex; flex-wrap: wrap; gap: 20px;\">\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"hotel\" style=\"color: var(--o);\"></i> Hotels</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"utensils\" style=\"color: var(--o);\"></i> Restaurants</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"coffee\" style=\"color: var(--o);\"></i> Catering companies</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"chef-hat\" style=\"color: var(--o);\"></i> Food production facilities</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o);\"></i> Hospitality institutions</li>\r\n            </ul>\r\n            <p style=\"margin-top: 15px;\">GoCare provides full placement support to ensure every student gains real industry experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Food &amp; Beverage Production (Culinary Arts) &ndash; Level 3 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Assistant Cook</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Food Production Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Kitchen Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Commis Chef</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Catering Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Pastry/Cold Kitchen Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Food &amp; Beverage Production Staff</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in the hospitality and culinary industry.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts<br>TVET CDACC Certificate<br>GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a skilled, industry-ready culinary professional.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Food & Beverage Production (Culinary Arts) – Level 3 is a practical, competency-based program designed to equip learners with foundational culinary skills for professional kitchen environments. The course prepares trainees to work confidently in hotels, restaurants, catering establishments, bakeries, food production facilities, and hospitality institutions. Learners gain hands-on experience in food preparation, cooking techniques, kitchen safety, hygiene, workstation organization, and production of starters, main dishes, and desserts. This Level 3 qualification provides a strong entry point into the hospitality industry and serves as a pathway to advanced culinary programs.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed hospitality training institution. 2 Competency-based TVET CDACC curriculum aligned with industry standards. 3 Hands-on practical training in real kitchen environments. 4 Guaranteed industrial attachment placement. 5 Highly employable skills for local and international hospitality markets. 6 Flexible study modes. 7 Strong progression pathway to higher-level culinary and hospitality programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCPE or KCSE Certificate (Any Grade)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"\", \"heading\": \"What You Will Learn\"}, {\"body\": \"Cold starters Hot starters Starter accompaniments Kitchen tools, equipment & hygiene Food safety and HACCP principles\", \"heading\": \"1 Starters & Accompaniments Preparation\"}, {\"body\": \"Protein dishes Starch dishes Vegetable dishes Breakfast items Standard recipes, portioning & presentation\", \"heading\": \"2 Main Meal Preparation\"}, {\"body\": \"Hot and cold desserts Pastry basics Dessert sauces Plating and garnishing techniques\", \"heading\": \"3 Desserts Preparation\"}, {\"body\": \"All learners undertake a two (2) month attachment in: Hotels Restaurants Catering companies Food production facilities Hospitality institutions GoCare provides full placement support to ensure every student gains real industry experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Food & Beverage Production (Culinary Arts) – Level 3 can work as: Assistant Cook Food Production Assistant Kitchen Assistant Commis Chef Catering Assistant Pastry/Cold Kitchen Assistant Food & Beverage Production Staff This qualification opens doors to diverse opportunities in the hospitality and culinary industry. Total Duration 3 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic TranscriptsTVET CDACC CertificateGoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a skilled, industry-ready culinary professional. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(11, 'Certificate in Front Office Operations ? Level 3 – GoCare Training Institute', 'certificate-in-front-office-operations-level-3', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Front Office Operations &ndash; Level 3</strong> is a foundational, competency-based program that equips learners with the essential skills required to work professionally in hotel front offices, hospitality establishments, corporate reception areas, and customer-facing administrative environments.</p>\r\n            <p>Learners gain practical competencies in guest relations, front desk procedures, reservations, communication, customer service, check-in and check-out processes, records management, and handling guest inquiries. The course also trains students to apply workplace etiquette, digital literacy, and service excellence standards expected in modern hospitality and corporate settings.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized Level 3 qualification provides a strong entry point into the hospitality industry and serves as a pathway to advanced programs in Front Office Operations, Hospitality Management, and related fields.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed hospitality training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with industry standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training in real hospitality and corporate environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed industrial attachment placement.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulatory recognized qualifications and certification.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">High employability in hotels, resorts, corporate offices, and service organizations.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Strong progression pathway to higher-level hospitality programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCPE or KCSE Certificate (Any Grade)</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            \r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h3 style=\"color: var(--dark); font-size: 18px; margin-bottom: 15px; display: flex; align-items: center; gap: 10px;\"><span style=\"background: var(--o); color: #F5F0E8; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 14px;\">1</span> Basic Guest Relations Services</h3>\r\n              <div style=\"background: #f8fafc; padding: 20px; border-radius: 8px;\">\r\n                <ul style=\"list-style: none; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Guest welcoming and orientation</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Customer service etiquette</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Handling guest inquiries and complaints</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication skills and interpersonal relations</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Professional grooming and workplace behavior</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n\r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h3 style=\"color: var(--dark); font-size: 18px; margin-bottom: 15px; display: flex; align-items: center; gap: 10px;\"><span style=\"background: var(--o); color: #F5F0E8; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 14px;\">2</span> Front Desk Operations</h3>\r\n              <div style=\"background: #f8fafc; padding: 20px; border-radius: 8px;\">\r\n                <ul style=\"list-style: none; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Reception procedures</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Check-in and check-out processes</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Reservations and booking systems</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Records management and documentation</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Telephone operations and switchboard handling</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Use of digital tools and office equipment</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n\r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h3 style=\"color: var(--dark); font-size: 18px; margin-bottom: 15px; display: flex; align-items: center; gap: 10px;\"><span style=\"background: var(--o); color: #F5F0E8; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 14px;\">3</span> Porterage &amp; Support Services</h3>\r\n              <div style=\"background: #f8fafc; padding: 20px; border-radius: 8px;\">\r\n                <ul style=\"list-style: none; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Guest luggage handling</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Escorting guests</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Safety and security procedures</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Workplace hygiene and organization</li>\r\n                  <li style=\"display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Coordination with other hotel departments</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a two (2) month attachment in:</p>\r\n            <ul style=\"list-style: none; padding: 0; margin-top: 15px; display: flex; flex-wrap: wrap; gap: 20px;\">\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"hotel\" style=\"color: var(--o);\"></i> Hotels &amp; Resorts</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o);\"></i> Corporate Offices</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"coffee\" style=\"color: var(--o);\"></i> Hospitality Establishments</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"users\" style=\"color: var(--o);\"></i> Customer Service Centers</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"plane\" style=\"color: var(--o);\"></i> Travel &amp; Tourism Facilities</li>\r\n            </ul>\r\n            <p style=\"margin-top: 15px;\">GoCare provides full placement support to ensure every student gains real industry experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Front Office Operations &ndash; Level 3 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Front Office Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Guest Relations Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Customer Service Representative</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Reservations Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Administrative Support Staff</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hotel Front Desk Attendant</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in hospitality, tourism, and corporate service environments.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts<br>TVET CDACC Certificate<br>GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a skilled, industry-ready Front Office Professional.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Front Office Operations – Level 3 is a foundational, competency-based program that equips learners with the essential skills required to work professionally in hotel front offices, hospitality establishments, corporate reception areas, and customer-facing administrative environments. Learners gain practical competencies in guest relations, front desk procedures, reservations, communication, customer service, check-in and check-out processes, records management, and handling guest inquiries. The course also trains students to apply workplace etiquette, digital literacy, and service excellence standards expected in modern hospitality and corporate settings. This nationally recognized Level 3 qualification provides a strong entry point into the hospitality industry and serves as a pathway to advanced programs in Front Office Operations, Hospitality Management, and related fields.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed hospitality training institution. 2 Competency-based TVET CDACC curriculum aligned with industry standards. 3 Hands-on practical training in real hospitality and corporate environments. 4 Guaranteed industrial attachment placement. 5 Government and regulatory recognized qualifications and certification. 6 High employability in hotels, resorts, corporate offices, and service organizations. 7 Flexible study modes. 8 Strong progression pathway to higher-level hospitality programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCPE or KCSE Certificate (Any Grade)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"\", \"heading\": \"What You Will Learn\"}, {\"body\": \"Guest welcoming and orientation Customer service etiquette Handling guest inquiries and complaints Communication skills and interpersonal relations Professional grooming and workplace behavior\", \"heading\": \"1 Basic Guest Relations Services\"}, {\"body\": \"Reception procedures Check-in and check-out processes Reservations and booking systems Records management and documentation Telephone operations and switchboard handling Use of digital tools and office equipment\", \"heading\": \"2 Front Desk Operations\"}, {\"body\": \"Guest luggage handling Escorting guests Safety and security procedures Workplace hygiene and organization Coordination with other hotel departments\", \"heading\": \"3 Porterage & Support Services\"}, {\"body\": \"All learners undertake a two (2) month attachment in: Hotels & Resorts Corporate Offices Hospitality Establishments Customer Service Centers Travel & Tourism Facilities GoCare provides full placement support to ensure every student gains real industry experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Front Office Operations – Level 3 can work as: Front Office Assistant Receptionist Guest Relations Assistant Customer Service Representative Reservations Assistant Administrative Support Staff Hotel Front Desk Attendant This qualification opens doors to diverse opportunities in hospitality, tourism, and corporate service environments. Total Duration 3 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic TranscriptsTVET CDACC CertificateGoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a skilled, industry-ready Front Office Professional. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(12, 'Certificate in Health Care Assistant (HCA) – GoCare Training Institute', 'certificate-in-health-care-assistant-hca', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 24px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Health Care Assistant (HCA)</strong> is a foundational, competency-based program that prepares learners to become Health Care Assistants, Home-Based Care Support Assistants, Caregivers, Patient Attendants, and Nursing Assistants capable of delivering safe, compassionate, and supportive care in homes, hospitals, clinics, nursing facilities, and community health environments.</p>\r\n            <p>Learners acquire essential skills in patient hygiene, feeding, mobility assistance, repositioning, communication, safety, and supportive care procedures. The course also trains students to observe and report patient concerns to nurses and other healthcare professionals, ensuring continuity of care and patient safety.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 10px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized HCA qualification provides a strong entry point into the healthcare profession and serves as a direct pathway to advanced programs such as Caregiving Level 4 and Healthcare Support Services Level 5 (CNA).</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 14px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national home-based care and healthcare support standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training with real patient exposure in hospitals, clinics, and home-based care environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">International certification options (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Clear progression pathway to Certificate in Caregiving &ndash; Level 4 and Healthcare Support Services &ndash; Level 5 (CNA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified nurses, clinicians, and professional caregivers.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for hygiene care, feeding, mobility assistance, vital signs, and home-based care procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">11</div>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and private home-based care.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 14px; background: #fcfcfc; padding: 16px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCPE or KCSE Certificate (Any Grade)</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 10px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr; gap: 10px; background: #f8fafc; padding: 16px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Healthcare Housekeeping &amp; Hygiene</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Client Dietary Support &amp; Nutrition Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Support for Clients</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Pre-Departure &amp; Patient Transfer Procedures</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <h3 style=\"color: var(--dark); margin-top: 10px; margin-bottom: 20px; font-size: 20px;\">Additional Institutional Competencies (GoCare Enhanced Training)</h3>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); padding: 16px; border-radius: 8px; border-left: 4px solid var(--o);\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Introduction to Caregiving and the Fundamental Skills of Caregiving</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Alzheimer&#8217;s, Dementia and Other Common Mental Health Disorders Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Infection Prevention and Control</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Home-Based Care Skills and Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communicable and Non-Communicable Diseases and Common Health Conditions</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Introduction to the Hospital Layout and Procedures</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"special-offer\" style=\"margin-top: 10px; background: linear-gradient(135deg, var(--dark), #2d184a); color: #F5F0E8; padding: 32px 40px; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.15); position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -50px; right: -50px; width: 200px; height: 200px; background: var(--o); opacity: 0.2; border-radius: 50%;\"></div>\r\n            <h2 style=\"color: #F5F0E8; font-size: 28px; margin-bottom: 10px; position: relative; z-index: 2; display: flex; align-items: center; gap: 15px;\"><i data-lucide=\"gift\" style=\"color: var(--o); width: 32px; height: 32px;\"></i> Second Course Sponsorship (Special Offer)</h2>\r\n            <p style=\"font-size: 16px; line-height: 1.6; position: relative; z-index: 2; margin-bottom: 15px; color: #fff; opacity: 1;\">Enrol for this Health Care Assistant (HCA) course and receive a fully sponsored international training and certification in an additional program.</p>\r\n            <p style=\"font-size: 16px; line-height: 1.6; position: relative; z-index: 2; margin-bottom: 15px; color: #fff; opacity: 1;\">This offer includes a second free course, giving every student access to internationally accredited training and certification in a complementary program aligned to your healthcare career pathway.</p>\r\n            <div style=\"background: rgba(255,255,255,0.15); padding: 20px; border-radius: 8px; border-left: 4px solid var(--o); margin-top: 10px; position: relative; z-index: 2;\">\r\n              <p style=\"margin: 0; font-weight: 500; font-size: 16px; color: #fff;\">You pay for one course, and GoCare sponsors and trains you in the second complimentary course at no extra cost &ndash; enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability.</p>\r\n            </div>\r\n            <div style=\"margin-top: 14px; position: relative; z-index: 2;\">\r\n              <a href=\"second-course-sponsorship.html\" class=\"btn btn-primary\" style=\"background: var(--o); border-color: var(--o); color: #F5F0E8; text-transform: uppercase; font-size: 14px; font-weight: bold; letter-spacing: 1px; padding: 12px 24px;\"><i data-lucide=\"arrow-right\"></i> Learn More About Sponsorship</a>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 10px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a two (2) month attachment in:</p>\r\n            <ul style=\"list-style: none; padding: 0; margin-top: 8px; display: flex; flex-wrap: wrap; gap: 20px;\">\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o);\"></i> Hospitals</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"activity\" style=\"color: var(--o);\"></i> Clinics</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o);\"></i> Nursing homes</li>\r\n              <li style=\"display: flex; gap: 10px;\"><i data-lucide=\"home\" style=\"color: var(--o);\"></i> Home-based care agencies</li>\r\n            </ul>\r\n            <p style=\"margin-top: 8px;\">GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 14px; border-top: 1px solid #e2e8f0; padding-top: 16px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Health Care Assistant (HCA) can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> HealthCare Assistant (HCA)</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Professional Caregiver</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Care Technician</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Medical Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Home-Based Care Provider</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Certified Nursing Assistant &ndash; CNA</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Support Worker in diverse healthcare settings</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 8px; font-weight: 500; color: var(--dark);\">This qualification opens doors to a wide range of healthcare support roles locally and internationally.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 20px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 10px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts<br>TVET CDACC Certificate<br>GoCare Completion Certificate<br>SDC Canada Int\'l Cert (HCA)</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a certified and globally recognized HCA / Caregiver.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Health Care Assistant (HCA) is a foundational, competency-based program that prepares learners to become Health Care Assistants, Home-Based Care Support Assistants, Caregivers, Patient Attendants, and Nursing Assistants capable of delivering safe, compassionate, and supportive care in homes, hospitals, clinics, nursing facilities, and community health environments. Learners acquire essential skills in patient hygiene, feeding, mobility assistance, repositioning, communication, safety, and supportive care procedures. The course also trains students to observe and report patient concerns to nurses and other healthcare professionals, ensuring continuity of care and patient safety. This nationally recognized HCA qualification provides a strong entry point into the healthcare profession and serves as a direct pathway to advanced programs such as Caregiving Level 4 and Healthcare Support Services Level 5 (CNA).\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national home-based care and healthcare support standards. 3 Hands-on practical training with real patient exposure in hospitals, clinics, and home-based care environments. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 International certification options (SDC Canada, AMCA USA). 7 Clear progression pathway to Certificate in Caregiving – Level 4 and Healthcare Support Services – Level 5 (CNA). 8 Training delivered by qualified nurses, clinicians, and professional caregivers. 9 Modern skills-lab and simulation-based training for hygiene care, feeding, mobility assistance, vital signs, and home-based care procedures. 10 Flexible study modes (Day, Online, Evening, Saturday). 11 High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and private home-based care.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCPE or KCSE Certificate (Any Grade)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Healthcare Housekeeping & Hygiene Client Dietary Support & Nutrition Care Psychosocial Support for Clients Pre-Departure & Patient Transfer Procedures\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"Introduction to Caregiving and the Fundamental Skills of Caregiving Alzheimer’s, Dementia and Other Common Mental Health Disorders Care Infection Prevention and Control Home-Based Care Skills and Procedures Communicable and Non-Communicable Diseases and Common Health Conditions Introduction to the Hospital Layout and Procedures\", \"heading\": \"Additional Institutional Competencies (GoCare Enhanced Training)\"}, {\"body\": \"Enrol for this Health Care Assistant (HCA) course and receive a fully sponsored international training and certification in an additional program. This offer includes a second free course, giving every student access to internationally accredited training and certification in a complementary program aligned to your healthcare career pathway. You pay for one course, and GoCare sponsors and trains you in the second complimentary course at no extra cost – enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability. Learn More About Sponsorship\", \"heading\": \"Second Course Sponsorship (Special Offer)\"}, {\"body\": \"All learners undertake a two (2) month attachment in: Hospitals Clinics Nursing homes Home-based care agencies GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Health Care Assistant (HCA) can work as: HealthCare Assistant (HCA) Professional Caregiver Patient Attendant Patient Care Technician Medical Receptionist Home-Based Care Provider Certified Nursing Assistant – CNA Support Worker in diverse healthcare settings This qualification opens doors to a wide range of healthcare support roles locally and internationally. Total Duration 3 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic TranscriptsTVET CDACC CertificateGoCare Completion CertificateSDC Canada Int\'l Cert (HCA)\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a certified and globally recognized HCA / Caregiver. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(13, 'Certificate in Healthcare Support Services ? Level 5 (Certified Nursing Assistant) – GoCare Training Institute', 'certificate-in-healthcare-support-services-level-5-certified-nursing-assistant', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Healthcare Support Services &ndash; Level 5</strong> is a comprehensive, competency-based program that prepares learners to become licensed Healthcare Support Assistants / Certified Nursing Assistants (CNA) capable of delivering safe, compassionate, and professional patient care in hospitals, clinics, nursing homes, and home-based care environments.</p>\r\n            <p>Learners acquire essential clinical skills, patient-handling techniques, infection-control practices, communication competencies, and supportive nursing procedures required in modern healthcare settings. The program trains students to work alongside nurses, doctors, and allied health professionals, ensuring comfort, dignity, and quality service delivery.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">Graduates emerge as confident, job-ready healthcare professionals with strong employability both locally and internationally.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national healthcare support standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on clinical training with real patient exposure in hospitals, clinics, and long-term care facilities.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">International certification options (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified nurses, clinicians, and healthcare support professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for patient care, vital signs, infection control, and bedside procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">11</div>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and community health facilities.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade D (Plain) and above</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Professional Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics &amp; Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial &amp; Workplace Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> First Aid &amp; Emergency Response</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Medical Terminology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy &amp; Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Medical-Legal Ethics in Healthcare</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Common Diseases &amp; Infection Control Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Healthcare Housekeeping &amp; Hygiene</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Client Dietary Support &amp; Nutrition Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Support for Patients</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Pre-Departure &amp; Patient Transfer Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Caregiving Catering &amp; Meal Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Special Needs Care Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Health Facility Procedures &amp; Workflow</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Infection Prevention &amp; Control (IPC)</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Patient Care Support &amp; Bedside Assistance</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Hospital Store &amp; Inventory Procedures</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <h3 style=\"color: var(--dark); margin-top: 30px; margin-bottom: 20px; font-size: 20px;\">Additional Institutional Competencies (GoCare Enhanced Training)</h3>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); padding: 25px; border-radius: 8px; border-left: 4px solid var(--o);\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Introduction to Caregiving and the Fundamental Skills of Caregiving</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Alzheimer&#8217;s, Dementia and Other Common Mental Health Disorders Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Home-Based Care Skills and Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communicable and Non-Communicable Diseases and Common Health Conditions</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Introduction to the Hospital Layout and Procedures</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"special-offer\" style=\"margin-top: 50px; background: linear-gradient(135deg, var(--dark), #2d184a); color: #F5F0E8; padding: 40px; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.15); position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -50px; right: -50px; width: 200px; height: 200px; background: var(--o); opacity: 0.2; border-radius: 50%;\"></div>\r\n            <h2 style=\"color: #F5F0E8; font-size: 28px; margin-bottom: 15px; position: relative; z-index: 2; display: flex; align-items: center; gap: 15px;\"><i data-lucide=\"gift\" style=\"color: var(--o); width: 32px; height: 32px;\"></i> Second Course Sponsorship (Special Offer)</h2>\r\n            <p style=\"font-size: 16px; line-height: 1.6; position: relative; z-index: 2; margin-bottom: 15px;\">Enrol for this 1½ Years Healthcare Support Services &ndash; Level 5 Course and receive a fully sponsored international training and certification in an additional program.</p>\r\n            <p style=\"font-size: 16px; line-height: 1.6; position: relative; z-index: 2; margin-bottom: 15px;\">This offer includes a second free course, giving every student access to internationally accredited training and certification for the Certified Nursing Assistant (CNA) program.</p>\r\n            <div style=\"background: rgba(255,255,255,0.1); padding: 20px; border-radius: 8px; border-left: 4px solid var(--o); margin-top: 20px; position: relative; z-index: 2;\">\r\n              <p style=\"margin: 0; font-weight: 500; font-size: 16px; color: #F5F0E8;\">You pay for one course, and GoCare sponsors and trains you in the second complimentary course at no extra cost &ndash; enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability.</p>\r\n            </div>\r\n            <div style=\"margin-top: 25px; position: relative; z-index: 2;\">\r\n              <a href=\"second-course-sponsorship.html\" class=\"btn btn-primary\" style=\"background: var(--o); border-color: var(--o); color: #F5F0E8; text-transform: uppercase; font-size: 14px; font-weight: bold; letter-spacing: 1px; padding: 12px 24px;\"><i data-lucide=\"arrow-right\"></i> Learn More About Sponsorship</a>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a Three (3) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Healthcare Support Services &ndash; Level 5 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Nursing Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Medical Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Care Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Care Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Professional Caregiver</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Medical Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Unit Coordinator</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuary Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospital Store Officer</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Healthcare Support Services Assistant</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse healthcare roles locally and internationally.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts<br>TVET CDACC Certificate<br>SDC Canada Int\'l Cert (CNA)<br>GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a certified, licensed, and globally recognized CNA.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Healthcare Support Services – Level 5 is a comprehensive, competency-based program that prepares learners to become licensed Healthcare Support Assistants / Certified Nursing Assistants (CNA) capable of delivering safe, compassionate, and professional patient care in hospitals, clinics, nursing homes, and home-based care environments. Learners acquire essential clinical skills, patient-handling techniques, infection-control practices, communication competencies, and supportive nursing procedures required in modern healthcare settings. The program trains students to work alongside nurses, doctors, and allied health professionals, ensuring comfort, dignity, and quality service delivery. Graduates emerge as confident, job-ready healthcare professionals with strong employability both locally and internationally.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national healthcare support standards. 3 Hands-on clinical training with real patient exposure in hospitals, clinics, and long-term care facilities. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 International certification options (SDC Canada, AMCA USA). 7 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 8 Training delivered by qualified nurses, clinicians, and healthcare support professionals. 9 Modern skills-lab and simulation-based training for patient care, vital signs, infection control, and bedside procedures. 10 Flexible study modes (Day, Online, Evening, Saturday). 11 High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and community health facilities.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade D (Plain) and above\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Professional Communication Skills Work Ethics & Professional Conduct Entrepreneurial & Workplace Skills First Aid & Emergency Response Medical Terminology Human Anatomy & Physiology Medical-Legal Ethics in Healthcare Common Diseases & Infection Control Support Healthcare Housekeeping & Hygiene Client Dietary Support & Nutrition Care Psychosocial Support for Patients Pre-Departure & Patient Transfer Procedures Caregiving Catering & Meal Support Special Needs Care Support Health Facility Procedures & Workflow Infection Prevention & Control (IPC) Patient Care Support & Bedside Assistance Hospital Store & Inventory Procedures\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"Introduction to Caregiving and the Fundamental Skills of Caregiving Alzheimer’s, Dementia and Other Common Mental Health Disorders Care Home-Based Care Skills and Procedures Communicable and Non-Communicable Diseases and Common Health Conditions Introduction to the Hospital Layout and Procedures\", \"heading\": \"Additional Institutional Competencies (GoCare Enhanced Training)\"}, {\"body\": \"Enrol for this 1½ Years Healthcare Support Services – Level 5 Course and receive a fully sponsored international training and certification in an additional program. This offer includes a second free course, giving every student access to internationally accredited training and certification for the Certified Nursing Assistant (CNA) program. You pay for one course, and GoCare sponsors and trains you in the second complimentary course at no extra cost – enabling you to graduate with two qualifications, including an international certification, and significantly enhanced global employability. Learn More About Sponsorship\", \"heading\": \"Second Course Sponsorship (Special Offer)\"}, {\"body\": \"All learners undertake a Three (3) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Healthcare Support Services – Level 5 can work as: Nursing Assistant Medical Assistant Health Care Assistant Patient Attendant Patient Care Technician Professional Caregiver Medical Receptionist Health Unit Coordinator Mortuary Attendant Hospital Store Officer Healthcare Support Services Assistant This qualification opens doors to diverse healthcare roles locally and internationally. Total Duration 1½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic TranscriptsTVET CDACC CertificateSDC Canada Int\'l Cert (CNA)GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a certified, licensed, and globally recognized CNA. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(14, 'Certificate in Homecare Management – Level 3 – GoCare Training Institute', 'certificate-in-homecare-management-level-3', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\">\r\n        <div class=\"course-body\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Programme Overview</h2>\r\n            <p>The Health Care Assistant / Caregiver programme at GoCare Training Institute is designed to equip learners\r\n              with the practical skills and theoretical knowledge required to provide high-quality care to individuals\r\n              in various healthcare settings.</p>\r\n            <p>Our curriculum focuses on patient safety, personal hygiene, basic nursing care, and effective\r\n              communication. Graduates are highly sought after by hospitals and international agencies due to our\r\n              hands-on training approach in modern labs.</p>\r\n          </section>\r\n\r\n          <section class=\"modules-list\">\r\n            <h2 class=\"course-sec-title\">Certifications & Accreditation</h2>\r\n            \r\n            <div style=\"margin-bottom: 24px; display: flex; align-items: center; gap: 12px; background: #f9fafb; padding: 16px 24px; border-radius: 12px; border: 1px solid #e5e7eb;\">\r\n               <div style=\"background: #5E2390; color: #F5F0E8; width: 40px; height: 40px; border-radius: 8px; display: flex; align-items: center; justify-content: center;\"><i data-lucide=\"building\"></i></div>\r\n               <div>\r\n                  <span style=\"display: block; font-size: 0.8rem; color: #6b7280; text-transform: uppercase; letter-spacing: 1px; font-weight: 700;\">Examination Body</span>\r\n                  <strong style=\"color: #111827; font-size: 1.05rem;\">TVET CDACC</strong>\r\n               </div>\r\n            </div>\r\n            <h4 style=\"margin-top: 16px; margin-bottom: 12px; font-weight: 700; color: #374151;\">You will receive the following certificates:</h4>\r\n            \r\n            <div class=\"module-item\" style=\"padding: 16px 20px;\">\r\n              <div class=\"module-num\" style=\"width: 32px; height: 32px; font-size: 0.8rem;\">01</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin-bottom:0;\">Academic Transcripts</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"padding: 16px 20px;\">\r\n              <div class=\"module-num\" style=\"width: 32px; height: 32px; font-size: 0.8rem;\">02</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin-bottom:0;\">TVET CDACC Certificate</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"padding: 16px 20px;\">\r\n              <div class=\"module-num\" style=\"width: 32px; height: 32px; font-size: 0.8rem;\">03</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin-bottom:0;\">GoCare Completion Certificate</h4>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div style=\"background: #fcfcfc; padding: 24px; border-radius: 16px; margin-top: 16px; border: 1px solid #f3f4f6; display: flex; align-items: flex-start; gap: 16px;\">\r\n               <i data-lucide=\"check-circle-2\" style=\"color: #ec7424; width: 32px; height: 32px; flex-shrink: 0;\"></i>\r\n               <div>\r\n                  <strong style=\"display: block; font-size: 1.1rem; color: #111827; margin-bottom: 8px;\">Academic Qualification</strong>\r\n                  <p style=\"font-size: 0.95rem; color: #4b5563; line-height: 1.6;\">KCPE or KCSE Certificate (Any Grade)</p>\r\n               </div>\r\n            </div>\r\n            \r\n            <div style=\"background: #fcfcfc; padding: 24px; border-radius: 16px; margin-top: 16px; border: 1px solid #f3f4f6; display: flex; align-items: flex-start; gap: 16px;\">\r\n               <i data-lucide=\"clock\" style=\"color: #5E2390; width: 32px; height: 32px; flex-shrink: 0;\"></i>\r\n               <div>\r\n                  <strong style=\"display: block; font-size: 1.1rem; color: #111827; margin-bottom: 8px;\">Detailed Duration</strong>\r\n                  <p style=\"font-size: 0.95rem; color: #4b5563; line-height: 1.6;\">One (1) Term: Three (3) Months Tuition Duration and Two (2) Months Industrial Attachment</p>\r\n               </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n<aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-lucide=\"mail\" aria-hidden=\"true\" class=\"lucide lucide-mail\"><path d=\"m22 7-8.991 5.727a2 2 0 0 1-2.009 0L2 7\"></path><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"></rect></svg> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n \r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts, gain advanced mortuary skills, and become licensed.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-lucide=\"phone-call\" aria-hidden=\"true\" class=\"lucide lucide-phone-call\"><path d=\"M13 2a9 9 0 0 1 9 9\"></path><path d=\"M13 6a5 5 0 0 1 5 5\"></path><path d=\"M13.832 16.568a1 1 0 0 0 1.213-.303l.355-.465A2 2 0 0 1 17 15h3a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2A18 18 0 0 1 2 4a2 2 0 0 1 2-2h3a2 2 0 0 1 2 2v3a2 2 0 0 1-.8 1.6l-.468.351a1 1 0 0 0-.292 1.233 14 14 0 0 0 6.392 6.384\"></path></svg> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Health Care Assistant / Caregiver programme at GoCare Training Institute is designed to equip learners with the practical skills and theoretical knowledge required to provide high-quality care to individuals in various healthcare settings. Our curriculum focuses on patient safety, personal hygiene, basic nursing care, and effective communication. Graduates are highly sought after by hospitals and international agencies due to our hands-on training approach in modern labs.\", \"heading\": \"Programme Overview\"}, {\"body\": \"Examination Body TVET CDACC\", \"heading\": \"Certifications & Accreditation\"}, {\"body\": \"01\", \"heading\": \"You will receive the following certificates:\"}, {\"body\": \"02\", \"heading\": \"Academic Transcripts\"}, {\"body\": \"03\", \"heading\": \"TVET CDACC Certificate\"}, {\"body\": \"\", \"heading\": \"GoCare Completion Certificate\"}, {\"body\": \"Academic Qualification KCPE or KCSE Certificate (Any Grade) Detailed Duration One (1) Term: Three (3) Months Tuition Duration and Two (2) Months Industrial Attachment Total Duration 3 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Train with experts, gain advanced mortuary skills, and become licensed. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(15, 'Certificate in Homecare Management – Level 4 – GoCare Training Institute', 'certificate-in-homecare-management-level-4', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\">\r\n        <div class=\"course-body\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Programme Overview</h2>\r\n            <p>The Health Care Assistant / Caregiver programme at GoCare Training Institute is designed to equip learners\r\n              with the practical skills and theoretical knowledge required to provide high-quality care to individuals\r\n              in various healthcare settings.</p>\r\n            <p>Our curriculum focuses on patient safety, personal hygiene, basic nursing care, and effective\r\n              communication. Graduates are highly sought after by hospitals and international agencies due to our\r\n              hands-on training approach in modern labs.</p>\r\n          </section>\r\n\r\n          <section class=\"modules-list\">\r\n            <h2 class=\"course-sec-title\">Certifications & Accreditation</h2>\r\n            \r\n            <div style=\"margin-bottom: 24px; display: flex; align-items: center; gap: 12px; background: #f9fafb; padding: 16px 24px; border-radius: 12px; border: 1px solid #e5e7eb;\">\r\n               <div style=\"background: #5E2390; color: #F5F0E8; width: 40px; height: 40px; border-radius: 8px; display: flex; align-items: center; justify-content: center;\"><i data-lucide=\"building\"></i></div>\r\n               <div>\r\n                  <span style=\"display: block; font-size: 0.8rem; color: #6b7280; text-transform: uppercase; letter-spacing: 1px; font-weight: 700;\">Examination Body</span>\r\n                  <strong style=\"color: #111827; font-size: 1.05rem;\">TVET CDACC</strong>\r\n               </div>\r\n            </div>\r\n            <h4 style=\"margin-top: 16px; margin-bottom: 12px; font-weight: 700; color: #374151;\">You will receive the following certificates:</h4>\r\n            \r\n            <div class=\"module-item\" style=\"padding: 16px 20px;\">\r\n              <div class=\"module-num\" style=\"width: 32px; height: 32px; font-size: 0.8rem;\">01</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin-bottom:0;\">Academic Transcripts</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"padding: 16px 20px;\">\r\n              <div class=\"module-num\" style=\"width: 32px; height: 32px; font-size: 0.8rem;\">02</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin-bottom:0;\">TVET CDACC Certificate</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"padding: 16px 20px;\">\r\n              <div class=\"module-num\" style=\"width: 32px; height: 32px; font-size: 0.8rem;\">03</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin-bottom:0;\">GoCare Completion Certificate</h4>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div style=\"background: #fcfcfc; padding: 24px; border-radius: 16px; margin-top: 16px; border: 1px solid #f3f4f6; display: flex; align-items: flex-start; gap: 16px;\">\r\n               <i data-lucide=\"check-circle-2\" style=\"color: #ec7424; width: 32px; height: 32px; flex-shrink: 0;\"></i>\r\n               <div>\r\n                  <strong style=\"display: block; font-size: 1.1rem; color: #111827; margin-bottom: 8px;\">Academic Qualification</strong>\r\n                  <p style=\"font-size: 0.95rem; color: #4b5563; line-height: 1.6;\">KCSE Certificate (Any Grade) or Homecare Management Level 3 Qualification</p>\r\n               </div>\r\n            </div>\r\n            \r\n            <div style=\"background: #fcfcfc; padding: 24px; border-radius: 16px; margin-top: 16px; border: 1px solid #f3f4f6; display: flex; align-items: flex-start; gap: 16px;\">\r\n               <i data-lucide=\"clock\" style=\"color: #5E2390; width: 32px; height: 32px; flex-shrink: 0;\"></i>\r\n               <div>\r\n                  <strong style=\"display: block; font-size: 1.1rem; color: #111827; margin-bottom: 8px;\">Detailed Duration</strong>\r\n                  <p style=\"font-size: 0.95rem; color: #4b5563; line-height: 1.6;\">Eight (8) Months (2 Terms) Tuition Duration and Two (2) Months Industrial Field Attachment</p>\r\n               </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">8 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-lucide=\"mail\" aria-hidden=\"true\" class=\"lucide lucide-mail\"><path d=\"m22 7-8.991 5.727a2 2 0 0 1-2.009 0L2 7\"></path><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"></rect></svg> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              \r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts, gain advanced mortuary skills, and become licensed.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-lucide=\"phone-call\" aria-hidden=\"true\" class=\"lucide lucide-phone-call\"><path d=\"M13 2a9 9 0 0 1 9 9\"></path><path d=\"M13 6a5 5 0 0 1 5 5\"></path><path d=\"M13.832 16.568a1 1 0 0 0 1.213-.303l.355-.465A2 2 0 0 1 17 15h3a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2A18 18 0 0 1 2 4a2 2 0 0 1 2-2h3a2 2 0 0 1 2 2v3a2 2 0 0 1-.8 1.6l-.468.351a1 1 0 0 0-.292 1.233 14 14 0 0 0 6.392 6.384\"></path></svg> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Health Care Assistant / Caregiver programme at GoCare Training Institute is designed to equip learners with the practical skills and theoretical knowledge required to provide high-quality care to individuals in various healthcare settings. Our curriculum focuses on patient safety, personal hygiene, basic nursing care, and effective communication. Graduates are highly sought after by hospitals and international agencies due to our hands-on training approach in modern labs.\", \"heading\": \"Programme Overview\"}, {\"body\": \"Examination Body TVET CDACC\", \"heading\": \"Certifications & Accreditation\"}, {\"body\": \"01\", \"heading\": \"You will receive the following certificates:\"}, {\"body\": \"02\", \"heading\": \"Academic Transcripts\"}, {\"body\": \"03\", \"heading\": \"TVET CDACC Certificate\"}, {\"body\": \"\", \"heading\": \"GoCare Completion Certificate\"}, {\"body\": \"Academic Qualification KCSE Certificate (Any Grade) or Homecare Management Level 3 Qualification Detailed Duration Eight (8) Months (2 Terms) Tuition Duration and Two (2) Months Industrial Field Attachment Total Duration 8 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Train with experts, gain advanced mortuary skills, and become licensed. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(16, 'Certificate in Housekeeping and Accommodation ? Level 3 – GoCare Training Institute', 'certificate-in-housekeeping-and-accommodation-level-3', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Housekeeping &ndash; Level 3</strong> is a foundational, competency-based program that equips learners with the essential skills required to deliver professional housekeeping services in hotels, resorts, corporate offices, institutions, and residential environments.</p>\r\n            <p>Learners gain hands-on competencies in guestroom cleaning, public area cleaning, laundry operations, hygiene and sanitation, equipment handling, linen management, and workplace safety. The course also develops essential soft skills such as communication, environmental responsibility, employability skills, and occupational safety practices.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized Level 3 qualification provides a strong entry point into the hospitality and accommodation industry and serves as a pathway to advanced programs in Housekeeping Supervision, Accommodation Operations, and Hospitality Management.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed hospitality training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with industry standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training in real housekeeping environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed industrial attachment placement.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulatory recognized qualifications and certification.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">High employability in hotels, resorts, corporate offices, and residential settings.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Strong progression pathway to higher-level hospitality programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCPE or KCSE Certificate (Any Grade).</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Employability Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Guestroom Cleaning Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Laundry Cleaning Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Public Area Cleaning Services</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a two (2) month attachment in:</p>\r\n            <ul style=\"list-style: none; padding: 0; margin-top: 15px;\">\r\n              <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hotels &amp; Resorts</li>\r\n              <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"briefcase\" style=\"color: var(--o); flex-shrink: 0;\"></i> Corporate Offices</li>\r\n              <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"coffee\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitality Establishments</li>\r\n              <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"home\" style=\"color: var(--o); flex-shrink: 0;\"></i> Residential Facilities</li>\r\n              <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"spray-can\" style=\"color: var(--o); flex-shrink: 0;\"></i> Cleaning &amp; Facilities Management Companies</li>\r\n            </ul>\r\n            <p style=\"margin-top: 15px;\">GoCare provides full placement support to ensure every student gains real industry experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Housekeeping &ndash; Level 3 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Room Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Laundry Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public Area Cleaner</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Housekeeping Assistant</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Accommodation Support Staff</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Professional Cleaner</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Floor Supervisor</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Housekeeping Manager</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in hospitality, accommodation, and corporate service environments.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a skilled, industry-ready Housekeeping Professional.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Housekeeping – Level 3 is a foundational, competency-based program that equips learners with the essential skills required to deliver professional housekeeping services in hotels, resorts, corporate offices, institutions, and residential environments. Learners gain hands-on competencies in guestroom cleaning, public area cleaning, laundry operations, hygiene and sanitation, equipment handling, linen management, and workplace safety. The course also develops essential soft skills such as communication, environmental responsibility, employability skills, and occupational safety practices. This nationally recognized Level 3 qualification provides a strong entry point into the hospitality and accommodation industry and serves as a pathway to advanced programs in Housekeeping Supervision, Accommodation Operations, and Hospitality Management.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed hospitality training institution. 2 Competency-based TVET CDACC curriculum aligned with industry standards. 3 Hands-on practical training in real housekeeping environments. 4 Guaranteed industrial attachment placement. 5 Government and regulatory recognized qualifications and certification. 6 High employability in hotels, resorts, corporate offices, and residential settings. 7 Flexible study modes. 8 Strong progression pathway to higher-level hospitality programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCPE or KCSE Certificate (Any Grade).\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Communication Skills Digital Literacy Entrepreneurial Skills Employability Skills Guestroom Cleaning Services Laundry Cleaning Services Public Area Cleaning Services\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a two (2) month attachment in: Hotels & Resorts Corporate Offices Hospitality Establishments Residential Facilities Cleaning & Facilities Management Companies GoCare provides full placement support to ensure every student gains real industry experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Housekeeping – Level 3 can work as: Room Attendant Laundry Attendant Public Area Cleaner Housekeeping Assistant Accommodation Support Staff Professional Cleaner Floor Supervisor Housekeeping Manager This qualification opens doors to diverse opportunities in hospitality, accommodation, and corporate service environments. Total Duration 3 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a skilled, industry-ready Housekeeping Professional. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(17, 'Certificate in Mortuary Science ? Level 5 – GoCare Training Institute', 'certificate-in-mortuary-science-level-5', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Mortuary Science &ndash; Level 5</strong> is a foundational, competency-based program that prepares learners for professional roles within mortuaries, funeral homes, hospitals, and forensic environments. The program equips students with essential skills in deceased body management, basic embalming, psychosocial support, mortuary microbiology, and post-mortem preparation procedures.</p>\r\n            <p>Learners gain hands-on experience in real mortuary settings, developing confidence, ethical practice, and technical competence. The course emphasizes safety, professionalism, communication, and adherence to legal and ethical standards in mortuary practice.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This Level 5 KHPOA licensed qualification provides a strong entry point into the mortuary profession and serves as a direct progression pathway to the Diploma in Mortuary Science &ndash; Level 6.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national mortuary science standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training in real mortuaries, funeral homes, pathology units, and post-mortem facilities.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed attachment placement in accredited mortuary and funeral service institutions.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Clear progression pathway to Diploma in Mortuary Science &ndash; Level 6.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified morticians, pathologists, and forensic science professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for body preservation, reconstruction, and restorative procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">Strong emphasis on ethics, dignity, cultural sensitivity, and professional conduct in death-care services.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">11</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">12</div>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across mortuaries, funeral homes, hospitals, pathology labs, and forensic departments.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade D (Plain) and above</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Microbiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Law and Ethical Practice</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Premises Maintenance</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Preparation of Mortuary Chemicals</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Research and Innovation in Mortuary Practice</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Support for Bereaved Families</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Deceased Body Handling and Management</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Embalming Techniques and Solutions</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Post-Mortem Examination Preparation</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a Three (3) month mortuary or funeral home attachment. GoCare provides full placement support to ensure every student gains real practical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Mortuary Science &ndash; Level 5 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuaries and funeral homes</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals and medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"landmark\" style=\"color: var(--o); flex-shrink: 0;\"></i> Government and private morgues</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"briefcase\" style=\"color: var(--o); flex-shrink: 0;\"></i> Funeral service companies</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"microscope\" style=\"color: var(--o); flex-shrink: 0;\"></i> Pathology and forensic support environments</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuary Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuary Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Funeral Home Assistant</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Embalming Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Post-Mortem Support Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Deceased Body Care Assistant</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Gain foundational skills and progress toward becoming a licensed Mortuary Attendant.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Mortuary Science – Level 5 is a foundational, competency-based program that prepares learners for professional roles within mortuaries, funeral homes, hospitals, and forensic environments. The program equips students with essential skills in deceased body management, basic embalming, psychosocial support, mortuary microbiology, and post-mortem preparation procedures. Learners gain hands-on experience in real mortuary settings, developing confidence, ethical practice, and technical competence. The course emphasizes safety, professionalism, communication, and adherence to legal and ethical standards in mortuary practice. This Level 5 KHPOA licensed qualification provides a strong entry point into the mortuary profession and serves as a direct progression pathway to the Diploma in Mortuary Science – Level 6.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national mortuary science standards. 3 Hands-on practical training in real mortuaries, funeral homes, pathology units, and post-mortem facilities. 4 Guaranteed attachment placement in accredited mortuary and funeral service institutions. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Clear progression pathway to Diploma in Mortuary Science – Level 6. 8 Training delivered by qualified morticians, pathologists, and forensic science professionals. 9 Modern skills-lab and simulation-based training for body preservation, reconstruction, and restorative procedures. 10 Strong emphasis on ethics, dignity, cultural sensitivity, and professional conduct in death-care services. 11 Flexible study modes. 12 High employability in Kenya and abroad across mortuaries, funeral homes, hospitals, pathology labs, and forensic departments.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade D (Plain) and above\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics and Professional Conduct Mortuary Microbiology Mortuary Law and Ethical Practice Basic Human Anatomy and Physiology Mortuary Premises Maintenance Preparation of Mortuary Chemicals Research and Innovation in Mortuary Practice Psychosocial Support for Bereaved Families Deceased Body Handling and Management Embalming Techniques and Solutions Post-Mortem Examination Preparation\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a Three (3) month mortuary or funeral home attachment. GoCare provides full placement support to ensure every student gains real practical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Mortuary Science – Level 5 can work in: Mortuaries and funeral homes Hospitals and medical centres Government and private morgues Funeral service companies Pathology and forensic support environments Job roles include: Mortuary Attendant Mortuary Assistant Funeral Home Assistant Embalming Assistant Post-Mortem Support Technician Deceased Body Care Assistant Total Duration 1½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Gain foundational skills and progress toward becoming a licensed Mortuary Attendant. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(18, 'Certificate in Office Administrator ? Level 5 – GoCare Training Institute', 'certificate-in-office-administrator-level-5', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Office Administrator &ndash; Level 5</strong> is a practical, competency-based program designed to equip learners with the professional skills required to manage modern office environments across corporate, government, NGO, and institutional settings.</p>\r\n            <p>Learners gain hands-on competencies in office operations, communication, records management, customer service, digital applications, workplace etiquette, and administrative support. The program prepares graduates to function effectively as office administrators, receptionists, clerical officers, and administrative assistants.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized Level 5 qualification provides a strong foundation for administrative careers and serves as a pathway to advanced programs in Business Management, Human Resource Management, Secretarial Studies, and Office Administration.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed business and administration training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with industry standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Practical, hands-on training in real office environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed industrial attachment placement.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulatory recognized qualifications and certification.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">High employability in corporate, government, NGO, and institutional offices.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Strong progression pathway to higher-level business and administrative programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade D (Plain) OR Level 4 Certificate in a related field.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills for Office Professionals</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy &amp; Office Computer Applications</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills for Administrative Roles</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Workplace Ethics &amp; Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Office Procedures &amp; Operations</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Customer Service &amp; Front Office Management</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Records Management &amp; Filing Systems</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Clerical Duties &amp; Administrative Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Business Correspondence &amp; Document Handling</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Office Equipment Operation &amp; Maintenance</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Workplace Communication &amp; Interpersonal Skills</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a three (3) month industrial attachment. GoCare provides full placement support to ensure every student gains real industry experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Office Administrator &ndash; Level 5 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Office Administrator</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Administrative Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Front Office Executive</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Records Clerk</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Customer Service Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Office Support Staff</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Secretary</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Clerical Officer</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in business, corporate, government, and administrative environments.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a skilled, confident, and industry-ready Office Administrator.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Office Administrator – Level 5 is a practical, competency-based program designed to equip learners with the professional skills required to manage modern office environments across corporate, government, NGO, and institutional settings. Learners gain hands-on competencies in office operations, communication, records management, customer service, digital applications, workplace etiquette, and administrative support. The program prepares graduates to function effectively as office administrators, receptionists, clerical officers, and administrative assistants. This nationally recognized Level 5 qualification provides a strong foundation for administrative careers and serves as a pathway to advanced programs in Business Management, Human Resource Management, Secretarial Studies, and Office Administration.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed business and administration training institution. 2 Competency-based TVET CDACC curriculum aligned with industry standards. 3 Practical, hands-on training in real office environments. 4 Guaranteed industrial attachment placement. 5 Government and regulatory recognized qualifications and certification. 6 High employability in corporate, government, NGO, and institutional offices. 7 Flexible study modes. 8 Strong progression pathway to higher-level business and administrative programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade D (Plain) OR Level 4 Certificate in a related field.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Communication Skills for Office Professionals Digital Literacy & Office Computer Applications Entrepreneurial Skills for Administrative Roles Workplace Ethics & Professional Conduct Office Procedures & Operations Customer Service & Front Office Management Records Management & Filing Systems Clerical Duties & Administrative Support Business Correspondence & Document Handling Office Equipment Operation & Maintenance Workplace Communication & Interpersonal Skills\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a three (3) month industrial attachment. GoCare provides full placement support to ensure every student gains real industry experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Office Administrator – Level 5 can work as: Office Administrator Administrative Assistant Receptionist Front Office Executive Records Clerk Customer Service Assistant Office Support Staff Secretary Clerical Officer This qualification opens doors to diverse opportunities in business, corporate, government, and administrative environments. Total Duration 1½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a skilled, confident, and industry-ready Office Administrator. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(19, 'Certificate in Office Assistant (Customer Service) ? Level 4 – GoCare Training Institute', 'certificate-in-office-assistant-customer-service-level-4', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Office Assistant / Customer Service &ndash; Level 4</strong> is a foundational, competency-based program designed to equip learners with essential administrative, clerical, and customer service skills required in modern office environments.</p>\r\n            <p>Learners gain practical competencies in office procedures, communication, customer relations, digital applications, records handling, front office operations, and workplace etiquette. The program prepares graduates to support daily office operations in corporate organizations, government institutions, NGOs, SMEs, and service-based environments.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized Level 4 qualification provides a strong entry point into administrative careers and serves as a pathway to advanced programs such as Office Administrator Level 5 and Business Management.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed business and administration training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with industry needs.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training in real office and customer service environments.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed industrial attachment placement.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulatory recognized qualifications and certification.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">High employability in corporate, government, NGO, and service sectors.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Strong progression pathway to higher-level administrative programs.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Certificate (Any Grade).</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills for Office Work</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy &amp; Computer Applications</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills for Office Support Roles</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Workplace Ethics &amp; Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Office Procedures &amp; Administrative Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Customer Service &amp; Client Relations</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Front Office Operations &amp; Reception Duties</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Records Handling &amp; Filing Systems</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Business Correspondence &amp; Document Processing</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Telephone Handling &amp; Communication Etiquette</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Office Equipment Operation &amp; Basic Maintenance</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Interpersonal Skills &amp; Professional Grooming</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a two (2) month industrial attachment. GoCare provides full placement support to ensure every student gains real industry experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Office Assistant / Customer Service &ndash; Level 4 can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Office Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Customer Service Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Receptionist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Front Office Clerk</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Administrative Support Staff</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Records Clerk</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Call Centre Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Messenger / Office Runner</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Clerical Assistant</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in administrative, customer service, and office support environments.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">8 Months</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Start your journey toward becoming a skilled, confident, and industry-ready Office Assistant.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Office Assistant / Customer Service – Level 4 is a foundational, competency-based program designed to equip learners with essential administrative, clerical, and customer service skills required in modern office environments. Learners gain practical competencies in office procedures, communication, customer relations, digital applications, records handling, front office operations, and workplace etiquette. The program prepares graduates to support daily office operations in corporate organizations, government institutions, NGOs, SMEs, and service-based environments. This nationally recognized Level 4 qualification provides a strong entry point into administrative careers and serves as a pathway to advanced programs such as Office Administrator Level 5 and Business Management.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed business and administration training institution. 2 Competency-based TVET CDACC curriculum aligned with industry needs. 3 Hands-on practical training in real office and customer service environments. 4 Guaranteed industrial attachment placement. 5 Government and regulatory recognized qualifications and certification. 6 High employability in corporate, government, NGO, and service sectors. 7 Flexible study modes. 8 Strong progression pathway to higher-level administrative programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Certificate (Any Grade).\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Communication Skills for Office Work Digital Literacy & Computer Applications Entrepreneurial Skills for Office Support Roles Workplace Ethics & Professional Conduct Office Procedures & Administrative Support Customer Service & Client Relations Front Office Operations & Reception Duties Records Handling & Filing Systems Business Correspondence & Document Processing Telephone Handling & Communication Etiquette Office Equipment Operation & Basic Maintenance Interpersonal Skills & Professional Grooming\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a two (2) month industrial attachment. GoCare provides full placement support to ensure every student gains real industry experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Office Assistant / Customer Service – Level 4 can work as: Office Assistant Customer Service Assistant Receptionist Front Office Clerk Administrative Support Staff Records Clerk Call Centre Assistant Messenger / Office Runner Clerical Assistant This qualification opens doors to diverse opportunities in administrative, customer service, and office support environments. Total Duration 8 Months Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Start your journey toward becoming a skilled, confident, and industry-ready Office Assistant. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(20, 'Certificate in Orthopaedic and Trauma Medicine ? Level 5 – GoCare Training Institute', 'certificate-in-orthopaedic-and-trauma-medicine-level-5', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Orthopaedic &amp; Trauma Medicine &ndash; Level 5</strong> is a specialized, competency-based program that equips learners with foundational skills in the management of musculoskeletal injuries, trauma care, emergency response, and orthopaedic support services.</p>\r\n            <p>The program prepares trainees to work in accident and emergency units, orthopaedic wards, outpatient clinics, plaster rooms, and trauma care facilities. Learners gain hands-on experience in first aid, soft tissue injury management, basic hospital procedures, anatomy and physiology, and the initial management of fractures and dislocations.</p>\r\n            <p>Through structured clinical exposure, students work alongside orthopaedic clinicians, trauma teams, and emergency care professionals, building confidence and competence in real healthcare environments.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This Level 5 KHPOA licensed qualification provides a strong foundation for employment and serves as a direct progression pathway to the Diploma in Orthopaedic &amp; Trauma Medicine &ndash; Level 6.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national orthopaedic and trauma care standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on clinical training with real patient exposure in orthopaedic, trauma, emergency, and rehabilitation units.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified orthopaedic, trauma, and emergency-care professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for casting, splinting, immobilization, and trauma procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">High employability across hospitals, trauma centres, orthopaedic clinics, and emergency departments.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600; margin-bottom: 8px;\">KCSE Mean Grade C (Minus) and:</p>\r\n                  <ul style=\"list-style: none; padding: 0; margin-left: 10px;\">\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> C (Minus) in English / Kiswahili</li>\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> C (Minus) in Biology</li>\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> D+ (Plus) in any one of Mathematics / Physics / Chemistry</li>\r\n                  </ul>\r\n                  <p style=\"margin: 15px 0 5px 0; font-size: 14px; font-weight: bold; color: var(--o);\">OR</p>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">Certificate Level 4 in Emergency Medical Technology or related course.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> First Aid Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy &amp; Physiology I</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Hospital Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Healthcare Support Services</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy &amp; Physiology II</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Medical-Legal Ethics</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Knowledge of Common Diseases</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Health Promotion Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Emergency Care in Disaster Incidents</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Soft Tissue Injuries</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Orthopaedic Conditions I</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Fractures and Dislocations</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Hospital Attachment</h2>\r\n            <p>All learners undertake a Six (6) month hospital attachment in accredited orthopaedic, trauma, emergency, or surgical units.</p>\r\n            <p>GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Orthopaedic &amp; Trauma Medicine &ndash; Level 5 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals and medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"alert-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Accident and emergency units</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"activity\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic wards and trauma units</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"scissors\" style=\"color: var(--o); flex-shrink: 0;\"></i> Plaster rooms and fracture clinics</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"truck\" style=\"color: var(--o); flex-shrink: 0;\"></i> Ambulance and emergency response teams</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"users\" style=\"color: var(--o); flex-shrink: 0;\"></i> Rehabilitation and physiotherapy centres</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic &amp; Trauma Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Plaster Technician / Cast Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Emergency Care Assistant</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic Ward Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Trauma Support Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Rehabilitation Support Assistant</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Journey</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts and become a licensed Orthopaedic &amp; Trauma Medicine professional.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Orthopaedic & Trauma Medicine – Level 5 is a specialized, competency-based program that equips learners with foundational skills in the management of musculoskeletal injuries, trauma care, emergency response, and orthopaedic support services. The program prepares trainees to work in accident and emergency units, orthopaedic wards, outpatient clinics, plaster rooms, and trauma care facilities. Learners gain hands-on experience in first aid, soft tissue injury management, basic hospital procedures, anatomy and physiology, and the initial management of fractures and dislocations. Through structured clinical exposure, students work alongside orthopaedic clinicians, trauma teams, and emergency care professionals, building confidence and competence in real healthcare environments. This Level 5 KHPOA licensed qualification provides a strong foundation for employment and serves as a direct progression pathway to the Diploma in Orthopaedic & Trauma Medicine – Level 6.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national orthopaedic and trauma care standards. 3 Hands-on clinical training with real patient exposure in orthopaedic, trauma, emergency, and rehabilitation units. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Training delivered by qualified orthopaedic, trauma, and emergency-care professionals. 8 Modern skills-lab and simulation-based training for casting, splinting, immobilization, and trauma procedures. 9 Flexible study modes. 10 High employability across hospitals, trauma centres, orthopaedic clinics, and emergency departments.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade C (Minus) and: C (Minus) in English / Kiswahili C (Minus) in Biology D+ (Plus) in any one of Mathematics / Physics / Chemistry OR Certificate Level 4 in Emergency Medical Technology or related course.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics and Professional Conduct Entrepreneurial Skills First Aid Services Human Anatomy & Physiology I Basic Hospital Procedures Psychosocial Healthcare Support Services Human Anatomy & Physiology II Medical-Legal Ethics Knowledge of Common Diseases Health Promotion Services Emergency Care in Disaster Incidents Management of Soft Tissue Injuries Management of Orthopaedic Conditions I Management of Fractures and Dislocations\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a Six (6) month hospital attachment in accredited orthopaedic, trauma, emergency, or surgical units. GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Hospital Attachment\"}, {\"body\": \"Graduates of the Certificate in Orthopaedic & Trauma Medicine – Level 5 can work in: Hospitals and medical centres Accident and emergency units Orthopaedic wards and trauma units Plaster rooms and fracture clinics Ambulance and emergency response teams Rehabilitation and physiotherapy centres Job roles include: Orthopaedic & Trauma Technician Plaster Technician / Cast Technician Emergency Care Assistant Orthopaedic Ward Assistant Trauma Support Technician Rehabilitation Support Assistant Total Duration 1½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts and become a licensed Orthopaedic & Trauma Medicine professional. 0703 115 502\", \"heading\": \"Begin Your Journey\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(21, 'Certificate in Perioperative Theatre Technology ? Level 5 – GoCare Training Institute', 'certificate-in-perioperative-theatre-technology-level-5', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Certificate in Perioperative Theatre Technology &ndash; Level 5</strong> is a foundational, competency-based program that prepares learners to support surgical teams within operating theatre environments. The course equips students with essential knowledge and practical skills in theatre preparation, infection prevention, patient handling, equipment setup, and perioperative safety procedures.</p>\r\n            <p>Learners gain hands-on experience in operating room workflows, instrument care, sterilization processes, and theatre support functions. The program emphasizes patient safety, communication, teamwork, and adherence to medical-legal and ethical standards within surgical settings.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This nationally recognized and KHPOA licensed Level 5 qualification provides a strong entry point into perioperative practice and serves as a direct upgrading pathway to the Diploma in Perioperative Theatre Technology &ndash; Level 6.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on clinical training with real patient and theatre exposure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">High employability across surgical and perioperative departments.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade C- (Minus) and above</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Prevention of Nosocomial Infections</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of First Aid Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Common Diseases</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Execution of Perioperative Theatre Safety Precautions</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Practices</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Medical-Legal Ethics in POTT</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of Perioperative Theatre Technical Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Hospital Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Maintenance of Perioperative Theatre Instruments and Apparatus</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of Health Education and Promotion Services</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a Three (3) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Certificate in Perioperative Theatre Technology &ndash; Level 5 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o); flex-shrink: 0;\"></i> Medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"scissors\" style=\"color: var(--o); flex-shrink: 0;\"></i> Surgical theatres</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"activity\" style=\"color: var(--o); flex-shrink: 0;\"></i> Specialized surgical units</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"heart-pulse\" style=\"color: var(--o); flex-shrink: 0;\"></i> Healthcare facilities</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Perioperative Theatre Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Operating Room Support Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Surgical Equipment Assistant</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Theatre Sterilization Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Theatre Circulation Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Patient Care Support Assistant</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts and become a licensed Perioperative Theatre Technician.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certificate in Perioperative Theatre Technology – Level 5 is a foundational, competency-based program that prepares learners to support surgical teams within operating theatre environments. The course equips students with essential knowledge and practical skills in theatre preparation, infection prevention, patient handling, equipment setup, and perioperative safety procedures. Learners gain hands-on experience in operating room workflows, instrument care, sterilization processes, and theatre support functions. The program emphasizes patient safety, communication, teamwork, and adherence to medical-legal and ethical standards within surgical settings. This nationally recognized and KHPOA licensed Level 5 qualification provides a strong entry point into perioperative practice and serves as a direct upgrading pathway to the Diploma in Perioperative Theatre Technology – Level 6.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national standards. 3 Hands-on clinical training with real patient and theatre exposure. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Flexible study modes. 8 High employability across surgical and perioperative departments.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade C- (Minus) and above\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Human Anatomy and Physiology Prevention of Nosocomial Infections Provision of First Aid Services Communication Skills Common Diseases Execution of Perioperative Theatre Safety Precautions Work Ethics and Practices Medical-Legal Ethics in POTT Provision of Perioperative Theatre Technical Services Basic Hospital Procedures Entrepreneurial Skills Maintenance of Perioperative Theatre Instruments and Apparatus Provision of Health Education and Promotion Services\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a Three (3) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Certificate in Perioperative Theatre Technology – Level 5 can work in: Hospitals Medical centres Surgical theatres Specialized surgical units Healthcare facilities Job roles include: Perioperative Theatre Technician Operating Room Support Technician Surgical Equipment Assistant Theatre Sterilization Assistant Theatre Circulation Assistant Patient Care Support Assistant Total Duration 1½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts and become a licensed Perioperative Theatre Technician. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(22, 'Certified Nursing Assistant (CNA) Options · GoCare Training Institute', 'certified-nursing-assistant-cna-options', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Overview</h2>\r\n            <p>The Certified Nursing Assistant (CNA) Options program provides GoCare Training Institute learners with internationally recognized training and certification through two globally respected healthcare accreditation bodies:</p>\r\n            <div style=\"display: grid; gap: 20px; margin-top: 20px;\">\r\n              <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px;\">\r\n                <h4 style=\"color: var(--dark); margin: 0 0 10px 0; font-size: 18px;\">Skill Development Council Canada (SDC Canada)</h4>\r\n                <p style=\"margin: 0; font-size: 15px;\">A Canadian international certification authority offering globally recognized healthcare qualifications, including the Certified Nursing Assistant (CNA) credential.</p>\r\n              </div>\r\n              <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px;\">\r\n                <h4 style=\"color: var(--dark); margin: 0 0 10px 0; font-size: 18px;\">American Medical Certification Association (AMCA USA)</h4>\r\n                <p style=\"margin: 0; font-size: 15px;\">A U.S.&ndash;based medical certification organization offering standardized healthcare examinations and credentials, including the Certified Nursing Assistant (CNA) certification.</p>\r\n              </div>\r\n            </div>\r\n            <p style=\"margin-top: 20px;\">These international CNA pathways significantly enhance employability in hospitals, long-term care facilities, home-based care, and global healthcare markets such as Canada, USA, Europe, and the Middle East.</p>\r\n            <p style=\"font-weight: 600; color: var(--dark);\">GoCare is an approved international training and examination center, making it one of Kenya&#8217;s leading institutions for globally portable CNA certification.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Pursue CNA Certification Options at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 12px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Internationally aligned CNA training pathways through SDC Canada and AMCA USA.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Competency-based curriculum designed to meet global healthcare support standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Hands-on clinical training with real patient exposure in hospitals, clinics, and long-term care facilities.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Eligibility for international CNA certification exams (SDC Canada, AMCA USA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA) for applicable / qualified programs.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Training delivered by qualified nurses, clinicians, and healthcare support professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for patient care, vital signs, infection control, and bedside procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">Flexible study modes (Day, Online, Evening, Saturday).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0; margin-top: 2px;\"></i>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and community health facilities.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">Who Qualifies for CNA Options?</h2>\r\n            <p>Every learner enrolled in any GoCare caregiving or healthcare support program automatically qualifies for CNA Options.</p>\r\n            <p style=\"margin-bottom: 25px;\">Below is the official GoCare Certified Nursing Assistant (CNA) sponsorship pathway, showing entry requirements, what you must complete, and how you earn the free CNA international certification:</p>\r\n            \r\n            <div style=\"display: grid; gap: 20px;\">\r\n              <!-- Course 1 -->\r\n              <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 25px; border-radius: 8px;\">\r\n                <div style=\"display: flex; gap: 15px; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 15px;\">\r\n                  <div style=\"background: var(--o); color: #F5F0E8; width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: bold;\">1</div>\r\n                  <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Certificate in Healthcare Support Services &ndash; Level 5</h4>\r\n                </div>\r\n                <p style=\"font-size: 15px; margin-bottom: 10px;\"><strong>Entry Requirements:</strong> KCSE D (Plain) and above</p>\r\n                <p style=\"font-size: 15px; font-weight: bold; margin-bottom: 10px;\">How You Earn CNA Sponsorship:</p>\r\n                <ul style=\"list-style: none; padding: 0; margin: 0;\">\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Enrol and pay for the Healthcare Support Services &ndash; Level 5 TVET CDACC Course</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Complete 1&frac12; years inclusive of the 3-month attachment</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> <strong>Earn SDC Canada International CNA Training and Certification</strong></li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> No extra tuition fee</li>\r\n                </ul>\r\n                <p style=\"font-size: 13px; font-style: italic; color: var(--gray); margin-top: 10px; margin-bottom: 0;\">(Level 5 already leads to KHPOA licensing; the sponsorship adds an international CNA credential.)</p>\r\n              </div>\r\n\r\n              <!-- Course 2 -->\r\n              <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 25px; border-radius: 8px;\">\r\n                <div style=\"display: flex; gap: 15px; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 15px;\">\r\n                  <div style=\"background: var(--o); color: #F5F0E8; width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: bold;\">2</div>\r\n                  <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Certificate in Caregiving &ndash; Level 4</h4>\r\n                </div>\r\n                <p style=\"font-size: 15px; margin-bottom: 10px;\"><strong>Entry Requirements:</strong> KCSE (Any Grade)</p>\r\n                <p style=\"font-size: 15px; font-weight: bold; margin-bottom: 10px;\">How You Earn CNA Sponsorship:</p>\r\n                <ul style=\"list-style: none; padding: 0; margin: 0;\">\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Enrol and pay for the Caregiving &ndash; Level 4 TVET CDACC Course</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Complete 6 months tuition + 2 months attachment</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> <strong>Earn Advanced HealthCare Assistant or Certified Nursing Assistant (CNA) Training and Certification</strong></li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> No extra tuition fee</li>\r\n                </ul>\r\n              </div>\r\n\r\n              <!-- Course 3 -->\r\n              <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 25px; border-radius: 8px;\">\r\n                <div style=\"display: flex; gap: 15px; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 15px;\">\r\n                  <div style=\"background: var(--o); color: #F5F0E8; width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: bold;\">3</div>\r\n                  <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Caregiver Course &ndash; Level II (NITA)</h4>\r\n                </div>\r\n                <p style=\"font-size: 15px; margin-bottom: 10px;\"><strong>Entry Requirements:</strong> KCSE D (Minus) and above</p>\r\n                <p style=\"font-size: 15px; font-weight: bold; margin-bottom: 10px;\">How You Earn CNA Sponsorship:</p>\r\n                <ul style=\"list-style: none; padding: 0; margin: 0;\">\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Enrol and pay for the Caregiver Course &ndash; Level II NITA Course</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Complete 4 months tuition + 2 months attachment</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> <strong>Earn Professional Caregiver or Certified Nursing Assistant (CNA) Training and Certification</strong></li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> No extra tuition fee</li>\r\n                </ul>\r\n              </div>\r\n\r\n              <!-- Course 4 -->\r\n              <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 25px; border-radius: 8px;\">\r\n                <div style=\"display: flex; gap: 15px; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 15px;\">\r\n                  <div style=\"background: var(--o); color: #F5F0E8; width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: bold;\">4</div>\r\n                  <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Certificate in Home-Based Care Support &ndash; Level 3</h4>\r\n                </div>\r\n                <p style=\"font-size: 15px; margin-bottom: 10px;\"><strong>Entry Requirements:</strong> KCPE or KCSE (Any Grade)</p>\r\n                <p style=\"font-size: 15px; font-weight: bold; margin-bottom: 10px;\">How You Earn CNA Sponsorship:</p>\r\n                <ul style=\"list-style: none; padding: 0; margin: 0;\">\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Enrol and pay for the Home-Based Care Support &ndash; Level 3 TVET CDACC Course</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> Complete 3 months tuition + 2 months attachment</li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> <strong>Earn HealthCare Assistant or Certified Nursing Assistant (CNA) Training and Certification</strong></li>\r\n                  <li style=\"display: flex; gap: 10px; margin-bottom: 8px;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); width: 16px; flex-shrink: 0;\"></i> No extra tuition fee</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">CNA Certification Pathways</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 30px;\">\r\n              <div style=\"border-top: 4px solid var(--o); padding-top: 20px;\">\r\n                <h4 style=\"color: var(--dark); font-size: 20px; margin-bottom: 15px;\">1. Skill Development Council Canada (SDC Canada)</h4>\r\n                <p style=\"font-weight: 600; margin-bottom: 10px;\">What You Will Get:</p>\r\n                <ul style=\"list-style: none; padding: 0;\">\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Additional international standard aligned and approved training.</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Internationally recognized qualification and certification.</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Canada-based accredited curriculum.</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Training duration: Four (4) weeks (for direct applicants).</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> GoCare alumni receive a 10% discount (for direct applicants).</li>\r\n                </ul>\r\n              </div>\r\n              \r\n              <div style=\"border-top: 4px solid var(--o); padding-top: 20px;\">\r\n                <h4 style=\"color: var(--dark); font-size: 20px; margin-bottom: 15px;\">2. American Medical Certification Association (AMCA USA)</h4>\r\n                <p style=\"font-weight: 600; margin-bottom: 10px;\">What You Will Get:</p>\r\n                <ul style=\"list-style: none; padding: 0;\">\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Additional international standard aligned and approved training.</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Internationally recognized qualification and certification.</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> USA-based accredited curriculum.</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Training duration: Four (4) weeks (for direct applicants).</li>\r\n                  <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> GoCare alumni receive a 10% discount (for direct applicants).</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px; background: rgba(237, 116, 37, 0.05); padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Two Training Pathways for CNA Certification</h2>\r\n            <div style=\"margin-bottom: 30px;\">\r\n              <h4 style=\"color: var(--dark); font-size: 18px; margin-bottom: 10px;\">OPTION 1: Integrated CNA Sponsorship (For GoCare Students)</h4>\r\n              <p>Included automatically for all GoCare Training Institute Home Based Care Support, Caregiving and Healthcare Support Services (HSS) students.</p>\r\n              <p style=\"font-weight: bold; margin-top: 15px;\">You receive:</p>\r\n              <ul style=\"list-style: none; padding: 0; margin-bottom: 15px;\">\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"star\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> One paid course</li>\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"star\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> One fully sponsored Certified Nursing Assistant (CNA) training and certification</li>\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"star\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> No extra tuition fee</li>\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"star\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> Two qualifications upon graduation</li>\r\n              </ul>\r\n              <p style=\"font-style: italic; color: var(--dark);\">This is the GoCare Training Institute Second Course Sponsorship.</p>\r\n            </div>\r\n            \r\n            <div style=\"border-top: 1px solid rgba(0,0,0,0.1); padding-top: 25px;\">\r\n              <h4 style=\"color: var(--dark); font-size: 18px; margin-bottom: 10px;\">OPTION 2: Customized CNA Training (For Alumni &amp; External Applicants)</h4>\r\n              <p style=\"font-weight: bold;\">Available for:</p>\r\n              <ul style=\"list-style: disc; margin-left: 20px; margin-bottom: 15px;\">\r\n                <li>GoCare alumni</li>\r\n                <li>Medical and healthcare professionals</li>\r\n                <li>Students trained in other institutions</li>\r\n                <li>Medical and healthcare Diploma and degree holders</li>\r\n              </ul>\r\n              <p style=\"font-weight: bold; margin-top: 15px;\">You receive:</p>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"award\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> Customized CNA training</li>\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"award\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> International examination</li>\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"award\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> International certification (SDC Canada or AMCA USA)</li>\r\n                <li style=\"margin-bottom: 8px; display: flex; gap: 10px;\"><i data-lucide=\"award\" style=\"color: var(--o); flex-shrink: 0; width: 16px;\"></i> Alumni 10% discount available</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 50px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Certified Nursing Assistants can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 15px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Nursing homes</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Assisted living facilities</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Home-based care</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Rehabilitation centers</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community health facilities</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> International healthcare markets (Canada, USA, Europe, Middle East)</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: bold; color: var(--o);\">CNA certification opens doors to global healthcare careers.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certifying Bodies</span>\r\n                <strong style=\"color: var(--dark); display: block;\">SDC Canada &amp; AMCA USA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Sponsorship</span>\r\n                <strong style=\"color: var(--dark); display: block;\">Available for Enrolled Students</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Global Reach</span>\r\n                <strong style=\"color: var(--dark); display: block;\">Canada, USA, Europe, Middle East, Africa</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Journey</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Become a globally recognized Certified Nursing Assistant (CNA) today.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Certified Nursing Assistant (CNA) Options program provides GoCare Training Institute learners with internationally recognized training and certification through two globally respected healthcare accreditation bodies:\", \"heading\": \"Overview\"}, {\"body\": \"A Canadian international certification authority offering globally recognized healthcare qualifications, including the Certified Nursing Assistant (CNA) credential.\", \"heading\": \"Skill Development Council Canada (SDC Canada)\"}, {\"body\": \"A U.S.–based medical certification organization offering standardized healthcare examinations and credentials, including the Certified Nursing Assistant (CNA) certification. These international CNA pathways significantly enhance employability in hospitals, long-term care facilities, home-based care, and global healthcare markets such as Canada, USA, Europe, and the Middle East. GoCare is an approved international training and examination center, making it one of Kenya’s leading institutions for globally portable CNA certification.\", \"heading\": \"American Medical Certification Association (AMCA USA)\"}, {\"body\": \"Fully accredited and licensed medical and health sciences training institution. Internationally aligned CNA training pathways through SDC Canada and AMCA USA. Competency-based curriculum designed to meet global healthcare support standards. Hands-on clinical training with real patient exposure in hospitals, clinics, and long-term care facilities. Guaranteed hospital attachment placement by the college. Government and regulator-recognized qualifications, certification, and practice licensure. Eligibility for international CNA certification exams (SDC Canada, AMCA USA). Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA) for applicable / qualified programs. Training delivered by qualified nurses, clinicians, and healthcare support professionals. Modern skills-lab and simulation-based training for patient care, vital signs, infection control, and bedside procedures. Flexible study modes (Day, Online, Evening, Saturday). High employability in Kenya and abroad across hospitals, homecare agencies, nursing homes, and community health facilities.\", \"heading\": \"Why Pursue CNA Certification Options at GoCare?\"}, {\"body\": \"Every learner enrolled in any GoCare caregiving or healthcare support program automatically qualifies for CNA Options. Below is the official GoCare Certified Nursing Assistant (CNA) sponsorship pathway, showing entry requirements, what you must complete, and how you earn the free CNA international certification: 1\", \"heading\": \"Who Qualifies for CNA Options?\"}, {\"body\": \"Entry Requirements: KCSE D (Plain) and above How You Earn CNA Sponsorship: Enrol and pay for the Healthcare Support Services – Level 5 TVET CDACC Course Complete 1½ years inclusive of the 3-month attachment Earn SDC Canada International CNA Training and Certification No extra tuition fee (Level 5 already leads to KHPOA licensing; the sponsorship adds an international CNA credential.) 2\", \"heading\": \"Certificate in Healthcare Support Services – Level 5\"}, {\"body\": \"Entry Requirements: KCSE (Any Grade) How You Earn CNA Sponsorship: Enrol and pay for the Caregiving – Level 4 TVET CDACC Course Complete 6 months tuition + 2 months attachment Earn Advanced HealthCare Assistant or Certified Nursing Assistant (CNA) Training and Certification No extra tuition fee 3\", \"heading\": \"Certificate in Caregiving – Level 4\"}, {\"body\": \"Entry Requirements: KCSE D (Minus) and above How You Earn CNA Sponsorship: Enrol and pay for the Caregiver Course – Level II NITA Course Complete 4 months tuition + 2 months attachment Earn Professional Caregiver or Certified Nursing Assistant (CNA) Training and Certification No extra tuition fee 4\", \"heading\": \"Caregiver Course – Level II (NITA)\"}, {\"body\": \"Entry Requirements: KCPE or KCSE (Any Grade) How You Earn CNA Sponsorship: Enrol and pay for the Home-Based Care Support – Level 3 TVET CDACC Course Complete 3 months tuition + 2 months attachment Earn HealthCare Assistant or Certified Nursing Assistant (CNA) Training and Certification No extra tuition fee\", \"heading\": \"Certificate in Home-Based Care Support – Level 3\"}, {\"body\": \"\", \"heading\": \"CNA Certification Pathways\"}, {\"body\": \"What You Will Get: Additional international standard aligned and approved training. Internationally recognized qualification and certification. Canada-based accredited curriculum. Training duration: Four (4) weeks (for direct applicants). GoCare alumni receive a 10% discount (for direct applicants).\", \"heading\": \"1. Skill Development Council Canada (SDC Canada)\"}, {\"body\": \"What You Will Get: Additional international standard aligned and approved training. Internationally recognized qualification and certification. USA-based accredited curriculum. Training duration: Four (4) weeks (for direct applicants). GoCare alumni receive a 10% discount (for direct applicants).\", \"heading\": \"2. American Medical Certification Association (AMCA USA)\"}, {\"body\": \"\", \"heading\": \"Two Training Pathways for CNA Certification\"}, {\"body\": \"Included automatically for all GoCare Training Institute Home Based Care Support, Caregiving and Healthcare Support Services (HSS) students. You receive: One paid course One fully sponsored Certified Nursing Assistant (CNA) training and certification No extra tuition fee Two qualifications upon graduation This is the GoCare Training Institute Second Course Sponsorship.\", \"heading\": \"OPTION 1: Integrated CNA Sponsorship (For GoCare Students)\"}, {\"body\": \"Available for: GoCare alumni Medical and healthcare professionals Students trained in other institutions Medical and healthcare Diploma and degree holders You receive: Customized CNA training International examination International certification (SDC Canada or AMCA USA) Alumni 10% discount available\", \"heading\": \"OPTION 2: Customized CNA Training (For Alumni & External Applicants)\"}, {\"body\": \"Certified Nursing Assistants can work in: Hospitals Nursing homes Assisted living facilities Home-based care Rehabilitation centers Community health facilities International healthcare markets (Canada, USA, Europe, Middle East) CNA certification opens doors to global healthcare careers. Apply Online Contact Admissions Certifying Bodies SDC Canada & AMCA USA Sponsorship Available for Enrolled Students Global Reach Canada, USA, Europe, Middle East, Africa\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Become a globally recognized Certified Nursing Assistant (CNA) today. 0703 115 502\", \"heading\": \"Begin Your Journey\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(23, 'Diploma in Community Health Assistant ? Level 6 – GoCare Training Institute', 'diploma-in-community-health-assistant-level-6', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Diploma in Community Health Assistant &ndash; Level 6</strong> is an advanced, competency-based program designed to prepare learners for professional roles in community health, public health promotion, disease prevention, and community-based healthcare services.</p>\r\n            <p>This program equips trainees with the knowledge, skills, and practical experience required to support and strengthen community health systems, deliver health education, participate in disease surveillance, support maternal and child health initiatives, and contribute to national and county-level public health programs.</p>\r\n            <p>Learners gain hands-on experience in community health information systems, epidemiology, health promotion, community diagnosis, environmental health, and the delivery of essential community-based interventions. The course emphasizes leadership, communication, ethical practice, and collaboration with healthcare teams, government agencies, NGOs, and community structures.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">This KHPOA-licensed Level 6 qualification prepares graduates for employment in diverse community and public health settings and provides a strong foundation for further progression into higher-level health programs.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national community health and public health standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on clinical and community-based training with real field exposure in households, facilities, and community units.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed attachment placement in accredited hospitals, health centres, NGOs, and community health programs.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified community health, public health, and primary healthcare professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for health promotion, disease prevention, community diagnosis, and household health support.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">High employability across hospitals, NGOs, community health programs, public health projects, and primary healthcare facilities.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600; margin-bottom: 8px;\">KCSE Mean Grade C (Minus) and:</p>\r\n                  <ul style=\"list-style: none; padding: 0; margin-left: 10px;\">\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> English / Kiswahili: C (Minus)</li>\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> Biology / Biological Science: D+ (Plus)</li>\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> Mathematics / Chemistry/Physics / Home Science: D (Plain)</li>\r\n                  </ul>\r\n                  <p style=\"margin: 15px 0 5px 0; font-size: 14px; font-weight: bold; color: var(--o);\">OR</p>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">Community Health Assistant Level 5 Qualification</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Practices</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Nutrition in Community Health</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Microbiology and Parasitology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Epidemiology in Community Health</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Statistics in Community Health</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Fundamentals of Primary Health Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Health System Management</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Information System</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Maternal, Newborn and Child Health Care</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Education and Promotion</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Services Strategies</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Linkages</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community-Based Health Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Gender, Disability and Vulnerable Groups</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Diagnosis and Partnership</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Common Diseases and Ailments</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> First Aid Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Care</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Programmes Monitoring and Evaluation</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Community Health Research</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Environmental Health</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Geriatric Care</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a Six (6) month industrial field attachment in accredited community health departments, public health programs, NGOs, hospitals, or community-based health facilities.</p>\r\n            <p>GoCare provides full placement support to ensure every student gains real, practical field experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Diploma in Community Health Assistant &ndash; Level 6 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"users\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community health organizations</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"landmark\" style=\"color: var(--o); flex-shrink: 0;\"></i> National and county government health departments</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"shield-plus\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public health programs</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"globe\" style=\"color: var(--o); flex-shrink: 0;\"></i> NGOs and international development agencies</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals and medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"activity\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community-based health projects</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"megaphone\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public health outreach and education programs</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Officer</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public Health Specialist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Program Manager</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Educator</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Coordinator</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Health Promotion Officer</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Public Health Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Maternal and Child Health Worker</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Health Volunteer</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Diverse roles in the medical and healthcare industry</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">2½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts and become a licensed Community Health Assistant.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Diploma in Community Health Assistant – Level 6 is an advanced, competency-based program designed to prepare learners for professional roles in community health, public health promotion, disease prevention, and community-based healthcare services. This program equips trainees with the knowledge, skills, and practical experience required to support and strengthen community health systems, deliver health education, participate in disease surveillance, support maternal and child health initiatives, and contribute to national and county-level public health programs. Learners gain hands-on experience in community health information systems, epidemiology, health promotion, community diagnosis, environmental health, and the delivery of essential community-based interventions. The course emphasizes leadership, communication, ethical practice, and collaboration with healthcare teams, government agencies, NGOs, and community structures. This KHPOA-licensed Level 6 qualification prepares graduates for employment in diverse community and public health settings and provides a strong foundation for further progression into higher-level health programs.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national community health and public health standards. 3 Hands-on clinical and community-based training with real field exposure in households, facilities, and community units. 4 Guaranteed attachment placement in accredited hospitals, health centres, NGOs, and community health programs. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Training delivered by qualified community health, public health, and primary healthcare professionals. 8 Modern skills-lab and simulation-based training for health promotion, disease prevention, community diagnosis, and household health support. 9 Flexible study modes. 10 High employability across hospitals, NGOs, community health programs, public health projects, and primary healthcare facilities.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade C (Minus) and: English / Kiswahili: C (Minus) Biology / Biological Science: D+ (Plus) Mathematics / Chemistry/Physics / Home Science: D (Plain) OR Community Health Assistant Level 5 Qualification\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics and Practices Entrepreneurial Skills Nutrition in Community Health Microbiology and Parasitology Human Anatomy and Physiology Epidemiology in Community Health Basic Statistics in Community Health Fundamentals of Primary Health Care Health System Management Community Health Information System Maternal, Newborn and Child Health Care Community Health Education and Promotion Community Health Services Strategies Community Health Linkages Community-Based Health Care Gender, Disability and Vulnerable Groups Community Health Diagnosis and Partnership Common Diseases and Ailments First Aid Services Community Health Care Community Health Programmes Monitoring and Evaluation Community Health Research Environmental Health Geriatric Care\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a Six (6) month industrial field attachment in accredited community health departments, public health programs, NGOs, hospitals, or community-based health facilities. GoCare provides full placement support to ensure every student gains real, practical field experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Diploma in Community Health Assistant – Level 6 can work in: Community health organizations National and county government health departments Public health programs NGOs and international development agencies Hospitals and medical centres Community-based health projects Public health outreach and education programs Job roles include: Community Health Officer Public Health Specialist Health Program Manager Community Health Educator Community Health Coordinator Health Promotion Officer Community Health Assistant Public Health Assistant Maternal and Child Health Worker Community Health Volunteer Diverse roles in the medical and healthcare industry Total Duration 2½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts and become a licensed Community Health Assistant. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(24, 'Diploma in Mortuary Science ? Level 6 – GoCare Training Institute', 'diploma-in-mortuary-science-level-6', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Diploma in Mortuary Science &ndash; Level 6</strong> is an advanced, competency-based program designed to prepare learners for professional practice in mortuary operations, embalming, forensic support, post-mortem procedures, and funeral service management. The program equips students with the technical, scientific, ethical, and psychosocial skills required to work confidently in mortuaries, funeral homes, hospitals, and forensic environments.</p>\r\n            <p>Learners gain hands-on experience in deceased body management, mortuary microbiology, chemical preparation, anatomical preservation, and advanced embalming techniques. The course emphasizes professionalism, ethical conduct, legal compliance, and compassionate support for bereaved families.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">Graduates emerge as highly skilled mortuary technologists with strong employability both locally and internationally.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national mortuary science and postmortem care standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on practical training in real mortuaries, funeral homes, pathology units, and post-mortem facilities.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed attachment placement in accredited mortuary and funeral service institutions.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified morticians, pathologists, and forensic science professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for embalming, body preservation, reconstruction, and restorative procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Strong emphasis on ethics, dignity, cultural sensitivity, and professional conduct in death-care services.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">11</div>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across mortuaries, funeral homes, hospitals, pathology labs, and forensic departments.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade C- (Minus) and above, OR Certificate in Mortuary Science Level 5 (or related Level 5 qualification).</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Microbiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Law and Ethical Practice</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Premises Maintenance</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Preparation of Mortuary Chemicals</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Research and Innovation in Mortuary Practice</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Advanced Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Forensic Services and Pathology Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Biostatistics and Health Informatics</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Mortuary Research Methods</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Funeral Service Management</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Deceased Body Handling and Management</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Support for Bereaved Families</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Remains Embalming Techniques</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Post-Mortem Examination Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Museum Techniques for Anatomical Preservation</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a Six (6) month mortuary or funeral home attachment. GoCare provides full placement support to ensure every student gains real practical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Diploma in Mortuary Science &ndash; Level 6 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"building\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuaries and funeral homes</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals and medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"microscope\" style=\"color: var(--o); flex-shrink: 0;\"></i> Forensic laboratories</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"file-text\" style=\"color: var(--o); flex-shrink: 0;\"></i> Pathology departments</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"landmark\" style=\"color: var(--o); flex-shrink: 0;\"></i> Government and private morgues</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"briefcase\" style=\"color: var(--o); flex-shrink: 0;\"></i> Funeral service companies</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"archive\" style=\"color: var(--o); flex-shrink: 0;\"></i> Museums and anatomical preservation facilities</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuary Attendant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuary Technologist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Embalmer</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Post-Mortem Technician</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Forensic Support Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Funeral Service Manager</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Anatomical Preservation Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Mortuary Operations Supervisor</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in the medical, forensic, and funeral service sectors.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">2½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts, gain advanced mortuary skills, and become licensed.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Diploma in Mortuary Science – Level 6 is an advanced, competency-based program designed to prepare learners for professional practice in mortuary operations, embalming, forensic support, post-mortem procedures, and funeral service management. The program equips students with the technical, scientific, ethical, and psychosocial skills required to work confidently in mortuaries, funeral homes, hospitals, and forensic environments. Learners gain hands-on experience in deceased body management, mortuary microbiology, chemical preparation, anatomical preservation, and advanced embalming techniques. The course emphasizes professionalism, ethical conduct, legal compliance, and compassionate support for bereaved families. Graduates emerge as highly skilled mortuary technologists with strong employability both locally and internationally.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national mortuary science and postmortem care standards. 3 Hands-on practical training in real mortuaries, funeral homes, pathology units, and post-mortem facilities. 4 Guaranteed attachment placement in accredited mortuary and funeral service institutions. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Training delivered by qualified morticians, pathologists, and forensic science professionals. 8 Modern skills-lab and simulation-based training for embalming, body preservation, reconstruction, and restorative procedures. 9 Strong emphasis on ethics, dignity, cultural sensitivity, and professional conduct in death-care services. 10 Flexible study modes. 11 High employability in Kenya and abroad across mortuaries, funeral homes, hospitals, pathology labs, and forensic departments.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade C- (Minus) and above, OR Certificate in Mortuary Science Level 5 (or related Level 5 qualification).\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics and Professional Conduct Entrepreneurial Skills Mortuary Microbiology Mortuary Law and Ethical Practice Basic Human Anatomy and Physiology Mortuary Premises Maintenance Preparation of Mortuary Chemicals Research and Innovation in Mortuary Practice Advanced Human Anatomy and Physiology Forensic Services and Pathology Support Biostatistics and Health Informatics Mortuary Research Methods Funeral Service Management Deceased Body Handling and Management Psychosocial Support for Bereaved Families Human Remains Embalming Techniques Post-Mortem Examination Procedures Museum Techniques for Anatomical Preservation\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a Six (6) month mortuary or funeral home attachment. GoCare provides full placement support to ensure every student gains real practical experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates of the Diploma in Mortuary Science – Level 6 can work in: Mortuaries and funeral homes Hospitals and medical centres Forensic laboratories Pathology departments Government and private morgues Funeral service companies Museums and anatomical preservation facilities Job roles include: Mortuary Attendant Mortuary Technologist Embalmer Post-Mortem Technician Forensic Support Technician Funeral Service Manager Anatomical Preservation Technician Mortuary Operations Supervisor This qualification opens doors to diverse opportunities in the medical, forensic, and funeral service sectors. Total Duration 2½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts, gain advanced mortuary skills, and become licensed. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(25, 'Diploma in Orthopaedic and Trauma Medicine ? Level 6 – GoCare Training Institute', 'diploma-in-orthopaedic-and-trauma-medicine-level-6', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Diploma in Orthopaedic &amp; Trauma Medicine &ndash; Level 6</strong> is an advanced, competency-based program that prepares learners to provide professional orthopaedic and trauma care in hospitals, emergency units, operating theatres, and orthopaedic wards.</p>\r\n            <p>The program equips trainees with specialized skills in managing musculoskeletal injuries, fractures, dislocations, soft tissue trauma, orthopaedic conditions, and emergency care. Learners also gain competencies in surgical support, hospital procedures, medical-legal ethics, health promotion, and administrative management within orthopaedic and trauma facilities.</p>\r\n            <p>Through structured clinical placements, students work alongside orthopaedic surgeons, trauma specialists, emergency teams, and rehabilitation professionals, gaining real-world experience in high-demand healthcare environments.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">Graduates emerge as highly skilled Orthopaedic &amp; Trauma Medicine Technologists, ready for employment locally and internationally.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national orthopaedic and trauma care standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Hands-on clinical training with real patient exposure in orthopaedic, trauma, emergency, and rehabilitation units.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement by the college.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Training delivered by qualified orthopaedic, trauma, and emergency-care professionals.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Modern skills-lab and simulation-based training for casting, splinting, immobilization, and trauma procedures.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">Flexible study modes.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">10</div>\r\n                <p style=\"margin: 0;\">High employability in Kenya and abroad across hospitals, trauma centres, orthopaedic clinics, and emergency departments.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600; margin-bottom: 8px;\">KCSE Mean Grade C (Plain) and:</p>\r\n                  <ul style=\"list-style: none; padding: 0; margin-left: 10px;\">\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> C (Plain) in English / Kiswahili</li>\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> C (Plain) in Biology</li>\r\n                    <li style=\"margin-bottom: 6px; display: flex; gap: 10px;\"><i data-lucide=\"minus\" style=\"color: var(--o); width: 14px;\"></i> C- (Minus) in any one of Mathematics / Physics / Chemistry</li>\r\n                  </ul>\r\n                  <p style=\"margin: 15px 0 5px 0; font-size: 14px; font-weight: bold; color: var(--o);\">OR</p>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">Certificate in Orthopaedic & Trauma Medicine Level 5 (or related Level 5 qualification)</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Professional Conduct</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> First Aid Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy &amp; Physiology I</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Hospital Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Psychosocial Healthcare Support</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy &amp; Physiology II</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Medical-Legal Ethics</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Common Diseases</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Health Promotion Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Principles of Action Research</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Emergency Care in Disaster Incidents</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Soft Tissue Injuries</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Orthopaedic Conditions I</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Fractures and Dislocations</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Orthopaedic Conditions II</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Administrative Services in Orthopaedic &amp; Trauma Medicine</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Orthopaedic &amp; Trauma Unit</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Orthopaedic &amp; Trauma Surgical Procedures</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n          \r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Hospital Attachment</h2>\r\n            <p>All learners undertake a Six (6) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Diploma in Orthopaedic &amp; Trauma Medicine &ndash; Level 6 can work in:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"hospital\" style=\"color: var(--o); flex-shrink: 0;\"></i> Hospitals and medical centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"activity\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic wards and trauma units</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"alert-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Emergency and casualty departments</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"scissors\" style=\"color: var(--o); flex-shrink: 0;\"></i> Operating theatres</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"users\" style=\"color: var(--o); flex-shrink: 0;\"></i> Rehabilitation and physiotherapy centres</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"truck\" style=\"color: var(--o); flex-shrink: 0;\"></i> Ambulance and emergency response teams</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"heart-pulse\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic clinics and surgical centres</li>\r\n              </ul>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\"><strong>Job roles include:</strong></p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic &amp; Trauma Medicine Technologist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Trauma Care Specialist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic Clinical Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Emergency &amp; Disaster Response Technician</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Plaster Technician / Cast Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic Surgical Support Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Orthopaedic Ward Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Rehabilitation Support Technician</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">2½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Career Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts and become a licensed Orthopaedic &amp; Trauma Medicine Technologist.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Diploma in Orthopaedic & Trauma Medicine – Level 6 is an advanced, competency-based program that prepares learners to provide professional orthopaedic and trauma care in hospitals, emergency units, operating theatres, and orthopaedic wards. The program equips trainees with specialized skills in managing musculoskeletal injuries, fractures, dislocations, soft tissue trauma, orthopaedic conditions, and emergency care. Learners also gain competencies in surgical support, hospital procedures, medical-legal ethics, health promotion, and administrative management within orthopaedic and trauma facilities. Through structured clinical placements, students work alongside orthopaedic surgeons, trauma specialists, emergency teams, and rehabilitation professionals, gaining real-world experience in high-demand healthcare environments. Graduates emerge as highly skilled Orthopaedic & Trauma Medicine Technologists, ready for employment locally and internationally.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national orthopaedic and trauma care standards. 3 Hands-on clinical training with real patient exposure in orthopaedic, trauma, emergency, and rehabilitation units. 4 Guaranteed hospital attachment placement by the college. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Training delivered by qualified orthopaedic, trauma, and emergency-care professionals. 8 Modern skills-lab and simulation-based training for casting, splinting, immobilization, and trauma procedures. 9 Flexible study modes. 10 High employability in Kenya and abroad across hospitals, trauma centres, orthopaedic clinics, and emergency departments.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade C (Plain) and: C (Plain) in English / Kiswahili C (Plain) in Biology C- (Minus) in any one of Mathematics / Physics / Chemistry OR Certificate in Orthopaedic & Trauma Medicine Level 5 (or related Level 5 qualification)\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics and Professional Conduct Entrepreneurial Skills First Aid Services Human Anatomy & Physiology I Basic Hospital Procedures Psychosocial Healthcare Support Human Anatomy & Physiology II Medical-Legal Ethics Common Diseases Health Promotion Services Principles of Action Research Emergency Care in Disaster Incidents Management of Soft Tissue Injuries Management of Orthopaedic Conditions I Management of Fractures and Dislocations Management of Orthopaedic Conditions II Administrative Services in Orthopaedic & Trauma Medicine Management of Orthopaedic & Trauma Unit Orthopaedic & Trauma Surgical Procedures\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"All learners undertake a Six (6) month hospital attachment in a hospital. GoCare provides full placement support to ensure every student gains real clinical experience.\", \"heading\": \"Hospital Attachment\"}, {\"body\": \"Graduates of the Diploma in Orthopaedic & Trauma Medicine – Level 6 can work in: Hospitals and medical centres Orthopaedic wards and trauma units Emergency and casualty departments Operating theatres Rehabilitation and physiotherapy centres Ambulance and emergency response teams Orthopaedic clinics and surgical centres Job roles include: Orthopaedic & Trauma Medicine Technologist Trauma Care Specialist Orthopaedic Clinical Assistant Emergency & Disaster Response Technician Plaster Technician / Cast Technician Orthopaedic Surgical Support Technician Orthopaedic Ward Technician Rehabilitation Support Technician Total Duration 2½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts and become a licensed Orthopaedic & Trauma Medicine Technologist. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(26, 'Diploma in Perioperative Theatre Technology ? Level 6 – GoCare Training Institute', 'diploma-in-perioperative-theatre-technology-level-6', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          \r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The <strong>Diploma in Perioperative Theatre Technology &ndash; Level 6</strong> provides advanced, comprehensive training for learners preparing to work in surgical and perioperative environments. The program equips students with in-depth knowledge of human anatomy and physiology, perioperative care processes, surgical procedures, patient safety, infection prevention, and operating theatre coordination.</p>\r\n            <p>Learners gain hands-on skills in the preparation, management, and maintenance of theatre instruments, equipment, and operating room systems. The course emphasizes preoperative, intraoperative, and postoperative care, surgical team support, theatre safety, and adherence to medical-legal and ethical standards.</p>\r\n            <div style=\"background: rgba(237, 116, 37, 0.05); border-left: 4px solid var(--o); padding: 20px; border-radius: 4px; margin-top: 20px;\">\r\n              <p style=\"margin: 0; font-style: italic; color: var(--dark);\">Graduates are trained to support surgeons, anaesthetists, nurses, and other healthcare professionals in delivering safe, efficient, and high-quality surgical care within hospital operating theatres.</p>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <div style=\"display: grid; gap: 15px;\">\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">1</div>\r\n                <p style=\"margin: 0;\">Fully accredited and licensed medical and health sciences training institution.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">2</div>\r\n                <p style=\"margin: 0;\">Competency-based TVET CDACC curriculum aligned with national perioperative standards.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">3</div>\r\n                <p style=\"margin: 0;\">Advanced hands-on clinical training in real operating theatres, recovery rooms, and sterilization units.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">4</div>\r\n                <p style=\"margin: 0;\">Guaranteed hospital attachment placement with supervised perioperative rotations.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">5</div>\r\n                <p style=\"margin: 0;\">Government and regulator-recognized qualifications, certification, and practice licensure.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">6</div>\r\n                <p style=\"margin: 0;\">Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA).</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">7</div>\r\n                <p style=\"margin: 0;\">Highly experienced perioperative and surgical-theatre faculty.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">8</div>\r\n                <p style=\"margin: 0;\">Modern simulation labs for instrument handling, aseptic techniques, and theatre workflow.</p>\r\n              </div>\r\n              <div style=\"display: flex; gap: 15px; align-items: flex-start;\">\r\n                <div style=\"background: var(--o); color: #F5F0E8; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-weight: bold;\">9</div>\r\n                <p style=\"margin: 0;\">High employability across surgical, perioperative, and specialized medical facilities.</p>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #fcfcfc; padding: 30px; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px; align-items: center;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0; width: 28px; height: 28px;\"></i>\r\n                <div>\r\n                  <p style=\"margin: 0; font-size: 16px; color: var(--dark); font-weight: 600;\">KCSE Mean Grade C (Plain) and above, or Certificate in Perioperative Theatre Technology Level 5.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 50px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competence)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px; background: #f8fafc; padding: 25px; border-radius: 8px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Human Anatomy and Physiology</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Prevention of Nosocomial Infections</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of First Aid Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Common Diseases</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Execution of Perioperative Theatre Safety Precautions</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Work Ethics and Practices</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Medical-Legal Ethics in POTT</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of Perioperative Theatre Technical Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Basic Hospital Procedures</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Entrepreneurial Skills</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Maintenance of Perioperative Theatre Instruments and Apparatus</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of Health Education and Promotion Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Participation in Perioperative Theatre Clinical Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Provision of Psychosocial Health Support Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Execution of Perioperative Theatre Administrative Services</li>\r\n                <li style=\"margin-bottom: 12px; display: flex; gap: 10px; align-items: flex-start;\"><i data-lucide=\"chevron-right\" style=\"color: var(--o); flex-shrink: 0; width: 18px; margin-top: 3px;\"></i> Management of Perioperative Theatre Resources</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 30px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates of the Diploma in Perioperative Theatre Technology &ndash; Level 6 are highly sought after and can work in hospitals, medical centres, surgical theatres, specialized surgical units, healthcare facilities, medical equipment and instrument companies, and surgical tools and equipment manufacturing industries.</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Perioperative Theatre Technician / Technologist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Surgical Technologist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Operating Room Assistant</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Anaesthetist Assistant</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Operating Theatre Equipment Technician</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Theatre Support Specialist</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check\" style=\"color: var(--o); flex-shrink: 0;\"></i> Surgical Instrument Technician</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px; font-weight: 500; color: var(--dark);\">This qualification opens doors to diverse opportunities in the medical and healthcare industry.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px; border-top: 5px solid var(--o);\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">2½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center; background: var(--o); border-color: var(--o); color: #F5F0E8;\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center; border-color: var(--o); color: var(--o);\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 30px;\">\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Internal Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">External Assessment</span>\r\n                <strong style=\"color: var(--dark); display: block;\">TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0; border-bottom: 1px dashed #e2e8f0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Practicing License</span>\r\n                <strong style=\"color: var(--dark); display: block;\">KHPOA</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"padding: 12px 0;\">\r\n                <span style=\"color: var(--gray); font-size: 13px; display: block; margin-bottom: 4px;\">Certificates Awarded</span>\r\n                <strong style=\"color: var(--dark); display: block; font-size: 14px; line-height: 1.4;\">Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--dark); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center; position: relative; overflow: hidden;\">\r\n            <div style=\"position: absolute; top: -20px; right: -20px; width: 100px; height: 100px; background: var(--o); opacity: 0.1; border-radius: 50%;\"></div>\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px; position: relative; z-index: 2;\">Begin Your Journey Today</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px; font-size: 14px; position: relative; z-index: 2;\">Train with experts and become a licensed Perioperative Theatre Technologist.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: var(--o); background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 8px; position: relative; z-index: 2;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Diploma in Perioperative Theatre Technology – Level 6 provides advanced, comprehensive training for learners preparing to work in surgical and perioperative environments. The program equips students with in-depth knowledge of human anatomy and physiology, perioperative care processes, surgical procedures, patient safety, infection prevention, and operating theatre coordination. Learners gain hands-on skills in the preparation, management, and maintenance of theatre instruments, equipment, and operating room systems. The course emphasizes preoperative, intraoperative, and postoperative care, surgical team support, theatre safety, and adherence to medical-legal and ethical standards. Graduates are trained to support surgeons, anaesthetists, nurses, and other healthcare professionals in delivering safe, efficient, and high-quality surgical care within hospital operating theatres.\", \"heading\": \"Course Overview\"}, {\"body\": \"1 Fully accredited and licensed medical and health sciences training institution. 2 Competency-based TVET CDACC curriculum aligned with national perioperative standards. 3 Advanced hands-on clinical training in real operating theatres, recovery rooms, and sterilization units. 4 Guaranteed hospital attachment placement with supervised perioperative rotations. 5 Government and regulator-recognized qualifications, certification, and practice licensure. 6 Practicing license eligibility under the Kenya Health Professions Oversight Authority (KHPOA). 7 Highly experienced perioperative and surgical-theatre faculty. 8 Modern simulation labs for instrument handling, aseptic techniques, and theatre workflow. 9 High employability across surgical, perioperative, and specialized medical facilities.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"KCSE Mean Grade C (Plain) and above, or Certificate in Perioperative Theatre Technology Level 5.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Digital Literacy Human Anatomy and Physiology Prevention of Nosocomial Infections Provision of First Aid Services Communication Skills Common Diseases Execution of Perioperative Theatre Safety Precautions Work Ethics and Practices Medical-Legal Ethics in POTT Provision of Perioperative Theatre Technical Services Basic Hospital Procedures Entrepreneurial Skills Maintenance of Perioperative Theatre Instruments and Apparatus Provision of Health Education and Promotion Services Participation in Perioperative Theatre Clinical Services Provision of Psychosocial Health Support Services Execution of Perioperative Theatre Administrative Services Management of Perioperative Theatre Resources\", \"heading\": \"What You Will Learn (Units of Competence)\"}, {\"body\": \"Graduates of the Diploma in Perioperative Theatre Technology – Level 6 are highly sought after and can work in hospitals, medical centres, surgical theatres, specialized surgical units, healthcare facilities, medical equipment and instrument companies, and surgical tools and equipment manufacturing industries. Perioperative Theatre Technician / Technologist Surgical Technologist Operating Room Assistant Anaesthetist Assistant Operating Theatre Equipment Technician Theatre Support Specialist Surgical Instrument Technician This qualification opens doors to diverse opportunities in the medical and healthcare industry. Total Duration 2½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Practicing License KHPOA Certificates Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Train with experts and become a licensed Perioperative Theatre Technologist. 0703 115 502\", \"heading\": \"Begin Your Journey Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(27, 'Diploma in Social Work and Community Development ? Level 6 – GoCare Training Institute', 'diploma-in-social-work-and-community-development-level-6', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\">\r\n        <div class=\"course-body\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Diploma in Social Work &ndash; Level 6 is an advanced, nationally recognized qualification designed to prepare learners to become competent, ethical, and community-focused social work professionals.</p>\r\n            <p>This program equips trainees with the knowledge, skills, and practical competencies required to support individuals, families, and communities through social interventions, empowerment programs, advocacy, crisis response, rehabilitation, and community development initiatives.</p>\r\n            <p>Learners are trained to assess social issues, design and implement community programs, provide psychosocial support, manage community-based groups, coordinate social services, conduct social research, and participate in policy implementation. The curriculum blends theory, practical skills, and extensive field exposure to ensure graduates are job-ready and aligned with Kenya&#8217;s social development priorities.</p>\r\n            <p>This Level 6 qualification provides a strong foundation for careers in NGOs, government agencies, community organizations, and international development institutions, and serves as a pathway to higher-level social sciences and community development programs.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn (Units of Competency)</h2>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 15px;\">\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Digital Literacy</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Communication Skills</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Work Ethics & Professional Practice</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Entrepreneurship for Social Work</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Home-Based Care & Support</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Child Welfare Programs</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community-Based Groups Management</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Psychosocial Support Services</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Empowerment Strategies</li>\r\n              </ul>\r\n              <ul style=\"list-style: none; padding: 0;\">\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Social Work Case Management</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Advocacy & Lobbying in Social Work</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Disaster Preparedness & Response</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Social Work Service Management</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Resource Mobilization for Community Programs</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Rehabilitation & Reintegration Programs</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Community Project Management</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Social Policy Administration</li>\r\n                <li style=\"margin-bottom: 10px; display: flex; gap: 10px;\"><i data-lucide=\"check-circle\" style=\"color: var(--o); flex-shrink: 0;\"></i> Social Work Research</li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\">\r\n              <div class=\"req-item\">\r\n                <i data-lucide=\"check-circle-2\"></i>\r\n                <div>\r\n                  <strong>Academic Qualification</strong>\r\n                  <p>KCSE Mean Grade C- (Minus) or Level 5 Certificate in Social Work & Community Development.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study This Course at GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8;\">\r\n              <li>Fully accredited and licensed training institution.</li>\r\n              <li>Competency-based TVET CDACC curriculum aligned with national and global social development standards.</li>\r\n              <li>Hands-on practical training, community fieldwork, and real-world case exposure.</li>\r\n              <li>Guaranteed industrial attachment placement.</li>\r\n              <li>Government and regulatory recognized qualifications and certification.</li>\r\n              <li>Strong employability in NGOs, government, community organizations, and international development agencies.</li>\r\n              <li>Flexible study modes.</li>\r\n              <li>Highly experienced faculty and industry-aligned training.</li>\r\n              <li>Clear progression pathway to higher diploma and degree programs.</li>\r\n            </ul>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Industrial Attachment</h2>\r\n            <p>All learners undertake a Six (6) Month Industrial Field Attachment. GoCare provides full placement support to ensure every student gains real field experience.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>Graduates can work as:</p>\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\r\n              <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8;\">\r\n                <li>Social Worker</li>\r\n                <li>Community Development Officer</li>\r\n                <li>Child Welfare Officer</li>\r\n                <li>Community Mobilizer</li>\r\n                <li>Social Work Administrator</li>\r\n                <li>NGO Program Assistant / Officer</li>\r\n                <li>Community Health & Development Worker</li>\r\n              </ul>\r\n              <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8;\">\r\n                <li>Rehabilitation Support Worker</li>\r\n                <li>Youth and Women Empowerment Officer</li>\r\n                <li>Disaster Response & Humanitarian Worker</li>\r\n                <li>Project Assistant / Project Manager (entry-level)</li>\r\n                <li>Psychosocial Support Assistant</li>\r\n                <li>Community Outreach Coordinator</li>\r\n              </ul>\r\n            </div>\r\n            <p style=\"margin-top: 15px;\">This qualification opens doors to diverse opportunities in the social development, humanitarian, and community empowerment sectors.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">2½ Years</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\">Apply Online</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\"><i data-lucide=\"mail\"></i> Contact Admissions</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\">\r\n              <div class=\"side-info-item\">\r\n                <span>Internal Assessment</span>\r\n                <strong>GoCare Training Institute</strong>\r\n              </div>\r\n              <div class=\"side-info-item\">\r\n                <span>External Assessment</span>\r\n                <strong>TVET CDACC</strong>\r\n              </div>\r\n              <div class=\"side-info-item\">\r\n                <span>Certifications Awarded</span>\r\n                <strong>Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\">\r\n            <h4>Begin Your Career Today</h4>\r\n            <p>Our admissions team will guide you through the registration process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Diploma in Social Work – Level 6 is an advanced, nationally recognized qualification designed to prepare learners to become competent, ethical, and community-focused social work professionals. This program equips trainees with the knowledge, skills, and practical competencies required to support individuals, families, and communities through social interventions, empowerment programs, advocacy, crisis response, rehabilitation, and community development initiatives. Learners are trained to assess social issues, design and implement community programs, provide psychosocial support, manage community-based groups, coordinate social services, conduct social research, and participate in policy implementation. The curriculum blends theory, practical skills, and extensive field exposure to ensure graduates are job-ready and aligned with Kenya’s social development priorities. This Level 6 qualification provides a strong foundation for careers in NGOs, government agencies, community organizations, and international development institutions, and serves as a pathway to higher-level social sciences and community development programs.\", \"heading\": \"Course Overview\"}, {\"body\": \"Digital Literacy Communication Skills Work Ethics & Professional Practice Entrepreneurship for Social Work Home-Based Care & Support Child Welfare Programs Community-Based Groups Management Psychosocial Support Services Community Empowerment Strategies Social Work Case Management Advocacy & Lobbying in Social Work Disaster Preparedness & Response Social Work Service Management Resource Mobilization for Community Programs Rehabilitation & Reintegration Programs Community Project Management Social Policy Administration Social Work Research\", \"heading\": \"What You Will Learn (Units of Competency)\"}, {\"body\": \"Academic Qualification KCSE Mean Grade C- (Minus) or Level 5 Certificate in Social Work & Community Development.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"Fully accredited and licensed training institution. Competency-based TVET CDACC curriculum aligned with national and global social development standards. Hands-on practical training, community fieldwork, and real-world case exposure. Guaranteed industrial attachment placement. Government and regulatory recognized qualifications and certification. Strong employability in NGOs, government, community organizations, and international development agencies. Flexible study modes. Highly experienced faculty and industry-aligned training. Clear progression pathway to higher diploma and degree programs.\", \"heading\": \"Why Study This Course at GoCare?\"}, {\"body\": \"All learners undertake a Six (6) Month Industrial Field Attachment. GoCare provides full placement support to ensure every student gains real field experience.\", \"heading\": \"Industrial Attachment\"}, {\"body\": \"Graduates can work as: Social Worker Community Development Officer Child Welfare Officer Community Mobilizer Social Work Administrator NGO Program Assistant / Officer Community Health & Development Worker Rehabilitation Support Worker Youth and Women Empowerment Officer Disaster Response & Humanitarian Worker Project Assistant / Project Manager (entry-level) Psychosocial Support Assistant Community Outreach Coordinator This qualification opens doors to diverse opportunities in the social development, humanitarian, and community empowerment sectors. Total Duration 2½ Years Apply Online Contact Admissions Internal Assessment GoCare Training Institute External Assessment TVET CDACC Certifications Awarded Academic Transcripts, TVET CDACC Certificate, GoCare Completion Certificate\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Our admissions team will guide you through the registration process. 0703 115 502\", \"heading\": \"Begin Your Career Today\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(28, 'Heartsaver First Aid - American Heart Association · GoCare Training Institute', 'heartsaver-first-aid', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Heartsaver First Aid course equips learners with essential first aid skills for responding to common workplace, home and community emergencies. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response &mdash; skills required in hospitals, clinics, emergency units, workplaces and community settings.</p>\r\n            <p>This AHA-aligned program focuses on bleeding control, burns, fractures, allergic reactions, medical emergencies and early recognition of life-threatening conditions. Training is delivered through hands-on demonstrations, guided practice and real-life emergency scenarios at GoCare&rsquo;s Nairobi CBD and Thika Road (Ruiru) campuses.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study First Aid at GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Internationally recognized AHA certification.</li>\r\n              <li>Hands-on, simulation-based first aid training.</li>\r\n              <li>Training delivered by certified emergency care instructors.</li>\r\n              <li>Modern skills-lab with emergency response equipment.</li>\r\n              <li>Affordable, accessible pricing for students, corporates and the general public.</li>\r\n              <li>Flexible study modes (Day, Evening, Weekend).</li>\r\n              <li>Ideal for workplaces, schools, factories, caregivers and community responders.</li>\r\n              <li>High employability in Kenya and abroad.</li>\r\n              <li>Strong add-on qualification for all GoCare medical and health sciences programs.</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #f0f4f8; padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Open Entry</strong>\r\n                  <p style=\"margin: 0;\">No medical background required.</p>\r\n                </div>\r\n              </div>\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Eligibility</strong>\r\n                  <p style=\"margin: 0;\">KCPE or KCSE graduates and the general public.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Course Duration</h2>\r\n            <p style=\"font-size:1.05rem;\"><strong style=\"color:var(--o);\">One (1) Day</strong></p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Bleeding control</li>\r\n              <li>Burns, fractures and sprains</li>\r\n              <li>Allergic reactions and anaphylaxis</li>\r\n              <li>Seizures, fainting and diabetic emergencies</li>\r\n              <li>Stroke and heart attack recognition</li>\r\n              <li>Basic emergency response procedures</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Ideal For</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>General public</li>\r\n              <li>KCPE and KCSE graduates</li>\r\n              <li>Health care students</li>\r\n              <li>Caregivers</li>\r\n              <li>Corporates, schools and factories</li>\r\n              <li>Security personnel</li>\r\n              <li>Community responders</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Certifications Awarded</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>AHA Heartsaver First Aid eCard Certification</li>\r\n              <li>GoCare Completion Certificate</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>First Aid-certified graduates qualify for roles in:</p>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Schools and educational institutions</li>\r\n              <li>Corporate safety teams</li>\r\n              <li>Security and emergency response units</li>\r\n              <li>Community health programs</li>\r\n              <li>NGOs and humanitarian organizations</li>\r\n              <li>Home-based care and caregiving environments</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 12px;\">\r\n            <p style=\"font-style: italic; color: var(--dark);\">First Aid certification is a mandatory or preferred requirement in many workplaces and safety-sensitive environments.</p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li><strong>Option 1:</strong> Apply Online via the <a href=\"../apply.html\" style=\"color:var(--o);font-weight:600;\">application form</a>.</li>\r\n              <li><strong>Option 2:</strong> Visit Any GoCare Campus &mdash; Nairobi CBD or Thika Road (Ruiru).</li>\r\n              <li><strong>Admissions Line:</strong> 0703 115 502</li>\r\n            </ul>\r\n            <p style=\"margin-top: 20px;\">Begin your Heartsaver First Aid certification today and gain essential emergency response skills with GoCare Training Institute.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">1 Day</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply for Certification</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Us</a>\r\n            </div>\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Accreditation</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA (USA)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Certification</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA Heartsaver eCard</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n                <span style=\"color: var(--gray);\">Entry</span>\r\n                <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">Open Entry</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Heartsaver First Aid course equips learners with essential first aid skills for responding to common workplace, home and community emergencies. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response — skills required in hospitals, clinics, emergency units, workplaces and community settings. This AHA-aligned program focuses on bleeding control, burns, fractures, allergic reactions, medical emergencies and early recognition of life-threatening conditions. Training is delivered through hands-on demonstrations, guided practice and real-life emergency scenarios at GoCare’s Nairobi CBD and Thika Road (Ruiru) campuses.\", \"heading\": \"Course Overview\"}, {\"body\": \"Internationally recognized AHA certification. Hands-on, simulation-based first aid training. Training delivered by certified emergency care instructors. Modern skills-lab with emergency response equipment. Affordable, accessible pricing for students, corporates and the general public. Flexible study modes (Day, Evening, Weekend). Ideal for workplaces, schools, factories, caregivers and community responders. High employability in Kenya and abroad. Strong add-on qualification for all GoCare medical and health sciences programs.\", \"heading\": \"Why Study First Aid at GoCare?\"}, {\"body\": \"Open Entry No medical background required. Eligibility KCPE or KCSE graduates and the general public.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"One (1) Day\", \"heading\": \"Course Duration\"}, {\"body\": \"Bleeding control Burns, fractures and sprains Allergic reactions and anaphylaxis Seizures, fainting and diabetic emergencies Stroke and heart attack recognition Basic emergency response procedures\", \"heading\": \"What You Will Learn\"}, {\"body\": \"General public KCPE and KCSE graduates Health care students Caregivers Corporates, schools and factories Security personnel Community responders\", \"heading\": \"Ideal For\"}, {\"body\": \"AHA Heartsaver First Aid eCard Certification GoCare Completion Certificate\", \"heading\": \"Certifications Awarded\"}, {\"body\": \"First Aid-certified graduates qualify for roles in: Schools and educational institutions Corporate safety teams Security and emergency response units Community health programs NGOs and humanitarian organizations Home-based care and caregiving environments First Aid certification is a mandatory or preferred requirement in many workplaces and safety-sensitive environments.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Option 1: Apply Online via the application form. Option 2: Visit Any GoCare Campus — Nairobi CBD or Thika Road (Ruiru). Admissions Line: 0703 115 502 Begin your Heartsaver First Aid certification today and gain essential emergency response skills with GoCare Training Institute. Total Duration 1 Day Apply for Certification Contact Us Accreditation AHA (USA) Certification AHA Heartsaver eCard Entry Open Entry\", \"heading\": \"How to Apply\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(29, 'Pediatric Advanced Life Support (PALS) - American Heart Association · GoCare Training Institute', 'pediatric-advanced-life-support-pals', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Course Overview</h2>\r\n            <p>The Pediatric Advanced Life Support (PALS) course equips healthcare providers with the knowledge and skills required to recognize and manage critically ill infants and children. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response &mdash; skills required in hospitals, clinics, emergency units, workplaces and community settings.</p>\r\n            <p>This AHA-aligned program focuses on pediatric assessment, respiratory and shock management, cardiac arrest algorithms and effective team dynamics. Training is delivered through hands-on simulations, case-based learning and pediatric emergency scenarios at GoCare&rsquo;s Nairobi CBD and Thika Road (Ruiru) campuses.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Study PALS at GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Internationally recognized AHA certification.</li>\r\n              <li>Hands-on, simulation-based pediatric emergency training.</li>\r\n              <li>Training delivered by certified pediatric emergency care instructors.</li>\r\n              <li>Modern skills-lab with pediatric manikins and emergency equipment.</li>\r\n              <li>Affordable, accessible pricing for healthcare professionals.</li>\r\n              <li>Flexible study modes (Day, Evening, Weekend).</li>\r\n              <li>Ideal for pediatric units, maternity, emergency and ICU staff.</li>\r\n              <li>High employability in Kenya and abroad.</li>\r\n              <li>Strong add-on qualification for all GoCare medical and health sciences programs.</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #f0f4f8; padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Entry Requirements</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Healthcare Background</strong>\r\n                  <p style=\"margin: 0;\">Student or qualified healthcare professional.</p>\r\n                </div>\r\n              </div>\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Recommended</strong>\r\n                  <p style=\"margin: 0;\">BLS knowledge recommended.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Course Duration</h2>\r\n            <p style=\"font-size:1.05rem;\"><strong style=\"color:var(--o);\">3 Days</strong></p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">What You Will Learn</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Pediatric assessment and triage</li>\r\n              <li>Respiratory distress and shock management</li>\r\n              <li>Pediatric cardiac arrest algorithms</li>\r\n              <li>Medication and fluid management</li>\r\n              <li>Pediatric emergency teamwork</li>\r\n              <li>Scenario-based pediatric resuscitation</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Ideal For</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Pediatric and neonatal nurses</li>\r\n              <li>Clinical officers and doctors</li>\r\n              <li>Emergency and ICU staff</li>\r\n              <li>Maternity and child health providers</li>\r\n              <li>Senior health sciences students</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Certifications Awarded</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>AHA PALS Provider eCard Certification</li>\r\n              <li>GoCare Completion Certificate</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>PALS-certified graduates qualify for roles in:</p>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Pediatric and neonatal units</li>\r\n              <li>Emergency departments</li>\r\n              <li>Intensive care units</li>\r\n              <li>Maternity and child health programs</li>\r\n              <li>Ambulance and rescue services</li>\r\n              <li>Hospitals and clinics</li>\r\n              <li>International healthcare facilities</li>\r\n            </ul>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 12px;\">\r\n            <p style=\"font-style: italic; color: var(--dark);\">PALS certification is a mandatory or preferred requirement in many pediatric and emergency care settings worldwide.</p>\r\n          </section>\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">How to Apply</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li><strong>Option 1:</strong> Apply Online via the <a href=\"../apply.html\" style=\"color:var(--o);font-weight:600;\">application form</a>.</li>\r\n              <li><strong>Option 2:</strong> Visit Any GoCare Campus &mdash; Nairobi CBD or Thika Road (Ruiru).</li>\r\n              <li><strong>Admissions Line:</strong> 0703 115 502</li>\r\n            </ul>\r\n            <p style=\"margin-top: 20px;\">Begin your Pediatric Advanced Life Support (PALS) certification today and strengthen your pediatric emergency care skills with GoCare Training Institute.</p>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n            <div class=\"sidebar-duration-box\" style=\"background: linear-gradient(135deg, #fff7ed, #fdf1e4); border: 1px solid #fbdcb5; border-radius: 12px; padding: 22px 24px; margin-bottom: 22px; text-align: center;\">\r\n              <span style=\"display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--gray); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\"><i data-lucide=\"clock\" style=\"width: 14px; height: 14px;\"></i> Total Duration</span>\r\n              <div style=\"font-family: \'Outfit\', sans-serif; font-size: 2.1rem; font-weight: 800; color: var(--dark); line-height: 1.1;\">3 Days</div>\r\n            </div>\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply for Certification</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Us</a>\r\n            </div>\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Accreditation</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA (USA)</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Certification</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">AHA PALS eCard</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n                <span style=\"color: var(--gray);\">Entry</span>\r\n                <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">Healthcare Background</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"The Pediatric Advanced Life Support (PALS) course equips healthcare providers with the knowledge and skills required to recognize and manage critically ill infants and children. Learners gain competencies in CPR, emergency cardiovascular care, pediatric life support and first aid response — skills required in hospitals, clinics, emergency units, workplaces and community settings. This AHA-aligned program focuses on pediatric assessment, respiratory and shock management, cardiac arrest algorithms and effective team dynamics. Training is delivered through hands-on simulations, case-based learning and pediatric emergency scenarios at GoCare’s Nairobi CBD and Thika Road (Ruiru) campuses.\", \"heading\": \"Course Overview\"}, {\"body\": \"Internationally recognized AHA certification. Hands-on, simulation-based pediatric emergency training. Training delivered by certified pediatric emergency care instructors. Modern skills-lab with pediatric manikins and emergency equipment. Affordable, accessible pricing for healthcare professionals. Flexible study modes (Day, Evening, Weekend). Ideal for pediatric units, maternity, emergency and ICU staff. High employability in Kenya and abroad. Strong add-on qualification for all GoCare medical and health sciences programs.\", \"heading\": \"Why Study PALS at GoCare?\"}, {\"body\": \"Healthcare Background Student or qualified healthcare professional. Recommended BLS knowledge recommended.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"3 Days\", \"heading\": \"Course Duration\"}, {\"body\": \"Pediatric assessment and triage Respiratory distress and shock management Pediatric cardiac arrest algorithms Medication and fluid management Pediatric emergency teamwork Scenario-based pediatric resuscitation\", \"heading\": \"What You Will Learn\"}, {\"body\": \"Pediatric and neonatal nurses Clinical officers and doctors Emergency and ICU staff Maternity and child health providers Senior health sciences students\", \"heading\": \"Ideal For\"}, {\"body\": \"AHA PALS Provider eCard Certification GoCare Completion Certificate\", \"heading\": \"Certifications Awarded\"}, {\"body\": \"PALS-certified graduates qualify for roles in: Pediatric and neonatal units Emergency departments Intensive care units Maternity and child health programs Ambulance and rescue services Hospitals and clinics International healthcare facilities PALS certification is a mandatory or preferred requirement in many pediatric and emergency care settings worldwide.\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Option 1: Apply Online via the application form. Option 2: Visit Any GoCare Campus — Nairobi CBD or Thika Road (Ruiru). Admissions Line: 0703 115 502 Begin your Pediatric Advanced Life Support (PALS) certification today and strengthen your pediatric emergency care skills with GoCare Training Institute. Total Duration 3 Days Apply for Certification Contact Us Accreditation AHA (USA) Certification AHA PALS eCard Entry Healthcare Background\", \"heading\": \"How to Apply\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(30, 'Skill Development Council (SDC) – Canada Certification – GoCare Training Institute', 'sdc-canada-certification', NULL, NULL, '<div class=\"wrap\">\r\n      <div class=\"course-grid-layout\" style=\"display: grid; grid-template-columns: 1fr 350px; gap: 40px; align-items: start;\">\r\n        <div class=\"course-body\" style=\"background: #fcfcfc; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);\">\r\n          <section class=\"course-description\">\r\n            <h2 class=\"course-sec-title\">Overview</h2>\r\n            <p>GoCare Training Institute offers Canada-aligned curriculum training, examination, and certification through the Skill Development Council (SDC) &ndash; Canada, a globally recognized credentialing body that validates professional competence in healthcare and caregiving.</p>\r\n            <p>This pathway provides career, professional, and international recognition, enabling graduates to qualify for healthcare roles across Canada, USA, Europe, the Middle East, Asia, and Africa.</p>\r\n          </section>\r\n\r\n          <section class=\"modules-list\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">SDC Canada Training, Examination & Certification Options</h2>\r\n            <p>Learners may pursue any of the following Canada-based certification programs:</p>\r\n            <div class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">01</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Certificate in Nursing Assistant</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">02</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Certificate in Health Care Assistant</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">03</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Certificate in Professional Caregiver</h4>\r\n              </div>\r\n            </div>\r\n            <div class=\"module-item\" style=\"display: flex; gap: 20px; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #eee;\">\r\n              <div class=\"module-num\" style=\"font-size: 24px; font-weight: bold; color: var(--o); opacity: 0.3;\">04</div>\r\n              <div class=\"module-info\">\r\n                <h4 style=\"margin: 0; font-size: 18px; color: var(--dark);\">Advanced Certificate in Health Care Assistant</h4>\r\n              </div>\r\n            </div>\r\n            <p style=\"margin-top: 20px;\">These certifications strengthen global employability and align with international healthcare support standards.</p>\r\n          </section>\r\n\r\n          <section class=\"requirements-box\" style=\"margin-top: 40px; background: #f0f4f8; padding: 30px; border-radius: 8px;\">\r\n            <h2 class=\"course-sec-title\">Who Qualifies for Skill Development Council (SDC) &ndash; Canada Certification?</h2>\r\n            <div class=\"requirements-grid\" style=\"display: grid; gap: 20px;\">\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Qualification</strong>\r\n                  <p style=\"margin: 0;\">Medical and healthcare professionals.</p>\r\n                </div>\r\n              </div>\r\n              <div class=\"req-item\" style=\"display: flex; gap: 15px;\">\r\n                <i data-lucide=\"check-circle-2\" style=\"color: var(--o); flex-shrink: 0;\"></i>\r\n                <div>\r\n                  <strong style=\"display: block; color: var(--o); margin-bottom: 5px;\">Requirements</strong>\r\n                  <p style=\"margin: 0;\">A relevant Certificate, Diploma, or Degree qualification in a medical or healthcare field.</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <p style=\"margin-top: 20px; font-style: italic;\">This ensures that only trained professionals pursue SDC Canada&#8217;s internationally recognized credentials.</p>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Why Choose Skill Development Council (SDC) &ndash; Canada Certification Through GoCare?</h2>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Canada-based accredited curriculum.</li>\r\n              <li>Internationally recognized certification.</li>\r\n              <li>Enhances global employability and career mobility.</li>\r\n              <li>Ideal for migration-linked healthcare opportunities.</li>\r\n              <li>Complements GoCare&#8217;s accredited medical and health sciences programs.</li>\r\n              <li>Strengthens professional credibility for overseas roles.</li>\r\n            </ul>\r\n          </section>\r\n\r\n          <section class=\"course-description\" style=\"margin-top: 40px;\">\r\n            <h2 class=\"course-sec-title\">Career Opportunities</h2>\r\n            <p>SDC-certified graduates qualify for roles such as:</p>\r\n            <ul style=\"list-style: disc; margin-left: 20px; line-height: 1.8; color: var(--dark);\">\r\n              <li>Nursing Assistant</li>\r\n              <li>Health Care Assistant</li>\r\n              <li>Professional Caregiver</li>\r\n              <li>Home Support Worker</li>\r\n              <li>Long-Term Care Assistant</li>\r\n              <li>Community Health Support Worker</li>\r\n            </ul>\r\n          </section>\r\n        </div>\r\n\r\n        <aside class=\"course-sidebar\">\r\n          <div class=\"sidebar-card\" style=\"background: #fcfcfc; padding: 30px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin-bottom: 30px;\">\r\n            <div class=\"sidebar-btns\" style=\"display: grid; gap: 15px;\">\r\n              <a href=\"../apply.html\" class=\"btn btn-primary\" style=\"text-align: center;\">Apply for Certification</a>\r\n              <a href=\"../contact.html\" class=\"btn btn-outline\" style=\"text-align: center;\"><i data-lucide=\"mail\"></i> Contact Us</a>\r\n            </div>\r\n\r\n            <div class=\"sidebar-info-list\" style=\"margin-top: 25px;\">\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px dashed #eee;\">\r\n                <span style=\"color: var(--gray);\">Accreditation</span>\r\n                <strong style=\"color: var(--dark); text-align: right;\">SDC Canada</strong>\r\n              </div>\r\n              <div class=\"side-info-item\" style=\"display: flex; justify-content: space-between; padding: 12px 0;\">\r\n                <span style=\"color: var(--gray);\">Global Reach</span>\r\n                <strong style=\"color: var(--dark); text-align: right; max-width: 60%;\">Canada, USA, Europe, Middle East, Asia, Africa</strong>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"help-card\" style=\"background: var(--o); color: #F5F0E8; padding: 30px; border-radius: 12px; text-align: center;\">\r\n            <h4 style=\"color: #F5F0E8; margin-bottom: 10px;\">Need Help?</h4>\r\n            <p style=\"color: rgba(255,255,255,0.8); margin-bottom: 20px;\">Our team is ready to guide you through the process.</p>\r\n            <a href=\"tel:+254703115502\" class=\"help-link\" style=\"display: inline-flex; align-items: center; gap: 10px; font-size: 20px; font-weight: bold; color: #F5F0E8;\"><i data-lucide=\"phone-call\"></i> 0703 115 502</a>\r\n          </div>\r\n        </aside>\r\n      </div>\r\n    </div>', '[{\"body\": \"GoCare Training Institute offers Canada-aligned curriculum training, examination, and certification through the Skill Development Council (SDC) – Canada, a globally recognized credentialing body that validates professional competence in healthcare and caregiving. This pathway provides career, professional, and international recognition, enabling graduates to qualify for healthcare roles across Canada, USA, Europe, the Middle East, Asia, and Africa.\", \"heading\": \"Overview\"}, {\"body\": \"Learners may pursue any of the following Canada-based certification programs: 01\", \"heading\": \"SDC Canada Training, Examination & Certification Options\"}, {\"body\": \"02\", \"heading\": \"Certificate in Nursing Assistant\"}, {\"body\": \"03\", \"heading\": \"Certificate in Health Care Assistant\"}, {\"body\": \"04\", \"heading\": \"Certificate in Professional Caregiver\"}, {\"body\": \"These certifications strengthen global employability and align with international healthcare support standards.\", \"heading\": \"Advanced Certificate in Health Care Assistant\"}, {\"body\": \"Qualification Medical and healthcare professionals. Requirements A relevant Certificate, Diploma, or Degree qualification in a medical or healthcare field. This ensures that only trained professionals pursue SDC Canada’s internationally recognized credentials.\", \"heading\": \"Who Qualifies for Skill Development Council (SDC) – Canada Certification?\"}, {\"body\": \"Canada-based accredited curriculum. Internationally recognized certification. Enhances global employability and career mobility. Ideal for migration-linked healthcare opportunities. Complements GoCare’s accredited medical and health sciences programs. Strengthens professional credibility for overseas roles.\", \"heading\": \"Why Choose Skill Development Council (SDC) – Canada Certification Through GoCare?\"}, {\"body\": \"SDC-certified graduates qualify for roles such as: Nursing Assistant Health Care Assistant Professional Caregiver Home Support Worker Long-Term Care Assistant Community Health Support Worker Apply for Certification Contact Us Accreditation SDC Canada Global Reach Canada, USA, Europe, Middle East, Asia, Africa\", \"heading\": \"Career Opportunities\"}, {\"body\": \"Our team is ready to guide you through the process. 0703 115 502\", \"heading\": \"Need Help?\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `courses` (`id`, `title`, `slug`, `school`, `summary`, `content`, `sections`, `image`, `is_published`, `created_at`, `updated_at`) VALUES
(31, 'Second Course Sponsorship – GoCare Training Institute', 'second-course-sponsorship', NULL, NULL, '<!-- COOKIE CONSENT -->\r\n  <div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\r\n    <div class=\"ck-inner\">\r\n      <div class=\"ck-left\">\r\n        <div class=\"ck-icon-wrap\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n            <path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/>\r\n            <path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/>\r\n          </svg>\r\n        </div>\r\n        <div class=\"ck-copy\">\r\n          <strong>We use cookies</strong>\r\n          <p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"ck-actions\">\r\n        <button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button>\r\n        <button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button>\r\n        <button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- -- NAVBAR ---------------------------------------- -->\r\n\r\n\r\n  <!-- -- SUB BAR --------------------------------------- -->\r\n  <div class=\"subbar\">\r\n    <div class=\"wrap subbar-inner\">\r\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\r\n      <div class=\"subbar-portals\">\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n\r\n  \r\n\r\n  \r\n\r\n  <!-- -- COURSE HERO ----------------------------------- -->\r\n  \r\n\r\n  \r\n\r\n  <!-- -- COURSE CONTENT -------------------------------- -->\r\n  <div class=\"scs-page\">\r\n\r\n    <!-- Stats bar -->\r\n    <div class=\"scs-stats\">\r\n      <div class=\"wrap\">\r\n        <div class=\"scs-stats-inner\">\r\n          <div class=\"scs-stat\">\r\n            <span class=\"scs-stat-num\">2</span>\r\n            <span class=\"scs-stat-lbl\">Qualifications</span>\r\n          </div>\r\n          <div class=\"scs-stat\">\r\n            <span class=\"scs-stat-num\">1</span>\r\n            <span class=\"scs-stat-lbl\">Tuition Fee</span>\r\n          </div>\r\n          <div class=\"scs-stat\">\r\n            <span class=\"scs-stat-num\">3</span>\r\n            <span class=\"scs-stat-lbl\">Eligible Courses</span>\r\n          </div>\r\n          <div class=\"scs-stat\">\r\n            <span class=\"scs-stat-num\">100%</span>\r\n            <span class=\"scs-stat-lbl\">Sponsored 2nd Course</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Main body -->\r\n    <section class=\"scs-body\">\r\n      <div class=\"wrap\">\r\n        <div class=\"scs-grid\">\r\n\r\n          <!-- LEFT -->\r\n          <div>\r\n\r\n            <!-- Eligible Courses -->\r\n            <div class=\"scs-courses-card\">\r\n              <div class=\"scs-courses-head\">\r\n                <h2>Eligible Courses for Sponsorship</h2>\r\n                <p>Enroll in any of these TVET CDACC / NITA programmes to qualify</p>\r\n              </div>\r\n              <div class=\"scs-courses-list\">\r\n                <a class=\"scs-course-item\" href=\"certificate-in-healthcare-support-services-level-5-certified-nursing-assistant.html\">\r\n                  <div class=\"scs-course-icon\"><i data-lucide=\"stethoscope\"></i></div>\r\n                  <div class=\"scs-course-info\">\r\n                    <strong>Healthcare Support Services</strong>\r\n                    <span>Certificate &ndash; Level 5</span>\r\n                  </div>\r\n                  <span class=\"scs-course-badge\">Level 5</span>\r\n                </a>\r\n                <a class=\"scs-course-item\" href=\"certificate-in-caregiving-level-4.html\">\r\n                  <div class=\"scs-course-icon\"><i data-lucide=\"heart-handshake\"></i></div>\r\n                  <div class=\"scs-course-info\">\r\n                    <strong>Caregiving</strong>\r\n                    <span>Certificate &ndash; Level II / 4</span>\r\n                  </div>\r\n                  <span class=\"scs-course-badge\">Level II/4</span>\r\n                </a>\r\n                <a class=\"scs-course-item\" href=\"certificate-in-home-based-care-support-level-3.html\">\r\n                  <div class=\"scs-course-icon\"><i data-lucide=\"home\"></i></div>\r\n                  <div class=\"scs-course-info\">\r\n                    <strong>Home-Based Care Support</strong>\r\n                    <span>Certificate &ndash; Level 3</span>\r\n                  </div>\r\n                  <span class=\"scs-course-badge\">Level 3</span>\r\n                </a>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- How it works -->\r\n            <div class=\"scs-steps-card\">\r\n              <div class=\"scs-section-label\"><i data-lucide=\"list-ordered\" style=\"width:14px;height:14px;\"></i> How It Works</div>\r\n              <h2 style=\"color:var(--dark); font-size:1.3rem; font-weight:800; margin:0;\">Simple. Straightforward. Rewarding.</h2>\r\n              <div class=\"scs-steps\">\r\n                <div class=\"scs-step\">\r\n                  <div class=\"scs-step-num\">1</div>\r\n                  <div class=\"scs-step-body\">\r\n                    <strong>Enroll in a Primary Course</strong>\r\n                    <p>Choose any of the three eligible TVET CDACC / NITA programmes and complete your registration.</p>\r\n                  </div>\r\n                </div>\r\n                <div class=\"scs-step\">\r\n                  <div class=\"scs-step-num\">2</div>\r\n                  <div class=\"scs-step-body\">\r\n                    <strong>GoCare Sponsors Your Second Course</strong>\r\n                    <p>We fully train you in an internationally accredited complementary programme &ndash; at zero extra tuition cost to you.</p>\r\n                  </div>\r\n                </div>\r\n                <div class=\"scs-step\">\r\n                  <div class=\"scs-step-num\">3</div>\r\n                  <div class=\"scs-step-body\">\r\n                    <strong>Graduate with Two Qualifications</strong>\r\n                    <p>You leave with both a national TVET CDACC certificate and an internationally recognised certification &ndash; boosting your global employability.</p>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Key offer -->\r\n            <div class=\"scs-offer-banner\">\r\n              <div class=\"scs-offer-tag\"><i data-lucide=\"gift\" style=\"width:13px;height:13px;\"></i> Special Offer</div>\r\n              <h3>Second Course Sponsorship</h3>\r\n              <p>Enroll for any of these <strong style=\"color:#fff;\">TVET CDACC / NITA Courses</strong> and receive an equivalent sponsorship for <strong style=\"color:var(--o);\">additional internationally accredited training and certification.</strong></p>\r\n              <div class=\"scs-offer-highlight\">\r\n                <strong>You Pay for One Course</strong>\r\n                <p>We sponsor and train you in the second complimentary course free of charge &ndash; and you acquire an internationally recognised certification!</p>\r\n              </div>\r\n            </div>\r\n\r\n\r\n          </div>\r\n\r\n          <!-- RIGHT: Sidebar -->\r\n          <div>\r\n\r\n            <!-- Apply card -->\r\n            <div class=\"scs-apply-card\">\r\n              <div class=\"scs-admission-badge\"><span></span> Ongoing Admission &amp; Registration</div>\r\n              <h3>Apply Now</h3>\r\n              <p>Don\'t miss this exclusive opportunity to earn two internationally recognised qualifications for the price of one.</p>\r\n              <a href=\"../apply.html\" class=\"scs-btn-primary\">Apply Now &rarr;</a>\r\n              <a href=\"../contact.html\" class=\"scs-btn-outline\">Check Eligibility</a>\r\n            </div>\r\n\r\n            <!-- Contact card -->\r\n            <div class=\"scs-contact-card\">\r\n              <h4>Get in Touch</h4>\r\n              <div class=\"scs-contact-item\">\r\n                <i data-lucide=\"phone\"></i>\r\n                <span>0703 115 502 / 0745 220 344 / 0745 229 485</span>\r\n              </div>\r\n              <div class=\"scs-contact-item\">\r\n                <i data-lucide=\"globe\"></i>\r\n                <span>www.gocareinstitute.ac.ke</span>\r\n              </div>\r\n              <div class=\"scs-contact-item\">\r\n                <i data-lucide=\"map-pin\"></i>\r\n                <span>Nairobi City Campus | Thika Road / Ruiru Campus<br><small>Hostels &amp; Accommodation Available</small></span>\r\n              </div>\r\n            </div>\r\n\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n  </div>\r\n  \r\n  \r\n  <!-- BACK TO TOP -->\r\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\r\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\r\n  </button>', '[{\"body\": \"Enroll in any of these TVET CDACC / NITA programmes to qualify Healthcare Support Services Certificate – Level 5 Level 5 Caregiving Certificate – Level II / 4 Level II/4 Home-Based Care Support Certificate – Level 3 Level 3 How It Works\", \"heading\": \"Eligible Courses for Sponsorship\"}, {\"body\": \"1 Enroll in a Primary Course Choose any of the three eligible TVET CDACC / NITA programmes and complete your registration. 2 GoCare Sponsors Your Second Course We fully train you in an internationally accredited complementary programme – at zero extra tuition cost to you. 3 Graduate with Two Qualifications You leave with both a national TVET CDACC certificate and an internationally recognised certification – boosting your global employability. Special Offer\", \"heading\": \"Simple. Straightforward. Rewarding.\"}, {\"body\": \"Enroll for any of these TVET CDACC / NITA Courses and receive an equivalent sponsorship for additional internationally accredited training and certification. You Pay for One Course We sponsor and train you in the second complimentary course free of charge – and you acquire an internationally recognised certification! Ongoing Admission & Registration\", \"heading\": \"Second Course Sponsorship\"}, {\"body\": \"Don\'t miss this exclusive opportunity to earn two internationally recognised qualifications for the price of one. Apply Now → Check Eligibility\", \"heading\": \"Apply Now\"}, {\"body\": \"0703 115 502 / 0745 220 344 / 0745 229 485 www.gocareinstitute.ac.ke Nairobi City Campus | Thika Road / Ruiru CampusHostels & Accommodation Available\", \"heading\": \"Get in Touch\"}]', NULL, 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');

