\", \"target\": null, \"children\": [], \"description\": \"Healthcare & clinical programs\", \"header_label\": \"\"}, {\"url\": \"/schools/hospitality-management\", \"icon\": \"utensils\", \"mega\": null, \"color\": \"amber\", \"label\": \"School of Hospitality Management\", \"target\": null, \"children\": [], \"description\": \"Tourism, food & front office\", \"header_label\": \"\"}, {\"url\": \"/schools/social-sciences-business\", \"icon\": \"users\", \"mega\": null, \"color\": \"indigo\", \"label\": \"School of Social Sciences & Business\", \"target\": null, \"children\": [], \"description\": \"Community & business programs\", \"header_label\": \"\"}, {\"url\": \"/schools/international-certifications\", \"icon\": \"globe\", \"mega\": null, \"color\": \"teal\", \"label\": \"International Certifications\", \"target\": null, \"children\": [], \"description\": \"Globally recognised qualifications\", \"header_label\": \"\"}, {\"url\": \"/courses\", \"icon\": \"search\", \"mega\": null, \"color\": \"purple\", \"label\": \"View All Courses\", \"target\": null, \"children\": [], \"description\": \"Browse the full programme list\", \"header_label\": \"\"}], \"description\": \"Explore our diverse range of courses\", \"header_label\": \"\"}, {\"url\": \"/admissions#overview\", \"icon\": \"clipboard-list\", \"mega\": \"standard\", \"color\": \"indigo\", \"label\": \"Admissions\", \"target\": null, \"children\": [{\"url\": \"/admissions#overview\", \"icon\": \"info\", \"mega\": null, \"color\": \"indigo\", \"label\": \"Admissions Overview\", \"target\": null, \"children\": [], \"description\": \"Everything you need to know\", \"header_label\": \"\"}, {\"url\": \"/admissions#how-to-apply\", \"icon\": \"file-edit\", \"mega\": null, \"color\": \"teal\", \"label\": \"How to Apply\", \"target\": null, \"children\": [], \"description\": \"Step-by-step application guide\", \"header_label\": \"\"}, {\"url\": \"/admissions#intakes\", \"icon\": \"calendar\", \"mega\": null, \"color\": 