INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'About Us — GoCare Training Institute — Kenya\'s Leading Healthcare College', 'about', '<!-- COOKIE CONSENT -->\r\n  <div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\r\n    <div class=\"ck-inner\">\r\n      <div class=\"ck-left\">\r\n        <div class=\"ck-icon-wrap\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n            <path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/>\r\n            <path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/>\r\n          </svg>\r\n        </div>\r\n        <div class=\"ck-copy\">\r\n          <strong>We use cookies</strong>\r\n          <p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"index.html\">Privacy Policy</a>.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"ck-actions\">\r\n        <button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button>\r\n        <button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button>\r\n        <button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- -- NAVBAR ---------------------------------------- -->\r\n\r\n\r\n  <!-- -- SUB BAR --------------------------------------- -->\r\n  <div class=\"subbar\">\r\n    <div class=\"wrap subbar-inner\">\r\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\r\n      <div class=\"subbar-portals\">\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n\r\n  \r\n\r\n  \r\n\r\n  <!-- -- PAGE TITLE HERO -------------------------------- -->\r\n    <!-- PAGE HERO -->\r\n  <section class=\"ph\">\r\n    <div class=\"ph-bg\">\r\n      <img loading=\"eager\" decoding=\"async\" src=\"images/new-images/WhatsApp%20Image%202026-03-26%20at%2011.59.07%20(1).jpeg\" alt=\"Welcome to GoCare Training Institute\">\r\n    </div>\r\n    <div class=\"ph-overlay\"></div>\r\n    <div class=\"ph-inner\">\r\n      <div class=\"ph-content\">\r\n        <span class=\"ph-eyebrow\"><i data-lucide=\"info\"></i> Discover GoCare</span>\r\n        \r\n        <h1>About <em>GoCare</em> Training Institute</h1>\r\n        <p>Kenya&#8217;s leading TVET college &mdash; accredited by TVETA, TVET CDACC, NITA, and internationally recognized, training the next generation of healthcare and hospitality professionals.</p>\r\n        <div class=\"ph-btns\">\r\n          <a href=\"apply.html\" class=\"ph-btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n          <a href=\"courses.html\" class=\"ph-btn-ghost\">Explore Courses <i data-lucide=\"arrow-right\"></i></a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n\r\n  <!-- -- ABOUT CONTENT SECTION -------------------------- -->\r\n  <section class=\"about-page-sec\" id=\"about\">\r\n    <div class=\"wrap\">\r\n      <div class=\"about-grid\">\r\n        <div class=\"about-text reveal\">\r\n          <span class=\"section-label\"><i data-lucide=\"award\"></i> Fully Accredited</span>\r\n          <h2 class=\"sec-title\">Welcome to <span style=\"color:var(--o)\">GoCare</span> Training Institute</h2>\r\n          <p style=\"margin-bottom: 20px;\">GoCare Training Institute (GTI) is a fully registered, accredited, and licensed Technical and Vocational Education and Training (TVET) college offering high quality artisan, certificate, and diploma programs. Since opening our doors in 2018, we have grown into one of Kenya&#8217;s most trusted institutions for competency based, practical, and industry aligned training.</p>\r\n          <p style=\"margin-bottom: 20px;\">We are accredited and regulated by the Ministry of Education, TVETA, TVET CDACC, NITA, KNEC, and recognized by the Kenya Health Professions Oversight Authority (KHPOA) for medical and health sciences programs lasting one year and above. GoCare is also a proud member of the Kenya Association of Technical Training Institutions (KATTI) and KENAPCO.</p>\r\n          <p style=\"margin-bottom: 20px;\">Beyond national accreditation, GoCare is an approved global examination and certification center for:</p>\r\n          <ul class=\"about-list\" style=\"margin-bottom: 25px;\">\r\n            <li><i data-lucide=\"check-circle-2\"></i> American Medical Certification Association (AMCA) &ndash; USA</li>\r\n            <li><i data-lucide=\"check-circle-2\"></i> Skill Development Council (SDC) &ndash; Canada</li>\r\n            <li><i data-lucide=\"check-circle-2\"></i> ICDL Global &ndash; Ireland</li>\r\n            <li><i data-lucide=\"check-circle-2\"></i> American Heart Association (AHA) &ndash; USA</li>\r\n          </ul>\r\n          <p style=\"margin-bottom: 20px; font-weight: 600; color: var(--o);\">This means our students graduate with locally recognized qualifications and internationally respected certifications, opening doors to employment and further studies both in Kenya and abroad.</p>\r\n          <p>At GoCare, we believe education must be practical, relevant, and transformative. Our programs are designed to equip learners with real world skills, hands on experience, and the confidence to excel in today&#8217;s competitive job market. With modern facilities, experienced trainers, guaranteed industrial attachments, and flexible study modes, GoCare continues to empower thousands of learners to build meaningful careers and brighter futures.</p>\r\n        </div>\r\n\r\n        <div class=\"about-visual reveal\">\r\n          <div class=\"visual-stack\">\r\n            <div class=\"v-img v-img--1\">\r\n              <img loading=\"lazy\" decoding=\"async\" src=\"images/Nursing-Assistant.jpg\" alt=\"CNA training session\">\r\n            </div>\r\n            <div class=\"v-img v-img--2\">\r\n              <img loading=\"lazy\" decoding=\"async\" src=\"images/Certificate-culinary-arts.jpg\" alt=\"Culinary arts students\">\r\n            </div>\r\n            <div class=\"v-img v-img--3\">\r\n              <img loading=\"lazy\" decoding=\"async\" src=\"images/caregiver-level-2.jpg\" alt=\"Caregiver practical training\">\r\n            </div>\r\n            <div class=\"v-experience-badge\">\r\n              <span class=\"v-exp-num\">10+</span>\r\n              <span class=\"v-exp-num\">Years of Excellence</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- -- PHOTO STRIP & SPLIT SECTION -- -->\r\n  <section style=\"padding: 20px 0 60px;\">\r\n    <div class=\"wrap\">\r\n      <div class=\"ab-photo-strip reveal\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/ABOUT-US.JPG.jpeg\" alt=\"GoCare Campus Life\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/IMG_6919.JPG\" alt=\"Practical Lectures\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/About-us-section.jpeg\" alt=\"Student Community\">\r\n      </div>\r\n      <div class=\"ab-split reveal\">\r\n        <div class=\"ab-split-img\">\r\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/SKILLS-LAB.JPG.jpeg\" alt=\"Modern Medical Lab\">\r\n        </div>\r\n        <div class=\"ab-split-body\">\r\n          <h3>State-of-the-Art Practical Laboratories</h3>\r\n          <p>We believe true excellence is built through practice. Our Nairobi CBD and Ruiru campuses feature highly modern, fully equipped simulation labs that replicate real hospital wards and clinical environments. This ensures our students master key caregiver, nursing assistant, and hospitality skills on campus before beginning their attachments.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n\r\n\r\n  <!-- -- VISION & MISSION ------------------------------- -->\r\n  \r\n\r\n  <section class=\"vm2-sec\" id=\"vision\">\r\n\r\n    <div class=\"vm2-split\">\r\n      <!-- Photo panel -->\r\n      <div class=\"vm2-photo\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about-mission-vision-section.jpeg\" alt=\"GoCare students\">\r\n        <div class=\"vm2-photo-overlay\"></div>\r\n        <div class=\"vm2-photo-badge\">\r\n          <div class=\"vm2-badge-num\">5,000+</div>\r\n          <div class=\"vm2-badge-label\">Graduates Since Founding</div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Content panel -->\r\n      <div class=\"vm2-content reveal\">\r\n\r\n        <!-- Vision -->\r\n        <div class=\"vm2-block\">\r\n          <div class=\"vm2-label vision\">\r\n            <span class=\"vm2-dot\"></span>\r\n            <i data-lucide=\"eye\"></i> Our Vision\r\n          </div>\r\n          <h3 class=\"vm2-heading\">A Leading Centre of <em>Excellence</em></h3>\r\n          <p class=\"vm2-text\">To be a leading and preferred centre of excellence that equips learners with relevant, practical, and industry-aligned knowledge and skills.</p>\r\n          <p class=\"vm2-text\">GoCare Training Institute envisions a future where every learner has access to high-quality, competency-based training that leads to meaningful employment, professional growth, and global opportunities. We aim to be Kenya\'s most trusted institution for medical, hospitality, social sciences, and business training, recognized for our commitment to excellence, innovation, and industry relevance.</p>\r\n          <p class=\"vm2-subtitle\">Our vision is driven by a passion to:</p>\r\n          <ul class=\"vm2-list\">\r\n            <li><i data-lucide=\"check\"></i>Deliver practical, hands-on training that prepares learners for real-world work environments.</li>\r\n            <li><i data-lucide=\"check\"></i>Provide internationally recognized certifications that open doors locally and abroad.</li>\r\n            <li><i data-lucide=\"check\"></i>Build a community of ethical, skilled, and confident professionals.</li>\r\n            <li><i data-lucide=\"check\"></i>Lead in TVET education, competent qualifications, and global workforce readiness.</li>\r\n          </ul>\r\n          <p class=\"vm2-text\">GoCare continues to grow as a centre of excellence where learners transform their potential into successful careers.</p>\r\n        </div>\r\n\r\n        <div class=\"vm2-divider\"></div>\r\n\r\n        <!-- Mission -->\r\n        <div class=\"vm2-block\">\r\n          <div class=\"vm2-label mission\">\r\n            <span class=\"vm2-dot\"></span>\r\n            <i data-lucide=\"target\"></i> Our Mission\r\n          </div>\r\n          <h3 class=\"vm2-heading\">Empowering Learners for <em>Real-World Success</em></h3>\r\n          <p class=\"vm2-text\">To provide high-quality, competency-based training that empowers learners with the skills, knowledge, and values required to excel in the job market and deliver exceptional service to society with confidence and professionalism.</p>\r\n          <p class=\"vm2-text\">Our mission is to deliver industry-aligned, practical, and transformative training that equips learners with the competencies needed to thrive in Kenya\'s evolving job market and the global workforce.</p>\r\n          <p class=\"vm2-subtitle\">We are committed to offering programs that are:</p>\r\n          <ul class=\"vm2-list\">\r\n            <li><i data-lucide=\"check\"></i>Accredited and regulator-aligned (TVETA, TVET CDACC, NITA, KHPOA, KNEC).</li>\r\n            <li><i data-lucide=\"check\"></i>Practical and hands-on, with guaranteed industrial attachments.</li>\r\n            <li><i data-lucide=\"check\"></i>Internationally recognized, through AMCA (USA), SDC Canada, and ICDL.</li>\r\n            <li><i data-lucide=\"check\"></i>Accessible, with flexible study modes and two strategic campuses.</li>\r\n          </ul>\r\n          <p class=\"vm2-text\">GoCare exists to empower learners to become skilled professionals, ethical practitioners, and leaders in their fields, contributing positively to communities and industries across Kenya and beyond.</p>\r\n        </div>\r\n\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Pillars strip -->\r\n    <div class=\"vm2-pillars\">\r\n      <div class=\"vm2-pillars-inner\">\r\n        <div class=\"vm2-pillar\">\r\n          <div class=\"vm2-pillar-icon\"><i data-lucide=\"award\"></i></div>\r\n          <div class=\"vm2-pillar-body\">\r\n            <h5>Fully Accredited</h5>\r\n            <p>TVETA licensed &amp; TVET CDACC approved</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"vm2-pillar\">\r\n          <div class=\"vm2-pillar-icon\"><i data-lucide=\"globe\"></i></div>\r\n          <div class=\"vm2-pillar-body\">\r\n            <h5>Globally Recognised</h5>\r\n            <p>AMCA USA &amp; SDC Canada certifications</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"vm2-pillar\">\r\n          <div class=\"vm2-pillar-icon\"><i data-lucide=\"briefcase\"></i></div>\r\n          <div class=\"vm2-pillar-body\">\r\n            <h5>Industry-Ready</h5>\r\n            <p>Graduates employed across Kenya &amp; beyond</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"vm2-pillar\">\r\n          <div class=\"vm2-pillar-icon\"><i data-lucide=\"heart-handshake\"></i></div>\r\n          <div class=\"vm2-pillar-body\">\r\n            <h5>Student-Centred</h5>\r\n            <p>Mentorship, support &amp; guaranteed attachment</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </section>\r\n\r\n  <!-- -- CORE VALUES ------------------------------------ -->\r\n  \r\n\r\n  <section class=\"values-sec\" id=\"core-values\">\r\n    <div class=\"wrap\">\r\n      <div class=\"section-head reveal\" style=\"max-width: 900px; margin-left: auto; margin-right: auto; text-align: center;\">\r\n        <span class=\"section-tagline\">What Drives Us</span>\r\n        <h2 class=\"section-title\">Our <span class=\"accent\">Core Values</span></h2>\r\n        <p class=\"section-sub\" style=\"font-size: 1.15rem; margin-top: 20px;\">The Institute upholds the following core values, which guide all academic, administrative, operational, and student-related functions.</p>\r\n        <div class=\"rule\" style=\"margin: 30px auto;\"></div>\r\n      </div>\r\n\r\n      <!-- First row of values -->\r\n      <div class=\"values-grid\">\r\n        <div class=\"value-card reveal\">\r\n          <div class=\"v-icon\"><i data-lucide=\"trophy\" style=\"width: 28px; height: 28px;\"></i></div>\r\n          <h4>Excellence and Professionalism</h4>\r\n          <p>Commitment to delivering high-quality, industry-aligned training and upholding the highest standards of professional conduct.</p>\r\n          <p style=\"margin-top: 12px; font-size: 0.95rem; color: #475569;\">GoCare strives for excellence in every aspect of training &mdash; from curriculum delivery to student support and industry partnerships. Our programs are designed to meet employer expectations, regulatory standards, and global best practices, ensuring our graduates stand out in the job market.</p>\r\n        </div>\r\n\r\n        <div class=\"value-card reveal delay-1\">\r\n          <div class=\"v-icon\"><i data-lucide=\"shield-check\" style=\"width: 28px; height: 28px;\"></i></div>\r\n          <h4>Integrity and Accountability</h4>\r\n          <p>Upholding honesty, transparency, ethical behaviour, and responsibility in all institutional operations.</p>\r\n          <p style=\"margin-top: 12px; font-size: 0.95rem; color: #475569;\">Integrity is the foundation of our institution. We maintain transparent processes, ethical training practices, and responsible governance to ensure trust among students, parents, regulators, and partners.</p>\r\n        </div>\r\n\r\n        <div class=\"value-card reveal delay-2\">\r\n          <div class=\"v-icon\"><i data-lucide=\"lightbulb\" style=\"width: 28px; height: 28px;\"></i></div>\r\n          <h4>Innovation and Continuous Improvement</h4>\r\n          <p>Promoting creativity, research, technology adoption, and ongoing enhancement of training, systems, and services.</p>\r\n          <p style=\"margin-top: 12px; font-size: 0.95rem; color: #475569;\">GoCare embraces innovation in teaching, digital learning, and curriculum development. We continuously upgrade our facilities, methodologies, and systems to stay ahead of industry trends and deliver modern, relevant training.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Photo mosaic break -->\r\n      <div class=\"cv-mosaic reveal\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"cv-m-main\" src=\"images/new-images/about/IMG_5546 (1).jpg.jpeg\" alt=\"GoCare graduation celebration\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/PXL_20251201_103802412 (1).jpg.jpeg\" alt=\"GoCare theatre technology lab\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/PXL_20251124_072942859.MP (1).jpg.jpeg\" alt=\"GoCare classroom session\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/IMG_2934.JPG.jpeg\" alt=\"GoCare culinary arts\">\r\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/about/IMG_2692.JPG.jpeg\" alt=\"GoCare student activities\">\r\n        <div class=\"cv-mosaic-overlay\">\r\n          <div class=\"cv-mosaic-quote\">\r\n            <strong>Train with the Experts&hellip; Become an Expert!</strong>\r\n            <span>Every value we hold shapes the professional you become.</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Second row of values -->\r\n      <div class=\"values-grid\">\r\n        <div class=\"value-card reveal\">\r\n          <div class=\"v-icon\"><i data-lucide=\"users\" style=\"width: 28px; height: 28px;\"></i></div>\r\n          <h4>Student-Centred Growth and Success</h4>\r\n          <p>Ensuring that all institutional processes, support systems, and learning experiences prioritize learner development and achievement.</p>\r\n          <p style=\"margin-top: 12px; font-size: 0.95rem; color: #475569;\">Our learners are at the heart of everything we do. We provide personalized support, mentorship, flexible study options, and a safe learning environment to help every student succeed academically, professionally, and personally.</p>\r\n        </div>\r\n\r\n        <div class=\"value-card reveal delay-1\">\r\n          <div class=\"v-icon\"><i data-lucide=\"hand-heart\" style=\"width: 28px; height: 28px;\"></i></div>\r\n          <h4>Inclusivity, Respect, and Diversity</h4>\r\n          <p>Fostering an environment that values diversity, equal opportunity, dignity, and respect for all individuals.</p>\r\n          <p style=\"margin-top: 12px; font-size: 0.95rem; color: #475569;\">GoCare fosters an inclusive environment where learners from all backgrounds feel welcome, respected, and empowered. We champion equal access to education and celebrate the diversity that strengthens our community.</p>\r\n        </div>\r\n\r\n        <div class=\"value-card reveal delay-2\">\r\n          <div class=\"v-icon\"><i data-lucide=\"briefcase\" style=\"width: 28px; height: 28px;\"></i></div>\r\n          <h4>Industry Partnership and Employability</h4>\r\n          <p>Strengthening collaboration with employers and stakeholders to enhance relevance, employability, and workforce readiness.</p>\r\n          <p style=\"margin-top: 12px; font-size: 0.95rem; color: #475569;\">Our strong partnerships with hospitals, hotels, NGOs, government agencies, and private sector organizations ensure our training remains relevant and our graduates are highly employable. We align our programs with industry needs to prepare learners for real-world success.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- -- NEWSLETTER ------------------------------------- -->\r\n  <section class=\"nl-sec\">\r\n    <div class=\"wrap nl-inner\">\r\n      <h2>Subscribe &amp; Stay Updated</h2>\r\n      <p>Get the latest programme news, intake dates and healthcare career tips &mdash; no spam, ever.</p>\r\n      <form class=\"nl-form\" onsubmit=\"event.preventDefault();this.innerHTML=\'<p style=\\\'color:#F5F0E8;font-weight:700;padding:16px 24px;font-size:.95rem\\\'>&#x2705; Subscribed! Thank you.</p>\'\">\r\n        <input type=\"email\" placeholder=\"Enter your email address&hellip;\" required>\r\n        <button type=\"submit\">Join 2,500+ Students</button>\r\n      </form>\r\n    </div>\r\n  </section>\r\n\r\n  \r\n\r\n  \r\n  <!-- BACK TO TOP -->\r\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\r\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\r\n  </button>', 'images/new-images/WhatsApp Image 2026-03-26 at 11.59.07 (1).jpeg', 0, '[{\"body\": \"Kenya’s leading TVET college — accredited by TVETA, TVET CDACC, NITA, and internationally recognized, training the next generation of healthcare and hospitality professionals. Apply Now Explore Courses Fully Accredited\", \"heading\": \"About GoCare Training Institute\"}, {\"body\": \"GoCare Training Institute (GTI) is a fully registered, accredited, and licensed Technical and Vocational Education and Training (TVET) college offering high quality artisan, certificate, and diploma programs. Since opening our doors in 2018, we have grown into one of Kenya’s most trusted institutions for competency based, practical, and industry aligned training. We are accredited and regulated by the Ministry of Education, TVETA, TVET CDACC, NITA, KNEC, and recognized by the Kenya Health Professions Oversight Authority (KHPOA) for medical and health sciences programs lasting one year and above. GoCare is also a proud member of the Kenya Association of Technical Training Institutions (KATTI) and KENAPCO. Beyond national accreditation, GoCare is an approved global examination and certification center for: American Medical Certification Association (AMCA) – USA Skill Development Council (SDC) – Canada ICDL Global – Ireland American Heart Association (AHA) – USA This means our students graduate with locally recognized qualifications and internationally respected certifications, opening doors to employment and further studies both in Kenya and abroad. At GoCare, we believe education must be practical, relevant, and transformative. Our programs are designed to equip learners with real world skills, hands on experience, and the confidence to excel in today’s competitive job market. With modern facilities, experienced trainers, guaranteed industrial attachments, and flexible study modes, GoCare continues to empower thousands of learners to build meaningful careers and brighter futures. 10+ Years of Excellence\", \"heading\": \"Welcome to GoCare Training Institute\"}, {\"body\": \"We believe true excellence is built through practice. Our Nairobi CBD and Ruiru campuses feature highly modern, fully equipped simulation labs that replicate real hospital wards and clinical environments. This ensures our students master key caregiver, nursing assistant, and hospitality skills on campus before beginning their attachments. 5,000+ Graduates Since Founding Our Vision\", \"heading\": \"State-of-the-Art Practical Laboratories\"}, {\"body\": \"To be a leading and preferred centre of excellence that equips learners with relevant, practical, and industry-aligned knowledge and skills. GoCare Training Institute envisions a future where every learner has access to high-quality, competency-based training that leads to meaningful employment, professional growth, and global opportunities. We aim to be Kenya\'s most trusted institution for medical, hospitality, social sciences, and business training, recognized for our commitment to excellence, innovation, and industry relevance. Our vision is driven by a passion to: Deliver practical, hands-on training that prepares learners for real-world work environments. Provide internationally recognized certifications that open doors locally and abroad. Build a community of ethical, skilled, and confident professionals. Lead in TVET education, competent qualifications, and global workforce readiness. GoCare continues to grow as a centre of excellence where learners transform their potential into successful careers. Our Mission\", \"heading\": \"A Leading Centre of Excellence\"}, {\"body\": \"To provide high-quality, competency-based training that empowers learners with the skills, knowledge, and values required to excel in the job market and deliver exceptional service to society with confidence and professionalism. Our mission is to deliver industry-aligned, practical, and transformative training that equips learners with the competencies needed to thrive in Kenya\'s evolving job market and the global workforce. We are committed to offering programs that are: Accredited and regulator-aligned (TVETA, TVET CDACC, NITA, KHPOA, KNEC). Practical and hands-on, with guaranteed industrial attachments. Internationally recognized, through AMCA (USA), SDC Canada, and ICDL. Accessible, with flexible study modes and two strategic campuses. GoCare exists to empower learners to become skilled professionals, ethical practitioners, and leaders in their fields, contributing positively to communities and industries across Kenya and beyond.\", \"heading\": \"Empowering Learners for Real-World Success\"}, {\"body\": \"TVETA licensed & TVET CDACC approved\", \"heading\": \"Fully Accredited\"}, {\"body\": \"AMCA USA & SDC Canada certifications\", \"heading\": \"Globally Recognised\"}, {\"body\": \"Graduates employed across Kenya & beyond\", \"heading\": \"Industry-Ready\"}, {\"body\": \"Mentorship, support & guaranteed attachment What Drives Us\", \"heading\": \"Student-Centred\"}, {\"body\": \"The Institute upholds the following core values, which guide all academic, administrative, operational, and student-related functions.\", \"heading\": \"Our Core Values\"}, {\"body\": \"Commitment to delivering high-quality, industry-aligned training and upholding the highest standards of professional conduct. GoCare strives for excellence in every aspect of training — from curriculum delivery to student support and industry partnerships. Our programs are designed to meet employer expectations, regulatory standards, and global best practices, ensuring our graduates stand out in the job market.\", \"heading\": \"Excellence and Professionalism\"}, {\"body\": \"Upholding honesty, transparency, ethical behaviour, and responsibility in all institutional operations. Integrity is the foundation of our institution. We maintain transparent processes, ethical training practices, and responsible governance to ensure trust among students, parents, regulators, and partners.\", \"heading\": \"Integrity and Accountability\"}, {\"body\": \"Promoting creativity, research, technology adoption, and ongoing enhancement of training, systems, and services. GoCare embraces innovation in teaching, digital learning, and curriculum development. We continuously upgrade our facilities, methodologies, and systems to stay ahead of industry trends and deliver modern, relevant training. Train with the Experts… Become an Expert! Every value we hold shapes the professional you become.\", \"heading\": \"Innovation and Continuous Improvement\"}, {\"body\": \"Ensuring that all institutional processes, support systems, and learning experiences prioritize learner development and achievement. Our learners are at the heart of everything we do. We provide personalized support, mentorship, flexible study options, and a safe learning environment to help every student succeed academically, professionally, and personally.\", \"heading\": \"Student-Centred Growth and Success\"}, {\"body\": \"Fostering an environment that values diversity, equal opportunity, dignity, and respect for all individuals. GoCare fosters an inclusive environment where learners from all backgrounds feel welcome, respected, and empowered. We champion equal access to education and celebrate the diversity that strengthens our community.\", \"heading\": \"Inclusivity, Respect, and Diversity\"}, {\"body\": \"Strengthening collaboration with employers and stakeholders to enhance relevance, employability, and workforce readiness. Our strong partnerships with hospitals, hotels, NGOs, government agencies, and private sector organizations ensure our training remains relevant and our graduates are highly employable. We align our programs with industry needs to prepare learners for real-world success.\", \"heading\": \"Industry Partnership and Employability\"}, {\"body\": \"Get the latest programme news, intake dates and healthcare career tips — no spam, ever. Join 2,500+ Students\", \"heading\": \"Subscribe & Stay Updated\"}]', 'about.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(2, 'Admissions | GoCare Training Institute', 'admissions', '<!-- COOKIE CONSENT -->\n  <div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\n    <div class=\"ck-inner\">\n      <div class=\"ck-left\">\n        <div class=\"ck-icon-wrap\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/>\n            <path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/>\n          </svg>\n        </div>\n        <div class=\"ck-copy\">\n          <strong>We use cookies</strong>\n          <p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p>\n        </div>\n      </div>\n      <div class=\"ck-actions\">\n        <button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button>\n        <button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button>\n        <button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- -- NAVBAR ---------------------------------------- -->\n\n\n  <!-- -- SUB BAR --------------------------------------- -->\n  <div class=\"subbar\">\n    <div class=\"wrap subbar-inner\">\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\n      <div class=\"subbar-portals\">\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\n      </div>\n    </div>\n  </div>\n\n\n  \n\n  \n\n  \n\n\n\n<div class=\"adm-page\">\n    <!-- PAGE HERO -->\n  <section class=\"ph ph--split\">\n    <div class=\"ph-bg\">\n      <img loading=\"eager\" decoding=\"async\" src=\"images/new-images/Admissions-hero.jpeg\" alt=\"Join GoCare\">\n    </div>\n    <div class=\"ph-overlay\"></div>\n    <div class=\"ph-inner\">\n      <div class=\"ph-content\">\n        <span class=\"ph-eyebrow\"><i data-lucide=\"graduation-cap\"></i> Join GoCare</span>\n        \n        <h1>Start Your Journey at <em>GoCare</em></h1>\n        <p>Enrol in Kenya&#8217;s leading healthcare, hospitality, and social sciences training college. TVETA licensed. TVET CDACC accredited. NITA recognised. Globally respected.</p>\n        <div class=\"ph-btns\">\n          <a href=\"apply.html\" class=\"ph-btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\n          <a href=\"courses.html\" class=\"ph-btn-ghost\">Explore Courses <i data-lucide=\"arrow-right\"></i></a>\n        </div>\n      </div>\n      <div class=\"ph-form-card\">\n        <h3>Apply Today</h3>\n        <p>Start your application &ndash; takes less than 5 minutes.</p>\n        <div class=\"ph-form-group\">\n          <label>Full Name</label>\n          <input type=\"text\" class=\"ph-form-input\" placeholder=\"Your full name\">\n        </div>\n        <div class=\"ph-form-group\">\n          <label>Phone Number</label>\n          <input type=\"tel\" class=\"ph-form-input\" placeholder=\"07XX XXX XXX\">\n        </div>\n        <div class=\"ph-form-group\">\n          <label>Course of Interest</label>\n          <select class=\"ph-form-input\">\n            <option value=\"\">Select a course</option>\n            <option>Healthcare Support Services (CNA)</option>\n            <option>Perioperative Theatre Technology</option>\n            <option>Mortuary Science</option>\n            <option>Orthopaedic &amp; Trauma Medicine</option>\n            <option>Culinary Arts / Food &amp; Beverage</option>\n            <option>Social Work &amp; Community Development</option>\n            <option>International Certifications</option>\n          </select>\n        </div>\n        <button class=\"ph-form-submit\" onclick=\"window.location=\'apply.html\'\">Start Application &rarr;</button>\n      </div>\n    </div>\n  </section>\n\n<!-- -- STICKY SECTION NAV ------------------------------- -->\n\n\n<!-- STICKY SECTION NAV -->\n\n\n<!-- ------------------ SECTION 1: OVERVIEW ------------------ -->\n<section id=\"overview\" class=\"adm-section adm-section--cream\">\n  <span class=\"adm-sec-num\">01</span>\n  <div class=\"adm-section-wrap\">\n    <div class=\"adm-eyebrow\"><i data-lucide=\"layout-grid\"></i> Admissions at GoCare</div>\n    <h2 class=\"adm-sec-heading\">Welcome to <em>GoCare</em> Admissions</h2>\n    <p class=\"adm-sec-sub\">Everything you need to join Kenya\'s leading healthcare, hospitality, and social sciences training institute &ndash; from choosing your programme to completing your enrolment.</p>\n\n    <div class=\"adm-overview-grid\">\n      <div class=\"adm-ov-card\">\n        <div class=\"adm-ov-icon adm-ov-icon--purple\"><i data-lucide=\"mouse-pointer-click\"></i></div>\n        <h4>Simple Application</h4>\n        <p>Apply online in minutes via our portal. No complex paperwork &ndash; just fill, upload, and submit.</p>\n        <a href=\"#how-to-apply\" class=\"adm-ov-link\">See the steps <i data-lucide=\"arrow-right\"></i></a>\n      </div>\n      <div class=\"adm-ov-card\">\n        <div class=\"adm-ov-icon adm-ov-icon--orange\"><i data-lucide=\"calendar-check\"></i></div>\n        <h4>Rolling Intake</h4>\n        <p>We accept new students every month &mdash; January through December &mdash; so you can start whenever you&rsquo;re ready.</p>\n        <a href=\"apply.html\" class=\"adm-ov-link\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\n      </div>\n      <div class=\"adm-ov-card\">\n        <div class=\"adm-ov-icon adm-ov-icon--teal\"><i data-lucide=\"shield-check\"></i></div>\n        <h4>TVETA Accredited &amp; Licensed</h4>\n        <p>Fully accredited by TVETA, TVET CDACC, NITA and internationally recognised &ndash; your certificate holds global value.</p>\n        <a href=\"#requirements\" class=\"adm-ov-link\">Check requirements <i data-lucide=\"arrow-right\"></i></a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div class=\"adm-divider\"></div>\n\n<!-- ------------------ SECTION 2: HOW TO APPLY ------------------ -->\n<section id=\"how-to-apply\" class=\"adm-section adm-section--dark\">\n  <span class=\"adm-sec-num\">02</span>\n  <div class=\"adm-section-wrap\">\n    <div class=\"adm-eyebrow\"><i data-lucide=\"mouse-pointer-click\"></i> Application Process</div>\n    <h2 class=\"adm-sec-heading\">How to <em>Apply</em></h2>\n    <p class=\"adm-sec-sub\">Our digital admissions process is fast and straightforward. Follow these four steps to secure your place at GoCare.</p>\n\n    <div class=\"adm-steps-layout\">\n      <div class=\"adm-steps-list\">\n        <div class=\"adm-step-item\">\n          <div class=\"adm-step-num\">1</div>\n          <div class=\"adm-step-body\">\n            <h4>Create an Account</h4>\n            <p>Visit our online admissions portal and register your student account with a valid email address and phone number.</p>\n          </div>\n        </div>\n        <div class=\"adm-step-item\">\n          <div class=\"adm-step-num\">2</div>\n          <div class=\"adm-step-body\">\n            <h4>Fill the Application Form</h4>\n            <p>Complete the online form with your personal details, academic background, and preferred programme of study.</p>\n          </div>\n        </div>\n        <div class=\"adm-step-item\">\n          <div class=\"adm-step-num\">3</div>\n          <div class=\"adm-step-body\">\n            <h4>Upload Your Documents</h4>\n            <p>Upload scanned copies of your KCSE certificate, National ID or Passport, and two recent passport photos.</p>\n          </div>\n        </div>\n        <div class=\"adm-step-item\">\n          <div class=\"adm-step-num\">4</div>\n          <div class=\"adm-step-body\">\n            <h4>Submit &amp; Track Your Status</h4>\n            <p>Submit your application and use the portal to track your admission status in real time. Receive your offer letter by email.</p>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"adm-steps-img\">\n        <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC06020.jpg\" alt=\"GoCare graduate holding her certificate\">\n        <div class=\"adm-steps-img-badge\">\n          <strong>5 min</strong>\n          <span>Average application time</span>\n        </div>\n      </div>\n    </div>\n\n    <div style=\"margin-top:40px;\">\n      <a href=\"apply.html\" style=\"display:inline-flex;align-items:center;gap:8px;background:#ec7424;color:#fff;padding:14px 32px;border-radius:50px;font-weight:700;font-size:.95rem;text-decoration:none;\">\n        Start Your Application <i data-lucide=\"arrow-right\"></i>\n      </a>\n    </div>\n  </div>\n</section>\n\n<div class=\"adm-divider\"></div>\n\n<!-- ------------------ SECTION 3: INTAKES ------------------ -->\n<section id=\"intakes\" class=\"adm-section adm-section--white\">\n  <span class=\"adm-sec-num\">03</span>\n  <div class=\"adm-section-wrap\">\n    \n    <div class=\"adm-eyebrow\"><i data-lucide=\"calendar\"></i> When to Join</div>\n    <div class=\"intk-block\">\n      <div>\n        <span class=\"intk-live\"><span class=\"intk-live-dot\"></span> Registration Ongoing</span>\n        <h2 class=\"intk-title\">Intakes &amp; <span>Deadlines</span></h2>\n        <p class=\"intk-sub\">Stay informed about current and upcoming intakes &mdash; plan your enrolment early and secure your place.</p>\n        <div class=\"intk-banner\">\n          <i data-lucide=\"megaphone\"></i>\n          <strong>Registration &amp; Admission for the Upcoming Intake is Ongoing &mdash; Apply Now!</strong>\n        </div>\n        <ul class=\"intk-list\">\n          <li><span class=\"intk-check\"><i data-lucide=\"check\"></i></span> Multiple intakes throughout the year for different schedules.</li>\n          <li><span class=\"intk-check\"><i data-lucide=\"check\"></i></span> Admissions open on a rolling basis for select programmes.</li>\n          <li><span class=\"intk-check\"><i data-lucide=\"check\"></i></span> Apply early to secure your place in the next intake.</li>\n        </ul>\n        <div class=\"intk-btns\">\n          <a href=\"apply.html\" class=\"intk-btn-primary\">Apply Now <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px;\"></i></a>\n          <a href=\"courses.html\" class=\"intk-btn-ghost\">View Programmes</a>\n        </div>\n      </div>\n\n      <div class=\"intk-cal\">\n        <div class=\"intk-cal-head\">\n          <div><b>Intake Calendar</b><small>New cohorts every month</small></div>\n          <span class=\"intk-cal-icon\"><i data-lucide=\"calendar-days\"></i></span>\n        </div>\n        <div class=\"intk-months\" id=\"intkMonths\">\n          <div class=\"intk-mchip\" data-m=\"0\"><b>Jan</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"1\"><b>Feb</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"2\"><b>Mar</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"3\"><b>Apr</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"4\"><b>May</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"5\"><b>Jun</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"6\"><b>Jul</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"7\"><b>Aug</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"8\"><b>Sep</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"9\"><b>Oct</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"10\"><b>Nov</b><span>Open</span></div>\n          <div class=\"intk-mchip\" data-m=\"11\"><b>Dec</b><span>Open</span></div>\n        </div>\n        <div class=\"intk-cal-foot\"><i data-lucide=\"repeat\"></i> Rolling admissions &mdash; enrol any month and start in the next available cohort.</div>\n      </div>\n    </div>\n    \n  </div>\n</section>\n\n<div class=\"adm-divider\"></div>\n\n<!-- ------------------ SECTION 4: ENTRY REQUIREMENTS ------------------ -->\n<section id=\"requirements\" class=\"adm-section adm-section--dark\">\n  <span class=\"adm-sec-num\">04</span>\n  <div class=\"adm-section-wrap\">\n    <div class=\"adm-eyebrow\"><i data-lucide=\"clipboard-list\"></i> Eligibility</div>\n    <h2 class=\"adm-sec-heading\">Entry <em>Requirements</em></h2>\n    <p class=\"adm-sec-sub\">At GoCare Training Institute, every learner has a pathway to success &mdash; no one is left behind.</p>\n\n    \n    <div class=\"er-grid\">\n      <div class=\"er-card\" data-num=\"01\">\n        <div class=\"er-icon\"><i data-lucide=\"award\"></i></div>\n        <h4>Any KCSE Grade Qualifies</h4>\n        <p>From A to E, your KCSE mean grade opens a pathway to a course that fits you.</p>\n      </div>\n      <div class=\"er-card\" data-num=\"02\">\n        <div class=\"er-icon\"><i data-lucide=\"sliders-horizontal\"></i></div>\n        <h4>Course-Specific Entry</h4>\n        <p>Different courses have their own entry requirements, levels, and durations.</p>\n      </div>\n      <div class=\"er-card\" data-num=\"03\">\n        <div class=\"er-icon\"><i data-lucide=\"file-check-2\"></i></div>\n        <h4>KCPE Holders Welcome</h4>\n        <p>Completed KCPE? You also qualify to enrol in selected foundation programmes.</p>\n      </div>\n      <a class=\"er-card er-card--cta\" data-num=\"04\" href=\"courses.html\">\n        <div class=\"er-icon\"><i data-lucide=\"search\"></i></div>\n        <h4>Check Your Course</h4>\n        <p>Visit individual course pages for the specific requirements of each programme.</p>\n        <span class=\"er-cta-link\">Browse all courses <i data-lucide=\"arrow-right\"></i></span>\n      </a>\n    </div>\n  </div>\n</section>\n\n<div class=\"adm-divider\"></div>\n\n<!-- ------------------ SECTION 5: FEES & PAYMENT ------------------ -->\n<section id=\"fees\" class=\"adm-section adm-section--cream\">\n  <span class=\"adm-sec-num\">05</span>\n  <div class=\"adm-section-wrap\">\n    <div class=\"adm-eyebrow\"><i data-lucide=\"wallet\"></i> Fees &amp; Financing</div>\n    <h2 class=\"adm-sec-heading\">Fees &amp; <em>Payment Options</em></h2>\n    <p class=\"adm-sec-sub\">GoCare offers transparent, affordable fees with multiple financing options to ensure quality education is accessible to everyone.</p>\n\n    <div class=\"adm-fees-grid\">\n      <div class=\"adm-fee-card\">\n        <div class=\"adm-fee-icon adm-fee-icon--plan\"><i data-lucide=\"wallet\"></i></div>\n        <h4>One-off Payments</h4>\n        <p>Settle your tuition in a single, full payment at the start of the term &ndash; simple, convenient, and hassle-free.</p>\n      </div>\n      <div class=\"adm-fee-card\">\n        <div class=\"adm-fee-icon adm-fee-icon--mobile\"><i data-lucide=\"calendar-range\"></i></div>\n        <h4>Flexible Payments</h4>\n        <p>Spread your tuition across manageable monthly or termly instalments, paid conveniently via M-Pesa Paybill, bank transfer, or direct deposit.</p>\n      </div>\n    </div>\n\n    <div class=\"adm-fee-note\">\n      <i data-lucide=\"info\"></i>\n      <p>Detailed fee structures are provided with your admission letter as costs vary by programme. For a fee estimate, contact our admissions team or <a href=\"#support\" style=\"color:#ec7424;font-weight:700;\">visit the Support section below.</a> <strong>Second course sponsorship</strong> is also available for eligible enrolled students.</p>\n    </div>\n  </div>\n</section>\n\n<div class=\"adm-divider\"></div>\n\n<!-- ------------------ SECTION 6: ADMISSIONS SUPPORT ------------------ -->\n<section id=\"support\" class=\"adm-section adm-section--dark\">\n  <span class=\"adm-sec-num\">06</span>\n  <div class=\"adm-section-wrap\">\n    <div class=\"adm-eyebrow\"><i data-lucide=\"headphones\"></i> We Are Here for You</div>\n    <h2 class=\"adm-sec-heading\">Admissions <em>Support</em></h2>\n    <p class=\"adm-sec-sub\">Our dedicated admissions team is available to guide you through every step of the process &ndash; from choosing a course to completing your enrolment.</p>\n\n    <div class=\"adm-support-grid\">\n      <div class=\"adm-support-card\">\n        <div class=\"adm-support-icon\"><i data-lucide=\"message-circle\"></i></div>\n        <h4>WhatsApp Helpdesk</h4>\n        <p>Get instant responses 24/7 via our WhatsApp helpdesk. Ideal for quick questions about courses, requirements, and deadlines.</p>\n        <a href=\"https://wa.me/254703115502\" class=\"adm-support-link\" target=\"_blank\">Chat on WhatsApp <i data-lucide=\"arrow-right\"></i></a>\n      </div>\n      <div class=\"adm-support-card\">\n        <div class=\"adm-support-icon\"><i data-lucide=\"mail\"></i></div>\n        <h4>Email Support</h4>\n        <p>Send detailed queries to our admissions team. We respond within 24 hours on business days.</p>\n        <a href=\"mailto:info@gocareinstitute.ac.ke\" class=\"adm-support-link\">Send an Email <i data-lucide=\"arrow-right\"></i></a>\n      </div>\n      <div class=\"adm-support-card\">\n        <div class=\"adm-support-icon\"><i data-lucide=\"map-pin\"></i></div>\n        <h4>Campus Visit</h4>\n        <p>Visit our Nairobi campus admissions desk Monday&ndash;Friday, 8:00 AM &ndash; 5:00 PM for in-person guidance and document submission.</p>\n        <a href=\"contact.html#location\" class=\"adm-support-link\">Get Directions <i data-lucide=\"arrow-right\"></i></a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- FINAL CTA -->\n<div class=\"adm-final-cta\">\n  <h3>Ready to Take the First Step?</h3>\n  <p>Join thousands of GoCare graduates building rewarding careers across Kenya and internationally.</p>\n  <div class=\"adm-final-btns\">\n    <a href=\"apply.html\" class=\"adm-final-btn-primary\"><i data-lucide=\"arrow-right\"></i> Apply Now</a>\n    <a href=\"docs/GoCare%20Training%20Institute%20Prospectus.pdf\" class=\"adm-final-btn-ghost\" target=\"_blank\">Download Prospectus</a>\n  </div>\n</div>\n\n\n\n\n  \n  <!-- BACK TO TOP -->\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\n  </button>', 'images/new-images/Admissions-hero.jpeg', 0, '[{\"body\": \"Enrol in Kenya’s leading healthcare, hospitality, and social sciences training college. TVETA licensed. TVET CDACC accredited. NITA recognised. Globally respected. Apply Now Explore Courses\", \"heading\": \"Start Your Journey at GoCare\"}, {\"body\": \"Start your application – takes less than 5 minutes. Full Name Phone Number Course of Interest Select a course Healthcare Support Services (CNA) Perioperative Theatre Technology Mortuary Science Orthopaedic & Trauma Medicine Culinary Arts / Food & Beverage Social Work & Community Development International Certifications Start Application → 01 Admissions at GoCare\", \"heading\": \"Apply Today\"}, {\"body\": \"Everything you need to join Kenya\'s leading healthcare, hospitality, and social sciences training institute – from choosing your programme to completing your enrolment.\", \"heading\": \"Welcome to GoCare Admissions\"}, {\"body\": \"Apply online in minutes via our portal. No complex paperwork – just fill, upload, and submit. See the steps\", \"heading\": \"Simple Application\"}, {\"body\": \"We accept new students every month — January through December — so you can start whenever you’re ready. Apply Now\", \"heading\": \"Rolling Intake\"}, {\"body\": \"Fully accredited by TVETA, TVET CDACC, NITA and internationally recognised – your certificate holds global value. Check requirements 02 Application Process\", \"heading\": \"TVETA Accredited & Licensed\"}, {\"body\": \"Our digital admissions process is fast and straightforward. Follow these four steps to secure your place at GoCare. 1\", \"heading\": \"How to Apply\"}, {\"body\": \"Visit our online admissions portal and register your student account with a valid email address and phone number. 2\", \"heading\": \"Create an Account\"}, {\"body\": \"Complete the online form with your personal details, academic background, and preferred programme of study. 3\", \"heading\": \"Fill the Application Form\"}, {\"body\": \"Upload scanned copies of your KCSE certificate, National ID or Passport, and two recent passport photos. 4\", \"heading\": \"Upload Your Documents\"}, {\"body\": \"Submit your application and use the portal to track your admission status in real time. Receive your offer letter by email. 5 min Average application time Start Your Application 03 When to Join Registration Ongoing\", \"heading\": \"Submit & Track Your Status\"}, {\"body\": \"Stay informed about current and upcoming intakes — plan your enrolment early and secure your place. Registration & Admission for the Upcoming Intake is Ongoing — Apply Now! Multiple intakes throughout the year for different schedules. Admissions open on a rolling basis for select programmes. Apply early to secure your place in the next intake. Apply Now View Programmes Intake CalendarNew cohorts every month JanOpen FebOpen MarOpen AprOpen MayOpen JunOpen JulOpen AugOpen SepOpen OctOpen NovOpen DecOpen Rolling admissions — enrol any month and start in the next available cohort. 04 Eligibility\", \"heading\": \"Intakes & Deadlines\"}, {\"body\": \"At GoCare Training Institute, every learner has a pathway to success — no one is left behind.\", \"heading\": \"Entry Requirements\"}, {\"body\": \"From A to E, your KCSE mean grade opens a pathway to a course that fits you.\", \"heading\": \"Any KCSE Grade Qualifies\"}, {\"body\": \"Different courses have their own entry requirements, levels, and durations.\", \"heading\": \"Course-Specific Entry\"}, {\"body\": \"Completed KCPE? You also qualify to enrol in selected foundation programmes.\", \"heading\": \"KCPE Holders Welcome\"}, {\"body\": \"Visit individual course pages for the specific requirements of each programme. Browse all courses 05 Fees & Financing\", \"heading\": \"Check Your Course\"}, {\"body\": \"GoCare offers transparent, affordable fees with multiple financing options to ensure quality education is accessible to everyone.\", \"heading\": \"Fees & Payment Options\"}, {\"body\": \"Settle your tuition in a single, full payment at the start of the term – simple, convenient, and hassle-free.\", \"heading\": \"One-off Payments\"}, {\"body\": \"Spread your tuition across manageable monthly or termly instalments, paid conveniently via M-Pesa Paybill, bank transfer, or direct deposit. Detailed fee structures are provided with your admission letter as costs vary by programme. For a fee estimate, contact our admissions team or visit the Support section below. Second course sponsorship is also available for eligible enrolled students. 06 We Are Here for You\", \"heading\": \"Flexible Payments\"}, {\"body\": \"Our dedicated admissions team is available to guide you through every step of the process – from choosing a course to completing your enrolment.\", \"heading\": \"Admissions Support\"}, {\"body\": \"Get instant responses 24/7 via our WhatsApp helpdesk. Ideal for quick questions about courses, requirements, and deadlines. Chat on WhatsApp\", \"heading\": \"WhatsApp Helpdesk\"}, {\"body\": \"Send detailed queries to our admissions team. We respond within 24 hours on business days. Send an Email\", \"heading\": \"Email Support\"}, {\"body\": \"Visit our Nairobi campus admissions desk Monday–Friday, 8:00 AM – 5:00 PM for in-person guidance and document submission. Get Directions\", \"heading\": \"Campus Visit\"}, {\"body\": \"Join thousands of GoCare graduates building rewarding careers across Kenya and internationally. Apply Now Download Prospectus\", \"heading\": \"Ready to Take the First Step?\"}]', 'admissions.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(3, 'Alumni Network | GoCare Training Institute', 'alumni-network', '<div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\n    <div class=\"ck-inner\"><div class=\"ck-left\"><div class=\"ck-icon-wrap\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/><path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/></svg></div><div class=\"ck-copy\"><strong>We use cookies</strong><p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p></div></div><div class=\"ck-actions\"><button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button><button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button><button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div></div>\n  </div>\n\n  \n  <!-- -- NAVBAR ---------------------------------------- -->\n  \n  <!-- -- NAVBAR ---------------------------------------- -->\n  \n\n  <!-- -- SUB BAR --------------------------------------- -->\n  <div class=\"subbar\">\n    <div class=\"wrap subbar-inner\">\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\n      <div class=\"subbar-portals\">\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\n      </div>\n    </div>\n  </div>\n\n\n  \n\n  \n\n\n<div class=\"an-page\">\n\n  <!-- HERO -->\n    <!-- PAGE HERO -->\n  <section class=\"ph\">\n    <div class=\"ph-bg\">\n      <img loading=\"eager\" decoding=\"async\" src=\"images/new-images/PXL_20260523_105012660.MP~2.jpg.jpeg\" alt=\"GoCare graduates at their graduation ceremony\">\n    </div>\n    <div class=\"ph-overlay\"></div>\n    <div class=\"ph-inner\">\n      <div class=\"ph-content\">\n        <span class=\"ph-eyebrow\"><i data-lucide=\"users\"></i> GoCare Community</span>\n        \n        <h1>Our <em>Alumni</em> Network</h1>\n        <p>Over 5,000 graduates working across Kenya and internationally. Join a thriving community of healthcare and hospitality professionals who started at GoCare.</p>\n        <div class=\"ph-btns\">\n          <a href=\"alumni-network.html#join\" class=\"ph-btn-primary\">Join the Network <i data-lucide=\"arrow-right\"></i></a>\n          <a href=\"student-testimonials-success-stories.html\" class=\"ph-btn-ghost\">Success Stories <i data-lucide=\"arrow-right\"></i></a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── SECTION 1: BENEFITS &mdash; image left, list right ── -->\n  <section class=\"an-benefits\">\n    <div class=\"an-benefits-img\">\n      <img loading=\"lazy\" decoding=\"async\" src=\"images/alumni-community.jpg\" alt=\"GoCare alumni and students celebrating together at a community event\">\n      <div class=\"an-benefits-img-badge\"><i data-lucide=\"users\" style=\"width:14px;height:14px\"></i> 5,000+ Alumni Worldwide</div>\n    </div>\n    <div class=\"an-benefits-body\">\n      <span class=\"an-eyebrow\"><i data-lucide=\"star\"></i> Why Join</span>\n      <h2>A Network Built on <em>Shared Purpose</em></h2>\n      <p>The GoCare Alumni Network connects thousands of graduates across Kenya and internationally &mdash; opening doors to mentorship, opportunities, and lifelong friendships.</p>\n      <div class=\"an-benefit-list\">\n        <div class=\"an-benefit-item\">\n          <div class=\"an-benefit-ico\"><i data-lucide=\"handshake\" style=\"width:22px;height:22px\"></i></div>\n          <div>\n            <strong>Connect &amp; Inspire</strong>\n            <span>Network with fellow graduates across industries and geographies. Share experiences and build lasting professional relationships.</span>\n            <a href=\"contact.html\">Join the network <i data-lucide=\"arrow-right\" style=\"width:13px;height:13px\"></i></a>\n          </div>\n        </div>\n        <div class=\"an-benefit-item\">\n          <div class=\"an-benefit-ico\"><i data-lucide=\"lightbulb\" style=\"width:22px;height:22px\"></i></div>\n          <div>\n            <strong>Career Mentorship</strong>\n            <span>Get guidance from senior alumni who have walked the same path and achieved remarkable success in their fields.</span>\n            <a href=\"#\">Find a mentor <i data-lucide=\"arrow-right\" style=\"width:13px;height:13px\"></i></a>\n          </div>\n        </div>\n        <div class=\"an-benefit-item\">\n          <div class=\"an-benefit-ico\"><i data-lucide=\"calendar\" style=\"width:22px;height:22px\"></i></div>\n          <div>\n            <strong>Exclusive Events</strong>\n            <span>Attend reunions, workshops, and networking events designed exclusively for GoCare graduates.</span>\n            <a href=\"events.html\">View events <i data-lucide=\"arrow-right\" style=\"width:13px;height:13px\"></i></a>\n          </div>\n        </div>\n        <div class=\"an-benefit-item\">\n          <div class=\"an-benefit-ico\"><i data-lucide=\"briefcase\" style=\"width:22px;height:22px\"></i></div>\n          <div>\n            <strong>Job Board Access</strong>\n            <span>Be the first to know about curated job vacancies shared through our alumni network and employer partners.</span>\n            <a href=\"careers.html\">Browse opportunities <i data-lucide=\"arrow-right\" style=\"width:13px;height:13px\"></i></a>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── SECTION 2: GRADUATE MOSAIC ── -->\n  <section class=\"an-mosaic-sec\">\n    <div class=\"an-wrap\">\n      <div class=\"an-mosaic-hd\">\n        <span class=\"an-eyebrow an-eyebrow--light\"><i data-lucide=\"graduation-cap\"></i> Class of GoCare</span>\n        <h2>Faces of Our Alumni Community</h2>\n        <p>Every face tells a story of determination, growth, and achievement. These are the men and women who define the GoCare legacy.</p>\n      </div>\n      <div class=\"an-mosaic-grid\">\n        <div class=\"an-mosaic-card\">\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC06020.jpg\" alt=\"GoCare graduate\">\n          <div class=\"an-mosaic-label\"><strong>Grace A.</strong><span>Healthcare &middot; Class of 2024</span></div>\n        </div>\n        <div class=\"an-mosaic-card\">\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC05974.jpg\" alt=\"GoCare graduate\">\n          <div class=\"an-mosaic-label\"><strong>Brian M.</strong><span>Business Admin &middot; Class of 2023</span></div>\n        </div>\n        <div class=\"an-mosaic-card\">\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC05978.jpg\" alt=\"GoCare graduate\">\n          <div class=\"an-mosaic-label\"><strong>Irene N.</strong><span>Community Dev &middot; Class of 2024</span></div>\n        </div>\n        <div class=\"an-mosaic-card\">\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC05970.jpg\" alt=\"GoCare graduate\">\n          <div class=\"an-mosaic-label\"><strong>Kevin O.</strong><span>Hospitality &middot; Class of 2023</span></div>\n        </div>\n        <div class=\"an-mosaic-card\">\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC05991.jpg\" alt=\"GoCare graduate\">\n          <div class=\"an-mosaic-label\"><strong>Sandra W.</strong><span>Medical Sciences &middot; Class of 2024</span></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── SECTION 3: COMMUNITY IMPACT &mdash; text left, image right ── -->\n  <section class=\"an-impact\">\n    <div class=\"an-impact-body\">\n      <span class=\"an-eyebrow\"><i data-lucide=\"globe\"></i> Giving Back</span>\n      <h2>Alumni Who <em>Give Back</em> to Society</h2>\n      <p>GoCare graduates don\'t just build careers &mdash; they build communities. Our alumni are at the forefront of environmental, social, and health initiatives across Kenya.</p>\n      <ul class=\"an-impact-points\">\n        <li>\n          <div class=\"an-impact-dot\"><i data-lucide=\"leaf\" style=\"width:16px;height:16px\"></i></div>\n          Community tree planting and environmental drives\n        </li>\n        <li>\n          <div class=\"an-impact-dot\"><i data-lucide=\"heart-pulse\" style=\"width:16px;height:16px\"></i></div>\n          Free health camps and awareness clinics in underserved areas\n        </li>\n        <li>\n          <div class=\"an-impact-dot\"><i data-lucide=\"users\" style=\"width:16px;height:16px\"></i></div>\n          Youth mentorship and career guidance programmes\n        </li>\n        <li>\n          <div class=\"an-impact-dot\"><i data-lucide=\"book-open\" style=\"width:16px;height:16px\"></i></div>\n          Scholarship drives for deserving incoming students\n        </li>\n      </ul>\n      <a href=\"contact.html\" class=\"an-impact-link\">Get Involved <i data-lucide=\"arrow-right\" style=\"width:16px;height:16px\"></i></a>\n    </div>\n    <div class=\"an-impact-img\">\n      <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/IMG_6389.JPG\" alt=\"GoCare alumni tree planting community activity\">\n    </div>\n  </section>\n\n  <!-- ── SECTION 4: STATS BANNER ── -->\n  <section class=\"an-stats-banner\">\n    <div class=\"an-stats-bg\"><img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC05519.jpg\" alt=\"GoCare graduation ceremony\"></div>\n    <div class=\"an-stats-overlay\"></div>\n    <div class=\"an-wrap an-stats-inner\">\n      <span class=\"an-eyebrow an-eyebrow--light\"><i data-lucide=\"bar-chart-2\"></i> Alumni Impact</span>\n      <h2>A Growing Legacy of <em>Excellence</em></h2>\n      <p>From Nairobi to the world &mdash; GoCare graduates are making their mark every day across healthcare, hospitality, business, and beyond.</p>\n      <div class=\"an-stats-row\">\n        <div class=\"an-stat\"><span>5,000+</span><small>Total Graduates</small></div>\n        <div class=\"an-stat-div\"></div>\n        <div class=\"an-stat\"><span>95%</span><small>Employment Rate</small></div>\n        <div class=\"an-stat-div\"></div>\n        <div class=\"an-stat\"><span>6+</span><small>Countries</small></div>\n        <div class=\"an-stat-div\"></div>\n        <div class=\"an-stat\"><span>30+</span><small>Industry Partners</small></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── SECTION 5: EVENTS &mdash; image left, text right ── -->\n  <section class=\"an-events\">\n    <div class=\"an-events-img\">\n      <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/WhatsApp Image 2026-04-20 at 12.29.14.jpeg\" alt=\"GoCare alumni event on campus\">\n    </div>\n    <div class=\"an-events-body\">\n      <span class=\"an-eyebrow\"><i data-lucide=\"calendar\"></i> Stay Connected</span>\n      <h2>Alumni <em>Events &amp; Reunions</em></h2>\n      <p>We keep the GoCare spirit alive through regular events that bring graduates together to celebrate, reconnect, and grow. Whether online or on campus, there\'s always a reason to come back.</p>\n      <div class=\"an-event-list\">\n        <div class=\"an-event-item\">\n          <i data-lucide=\"award\" class=\"an-event-ico\" style=\"width:22px;height:22px\"></i>\n          <div><strong>Annual Graduation Ceremony</strong><span>Celebrating each new class of GoCare graduates with dignity and pride.</span></div>\n        </div>\n        <div class=\"an-event-item\">\n          <i data-lucide=\"users\" class=\"an-event-ico\" style=\"width:22px;height:22px\"></i>\n          <div><strong>Alumni Networking Nights</strong><span>Quarterly evenings where professionals connect, mentor, and collaborate.</span></div>\n        </div>\n        <div class=\"an-event-item\">\n          <i data-lucide=\"mic\" class=\"an-event-ico\" style=\"width:22px;height:22px\"></i>\n          <div><strong>Career Talk Series</strong><span>Senior alumni return to campus to inspire and guide current students.</span></div>\n        </div>\n        <div class=\"an-event-item\">\n          <i data-lucide=\"leaf\" class=\"an-event-ico\" style=\"width:22px;height:22px\"></i>\n          <div><strong>Community Service Days</strong><span>Alumni come together for tree planting, health camps, and social impact activities.</span></div>\n        </div>\n      </div>\n      <a href=\"events.html\" class=\"an-events-link\">View All Events <i data-lucide=\"arrow-right\" style=\"width:16px;height:16px\"></i></a>\n    </div>\n  </section>\n\n  <!-- ── SECTION 6: CTA ── -->\n  <section class=\"an-cta\" id=\"join\">\n    <div class=\"an-cta-bg\"><img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/PXL_20260207_075037132.PORTRAIT.ORIGINAL~2.jpg\" alt=\"GoCare students at campus\"></div>\n    <div class=\"an-cta-overlay\"></div>\n    <div class=\"an-wrap an-cta-inner\">\n      <h2>Ready to Join Our Alumni Network?</h2>\n      <p>Stay connected with GoCare, unlock exclusive opportunities, and become part of a community that continues to grow and give back long after graduation.</p>\n      <div class=\"an-cta-btns\">\n        <a href=\"contact.html\" class=\"an-cta-btn-primary\">Join Now <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></a>\n        <a href=\"student-testimonials-success-stories.html\" class=\"an-cta-btn-ghost\">Success Stories <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></a>\n      </div>\n    </div>\n  </section>\n</div>\n  \n  \n  <!-- BACK TO TOP -->\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\n  </button>', 'images/new-images/PXL_20260523_105012660.MP~2.jpg.jpeg', 0, '[{\"body\": \"Over 5,000 graduates working across Kenya and internationally. Join a thriving community of healthcare and hospitality professionals who started at GoCare. Join the Network Success Stories 5,000+ Alumni Worldwide Why Join\", \"heading\": \"Our Alumni Network\"}, {\"body\": \"The GoCare Alumni Network connects thousands of graduates across Kenya and internationally — opening doors to mentorship, opportunities, and lifelong friendships. Connect & Inspire Network with fellow graduates across industries and geographies. Share experiences and build lasting professional relationships. Join the network Career Mentorship Get guidance from senior alumni who have walked the same path and achieved remarkable success in their fields. Find a mentor Exclusive Events Attend reunions, workshops, and networking events designed exclusively for GoCare graduates. View events Job Board Access Be the first to know about curated job vacancies shared through our alumni network and employer partners. Browse opportunities Class of GoCare\", \"heading\": \"A Network Built on Shared Purpose\"}, {\"body\": \"Every face tells a story of determination, growth, and achievement. These are the men and women who define the GoCare legacy. Grace A.Healthcare · Class of 2024 Brian M.Business Admin · Class of 2023 Irene N.Community Dev · Class of 2024 Kevin O.Hospitality · Class of 2023 Sandra W.Medical Sciences · Class of 2024 Giving Back\", \"heading\": \"Faces of Our Alumni Community\"}, {\"body\": \"GoCare graduates don\'t just build careers — they build communities. Our alumni are at the forefront of environmental, social, and health initiatives across Kenya. Community tree planting and environmental drives Free health camps and awareness clinics in underserved areas Youth mentorship and career guidance programmes Scholarship drives for deserving incoming students Get Involved Alumni Impact\", \"heading\": \"Alumni Who Give Back to Society\"}, {\"body\": \"From Nairobi to the world — GoCare graduates are making their mark every day across healthcare, hospitality, business, and beyond. 5,000+Total Graduates 95%Employment Rate 6+Countries 30+Industry Partners Stay Connected\", \"heading\": \"A Growing Legacy of Excellence\"}, {\"body\": \"We keep the GoCare spirit alive through regular events that bring graduates together to celebrate, reconnect, and grow. Whether online or on campus, there\'s always a reason to come back. Annual Graduation CeremonyCelebrating each new class of GoCare graduates with dignity and pride. Alumni Networking NightsQuarterly evenings where professionals connect, mentor, and collaborate. Career Talk SeriesSenior alumni return to campus to inspire and guide current students. Community Service DaysAlumni come together for tree planting, health camps, and social impact activities. View All Events\", \"heading\": \"Alumni Events & Reunions\"}, {\"body\": \"Stay connected with GoCare, unlock exclusive opportunities, and become part of a community that continues to grow and give back long after graduation. Join Now Success Stories\", \"heading\": \"Ready to Join Our Alumni Network?\"}]', 'alumni-network.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(4, 'Application Form - Step 2: Education Background | GoCare Training Institute', 'application-form-step2', '<div class=\"app-hero\">\r\n      <div class=\"app-hero-inner\">\r\n        <h1>Application Form</h1>\r\n        <p>Step 2 of 6 &mdash; Education Background</p>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"app-wrap\">\r\n      <div class=\"stepper\">\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Personal Details</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle active\">2</div><div class=\"step-label active-label\">Education</div></div></div>\r\n        <div class=\"step-line active\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">3</div><div class=\"step-label pending-label\">Course Selection</div></div></div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">4</div><div class=\"step-label pending-label\">Documents</div></div></div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">5</div><div class=\"step-label pending-label\">Payment</div></div></div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">6</div><div class=\"step-label pending-label\">Review &amp; Submit</div></div></div>\r\n      </div>\r\n\r\n      <div class=\"app-grid\">\r\n        <div class=\"app-form-card\">\r\n          <h2><i data-lucide=\"graduation-cap\" style=\"color:var(--o)\"></i> Step 2: Education Background</h2>\r\n          <form id=\"step2Form\">\r\n            <div class=\"form-group\">\r\n              <label>Highest Qualification *</label>\r\n              <select required>\r\n                <option value=\"\">Select</option>\r\n                <option>KCPE</option>\r\n                <option selected>KCSE</option>\r\n                <option>Certificate</option>\r\n                <option>Diploma</option>\r\n                <option>Degree</option>\r\n                <option>Other</option>\r\n              </select>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>School Name *</label>\r\n                <input type=\"text\" placeholder=\"e.g. Alliance High School\" required>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Year of Completion *</label>\r\n                <select required>\r\n                  <option value=\"\">Select Year</option>\r\n                  <option>2025</option><option>2024</option><option>2023</option><option>2022</option><option>2021</option><option>2020</option><option>2019</option><option>Earlier</option>\r\n                </select>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>KCSE Grade *</label>\r\n                <select required>\r\n                  <option value=\"\">Select Grade</option>\r\n                  <option>A</option><option>A-</option><option>B+</option><option>B</option><option>B-</option><option selected>C+</option><option>C</option><option>C-</option><option>D+</option><option>D</option><option>D-</option><option>E</option>\r\n                </select>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Index Number</label>\r\n                <input type=\"text\" placeholder=\"e.g. 12345678/2024\">\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label>Any Additional Qualifications / Certifications</label>\r\n              <textarea rows=\"3\" placeholder=\"List any additional certificates, diplomas, or professional qualifications...\"></textarea>\r\n            </div>\r\n            <div class=\"form-actions\">\r\n              <a href=\"application-form.html\" class=\"btn-prev\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i> Previous</a>\r\n              <button type=\"button\" class=\"btn-next\" onclick=\"window.location.href=\'application-form-step3.html\'\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></button>\r\n            </div>\r\n          </form>\r\n        </div>\r\n\r\n        <div style=\"display:flex;flex-direction:column;gap:24px;\">\r\n          <div class=\"sidebar-tips\">\r\n            <h3><i data-lucide=\"lightbulb\"></i> Education Tips</h3>\r\n            <ul>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Enter your highest completed qualification.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> KCSE C+ and above qualify for diploma programs.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> KCSE C- to D+ qualify for certificate programs.</li>\r\n            </ul>\r\n          </div>\r\n          <div class=\"sidebar-card\">\r\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/Certificate-culinary-arts.jpg\" alt=\"Students in class\">\r\n            <div class=\"sidebar-body\">\r\n              <h3>Entry Requirements</h3>\r\n              <p>Check if you qualify for your desired program:</p>\r\n              <ul>\r\n                <li><i data-lucide=\"award\"></i> Diploma: KCSE C+ or above</li>\r\n                <li><i data-lucide=\"award\"></i> Certificate: KCSE C- to D+</li>\r\n                <li><i data-lucide=\"award\"></i> Artisan: KCSE D or below</li>\r\n              </ul>\r\n              <a href=\"admissions.html#requirements\" class=\"btn-next\" style=\"display:block;text-align:center;margin-top:16px;text-decoration:none;font-size:0.9rem;\">View Full Requirements</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"app-footer-nav\">\r\n        <div></div>\r\n        <a href=\"admissions.html#how-to-apply\" class=\"btn-prev\">View How to Apply Guide <i data-lucide=\"external-link\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></a>\r\n      </div>\r\n    </div>', NULL, 0, '[{\"body\": \"Step 2 of 6 — Education Background Personal Details 2Education 3Course Selection 4Documents 5Payment 6Review & Submit\", \"heading\": \"Application Form\"}, {\"body\": \"Highest Qualification * Select KCPE KCSE Certificate Diploma Degree Other School Name * Year of Completion * Select Year 2025202420232022202120202019Earlier KCSE Grade * Select Grade AA-B+BB-C+CC-D+DD-E Index Number Any Additional Qualifications / Certifications Previous Save & Continue\", \"heading\": \"Step 2: Education Background\"}, {\"body\": \"Enter your highest completed qualification. KCSE C+ and above qualify for diploma programs. KCSE C- to D+ qualify for certificate programs.\", \"heading\": \"Education Tips\"}, {\"body\": \"Check if you qualify for your desired program: Diploma: KCSE C+ or above Certificate: KCSE C- to D+ Artisan: KCSE D or below View Full Requirements View How to Apply Guide\", \"heading\": \"Entry Requirements\"}]', 'application-form-step2.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(5, 'Application Form - Step 3: Course Selection | GoCare Training Institute', 'application-form-step3', '<div class=\"app-hero\">\r\n      <div class=\"app-hero-inner\">\r\n        <h1>Application Form</h1>\r\n        <p>Step 3 of 6 &mdash; Course Selection</p>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"app-wrap\">\r\n      <div class=\"stepper\">\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Personal Details</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Education</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle active\">3</div><div class=\"step-label active-label\">Course Selection</div></div></div>\r\n        <div class=\"step-line active\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">4</div><div class=\"step-label pending-label\">Documents</div></div></div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">5</div><div class=\"step-label pending-label\">Payment</div></div></div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">6</div><div class=\"step-label pending-label\">Review &amp; Submit</div></div></div>\r\n      </div>\r\n\r\n      <div class=\"app-grid\">\r\n        <div class=\"app-form-card\">\r\n          <h2><i data-lucide=\"book-open\" style=\"color:var(--o)\"></i> Step 3: Select Your Course</h2>\r\n          <form id=\"step3Form\">\r\n            <div class=\"form-group\">\r\n              <label>Preferred School *</label>\r\n              <select id=\"schoolSelect\" required>\r\n                <option value=\"\">Select School</option>\r\n                <option>School of Medical &amp; Health Sciences</option>\r\n                <option>School of Hospitality Management</option>\r\n                <option>School of Social Sciences &amp; Business Management</option>\r\n                <option>International Certifications</option>\r\n              </select>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label>Program *</label>\r\n              <select required>\r\n                <option value=\"\">Select Program</option>\r\n                <option>Diploma in Perioperative Theatre Technology - Level 6</option>\r\n                <option>Diploma in Mortuary Science - Level 6</option>\r\n                <option>Diploma in Orthopaedic &amp; Trauma Medicine - Level 6</option>\r\n                <option>Diploma in Community Health Assistant - Level 6</option>\r\n                <option>Certificate in Healthcare Support Services - Level 5 (CNA)</option>\r\n                <option>Certificate in Caregiving - Level 4</option>\r\n                <option>Certificate in Home-Based Care Support - Level 3</option>\r\n                <option>Certificate in Food &amp; Beverage Production (Culinary Arts) - Level 3</option>\r\n                <option>Certificate in Front Office Operations - Level 3</option>\r\n                <option>Certificate in Housekeeping &amp; Accommodation - Level 3</option>\r\n                <option>Certificate in Homecare Management - Level 4</option>\r\n                <option>Diploma in Social Work &amp; Community Development - Level 6</option>\r\n                <option>Certificate in Office Administrator - Level 5</option>\r\n                <option>AMCA (USA) Certification</option>\r\n                <option>SDC Canada Certification</option>\r\n              </select>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>Preferred Intake *</label>\r\n                <select required>\r\n                  <option value=\"\">Select Intake</option>\r\n                  <option>January 2026</option>\r\n                  <option>May 2026</option>\r\n                  <option>September 2026</option>\r\n                </select>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Preferred Campus *</label>\r\n                <select required>\r\n                  <option value=\"\">Select Campus</option>\r\n                  <option>Nairobi City Campus (CBD)</option>\r\n                  <option>Thika Road Campus</option>\r\n                </select>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label>Preferred Study Mode *</label>\r\n              <div style=\"display:flex;gap:15px;flex-wrap:wrap;padding:8px 0;\">\r\n                <label style=\"display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:500;\"><input type=\"radio\" name=\"mode\" value=\"day\"> Day</label>\r\n                <label style=\"display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:500;\"><input type=\"radio\" name=\"mode\" value=\"evening\"> Evening</label>\r\n                <label style=\"display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:500;\"><input type=\"radio\" name=\"mode\" value=\"saturday\"> Saturday</label>\r\n                <label style=\"display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:500;\"><input type=\"radio\" name=\"mode\" value=\"online\"> Online/Distance</label>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-actions\">\r\n              <a href=\"application-form-step2.html\" class=\"btn-prev\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i> Previous</a>\r\n              <button type=\"button\" class=\"btn-next\" onclick=\"window.location.href=\'application-form-step4.html\'\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></button>\r\n            </div>\r\n          </form>\r\n        </div>\r\n\r\n        <div style=\"display:flex;flex-direction:column;gap:24px;\">\r\n          <div class=\"sidebar-tips\">\r\n            <h3><i data-lucide=\"lightbulb\"></i> Choosing a Course</h3>\r\n            <ul>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Select your preferred school and specific program.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Eligible students get a FREE second international certification.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> You can change your selection later if needed.</li>\r\n            </ul>\r\n          </div>\r\n          <div class=\"sidebar-card\">\r\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/gocare-students-group.jpg\" alt=\"GoCare students\">\r\n            <div class=\"sidebar-body\">\r\n              <h3>Popular Programs</h3>\r\n              <ul>\r\n                <li><i data-lucide=\"trending-up\"></i> Healthcare Support Services (CNA)</li>\r\n                <li><i data-lucide=\"trending-up\"></i> Caregiving Level 4</li>\r\n                <li><i data-lucide=\"trending-up\"></i> Perioperative Theatre Technology</li>\r\n                <li><i data-lucide=\"trending-up\"></i> Culinary Arts</li>\r\n              </ul>\r\n              <a href=\"courses.html\" class=\"btn-next\" style=\"display:block;text-align:center;margin-top:16px;text-decoration:none;font-size:0.9rem;\">Browse All Courses</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"app-footer-nav\">\r\n        <a href=\"courses.html\" class=\"btn-prev\">View All Courses <i data-lucide=\"external-link\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></a>\r\n      </div>\r\n    </div>', NULL, 0, '[{\"body\": \"Step 3 of 6 — Course Selection Personal Details Education 3Course Selection 4Documents 5Payment 6Review & Submit\", \"heading\": \"Application Form\"}, {\"body\": \"Preferred School * Select School School of Medical & Health Sciences School of Hospitality Management School of Social Sciences & Business Management International Certifications Program * Select Program Diploma in Perioperative Theatre Technology - Level 6 Diploma in Mortuary Science - Level 6 Diploma in Orthopaedic & Trauma Medicine - Level 6 Diploma in Community Health Assistant - Level 6 Certificate in Healthcare Support Services - Level 5 (CNA) Certificate in Caregiving - Level 4 Certificate in Home-Based Care Support - Level 3 Certificate in Food & Beverage Production (Culinary Arts) - Level 3 Certificate in Front Office Operations - Level 3 Certificate in Housekeeping & Accommodation - Level 3 Certificate in Homecare Management - Level 4 Diploma in Social Work & Community Development - Level 6 Certificate in Office Administrator - Level 5 AMCA (USA) Certification SDC Canada Certification Preferred Intake * Select Intake January 2026 May 2026 September 2026 Preferred Campus * Select Campus Nairobi City Campus (CBD) Thika Road Campus Preferred Study Mode * Day Evening Saturday Online/Distance Previous Save & Continue\", \"heading\": \"Step 3: Select Your Course\"}, {\"body\": \"Select your preferred school and specific program. Eligible students get a FREE second international certification. You can change your selection later if needed.\", \"heading\": \"Choosing a Course\"}, {\"body\": \"Healthcare Support Services (CNA) Caregiving Level 4 Perioperative Theatre Technology Culinary Arts Browse All Courses View All Courses\", \"heading\": \"Popular Programs\"}]', 'application-form-step3.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(6, 'Application Form - Step 4: Documents | GoCare Training Institute', 'application-form-step4', '<div class=\"app-hero\">\r\n      <div class=\"app-hero-inner\">\r\n        <h1>Application Form</h1>\r\n        <p>Step 4 of 6 &mdash; Documents Upload</p>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"app-wrap\">\r\n      <div class=\"stepper\">\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Personal Details</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Education</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Course Selection</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle active\">4</div><div class=\"step-label active-label\">Documents</div></div></div>\r\n        <div class=\"step-line active\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">5</div><div class=\"step-label pending-label\">Payment</div></div></div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">6</div><div class=\"step-label pending-label\">Review &amp; Submit</div></div></div>\r\n      </div>\r\n\r\n      <div class=\"app-grid\">\r\n        <div class=\"app-form-card\">\r\n          <h2><i data-lucide=\"file-up\" style=\"color:var(--o)\"></i> Step 4: Upload Documents</h2>\r\n          <form id=\"step4Form\">\r\n            <div class=\"form-group\">\r\n              <label>National ID / Passport Copy *</label>\r\n              <div class=\"upload-zone\">\r\n                <i data-lucide=\"upload-cloud\"></i>\r\n                <p class=\"upload-label\">Click to upload or drag and drop</p>\r\n                <p>PDF, JPG or PNG (Max 5MB)</p>\r\n                <input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" style=\"display:none\">\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label>KCSE Result Slip / Certificate *</label>\r\n              <div class=\"upload-zone\">\r\n                <i data-lucide=\"upload-cloud\"></i>\r\n                <p class=\"upload-label\">Click to upload or drag and drop</p>\r\n                <p>PDF, JPG or PNG (Max 5MB)</p>\r\n                <input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" style=\"display:none\">\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label>Passport-Size Photo *</label>\r\n              <div class=\"upload-zone\">\r\n                <i data-lucide=\"upload-cloud\"></i>\r\n                <p class=\"upload-label\">Click to upload or drag and drop</p>\r\n                <p>JPG or PNG (Max 2MB)</p>\r\n                <input type=\"file\" accept=\".jpg,.jpeg,.png\" style=\"display:none\">\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label>Additional Certificates (Optional)</label>\r\n              <div class=\"upload-zone\">\r\n                <i data-lucide=\"upload-cloud\"></i>\r\n                <p class=\"upload-label\">Click to upload or drag and drop</p>\r\n                <p>PDF, JPG or PNG (Max 5MB each)</p>\r\n                <input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" multiple style=\"display:none\">\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <p style=\"font-size:0.85rem;color:#64748b;\"><i data-lucide=\"info\" style=\"width:16px;height:16px;display:inline;vertical-align:middle;color:var(--o)\"></i> Don&rsquo;t have documents yet? You can upload them later. Click &ldquo;Continue&rdquo; to proceed.</p>\r\n            </div>\r\n            <div class=\"form-actions\">\r\n              <a href=\"application-form-step3.html\" class=\"btn-prev\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i> Previous</a>\r\n              <button type=\"button\" class=\"btn-next\" onclick=\"window.location.href=\'application-form-step5.html\'\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></button>\r\n            </div>\r\n          </form>\r\n        </div>\r\n\r\n        <div style=\"display:flex;flex-direction:column;gap:24px;\">\r\n          <div class=\"sidebar-tips\">\r\n            <h3><i data-lucide=\"lightbulb\"></i> Document Requirements</h3>\r\n            <ul>\r\n              <li><i data-lucide=\"check-circle-2\"></i> ID/Passport must be clear and legible.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Result slip must show all subjects and grades.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Photo should be passport-size with white background.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> All files should be under 5MB each.</li>\r\n            </ul>\r\n          </div>\r\n          <div class=\"sidebar-card\">\r\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/Healthcare-professional.jpg\" alt=\"GoCare campus\">\r\n            <div class=\"sidebar-body\">\r\n              <h3>Submission Options</h3>\r\n              <p>If you cannot upload online, you may submit physical copies:</p>\r\n              <ul>\r\n                <li><i data-lucide=\"map-pin\"></i> Nairobi CBD Campus: GatKim Complex</li>\r\n                <li><i data-lucide=\"map-pin\"></i> Ruiru Campus: Eastern Bypass</li>\r\n                <li><i data-lucide=\"mail\"></i> Email: admissions@gocareinstitute.ac.ke</li>\r\n              </ul>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"app-footer-nav\">\r\n        <a href=\"admissions.html#requirements\" class=\"btn-prev\">Check Entry Requirements <i data-lucide=\"external-link\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></a>\r\n      </div>\r\n    </div>', NULL, 0, '[{\"body\": \"Step 4 of 6 — Documents Upload Personal Details Education Course Selection 4Documents 5Payment 6Review & Submit\", \"heading\": \"Application Form\"}, {\"body\": \"National ID / Passport Copy * Click to upload or drag and drop PDF, JPG or PNG (Max 5MB) KCSE Result Slip / Certificate * Click to upload or drag and drop PDF, JPG or PNG (Max 5MB) Passport-Size Photo * Click to upload or drag and drop JPG or PNG (Max 2MB) Additional Certificates (Optional) Click to upload or drag and drop PDF, JPG or PNG (Max 5MB each) Don’t have documents yet? You can upload them later. Click “Continue” to proceed. Previous Save & Continue\", \"heading\": \"Step 4: Upload Documents\"}, {\"body\": \"ID/Passport must be clear and legible. Result slip must show all subjects and grades. Photo should be passport-size with white background. All files should be under 5MB each.\", \"heading\": \"Document Requirements\"}, {\"body\": \"If you cannot upload online, you may submit physical copies: Nairobi CBD Campus: GatKim Complex Ruiru Campus: Eastern Bypass Email: admissions@gocareinstitute.ac.ke Check Entry Requirements\", \"heading\": \"Submission Options\"}]', 'application-form-step4.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(7, 'Application Form - Step 5: Payment | GoCare Training Institute', 'application-form-step5', '<div class=\"app-hero\">\r\n      <div class=\"app-hero-inner\">\r\n        <h1>Application Form</h1>\r\n        <p>Step 5 of 6 &mdash; Payment</p>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"app-wrap\">\r\n      <div class=\"stepper\">\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Personal Details</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Education</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Course Selection</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Documents</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle active\">5</div><div class=\"step-label active-label\">Payment</div></div></div>\r\n        <div class=\"step-line active\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\">6</div><div class=\"step-label pending-label\">Review &amp; Submit</div></div></div>\r\n      </div>\r\n\r\n      <div class=\"app-grid\">\r\n        <div class=\"app-form-card\">\r\n          <h2><i data-lucide=\"credit-card\" style=\"color:var(--o)\"></i> Step 5: Application Fee Payment</h2>\r\n          <form id=\"step5Form\">\r\n            <div class=\"form-group\">\r\n              <label>Select Payment Method</label>\r\n              <div class=\"pay-methods\">\r\n                <div class=\"pay-card\" onclick=\"selectPay(this)\">\r\n                  <i data-lucide=\"smartphone\"></i>\r\n                  <h4>M-Pesa</h4>\r\n                  <p>Pay via Lipa Na M-Pesa</p>\r\n                </div>\r\n                <div class=\"pay-card\" onclick=\"selectPay(this)\">\r\n                  <i data-lucide=\"landmark\"></i>\r\n                  <h4>Bank Transfer</h4>\r\n                  <p>Direct bank deposit</p>\r\n                </div>\r\n                <div class=\"pay-card\" onclick=\"selectPay(this)\">\r\n                  <i data-lucide=\"receipt\"></i>\r\n                  <h4>Pay at Campus</h4>\r\n                  <p>Cash or card at counter</p>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"payment-info-box\" id=\"mpesaInfo\" style=\"display:none\">\r\n              <h4><i data-lucide=\"smartphone\"></i> M-Pesa Payment Instructions</h4>\r\n              <p>1. Go to M-Pesa on your phone<br>2. Select <strong>Lipa Na M-Pesa</strong> then <strong>Pay Bill</strong><br>3. Enter Business Number: <strong>400200</strong><br>4. Enter Account: <strong>Your ID Number</strong><br>5. Confirm and enter your M-Pesa PIN</p>\r\n            </div>\r\n\r\n            <div class=\"payment-info-box\" id=\"bankInfo\" style=\"display:none\">\r\n              <h4><i data-lucide=\"landmark\"></i> Bank Transfer Details</h4>\r\n              <p><strong>Bank:</strong> Kenya Commercial Bank<br><strong>Account Name:</strong> GoCare Training Institute<br><strong>Account Number:</strong> 1234567890<br><strong>Branch:</strong> Nairobi CBD<br>Use your name as the payment reference.</p>\r\n            </div>\r\n\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>Transaction Code (if paid)</label>\r\n                <input type=\"text\" placeholder=\"e.g. SHK3XY8ZT9\">\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Payment Date</label>\r\n                <input type=\"date\">\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"form-group\">\r\n              <label>Upload Payment Receipt (Optional)</label>\r\n              <div class=\"upload-zone\" style=\"border:2px dashed #cbd5e1;border-radius:12px;padding:20px;text-align:center;cursor:pointer;transition:0.3s;background:#f8fafc;\">\r\n                <i data-lucide=\"upload-cloud\" style=\"color:var(--o)\"></i>\r\n                <p style=\"color:#64748b;font-size:0.9rem;margin-top:5px\">JPG, PNG or PDF (Max 2MB)</p>\r\n                <input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" style=\"display:none\">\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"form-group\">\r\n              <p style=\"font-size:0.85rem;color:#64748b;\"><i data-lucide=\"info\" style=\"width:16px;height:16px;display:inline;vertical-align:middle;color:var(--o)\"></i> Payment must be completed before your application can be processed. Allow 24 hours for confirmation.</p>\r\n            </div>\r\n\r\n            <div class=\"form-actions\">\r\n              <a href=\"application-form-step4.html\" class=\"btn-prev\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i> Previous</a>\r\n              <button type=\"button\" class=\"btn-next\" onclick=\"window.location.href=\'application-form-step6.html\'\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></button>\r\n            </div>\r\n          </form>\r\n        </div>\r\n\r\n        <div style=\"display:flex;flex-direction:column;gap:24px;\">\r\n          <div class=\"sidebar-tips\">\r\n            <h3><i data-lucide=\"lightbulb\"></i> Payment Tips</h3>\r\n            <ul>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Save your M-Pesa confirmation SMS.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Use your full name as payment reference.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Keep your receipt for records.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Contact finance if payment fails: <strong>0703 115 502</strong></li>\r\n            </ul>\r\n          </div>\r\n          <div class=\"sidebar-card\">\r\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/Healthcare-professional.jpg\" alt=\"GoCare campus\">\r\n            <div class=\"sidebar-body\">\r\n              <h3>Fee Assistance</h3>\r\n              <p>Need help with fees? We offer flexible payment plans and can guide you on available options.</p>\r\n              <ul>\r\n                <li><i data-lucide=\"clock\"></i> Pay at counter: Mon-Fri, 8AM-5PM</li>\r\n                <li><i data-lucide=\"phone\"></i> Call: 0703 115 502</li>\r\n                <li><i data-lucide=\"mail\"></i> finance@gocareinstitute.ac.ke</li>\r\n              </ul>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"app-footer-nav\">\r\n        <a href=\"admissions.html#fees\" class=\"btn-prev\">View Fee Structure <i data-lucide=\"external-link\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></a>\r\n      </div>\r\n    </div>', NULL, 0, '[{\"body\": \"Step 5 of 6 — Payment Personal Details Education Course Selection Documents 5Payment 6Review & Submit\", \"heading\": \"Application Form\"}, {\"body\": \"Select Payment Method\", \"heading\": \"Step 5: Application Fee Payment\"}, {\"body\": \"Pay via Lipa Na M-Pesa\", \"heading\": \"M-Pesa\"}, {\"body\": \"Direct bank deposit\", \"heading\": \"Bank Transfer\"}, {\"body\": \"Cash or card at counter\", \"heading\": \"Pay at Campus\"}, {\"body\": \"1. Go to M-Pesa on your phone2. Select Lipa Na M-Pesa then Pay Bill3. Enter Business Number: 4002004. Enter Account: Your ID Number5. Confirm and enter your M-Pesa PIN\", \"heading\": \"M-Pesa Payment Instructions\"}, {\"body\": \"Bank: Kenya Commercial BankAccount Name: GoCare Training InstituteAccount Number: 1234567890Branch: Nairobi CBDUse your name as the payment reference. Transaction Code (if paid) Payment Date Upload Payment Receipt (Optional) JPG, PNG or PDF (Max 2MB) Payment must be completed before your application can be processed. Allow 24 hours for confirmation. Previous Save & Continue\", \"heading\": \"Bank Transfer Details\"}, {\"body\": \"Save your M-Pesa confirmation SMS. Use your full name as payment reference. Keep your receipt for records. Contact finance if payment fails: 0703 115 502\", \"heading\": \"Payment Tips\"}, {\"body\": \"Need help with fees? We offer flexible payment plans and can guide you on available options. Pay at counter: Mon-Fri, 8AM-5PM Call: 0703 115 502 finance@gocareinstitute.ac.ke View Fee Structure\", \"heading\": \"Fee Assistance\"}]', 'application-form-step5.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(8, 'Application Form - Step 6: Review & Submit | GoCare Training Institute', 'application-form-step6', '<div class=\"app-hero\">\r\n      <div class=\"app-hero-inner\">\r\n        <h1>Application Form</h1>\r\n        <p>Step 6 of 6 &mdash; Review &amp; Submit</p>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"app-wrap\">\r\n      <div class=\"stepper\">\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Personal Details</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Education</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Course Selection</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Documents</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle done\"><i data-lucide=\"check\" style=\"width:20px;height:20px\"></i></div><div class=\"step-label done-label\">Payment</div></div></div>\r\n        <div class=\"step-line done\"></div>\r\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle active\">6</div><div class=\"step-label active-label\">Review &amp; Submit</div></div></div>\r\n      </div>\r\n\r\n      <div class=\"app-grid\">\r\n        <div class=\"app-form-card\">\r\n          <h2><i data-lucide=\"clipboard-check\" style=\"color:var(--o)\"></i> Step 6: Review Your Application</h2>\r\n\r\n          <div class=\"review-section\">\r\n            <div class=\"review-header\" onclick=\"toggleReview(this)\">\r\n              <h3><i data-lucide=\"user\"></i> Personal Details</h3>\r\n              <a href=\"application-form.html\">Edit</a>\r\n            </div>\r\n            <div class=\"review-body\">\r\n              <div class=\"review-row\"><span class=\"review-label\">Full Name</span><span class=\"review-value\">Jane Doe</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Email</span><span class=\"review-value\">jane@example.com</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Phone</span><span class=\"review-value\">0712 345 678</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Date of Birth</span><span class=\"review-value\">15 Jan 2000</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Gender</span><span class=\"review-value\">Female</span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"review-section\">\r\n            <div class=\"review-header\" onclick=\"toggleReview(this)\">\r\n              <h3><i data-lucide=\"graduation-cap\"></i> Education Background</h3>\r\n              <a href=\"application-form-step2.html\">Edit</a>\r\n            </div>\r\n            <div class=\"review-body\">\r\n              <div class=\"review-row\"><span class=\"review-label\">Highest Level</span><span class=\"review-value\">KCSE (Secondary)</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">School</span><span class=\"review-value\">Nairobi High School</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Year Completed</span><span class=\"review-value\">2019</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Grade / Index</span><span class=\"review-value\">B+ (Plus 68)</span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"review-section\">\r\n            <div class=\"review-header\" onclick=\"toggleReview(this)\">\r\n              <h3><i data-lucide=\"book-open\"></i> Course Selection</h3>\r\n              <a href=\"application-form-step3.html\">Edit</a>\r\n            </div>\r\n            <div class=\"review-body\">\r\n              <div class=\"review-row\"><span class=\"review-label\">Program</span><span class=\"review-value\">School of Medical & Health Sciences</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Course</span><span class=\"review-value\">Certificate in Nursing (Enrolled)</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Campus</span><span class=\"review-value\">Nairobi CBD</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Intake</span><span class=\"review-value\">May 2026</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Mode of Study</span><span class=\"review-value\">Full-time</span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"review-section\">\r\n            <div class=\"review-header\" onclick=\"toggleReview(this)\">\r\n              <h3><i data-lucide=\"file-text\"></i> Documents &amp; Payment</h3>\r\n              <a href=\"application-form-step4.html\">Edit</a>\r\n            </div>\r\n            <div class=\"review-body\">\r\n              <div class=\"review-row\"><span class=\"review-label\">ID/Passport</span><span class=\"review-value\">Uploaded</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Result Slip</span><span class=\"review-value\">Uploaded</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Passport Photo</span><span class=\"review-value\">Uploaded</span></div>\r\n              <div class=\"review-row\"><span class=\"review-label\">Payment Method</span><span class=\"review-value\">M-Pesa</span></div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"checkbox-agree\">\r\n            <input type=\"checkbox\" id=\"agreeTerms\">\r\n            <label for=\"agreeTerms\">I confirm that all the information provided is accurate and complete. I agree to the <a href=\"index.html#\">Terms &amp; Conditions</a> and <a href=\"index.html#\">Privacy Policy</a> of GoCare Training Institute. I understand that providing false information may lead to disqualification.</label>\r\n          </div>\r\n\r\n          <div class=\"form-actions\">\r\n            <a href=\"application-form-step5.html\" class=\"btn-prev\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i> Previous</a>\r\n            <button type=\"button\" class=\"btn-submit\" id=\"submitBtn\" onclick=\"submitApplication()\"><i data-lucide=\"send\"></i> Submit Application</button>\r\n          </div>\r\n        </div>\r\n\r\n        <div style=\"display:flex;flex-direction:column;gap:24px;\">\r\n          <div class=\"sidebar-tips\">\r\n            <h3><i data-lucide=\"lightbulb\"></i> Before You Submit</h3>\r\n            <ul>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Double-check all personal details for accuracy.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Ensure your course selection is correct.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Confirm payment has been made.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> You will receive a confirmation email after submission.</li>\r\n            </ul>\r\n          </div>\r\n          <div class=\"sidebar-card\">\r\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/Healthcare-professional.jpg\" alt=\"GoCare campus\">\r\n            <div class=\"sidebar-body\">\r\n              <h3>Need Help?</h3>\r\n              <p>If you have questions about your application, reach out to our admissions team.</p>\r\n              <ul>\r\n                <li><i data-lucide=\"phone\"></i> 0703 115 502 / 0745 220 344</li>\r\n                <li><i data-lucide=\"mail\"></i> admissions@gocareinstitute.ac.ke</li>\r\n                <li><i data-lucide=\"clock\"></i> Mon-Fri: 8AM - 5PM</li>\r\n              </ul>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>', NULL, 0, '[{\"body\": \"Step 6 of 6 — Review & Submit Personal Details Education Course Selection Documents Payment 6Review & Submit\", \"heading\": \"Application Form\"}, {\"body\": \"\", \"heading\": \"Step 6: Review Your Application\"}, {\"body\": \"Edit Full NameJane Doe Emailjane@example.com Phone0712 345 678 Date of Birth15 Jan 2000 GenderFemale\", \"heading\": \"Personal Details\"}, {\"body\": \"Edit Highest LevelKCSE (Secondary) SchoolNairobi High School Year Completed2019 Grade / IndexB+ (Plus 68)\", \"heading\": \"Education Background\"}, {\"body\": \"Edit ProgramSchool of Medical & Health Sciences CourseCertificate in Nursing (Enrolled) CampusNairobi CBD IntakeMay 2026 Mode of StudyFull-time\", \"heading\": \"Course Selection\"}, {\"body\": \"Edit ID/PassportUploaded Result SlipUploaded Passport PhotoUploaded Payment MethodM-Pesa I confirm that all the information provided is accurate and complete. I agree to the Terms & Conditions and Privacy Policy of GoCare Training Institute. I understand that providing false information may lead to disqualification. Previous Submit Application\", \"heading\": \"Documents & Payment\"}, {\"body\": \"Double-check all personal details for accuracy. Ensure your course selection is correct. Confirm payment has been made. You will receive a confirmation email after submission.\", \"heading\": \"Before You Submit\"}, {\"body\": \"If you have questions about your application, reach out to our admissions team. 0703 115 502 / 0745 220 344 admissions@gocareinstitute.ac.ke Mon-Fri: 8AM - 5PM\", \"heading\": \"Need Help?\"}]', 'application-form-step6.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46'),
(9, 'Application Form - Step 1: Personal Details | GoCare Training Institute', 'application-form', '<div class=\"app-hero\">\r\n      <div class=\"app-hero-inner\">\r\n        <h1>Application Form</h1>\r\n        <p>Step 1 of 6 &mdash; Personal Details</p>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"app-wrap\">\r\n      <!-- Stepper -->\r\n      <div class=\"stepper\">\r\n        <div class=\"step-item\">\r\n          <div class=\"step-col\">\r\n            <div class=\"step-circle active\">1</div>\r\n            <div class=\"step-label active-label\">Personal Details</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"step-line active\"></div>\r\n        <div class=\"step-item\">\r\n          <div class=\"step-col\">\r\n            <div class=\"step-circle pending\">2</div>\r\n            <div class=\"step-label pending-label\">Education</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\">\r\n          <div class=\"step-col\">\r\n            <div class=\"step-circle pending\">3</div>\r\n            <div class=\"step-label pending-label\">Course Selection</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\">\r\n          <div class=\"step-col\">\r\n            <div class=\"step-circle pending\">4</div>\r\n            <div class=\"step-label pending-label\">Documents</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\">\r\n          <div class=\"step-col\">\r\n            <div class=\"step-circle pending\">5</div>\r\n            <div class=\"step-label pending-label\">Payment</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"step-line pending\"></div>\r\n        <div class=\"step-item\">\r\n          <div class=\"step-col\">\r\n            <div class=\"step-circle pending\">6</div>\r\n            <div class=\"step-label pending-label\">Review &amp; Submit</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"app-grid\">\r\n        <!-- Form -->\r\n        <div class=\"app-form-card\">\r\n          <h2><i data-lucide=\"user\" style=\"color:var(--o)\"></i> Step 1: Personal Details</h2>\r\n          <form id=\"step1Form\">\r\n            <div class=\"form-group\">\r\n              <label>Full Name (As per ID/Passport) *</label>\r\n              <input type=\"text\" placeholder=\"e.g. John Kamau Mwangi\" required>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>Gender *</label>\r\n                <div class=\"radio-group\">\r\n                  <label><input type=\"radio\" name=\"gender\" value=\"male\"> Male</label>\r\n                  <label><input type=\"radio\" name=\"gender\" value=\"female\"> Female</label>\r\n                </div>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Date of Birth *</label>\r\n                <input type=\"date\" required>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>Nationality *</label>\r\n                <select required>\r\n                  <option value=\"\">Select</option>\r\n                  <option selected>Kenyan</option>\r\n                  <option>Ugandan</option>\r\n                  <option>Tanzanian</option>\r\n                  <option>Other</option>\r\n                </select>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>ID/Passport Number *</label>\r\n                <input type=\"text\" placeholder=\"e.g. 12345678\" required>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>Phone Number *</label>\r\n                <div class=\"phone-prefix\">\r\n                  <span>+254</span>\r\n                  <input type=\"tel\" placeholder=\"712345678\" required>\r\n                </div>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Email Address *</label>\r\n                <input type=\"email\" placeholder=\"john@example.com\" required>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-row\">\r\n              <div class=\"form-group\">\r\n                <label>County of Residence *</label>\r\n                <select required>\r\n                  <option value=\"\">Select County</option>\r\n                  <option>Nairobi</option>\r\n                  <option>Mombasa</option>\r\n                  <option>Kiambu</option>\r\n                  <option>Nakuru</option>\r\n                  <option>Kisumu</option>\r\n                  <option>Other</option>\r\n                </select>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label>Home Address</label>\r\n                <input type=\"text\" placeholder=\"Estate, Street, House No.\">\r\n              </div>\r\n            </div>\r\n            <div class=\"form-actions\">\r\n              <a href=\"apply.html\" class=\"btn-cancel\">Cancel</a>\r\n              <button type=\"button\" class=\"btn-next\" onclick=\"window.location.href=\'application-form-step2.html\'\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i></button>\r\n            </div>\r\n          </form>\r\n        </div>\r\n\r\n        <!-- Sidebar -->\r\n        <div style=\"display:flex;flex-direction:column;gap:24px;\">\r\n          <div class=\"sidebar-tips\">\r\n            <h3><i data-lucide=\"lightbulb\"></i> Application Tips</h3>\r\n            <ul>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Ensure your name matches your national ID exactly.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Provide a valid email &mdash; admission updates go there.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> You can save your progress and return later.</li>\r\n            </ul>\r\n          </div>\r\n\r\n          <div class=\"sidebar-card\">\r\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/Nursing-Assistant.jpg\" alt=\"GoCare student in training\">\r\n            <div class=\"sidebar-body\">\r\n              <h3>Need Help?</h3>\r\n              <p>Our admissions team is ready to assist you.</p>\r\n              <ul>\r\n                <li><i data-lucide=\"phone\"></i> 0703 115 502 / 0745 229 485</li>\r\n                <li><i data-lucide=\"mail\"></i> admissions@gocareinstitute.ac.ke</li>\r\n                <li><i data-lucide=\"message-circle\"></i> WhatsApp Support Available</li>\r\n              </ul>\r\n              <a href=\"contact.html\" class=\"btn-next\" style=\"display:block;text-align:center;margin-top:16px;text-decoration:none;font-size:0.9rem;\">Contact Support</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"app-footer-nav\">\r\n        <a href=\"apply.html\" class=\"btn-cancel\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px;display:inline;vertical-align:middle\"></i> Back to Apply</a>\r\n      </div>\r\n    </div>', NULL, 0, '[{\"body\": \"Step 1 of 6 — Personal Details 1 Personal Details 2 Education 3 Course Selection 4 Documents 5 Payment 6 Review & Submit\", \"heading\": \"Application Form\"}, {\"body\": \"Full Name (As per ID/Passport) * Gender * Male Female Date of Birth * Nationality * Select Kenyan Ugandan Tanzanian Other ID/Passport Number * Phone Number * +254 Email Address * County of Residence * Select County Nairobi Mombasa Kiambu Nakuru Kisumu Other Home Address Cancel Save & Continue\", \"heading\": \"Step 1: Personal Details\"}, {\"body\": \"Ensure your name matches your national ID exactly. Provide a valid email — admission updates go there. You can save your progress and return later.\", \"heading\": \"Application Tips\"}, {\"body\": \"Our admissions team is ready to assist you. 0703 115 502 / 0745 229 485 admissions@gocareinstitute.ac.ke WhatsApp Support Available Contact Support Back to Apply\", \"heading\": \"Need Help?\"}]', 'application-form.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(10, 'Online Application · GoCare Training Institute', 'apply', '<!-- PAGE HERO -->\n    <section class=\"ph\">\n      <div class=\"ph-bg\">\n        <img loading=\"eager\" decoding=\"async\" src=\"images/new-images/Admissions-hero.jpeg\" alt=\"Apply to GoCare Training Institute\">\n      </div>\n      <div class=\"ph-overlay\"></div>\n      <div class=\"ph-inner\">\n        <div class=\"ph-content\">\n          <span class=\"ph-eyebrow\"><i data-lucide=\"file-edit\"></i> Admissions Open</span>\n          <nav class=\"ph-breadcrumb\" aria-label=\"Breadcrumb\">\n            <a href=\"index.html\">Home</a><i data-lucide=\"chevron-right\"></i><span>Apply Now</span>\n          </nav>\n          <h1>Application <em>Form</em></h1>\n          <p id=\"heroSub\">Registration and Admission Ongoing &mdash; Begin Your Journey</p>\n          <div class=\"ph-btns\">\n            <a href=\"#formIntro\" class=\"ph-btn-primary\">Start Application <i data-lucide=\"arrow-right\"></i></a>\n            <a href=\"courses.html\" class=\"ph-btn-ghost\">Explore Courses <i data-lucide=\"arrow-right\"></i></a>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <div class=\"app-wrap\">\n\n      <!-- INTRO WELCOME SCREEN -->\n      <div class=\"form-intro\" id=\"formIntro\">\n        <h1>APPLICATION FORM - 2026</h1>\n        <p class=\"intro-lead\"><strong>Welcome! Follow the next steps as guided to kickstart your journey to academic empowerment and career success!</strong></p>\n        <p><em>We are honored and delighted by your interest and decision to join us to pursue a course that will lead you to your dream career. We have established a tradition of excellence and high academic standards, and we commit to work endlessly to retain our position as your ideal training college of choice.</em></p>\n        <p><em>Our college provides our students with a well-rounded training experience that meets international standards coupled with character development, holistic education and exposure to appropriate skills and competencies to empower, equip and prepare students who are confident, proactive and responsible citizens with the capacity to compete, access and pursue opportunities locally and globally.</em></p>\n        <p><em>We are fully registered, regulated, licensed and accredited by the Ministry of Education, TVETA, TVET CDACC, NITA, KNEC and KHPOA. We are also an approved international training and examination center; USA, CANADA, IRELAND etc.</em></p>\n        <button class=\"intro-begin-btn\" id=\"introBeginBtn\">Begin Application <i data-lucide=\"arrow-right\"></i></button>\n      </div>\n\n      <!-- STEPPER -->\n      <div class=\"stepper\" id=\"stepper\" style=\"display:none;\">\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"1\">1</div><div class=\"step-label pending-label\">Personal Details</div></div></div>\n        <div class=\"step-line pending\" data-line=\"1\"></div>\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"2\">2</div><div class=\"step-label pending-label\">Education</div></div></div>\n        <div class=\"step-line pending\" data-line=\"2\"></div>\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"3\">3</div><div class=\"step-label pending-label\">Course Selection</div></div></div>\n        <div class=\"step-line pending\" data-line=\"3\"></div>\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"4\">4</div><div class=\"step-label pending-label\">Documents</div></div></div>\n        <div class=\"step-line pending\" data-line=\"4\"></div>\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"5\">5</div><div class=\"step-label pending-label\">Payment</div></div></div>\n        <div class=\"step-line pending\" data-line=\"5\"></div>\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"6\">6</div><div class=\"step-label pending-label\">Accommodation</div></div></div>\n        <div class=\"step-line pending\" data-line=\"6\"></div>\n        <div class=\"step-item\"><div class=\"step-col\"><div class=\"step-circle pending\" data-circle=\"7\">7</div><div class=\"step-label pending-label\">Review &amp; Submit</div></div></div>\n      </div>\n\n      <!-- FORM GRID -->\n      <div class=\"app-grid\" id=\"appGrid\" style=\"display:none;\">\n        <div>\n\n          <!-- STEP 1: PERSONAL DETAILS -->\n          <div class=\"form-step active\" id=\"step1\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"user\" style=\"color:var(--o)\"></i> Step 1: Personal Details</h2>\n              <div class=\"form-group\">\n                <label>Full Name (As per ID/Passport) *</label>\n                <input type=\"text\" id=\"f_name\" placeholder=\"e.g. John Kamau Mwangi\">\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>Gender *</label>\n                  <div class=\"radio-group\">\n                    <label><input type=\"radio\" name=\"gender\" value=\"Male\"> Male</label>\n                    <label><input type=\"radio\" name=\"gender\" value=\"Female\"> Female</label>\n                  </div>\n                </div>\n                <div class=\"form-group\">\n                  <label>Date of Birth *</label>\n                  <input type=\"date\" id=\"f_dob\">\n                </div>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>Nationality *</label>\n                  <select id=\"f_nationality\"><option value=\"\">Select</option><option selected>Kenyan</option><option>Ugandan</option><option>Tanzanian</option><option>Other</option></select>\n                </div>\n                <div class=\"form-group\">\n                  <label>ID/Passport Number *</label>\n                  <input type=\"text\" id=\"f_id\" placeholder=\"e.g. 12345678\">\n                </div>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>Phone Number *</label>\n                  <div class=\"phone-prefix\"><span>+254</span><input type=\"tel\" id=\"f_phone\" placeholder=\"712345678\"></div>\n                </div>\n                <div class=\"form-group\">\n                  <label>Email Address *</label>\n                  <input type=\"email\" id=\"f_email\" placeholder=\"john@example.com\">\n                </div>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>County of Residence *</label>\n                  <select id=\"f_county\">\n                    <option value=\"\">Select County</option>\n                    <option>Baringo</option>\n                    <option>Bomet</option>\n                    <option>Bungoma</option>\n                    <option>Busia</option>\n                    <option>Elgeyo-Marakwet</option>\n                    <option>Embu</option>\n                    <option>Garissa</option>\n                    <option>Homa Bay</option>\n                    <option>Isiolo</option>\n                    <option>Kajiado</option>\n                    <option>Kakamega</option>\n                    <option>Kericho</option>\n                    <option>Kiambu</option>\n                    <option>Kilifi</option>\n                    <option>Kirinyaga</option>\n                    <option>Kisii</option>\n                    <option>Kisumu</option>\n                    <option>Kitui</option>\n                    <option>Kwale</option>\n                    <option>Laikipia</option>\n                    <option>Lamu</option>\n                    <option>Machakos</option>\n                    <option>Makueni</option>\n                    <option>Mandera</option>\n                    <option>Marsabit</option>\n                    <option>Meru</option>\n                    <option>Migori</option>\n                    <option>Mombasa</option>\n                    <option>Murang\'a</option>\n                    <option>Nairobi</option>\n                    <option>Nakuru</option>\n                    <option>Nandi</option>\n                    <option>Narok</option>\n                    <option>Nyamira</option>\n                    <option>Nyandarua</option>\n                    <option>Nyeri</option>\n                    <option>Samburu</option>\n                    <option>Siaya</option>\n                    <option>Taita-Taveta</option>\n                    <option>Tana River</option>\n                    <option>Tharaka-Nithi</option>\n                    <option>Trans Nzoia</option>\n                    <option>Turkana</option>\n                    <option>Uasin Gishu</option>\n                    <option>Vihiga</option>\n                    <option>Wajir</option>\n                    <option>West Pokot</option>\n                  </select>\n                </div>\n                <div class=\"form-group\">\n                  <label>Home Address</label>\n                  <input type=\"text\" id=\"f_address\" placeholder=\"Estate, Street, House No.\">\n                </div>\n              </div>\n              <div class=\"form-actions\">\n                <a href=\"index.html\" class=\"btn-prev\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Cancel</a>\n                <button type=\"button\" class=\"btn-next\" data-next=\"2\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></button>\n              </div>\n            </div>\n          </div>\n\n          <!-- STEP 2: EDUCATION -->\n          <div class=\"form-step\" id=\"step2\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"graduation-cap\" style=\"color:var(--o)\"></i> Step 2: Education Background</h2>\n              <div class=\"form-group\">\n                <label>Highest Qualification *</label>\n                <select id=\"f_qual\"><option value=\"\">Select</option><option>KCPE</option><option selected>KCSE</option><option>Certificate</option><option>Diploma</option><option>Degree</option><option>Other</option></select>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>School Name *</label>\n                  <input type=\"text\" id=\"f_school\" placeholder=\"e.g. Alliance High School\">\n                </div>\n                <div class=\"form-group\">\n                  <label>Year of Completion *</label>\n                  <select id=\"f_year\"><option value=\"\">Select Year</option><option>2025</option><option>2024</option><option>2023</option><option>2022</option><option>2021</option><option>2020</option><option>2019</option><option>Earlier</option></select>\n                </div>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>KCSE Grade *</label>\n                  <select id=\"f_grade\"><option value=\"\">Select Grade</option><option>A</option><option>A-</option><option>B+</option><option>B</option><option>B-</option><option selected>C+</option><option>C</option><option>C-</option><option>D+</option><option>D</option><option>D-</option><option>E</option></select>\n                </div>\n                <div class=\"form-group\">\n                  <label>Index Number</label>\n                  <input type=\"text\" id=\"f_index\" placeholder=\"e.g. 12345678/2024\">\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>Any Additional Qualifications / Certifications</label>\n                <textarea id=\"f_addqual\" rows=\"3\" placeholder=\"List any additional certificates, diplomas, or professional qualifications...\"></textarea>\n              </div>\n              <div class=\"form-actions\">\n                <button type=\"button\" class=\"btn-prev\" data-prev=\"1\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Previous</button>\n                <button type=\"button\" class=\"btn-next\" data-next=\"3\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></button>\n              </div>\n            </div>\n          </div>\n\n          <!-- STEP 3: COURSE SELECTION -->\n          <div class=\"form-step\" id=\"step3\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"book-open\" style=\"color:var(--o)\"></i> Step 3: Select Your Course</h2>\n              <div class=\"form-group\">\n                <label>Preferred School *</label>\n                <select id=\"f_school_sel\">\n                  <option value=\"\">Select School</option>\n                  <option value=\"medical\">School of Medical &amp; Health Sciences</option>\n                  <option value=\"hospitality\">School of Hospitality Management</option>\n                  <option value=\"social\">School of Social Sciences &amp; Business Management</option>\n                  <option value=\"intl\">International Certifications</option>\n                </select>\n              </div>\n              <div class=\"form-group\">\n                <label>Program *</label>\n                <select id=\"f_program\">\n                  <option value=\"\">Select Program</option>\n                </select>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\">\n                  <label>Preferred Intake *</label>\n                  <div style=\"display:flex;gap:10px;\">\n                    <select id=\"f_intake_month\" style=\"flex:1.4;\">\n                      <option value=\"\">Month</option>\n                      <option>January</option>\n                      <option>February</option>\n                      <option>March</option>\n                      <option>April</option>\n                      <option>May</option>\n                      <option>June</option>\n                      <option>July</option>\n                      <option>August</option>\n                      <option>September</option>\n                      <option>October</option>\n                      <option>November</option>\n                      <option>December</option>\n                    </select>\n                    <input type=\"number\" id=\"f_intake_year\" placeholder=\"Year\" min=\"2024\" max=\"2035\" style=\"flex:1;min-width:0;\">\n                  </div>\n                </div>\n                <div class=\"form-group\">\n                  <label>Preferred Campus *</label>\n                  <select id=\"f_campus\"><option value=\"\">Select Campus</option><option>Nairobi City Campus (CBD)</option><option>Thika Road Campus</option></select>\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>Preferred Study Mode *</label>\n                <div class=\"radio-group\">\n                  <label><input type=\"radio\" name=\"mode\" value=\"Day\"> Day</label>\n                  <label><input type=\"radio\" name=\"mode\" value=\"Evening\"> Evening</label>\n                  <label><input type=\"radio\" name=\"mode\" value=\"Saturday\"> Saturday</label>\n                  <label><input type=\"radio\" name=\"mode\" value=\"Online/Distance\"> Online/Distance</label>\n                </div>\n              </div>\n              <div class=\"form-actions\">\n                <button type=\"button\" class=\"btn-prev\" data-prev=\"2\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Previous</button>\n                <button type=\"button\" class=\"btn-next\" data-next=\"4\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></button>\n              </div>\n            </div>\n          </div>\n\n          <!-- STEP 4: DOCUMENTS -->\n          <div class=\"form-step\" id=\"step4\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"file-up\" style=\"color:var(--o)\"></i> Step 4: Upload Documents</h2>\n              <div class=\"form-group\">\n                <label>National ID / Passport Copy *</label>\n                <div class=\"upload-zone\"><i data-lucide=\"upload-cloud\"></i><p class=\"upload-label\">Click to upload or drag and drop</p><p>PDF, JPG or PNG (Max 5MB)</p><input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" style=\"display:none\"></div>\n              </div>\n              <div class=\"form-group\">\n                <label>KCSE Result Slip / Certificate *</label>\n                <div class=\"upload-zone\"><i data-lucide=\"upload-cloud\"></i><p class=\"upload-label\">Click to upload or drag and drop</p><p>PDF, JPG or PNG (Max 5MB)</p><input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" style=\"display:none\"></div>\n              </div>\n              <div class=\"form-group\">\n                <label>Passport-Size Photo *</label>\n                <div class=\"upload-zone\"><i data-lucide=\"upload-cloud\"></i><p class=\"upload-label\">Click to upload or drag and drop</p><p>JPG or PNG (Max 2MB)</p><input type=\"file\" accept=\".jpg,.jpeg,.png\" style=\"display:none\"></div>\n              </div>\n              <div class=\"form-group\">\n                <label>Additional Certificates (Optional)</label>\n                <div class=\"upload-zone\"><i data-lucide=\"upload-cloud\"></i><p class=\"upload-label\">Click to upload or drag and drop</p><p>PDF, JPG or PNG (Max 5MB each)</p><input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" multiple style=\"display:none\"></div>\n              </div>\n              <div class=\"form-group\">\n                <p style=\"font-size:0.85rem;color:#64748b;\"><i data-lucide=\"info\" style=\"width:16px;height:16px;display:inline;vertical-align:middle;color:var(--o)\"></i> Don&rsquo;t have documents yet? You can upload them later. Click &ldquo;Continue&rdquo; to proceed.</p>\n              </div>\n              <div class=\"form-actions\">\n                <button type=\"button\" class=\"btn-prev\" data-prev=\"3\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Previous</button>\n                <button type=\"button\" class=\"btn-next\" data-next=\"5\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></button>\n              </div>\n            </div>\n          </div>\n\n          <!-- STEP 5: PAYMENT -->\n          <div class=\"form-step\" id=\"step5\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"credit-card\" style=\"color:var(--o)\"></i> Step 5: Application Fee Payment</h2>\n              <div class=\"form-group\">\n                <label>Payment Method</label>\n                <div class=\"pay-methods\">\n                  <div class=\"pay-card selected\" id=\"mpesaCard\"><i data-lucide=\"smartphone\"></i><h4>M-Pesa</h4><p>STK Push to your phone</p></div>\n                </div>\n              </div>\n\n              <!-- M-Pesa STK Push prompt -->\n              <div class=\"payment-info-box\" id=\"mpesaInfo\" style=\"display:block\">\n                <h4><i data-lucide=\"smartphone\"></i> Pay via M-Pesa STK Push</h4>\n                <p style=\"margin-bottom:14px;\">Enter your M-Pesa registered phone number and click <strong>Send Payment Request</strong>. You will receive a prompt on your phone to confirm the payment.</p>\n                <div style=\"display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;\">\n                  <div style=\"flex:1;min-width:200px;\">\n                    <label style=\"font-size:.85rem;font-weight:600;color:#475569;display:block;margin-bottom:6px;\">M-Pesa Phone Number</label>\n                    <div class=\"phone-prefix\">\n                      <span>+254</span>\n                      <input type=\"tel\" id=\"f_mpesa_phone\" placeholder=\"7XX XXX XXX\" maxlength=\"9\" pattern=\"[0-9]{9}\" style=\"border-radius:0 10px 10px 0;\">\n                    </div>\n                  </div>\n                  <button type=\"button\" id=\"mpesaPromptBtn\" onclick=\"sendMpesaPrompt()\" style=\"background:linear-gradient(135deg,#4caf50,#388e3c);color:#fff;border:none;padding:14px 24px;border-radius:10px;font-weight:700;font-size:.95rem;cursor:pointer;white-space:nowrap;display:flex;align-items:center;gap:8px;\">\n                    <i data-lucide=\"send\"></i> Send Payment Request\n                  </button>\n                </div>\n                <div id=\"mpesaStatus\" style=\"margin-top:12px;display:none;\"></div>\n              </div>\n              <div class=\"form-row\">\n                <div class=\"form-group\"><label>Transaction Code (if paid)</label><input type=\"text\" id=\"f_txn\" placeholder=\"e.g. SHK3XY8ZT9\"></div>\n                <div class=\"form-group\"><label>Payment Date</label><input type=\"date\" id=\"f_paydate\"></div>\n              </div>\n              <div class=\"form-group\">\n                <label>Upload Payment Receipt (Optional)</label>\n                <div class=\"upload-zone\"><i data-lucide=\"upload-cloud\"></i><p>JPG, PNG or PDF (Max 2MB)</p><input type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" style=\"display:none\"></div>\n              </div>\n              <div class=\"form-group\">\n                <p style=\"font-size:0.85rem;color:#64748b;\"><i data-lucide=\"info\" style=\"width:16px;height:16px;display:inline;vertical-align:middle;color:var(--o)\"></i> Payment must be completed before your application can be processed. Allow 24 hours for confirmation.</p>\n              </div>\n              <div class=\"form-actions\">\n                <button type=\"button\" class=\"btn-prev\" data-prev=\"4\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Previous</button>\n                <button type=\"button\" class=\"btn-next\" data-next=\"6\">Save &amp; Continue <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></button>\n              </div>\n            </div>\n          </div>\n\n          <!-- STEP 6: HOSTEL & ACCOMMODATION -->\n          <div class=\"form-step\" id=\"step6\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"bed\" style=\"color:var(--o)\"></i> Step 6: Hostel &amp; Accommodation Preference</h2>\n              <p style=\"font-size:.92rem;color:#64748b;margin-bottom:20px;\">Would you like to apply for hostel accommodation at your campus?</p>\n\n              <div class=\"acc-toggle\">\n                <label class=\"acc-opt\" id=\"accYesOpt\">\n                  <input type=\"radio\" name=\"accommodation\" value=\"Yes\" onchange=\"toggleAccommodation()\">\n                  <i data-lucide=\"check-circle-2\"></i> Yes, I need accommodation\n                </label>\n                <label class=\"acc-opt selected\" id=\"accNoOpt\">\n                  <input type=\"radio\" name=\"accommodation\" value=\"No\" checked onchange=\"toggleAccommodation()\">\n                  <i data-lucide=\"x-circle\"></i> No, I&rsquo;ll arrange my own\n                </label>\n              </div>\n\n              <div class=\"acc-grid\">\n                <div class=\"acc-main\">\n                  <!-- YES panel -->\n                  <div id=\"accYesPanel\" style=\"display:none;\">\n                    <div class=\"form-group\">\n                      <label>Preferred Room Type *</label>\n                      <select id=\"f_room_type\">\n                        <option value=\"\">Select room type</option>\n                        <option>4 Occupants &middot; Shared Room</option>\n                        <option>6 Occupants &middot; Shared Room</option>\n                        <option>8 Occupants &middot; Shared Room</option>\n                      </select>\n                    </div>\n                    <div class=\"form-row\">\n                      <div class=\"form-group\">\n                        <label>Preferred Campus</label>\n                        <select id=\"f_acc_campus\">\n                          <option value=\"\">Select campus</option>\n                          <option>Nairobi City Campus</option>\n                          <option>Thika Road Campus &middot; Ruiru</option>\n                        </select>\n                      </div>\n                      <div class=\"form-group\">\n                        <label>Check-in Intake</label>\n                        <select id=\"f_acc_intake\">\n                          <option value=\"\">Select intake</option>\n                          <option>January</option>\n                          <option>February</option>\n                          <option>March</option>\n                          <option>April</option>\n                          <option>May</option>\n                          <option>June</option>\n                          <option>July</option>\n                          <option>August</option>\n                          <option>September</option>\n                          <option>October</option>\n                          <option>November</option>\n                          <option>December</option>\n                        </select>\n                      </div>\n                    </div>\n                    <div class=\"form-group\">\n                      <label>Special Requirements (Optional)</label>\n                      <textarea id=\"f_acc_notes\" rows=\"3\" placeholder=\"e.g. ground-floor room, accessibility or dietary needs\"></textarea>\n                    </div>\n                  </div>\n                  <!-- NO panel -->\n                  <div id=\"accNoPanel\" class=\"acc-nobox\">\n                    <i data-lucide=\"home\"></i>\n                    <p>You have chosen <strong>not to book</strong> hostel accommodation. You can still request it later by contacting the admissions office.</p>\n                  </div>\n                </div>\n\n                <aside class=\"acc-info\">\n                  <h4><i data-lucide=\"info\"></i> Important Info</h4>\n                  <ul>\n                    <li><i data-lucide=\"check-circle-2\"></i> Hostel rooms are allocated on a first-come, first-served basis.</li>\n                    <li><i data-lucide=\"wifi\"></i> All rooms include Wi-Fi &amp; study desks.</li>\n                    <li><i data-lucide=\"wallet\"></i> Accommodation fees are payable after admission confirmation.</li>\n                  </ul>\n                  <a href=\"hostels-and-accommodation.html\" class=\"acc-info-link\">View hostel details <i data-lucide=\"arrow-right\"></i></a>\n                </aside>\n              </div>\n\n              <div class=\"form-actions\">\n                <button type=\"button\" class=\"btn-prev\" data-prev=\"5\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Previous</button>\n                <button type=\"button\" class=\"btn-next\" data-next=\"7\">Proceed to Final Submission <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></button>\n              </div>\n            </div>\n          </div>\n\n          <!-- STEP 7: REVIEW & SUBMIT -->\n          <div class=\"form-step\" id=\"step7\">\n            <div class=\"app-form-card\">\n              <h2><i data-lucide=\"clipboard-check\" style=\"color:var(--o)\"></i> Step 7: Review Your Application</h2>\n\n              <div class=\"review-section\">\n                <div class=\"review-header\"><h3><i data-lucide=\"user\"></i> Personal Details</h3><button type=\"button\" data-goto=\"1\">Edit</button></div>\n                <div class=\"review-body\">\n                  <div class=\"review-row\"><span class=\"review-label\">Full Name</span><span class=\"review-value\" id=\"rv_name\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Email</span><span class=\"review-value\" id=\"rv_email\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Phone</span><span class=\"review-value\" id=\"rv_phone\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Date of Birth</span><span class=\"review-value\" id=\"rv_dob\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Gender</span><span class=\"review-value\" id=\"rv_gender\">&mdash;</span></div>\n                </div>\n              </div>\n\n              <div class=\"review-section\">\n                <div class=\"review-header\"><h3><i data-lucide=\"graduation-cap\"></i> Education Background</h3><button type=\"button\" data-goto=\"2\">Edit</button></div>\n                <div class=\"review-body\">\n                  <div class=\"review-row\"><span class=\"review-label\">Highest Level</span><span class=\"review-value\" id=\"rv_qual\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">School</span><span class=\"review-value\" id=\"rv_school\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Year Completed</span><span class=\"review-value\" id=\"rv_year\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Grade</span><span class=\"review-value\" id=\"rv_grade\">&mdash;</span></div>\n                </div>\n              </div>\n\n              <div class=\"review-section\">\n                <div class=\"review-header\"><h3><i data-lucide=\"book-open\"></i> Course Selection</h3><button type=\"button\" data-goto=\"3\">Edit</button></div>\n                <div class=\"review-body\">\n                  <div class=\"review-row\"><span class=\"review-label\">Course</span><span class=\"review-value\" id=\"rv_program\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Campus</span><span class=\"review-value\" id=\"rv_campus\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Intake</span><span class=\"review-value\" id=\"rv_intake\">&mdash;</span></div>\n                  <div class=\"review-row\"><span class=\"review-label\">Mode of Study</span><span class=\"review-value\" id=\"rv_mode\">&mdash;</span></div>\n                </div>\n              </div>\n\n              <div class=\"review-section\">\n                <div class=\"review-header\"><h3><i data-lucide=\"file-text\"></i> Payment</h3><button type=\"button\" data-goto=\"5\">Edit</button></div>\n                <div class=\"review-body\">\n                  <div class=\"review-row\"><span class=\"review-label\">Payment Method</span><span class=\"review-value\" id=\"rv_payment\">&mdash;</span></div>\n                </div>\n              </div>\n\n              <div class=\"review-section\">\n                <div class=\"review-header\"><h3><i data-lucide=\"bed\"></i> Hostel &amp; Accommodation</h3><button type=\"button\" data-goto=\"6\">Edit</button></div>\n                <div class=\"review-body\">\n                  <div class=\"review-row\"><span class=\"review-label\">Apply for Hostel</span><span class=\"review-value\" id=\"rv_acc\">&mdash;</span></div>\n                  <div class=\"review-row\" id=\"rv_room_row\" style=\"display:none;\"><span class=\"review-label\">Room Type</span><span class=\"review-value\" id=\"rv_room\">&mdash;</span></div>\n                </div>\n              </div>\n\n              <div class=\"checkbox-agree\">\n                <input type=\"checkbox\" id=\"agreeTerms\">\n                <label for=\"agreeTerms\">I confirm that all the information provided is accurate and complete. I agree to the <a href=\"index.html#\">Terms &amp; Conditions</a> and <a href=\"index.html#\">Privacy Policy</a> of GoCare Training Institute. I understand that providing false information may lead to disqualification.</label>\n              </div>\n\n              <div class=\"form-actions\">\n                <button type=\"button\" class=\"btn-prev\" data-prev=\"6\"><i data-lucide=\"arrow-left\" style=\"width:18px;height:18px\"></i> Previous</button>\n                <button type=\"button\" class=\"btn-submit\" id=\"submitBtn\" onclick=\"submitApplication()\"><i data-lucide=\"send\"></i> Submit Application</button>\n              </div>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- SIDEBAR -->\n        <aside class=\"app-sidebar\">\n          <div class=\"sidebar-tips\">\n            <h3><i data-lucide=\"lightbulb\"></i> Application Tips</h3>\n            <ul>\n              <li><i data-lucide=\"check-circle-2\"></i> Use your name exactly as it appears on your ID.</li>\n              <li><i data-lucide=\"check-circle-2\"></i> Provide a valid email &mdash; admission updates go there.</li>\n              <li><i data-lucide=\"check-circle-2\"></i> Eligible students get a FREE second international certification.</li>\n              <li><i data-lucide=\"check-circle-2\"></i> You can save progress and return to any step.</li>\n            </ul>\n          </div>\n          <div class=\"sidebar-card\">\n            <img loading=\"lazy\" decoding=\"async\" src=\"images/Nursing-Assistant.jpg\" alt=\"GoCare student in training\">\n            <div class=\"sidebar-body\">\n              <h3>Need Help?</h3>\n              <p>Our admissions team is ready to assist you through every step.</p>\n              <ul>\n                <li><i data-lucide=\"phone\"></i> 0703 115 502 / 0745 229 485</li>\n                <li><i data-lucide=\"mail\"></i> admissions@gocareinstitute.ac.ke</li>\n                <li><i data-lucide=\"clock\"></i> Mon-Fri: 8AM - 5PM</li>\n              </ul>\n              <a href=\"contact.html\" class=\"btn-next\" style=\"display:flex;justify-content:center;margin-top:16px;text-decoration:none;font-size:0.9rem;\">Contact Support</a>\n            </div>\n          </div>\n        </aside>\n      </div>\n    </div>', NULL, 0, '[{\"body\": \"Registration and Admission Ongoing — Begin Your Journey Start Application Explore Courses\", \"heading\": \"Application Form\"}, {\"body\": \"Welcome! Follow the next steps as guided to kickstart your journey to academic empowerment and career success! We are honored and delighted by your interest and decision to join us to pursue a course that will lead you to your dream career. We have established a tradition of excellence and high academic standards, and we commit to work endlessly to retain our position as your ideal training college of choice. Our college provides our students with a well-rounded training experience that meets international standards coupled with character development, holistic education and exposure to appropriate skills and competencies to empower, equip and prepare students who are confident, proactive and responsible citizens with the capacity to compete, access and pursue opportunities locally and globally. We are fully registered, regulated, licensed and accredited by the Ministry of Education, TVETA, TVET CDACC, NITA, KNEC and KHPOA. We are also an approved international training and examination center; USA, CANADA, IRELAND etc. Begin Application 1Personal Details 2Education 3Course Selection 4Documents 5Payment 6Accommodation 7Review & Submit\", \"heading\": \"APPLICATION FORM - 2026\"}, {\"body\": \"Full Name (As per ID/Passport) * Gender * Male Female Date of Birth * Nationality * SelectKenyanUgandanTanzanianOther ID/Passport Number * Phone Number * +254 Email Address * County of Residence * Select County Baringo Bomet Bungoma Busia Elgeyo-Marakwet Embu Garissa Homa Bay Isiolo Kajiado Kakamega Kericho Kiambu Kilifi Kirinyaga Kisii Kisumu Kitui Kwale Laikipia Lamu Machakos Makueni Mandera Marsabit Meru Migori Mombasa Murang\'a Nairobi Nakuru Nandi Narok Nyamira Nyandarua Nyeri Samburu Siaya Taita-Taveta Tana River Tharaka-Nithi Trans Nzoia Turkana Uasin Gishu Vihiga Wajir West Pokot Home Address Cancel Save & Continue\", \"heading\": \"Step 1: Personal Details\"}, {\"body\": \"Highest Qualification * SelectKCPEKCSECertificateDiplomaDegreeOther School Name * Year of Completion * Select Year2025202420232022202120202019Earlier KCSE Grade * Select GradeAA-B+BB-C+CC-D+DD-E Index Number Any Additional Qualifications / Certifications Previous Save & Continue\", \"heading\": \"Step 2: Education Background\"}, {\"body\": \"Preferred School * Select School School of Medical & Health Sciences School of Hospitality Management School of Social Sciences & Business Management International Certifications Program * Select Program Preferred Intake * Month January February March April May June July August September October November December Preferred Campus * Select CampusNairobi City Campus (CBD)Thika Road Campus Preferred Study Mode * Day Evening Saturday Online/Distance Previous Save & Continue\", \"heading\": \"Step 3: Select Your Course\"}, {\"body\": \"National ID / Passport Copy * Click to upload or drag and dropPDF, JPG or PNG (Max 5MB) KCSE Result Slip / Certificate * Click to upload or drag and dropPDF, JPG or PNG (Max 5MB) Passport-Size Photo * Click to upload or drag and dropJPG or PNG (Max 2MB) Additional Certificates (Optional) Click to upload or drag and dropPDF, JPG or PNG (Max 5MB each) Don’t have documents yet? You can upload them later. Click “Continue” to proceed. Previous Save & Continue\", \"heading\": \"Step 4: Upload Documents\"}, {\"body\": \"Payment Method\", \"heading\": \"Step 5: Application Fee Payment\"}, {\"body\": \"STK Push to your phone\", \"heading\": \"M-Pesa\"}, {\"body\": \"Enter your M-Pesa registered phone number and click Send Payment Request. You will receive a prompt on your phone to confirm the payment. M-Pesa Phone Number +254 Send Payment Request Transaction Code (if paid) Payment Date Upload Payment Receipt (Optional) JPG, PNG or PDF (Max 2MB) Payment must be completed before your application can be processed. Allow 24 hours for confirmation. Previous Save & Continue\", \"heading\": \"Pay via M-Pesa STK Push\"}, {\"body\": \"Would you like to apply for hostel accommodation at your campus? Yes, I need accommodation No, I’ll arrange my own Preferred Room Type * Select room type 4 Occupants · Shared Room 6 Occupants · Shared Room 8 Occupants · Shared Room Preferred Campus Select campus Nairobi City Campus Thika Road Campus · Ruiru Check-in Intake Select intake January February March April May June July August September October November December Special Requirements (Optional) You have chosen not to book hostel accommodation. You can still request it later by contacting the admissions office.\", \"heading\": \"Step 6: Hostel & Accommodation Preference\"}, {\"body\": \"Hostel rooms are allocated on a first-come, first-served basis. All rooms include Wi-Fi & study desks. Accommodation fees are payable after admission confirmation. View hostel details Previous Proceed to Final Submission\", \"heading\": \"Important Info\"}, {\"body\": \"\", \"heading\": \"Step 7: Review Your Application\"}, {\"body\": \"Edit Full Name— Email— Phone— Date of Birth— Gender—\", \"heading\": \"Personal Details\"}, {\"body\": \"Edit Highest Level— School— Year Completed— Grade—\", \"heading\": \"Education Background\"}, {\"body\": \"Edit Course— Campus— Intake— Mode of Study—\", \"heading\": \"Course Selection\"}, {\"body\": \"Edit Payment Method—\", \"heading\": \"Payment\"}, {\"body\": \"Edit Apply for Hostel— Room Type— I confirm that all the information provided is accurate and complete. I agree to the Terms & Conditions and Privacy Policy of GoCare Training Institute. I understand that providing false information may lead to disqualification. Previous Submit Application\", \"heading\": \"Hostel & Accommodation\"}, {\"body\": \"Use your name exactly as it appears on your ID. Provide a valid email — admission updates go there. Eligible students get a FREE second international certification. You can save progress and return to any step.\", \"heading\": \"Application Tips\"}, {\"body\": \"Our admissions team is ready to assist you through every step. 0703 115 502 / 0745 229 485 admissions@gocareinstitute.ac.ke Mon-Fri: 8AM - 5PM Contact Support\", \"heading\": \"Need Help?\"}]', 'apply.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:46');
INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(11, 'Insights & Updates | GoCare Training Institute', 'blog', '<div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\n    <div class=\"ck-inner\"><div class=\"ck-left\"><div class=\"ck-icon-wrap\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/><path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/></svg></div><div class=\"ck-copy\"><strong>We use cookies</strong><p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p></div></div><div class=\"ck-actions\"><button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button><button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button><button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div></div>\n  </div>\n\n  \n  <!-- -- NAVBAR ---------------------------------------- -->\n  \n  <!-- -- NAVBAR ---------------------------------------- -->\n  \n\n  <!-- -- SUB BAR --------------------------------------- -->\n  <div class=\"subbar\">\n    <div class=\"wrap subbar-inner\">\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\n      <div class=\"subbar-portals\">\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\n      </div>\n    </div>\n  </div>\n\n\n  \n\n  \n\n<div class=\"blog-page\">\n    <!-- PAGE HERO -->\n  <section class=\"ph\">\n    <div class=\"ph-bg\">\n      <img loading=\"eager\" decoding=\"async\" src=\"images/news-bg.jpg\" alt=\"Blog & Insights\">\n    </div>\n    <div class=\"ph-overlay\"></div>\n    <div class=\"ph-inner\">\n      <div class=\"ph-content\">\n        <span class=\"ph-eyebrow\"><i data-lucide=\"edit-3\"></i> Blog & Insights</span>\n        \n        <h1>GoCare <em>Insights</em> & Updates</h1>\n        <p>Expert articles, student success stories, industry news, and career advice from Kenya\'s leading healthcare and hospitality training institute.</p>\n        <div class=\"ph-btns\">\n          <a href=\"apply.html\" class=\"ph-btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- â”€â”€ FEATURED LEAD STORY â”€â”€ -->\n  <section class=\"blog-lead\">\n    <div class=\"blog-wrap\">\n      <div class=\"blog-lead-card\">\n        <div class=\"blog-lead-bg\">\n          <img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/DSC05874.jpg\" alt=\"GoCare graduation ceremony\">\n        </div>\n        <div class=\"blog-lead-overlay\"></div>\n        <div class=\"blog-lead-body\">\n          <div class=\"blog-lead-meta\">\n            <span class=\"blog-lead-tag\">Announcement</span>\n            <span class=\"blog-lead-date\"><i data-lucide=\"clock\" style=\"width:13px;height:13px\"></i> &nbsp;8 min read &middot; 15 May 2026</span>\n          </div>\n          <h2>GoCare Celebrates Its <em>Largest Graduating Class</em> Yet</h2>\n          <p>Over 600 graduates crossed the stage at this year\'s graduation ceremony &mdash; a record that reflects GoCare\'s commitment to transforming lives through quality, accessible education across Kenya.</p>\n          <a href=\"blog-graduation-class-2026.html\" class=\"blog-lead-btn\">Read Full Story <i data-lucide=\"arrow-right\" style=\"width:16px;height:16px\"></i></a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- â”€â”€ CATEGORY FILTER â”€â”€ -->\n  <section class=\"blog-filter\">\n    <div class=\"blog-wr