INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(21, 'Home Based Care | GoCare Training Institute', 'home-based-care', '<!-- COOKIE CONSENT -->\n  <div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\n    <div class=\"ck-inner\">\n      <div class=\"ck-left\">\n        <div class=\"ck-icon-wrap\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/>\n            <path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/>\n          </svg>\n        </div>\n        <div class=\"ck-copy\">\n          <strong>We use cookies</strong>\n          <p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p>\n        </div>\n      </div>\n      <div class=\"ck-actions\">\n        <button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button>\n        <button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button>\n        <button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- -- NAVBAR ---------------------------------------- -->\n  \n\n  <!-- -- SUB BAR --------------------------------------- -->\n  <div class=\"subbar\">\n    <div class=\"wrap subbar-inner\">\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\n      <div class=\"subbar-portals\">\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\n      </div>\n    </div>\n  </div>\n\n\n  \n\n  \n\n  \n\n\n\n<div class=\"ghs-page\">\n    <!-- PAGE HERO -->\n  <section class=\"ph\">\n    <div class=\"ph-bg\">\n      <img loading=\"eager\" decoding=\"async\" src=\"images/female-nurse-portrait-with-older-patient.jpg\" alt=\"GoCare caregiver with an elderly patient at home\">\n    </div>\n    <div class=\"ph-overlay\"></div>\n    <div class=\"ph-inner\">\n      <div class=\"ph-content\">\n        <span class=\"ph-eyebrow\"><i data-lucide=\"heart-pulse\"></i> GoCare Health Solutions</span>\n        \n        <h1>Professional <em>Home-Based Care</em></h1>\n        <p>Compassionate, professional healthcare in the comfort of your home &ndash; from nursing and elderly care to post-operative support, delivered by GoCare-trained caregivers.</p>\n        <div class=\"ph-btns\">\n          <a href=\"https://gocare.co.ke/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ph-btn-primary\">Request Home Care <i data-lucide=\"arrow-right\"></i></a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n    <!-- GHS BANNER HERO (mirrors GoCare Health Solutions banner) -->\n  <section class=\"ghs-hero\">\n    <div class=\"wrap\">\n      <div class=\"ghs-hero-top\">\n        <div class=\"ghs-logo\">\n          <div class=\"ghs-logo-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\" width=\"32\" height=\"32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 10.5 12 3l9 7.5\"/><path d=\"M5 9.5V21h14V9.5\"/><path d=\"M12 12v5M9.5 14.5h5\"/></svg>\n          </div>\n          <div class=\"ghs-logo-text\">\n            <h2>Go<em style=\"color:#642a7e;font-style:normal\">Care</em></h2>\n            <span>Health Solutions</span>\n          </div>\n        </div>\n        <p class=\"ghs-tagline\">The Homecare Experts&hellip; Experience Peace &amp; Joy!</p>\n      </div>\n\n      <div class=\"ghs-hero-main\">\n        <div class=\"ghs-hero-img\">\n          <img loading=\"eager\" decoding=\"async\" src=\"images/new-images/IMG_5629.jpeg\" alt=\"GoCare caregiver with an elderly patient at home\">\n        </div>\n\n        <div class=\"ghs-cards-wrap\">\n          <div class=\"ghs-cards-row\">\n            <div class=\"ghs-card\">\n              <div class=\"ghs-card-icon\"><i data-lucide=\"heart-pulse\" style=\"width:48px;height:48px\"></i></div>\n              <h4>Home-Based Care Services</h4>\n              <p>Personalized medical support at home</p>\n            </div>\n            <div class=\"ghs-card ghs-card--purple\">\n              <div class=\"ghs-card-icon\" style=\"color:#4a1a6d\"><i data-lucide=\"dumbbell\" style=\"width:48px;height:48px\"></i></div>\n              <h4 style=\"color:#4a1a6d\">Physiotherapy at Home</h4>\n              <p>Rehabilitation &amp; mobility recovery</p>\n            </div>\n            <div class=\"ghs-card\">\n              <div class=\"ghs-card-icon\"><i data-lucide=\"accessibility\" style=\"width:48px;height:48px\"></i></div>\n              <h4>Medical Devices &amp; Equipment <span class=\"ghs-card-tag\">(Rent &amp; Sell)</span></h4>\n              <p>Hospital beds, wheelchairs &amp; more</p>\n            </div>\n          </div>\n\n          <div class=\"ghs-hero-footer\">\n            <a href=\"https://gocare.co.ke/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-ghs\">Learn More <i data-lucide=\"arrow-right\"></i></a>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n\n  <div class=\"ghs-contact-bar\">\n    <div class=\"ghs-contact-item\"><i data-lucide=\"phone\"></i> 0716 096 325</div>\n    <div class=\"ghs-contact-item\"><i data-lucide=\"phone\"></i> 0705 004 037</div>\n    <div class=\"ghs-contact-item\"><i data-lucide=\"phone\"></i> 0708 375 001</div>\n    <div class=\"ghs-contact-item\"><i data-lucide=\"mail\"></i> <a href=\"mailto:info@gocare.co.ke\">info@gocare.co.ke</a></div>\n    <div class=\"ghs-contact-item\"><i data-lucide=\"globe\"></i> <a href=\"http://www.gocare.co.ke\">www.gocare.co.ke</a></div>\n  </div>\n\n  <!-- Detailed Services Section -->\n  <section id=\"services\" style=\"padding: 100px 0; background: #F5F0E8; scroll-margin-top: 90px;\">\n    <div class=\"wrap\">\n       <div style=\"text-align:center; margin-bottom:60px\">\n         <h2 style=\"font-family:\'Outfit\', sans-serif; font-size:2.8rem; color:var(--dark); font-weight:800; margin-bottom:20px\">Comprehensive <span style=\"color:var(--p)\">Homecare</span> Solutions</h2>\n         <p style=\"font-size:1.2rem; color:var(--gray); max-width:800px; margin:0 auto; line-height:1.8\">We bring the hospital experience to your home with professional expertise and compassionate care.</p>\n       </div>\n       <div style=\"display:grid; grid-template-columns:repeat(auto-fill, minmax(320px, 1fr)); gap:30px\">\n          <div style=\"background:#fff; padding:40px; border-radius:24px; box-shadow:0 10px 30px rgba(0,0,0,0.05)\">\n            <h4 style=\"font-family:\'Outfit\', sans-serif; font-size:1.6rem; color:var(--dark); margin-bottom:20px\">Nursing Care</h4>\n            <p style=\"color:var(--gray); line-height:1.7; font-size:0.95rem\">Professional nursing services including wound dressing, medication administration, and vital signs monitoring by certified experts.</p>\n          </div>\n          <div style=\"background:#fff; padding:40px; border-radius:24px; box-shadow:0 10px 30px rgba(0,0,0,0.05)\">\n            <h4 style=\"font-family:\'Outfit\', sans-serif; font-size:1.6rem; color:var(--dark); margin-bottom:20px\">Elderly Support</h4>\n            <p style=\"color:var(--gray); line-height:1.7; font-size:0.95rem\">Dedicated companionship and assistance for the elderly, ensuring dignity, safety, and comfort in their familiar surroundings.</p>\n          </div>\n          <div style=\"background:#fff; padding:40px; border-radius:24px; box-shadow:0 10px 30px rgba(0,0,0,0.05)\">\n            <h4 style=\"font-family:\'Outfit\', sans-serif; font-size:1.6rem; color:var(--dark); margin-bottom:20px\">Medical Equipment</h4>\n            <p style=\"color:var(--gray); line-height:1.7; font-size:0.95rem\">Access to high-quality medical devices including oxygen concentrators, hospital beds, and mobility aids for both rent and sale.</p>\n          </div>\n       </div>\n    </div>\n  </section>\n</div>\n  \n  \n  <!-- BACK TO TOP -->\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\n  </button>', 'images/female-nurse-portrait-with-older-patient.jpg', 0, '[{\"body\": \"Compassionate, professional healthcare in the comfort of your home – from nursing and elderly care to post-operative support, delivered by GoCare-trained caregivers. Request Home Care\", \"heading\": \"Professional Home-Based Care\"}, {\"body\": \"Health Solutions The Homecare Experts… Experience Peace & Joy!\", \"heading\": \"GoCare\"}, {\"body\": \"Personalized medical support at home\", \"heading\": \"Home-Based Care Services\"}, {\"body\": \"Rehabilitation & mobility recovery\", \"heading\": \"Physiotherapy at Home\"}, {\"body\": \"Hospital beds, wheelchairs & more Learn More 0716 096 325 0705 004 037 0708 375 001 info@gocare.co.ke www.gocare.co.ke\", \"heading\": \"Medical Devices & Equipment (Rent & Sell)\"}, {\"body\": \"We bring the hospital experience to your home with professional expertise and compassionate care.\", \"heading\": \"Comprehensive Homecare Solutions\"}, {\"body\": \"Professional nursing services including wound dressing, medication administration, and vital signs monitoring by certified experts.\", \"heading\": \"Nursing Care\"}, {\"body\": \"Dedicated companionship and assistance for the elderly, ensuring dignity, safety, and comfort in their familiar surroundings.\", \"heading\": \"Elderly Support\"}, {\"body\": \"Access to high-quality medical devices including oxygen concentrators, hospital beds, and mobility aids for both rent and sale.\", \"heading\": \"Medical Equipment\"}]', 'home-based-care.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:47'),
(22, 'Hostels and Accommodation | GoCare Training Institute', 'hostels-and-accommodation', '<div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\n    <div class=\"ck-inner\"><div class=\"ck-left\"><div class=\"ck-icon-wrap\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/><path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/></svg></div><div class=\"ck-copy\"><strong>We use cookies</strong><p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"index.html\">Privacy Policy</a>.</p></div></div><div class=\"ck-actions\"><button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button><button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button><button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div></div>\n  </div>\n\n  \n\n  <!-- -- SUB BAR --------------------------------------- -->\n  <div class=\"subbar\">\n    <div class=\"wrap subbar-inner\">\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\n      <div class=\"subbar-portals\">\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\n      </div>\n    </div>\n  </div>\n\n\n<div class=\"hst-page\">\n    <!-- PAGE HERO -->\n  <section class=\"ph\">\n    <div class=\"ph-bg\">\n      <img loading=\"eager\" decoding=\"async\" src=\"images/new-images/IMG_2063.jpg\" alt=\"GoCare Hostel Room\">\n    </div>\n    <div class=\"ph-overlay\"></div>\n    <div class=\"ph-inner\">\n      <div class=\"ph-content\">\n        <span class=\"ph-eyebrow\"><i data-lucide=\"home\"></i> Campus Life</span>\n        \n        <h1>Hostels & <em>Accommodation</em></h1>\n        <p>Safe, comfortable, and affordable student accommodation near our Nairobi campus &mdash; so you can focus entirely on your studies.</p>\n        <div class=\"ph-btns\">\n          <a href=\"apply.html\" class=\"ph-btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\n          <a href=\"contact.html\" class=\"ph-btn-ghost\">Contact Us <i data-lucide=\"arrow-right\"></i></a>\n        </div>\n\n  </div>\n\n      </div>\n    </div>\n  </section>\n\n  <section class=\"hst-section\"><div class=\"hst-wrap\"><div class=\"hst-section-header\" style=\"text-align:center;margin-bottom:56px\"><h2 style=\"font-size:2.4rem;font-weight:800;color:var(--dark);margin-bottom:12px\">Why Students Love GoCare Hostels</h2><p style=\"font-size:1.05rem;color:#64748b;max-width:550px;margin:0 auto\">Discover why our students feel right at home in our modern and secure campus hostels.</p></div><div class=\"hst-grid\">\n    <div class=\"hst-card\"><div class=\"hst-card-head\"><div class=\"hst-card-icon\"><i data-lucide=\"shield-check\" style=\"width:24px;height:24px\"></i></div><h3>Safe &amp; Secure Environment</h3></div><div class=\"hst-card-body\"><p>Your safety is our priority. Our hostels offer:</p><ul><li>24/7 security</li><li>Well-lit surroundings</li><li>Controlled access</li><li>A peaceful, student-friendly atmosphere</li></ul><p>Parents trust GoCare because we provide a secure and protected living environment.</p></div></div>\n    <div class=\"hst-card\"><div class=\"hst-card-head\"><div class=\"hst-card-icon\"><i data-lucide=\"bed\" style=\"width:24px;height:24px\"></i></div><h3>Modern, Clean &amp; Comfortable Rooms</h3></div><div class=\"hst-card-body\"><p>Our hostels are designed to support a healthy and productive student lifestyle, with:</p><ul><li>Clean, well-maintained rooms</li><li>Comfortable beds</li><li>Adequate ventilation</li><li>Quiet study spaces</li><li>Reliable water supply</li></ul><p>Students enjoy a comfortable home-away-from-home experience.</p></div></div>\n    <div class=\"hst-card\"><div class=\"hst-card-head\"><div class=\"hst-card-icon\"><i data-lucide=\"map-pin\" style=\"width:24px;height:24px\"></i></div><h3>Convenient Location Near Campus</h3></div><div class=\"hst-card-body\"><p>GoCare Training Institute hostels are located close to our campuses, making it easy for students to:</p><ul><li>Attend classes on time</li><li>Access labs and study areas</li><li>Participate in group work</li><li>Save on transport costs</li></ul><p>This convenience enhances academic performance and student wellbeing.</p></div></div>\n    <div class=\"hst-card\"><div class=\"hst-card-head\"><div class=\"hst-card-icon\"><i data-lucide=\"users\" style=\"width:24px;height:24px\"></i></div><h3>Supportive Student Community</h3></div><div class=\"hst-card-body\"><p>Living in GoCare hostels allows students to:</p><ul><li>Build friendships</li><li>Study together</li><li>Share experiences</li><li>Support each other</li><li>Grow socially and academically</li></ul><p>Our hostels foster a positive, respectful, and inclusive community.</p></div></div>\n    <div class=\"hst-card\"><div class=\"hst-card-head\"><div class=\"hst-card-icon\"><i data-lucide=\"wallet\" style=\"width:24px;height:24px\"></i></div><h3>Affordable &amp; Flexible Options</h3></div><div class=\"hst-card-body\"><p>GoCare Training Institute offers accommodation at affordable rates, ensuring students from all backgrounds can access safe and comfortable housing.</p><p>Benefits include:</p><ul><li>Reasonable pricing</li><li>Flexible payment options</li><li>Value for money</li></ul><p class=\"hst-highlight\">We believe quality accommodation should be accessible to all learners.</p></div></div>\n  </div></div></section>\n  <section class=\"hst-ideal\"><div class=\"hst-wrap\"><div class=\"hst-ideal-grid\"><div><h2>Who Our Hostels Are Ideal For</h2><ul class=\"hst-ideal-list\"><li>Students from outside Nairobi.</li><li>Learners who prefer a structured, safe environment.</li><li>Students who want to minimize transport costs.</li><li>Young learners who need close supervision.</li><li>Anyone seeking a peaceful, study-friendly space.</li></ul><p style=\"margin-top:20px;font-size:1.05rem;color:#475569;line-height:1.7\">Whether you are a first-time student or continuing your studies, GoCare hostels provide the perfect environment for academic success.</p></div><div style=\"display:flex;justify-content:center;align-items:center\"><img loading=\"lazy\" decoding=\"async\" src=\"images/new-images/IMG_2073.jpg\" alt=\"GoCare Student Hostel Room\" style=\"max-width:100%;border-radius:16px;box-shadow:0 20px 40px rgba(0,0,0,0.1)\"></div></div></div></section>\n  <section class=\"hst-cta\"><h2>A Home That Supports Your Success</h2><p>At GoCare Training Institute, accommodation is more than a place to sleep &mdash; it is a support system that helps learners stay focused, motivated, and safe.</p><p class=\"hst-cta-tagline\">Your comfort matters. Your safety matters. Your success matters.</p><a href=\"apply.html\" class=\"hst-cta-btn\">Book a Hostel <i data-lucide=\"arrow-right\" style=\"width:18px;height:18px\"></i></a></section>\n</div>\n  \n  \n\n  <!-- BACK TO TOP -->\n  <button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Back to top\">\n    <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 15l-6-6-6 6\"/></svg>\n  </button>', 'images/new-images/IMG_2063.jpg', 0, '[{\"body\": \"Safe, comfortable, and affordable student accommodation near our Nairobi campus — so you can focus entirely on your studies. Apply Now Contact Us\", \"heading\": \"Hostels & Accommodation\"}, {\"body\": \"Discover why our students feel right at home in our modern and secure campus hostels.\", \"heading\": \"Why Students Love GoCare Hostels\"}, {\"body\": \"Your safety is our priority. Our hostels offer:24/7 securityWell-lit surroundingsControlled accessA peaceful, student-friendly atmosphereParents trust GoCare because we provide a secure and protected living environment.\", \"heading\": \"Safe & Secure Environment\"}, {\"body\": \"Our hostels are designed to support a healthy and productive student lifestyle, with:Clean, well-maintained roomsComfortable bedsAdequate ventilationQuiet study spacesReliable water supplyStudents enjoy a comfortable home-away-from-home experience.\", \"heading\": \"Modern, Clean & Comfortable Rooms\"}, {\"body\": \"GoCare Training Institute hostels are located close to our campuses, making it easy for students to:Attend classes on timeAccess labs and study areasParticipate in group workSave on transport costsThis convenience enhances academic performance and student wellbeing.\", \"heading\": \"Convenient Location Near Campus\"}, {\"body\": \"Living in GoCare hostels allows students to:Build friendshipsStudy togetherShare experiencesSupport each otherGrow socially and academicallyOur hostels foster a positive, respectful, and inclusive community.\", \"heading\": \"Supportive Student Community\"}, {\"body\": \"GoCare Training Institute offers accommodation at affordable rates, ensuring students from all backgrounds can access safe and comfortable housing.Benefits include:Reasonable pricingFlexible payment optionsValue for moneyWe believe quality accommodation should be accessible to all learners.\", \"heading\": \"Affordable & Flexible Options\"}, {\"body\": \"Students from outside Nairobi.Learners who prefer a structured, safe environment.Students who want to minimize transport costs.Young learners who need close supervision.Anyone seeking a peaceful, study-friendly space.Whether you are a first-time student or continuing your studies, GoCare hostels provide the perfect environment for academic success.\", \"heading\": \"Who Our Hostels Are Ideal For\"}, {\"body\": \"At GoCare Training Institute, accommodation is more than a place to sleep — it is a support system that helps learners stay focused, motivated, and safe.Your comfort matters. Your safety matters. Your success matters.Book a Hostel\", \"heading\": \"A Home That Supports Your Success\"}]', 'hostels-and-accommodation.html', 1, '2026-08-03 10:29:26', '2026-08-03 10:34:47');
INSERT INTO `site_pages` (`id`, `title`, `slug`, `content`, `image`, `use_builder`, `sections`, `source_path`, `is_published`, `created_at`, `updated_at`) VALUES
(23, 'GoCare Training Institute ? Kenya\'s Leading Healthcare College', 'index', '<!-- COOKIE CONSENT -->\r\n  <div id=\"cookie-banner\" role=\"dialog\" aria-label=\"Cookie consent\" aria-live=\"polite\">\r\n    <div class=\"ck-inner\">\r\n      <div class=\"ck-left\">\r\n        <div class=\"ck-icon-wrap\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n            <path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/>\r\n            <path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/>\r\n          </svg>\r\n        </div>\r\n        <div class=\"ck-copy\">\r\n          <strong>We use cookies</strong>\r\n          <p>We use cookies to improve your experience, analyse site traffic, and personalise content. By continuing, you agree to our <a href=\"#\">Privacy Policy</a>.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"ck-actions\">\r\n        <button class=\"ck-btn-decline\" id=\"ckDecline\">Decline</button>\r\n        <button class=\"ck-btn-accept\" id=\"ckAccept\">Accept All</button>\r\n        <button class=\"ck-close\" id=\"ckClose\" aria-label=\"Close\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n<!-- -- NAVBAR ---------------------------------------- -->\r\n  \r\n\r\n  <!-- -- SUB BAR --------------------------------------- -->\r\n  <div class=\"subbar\">\r\n    <div class=\"wrap subbar-inner\">\r\n      <span class=\"subbar-tagline\">Train With The Experts... Become an Expert!</span>\r\n      <div class=\"subbar-portals\">\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--student\">Student Portal</a>\r\n        <a href=\"#\" class=\"subbar-btn subbar-btn--staff\">Staff Portal</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  \r\n\r\n  <!-- -- HERO SLIDER ----------------------------------- -->\r\n  <section class=\"hero\" id=\"home\">\r\n    <div class=\"slider-wrap\" id=\"sliderWrap\">\r\n      <div class=\"slide s1 active\">\r\n        <img loading=\"eager\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/IMG_2910.JPG\" alt=\"Discover Your Path to Professional Excellence\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Discover Your Path to<br><em>Professional Excellence</em><br>and Career Fulfilment!</h1>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"apply.html\" class=\"btn btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"docs/GoCare%20Training%20Institute%20Prospectus.pdf\" class=\"btn btn-ghost\" target=\"_blank\">Download Prospectus</a>\r\n              <a href=\"courses.html\" class=\"btn btn-white\">Explore Courses</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s2\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/slider/EMPOWERING PROFESSIONS THROUGH EXPERT-LED TRAINING.jpeg\" alt=\"Empowering Professions Through Expert-Led Training\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Empowering Professions<br><em>Through Expert-Led Training</em></h1>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"apply.html\" class=\"btn btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"courses.html\" class=\"btn btn-ghost\">Explore Courses</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s3\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/slider/GUARANTEED INDUSTRIAL ATTACHMENT FOR EVERY GOCARE STUDENT.JPG.jpeg\" alt=\"Guaranteed Industrial Attachment for Every GoCare Student\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Guaranteed Industrial Attachment<br><em>for Every GoCare Student</em></h1>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"industrial-attachment.html\" class=\"btn btn-primary\">Learn More <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"apply.html\" class=\"btn btn-ghost\">Apply Now</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s4\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/slider/INSPIRING TOMORROW\'S EXPERTS THROUGH INNOVATION.JPG.jpeg\" alt=\"Inspiring Tomorrow\'s Experts Through Innovation\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Inspiring Tomorrow\'s Experts<br><em>Through Innovation</em></h1>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"apply.html\" class=\"btn btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"courses.html\" class=\"btn btn-white\">Explore Courses</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s5\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/slider/TRAIN WITH THE EXPERTS... BECOME AN EXPERT!...jpg.jpeg\" alt=\"Train With The Experts Become An Expert\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Train With The Experts&ndash;<br><em>Become an Expert!</em></h1>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"apply.html\" class=\"btn btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"docs/GoCare%20Training%20Institute%20Prospectus.pdf\" class=\"btn btn-ghost\" target=\"_blank\">Download Prospectus</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s6\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/slider/YOUR GATE WAY TO INTERNATIONAL CERTIFICATIONS.jpg.jpeg\" alt=\"Your Gateway to International Certifications\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Your Gateway to<br><em>International Certifications</em></h1>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"courses.html\" class=\"btn btn-primary\">View Accredited Courses <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"apply.html\" class=\"btn btn-ghost\">Start Your Journey</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s7\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/Admissions-hero.jpeg\" alt=\"Intakes and Deadlines\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Intakes & <em>Deadlines</em></h1>\r\n            <p style=\"color: rgba(255,255,255,0.85); font-size: 1.1rem; line-height: 1.6; max-width: 600px; margin-bottom: 20px;\">Stay informed about current and upcoming intakes &mdash; plan your enrollment early.</p>\r\n            <div class=\"slide-highlight\">Registration &amp; Admission for the Upcoming Intake is Ongoing &mdash; Apply Now!</div>\r\n            <ul class=\"slide-points\">\r\n              <li><i data-lucide=\"check-circle-2\"></i> Multiple intakes throughout the year for different schedules.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Admissions open on a rolling basis for select programs.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Apply early to secure your place in the next intake.</li>\r\n            </ul>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"apply.html\" class=\"btn btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"courses.html\" class=\"btn btn-white\">View Programs</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"slide s8\">\r\n        <img loading=\"lazy\" decoding=\"async\" class=\"slide-img\" src=\"images/new-images/slider/slider-img-new.jpeg\" alt=\"Entry Requirements\">\r\n        <div class=\"slide-overlay\"></div>\r\n        <div class=\"slide-body\">\r\n          <div class=\"slide-text\">\r\n            <h1>Entry <em>Requirements</em></h1>\r\n            <p style=\"color: rgba(255,255,255,0.85); font-size: 1.1rem; line-height: 1.6; max-width: 600px; margin-bottom: 20px;\">At GoCare Training Institute, every learner has a pathway to success.</p>\r\n            <ul class=\"slide-points\">\r\n              <li><i data-lucide=\"check-circle-2\"></i> Any KCSE mean grade qualifies for a course.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Different courses have different entry requirements.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> KCPE certificate holders also qualify.</li>\r\n              <li><i data-lucide=\"check-circle-2\"></i> Visit individual course pages for specific requirements.</li>\r\n            </ul>\r\n            <div class=\"slide-actions\">\r\n              <a href=\"apply.html\" class=\"btn btn-primary\">Apply Now <i data-lucide=\"arrow-right\"></i></a>\r\n              <a href=\"courses.html\" class=\"btn btn-white\">Explore Courses</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"hero-ctrl\">\r\n      <button class=\"arrow\" id=\"prevSlide\"><i class=\"fas fa-chevron-left\"></i></button>\r\n      <button class=\"arrow\" id=\"nextSlide\"><i class=\"fas fa-chevron-right\"></i></button>\r\n    </div>\r\n    <div class=\"hero-dots\">\r\n      <div class=\"dot active\" data-i=\"0\"></div>\r\n      <div class=\"dot\" data-i=\"1\"></div>\r\n      <div class=\"dot\" data-i=\"2\"></div>\r\n      <div class=\"dot\" data-i=\"3\"></div>\r\n      <div class=\"dot\" data-i=\"4\"></div>\r\n      <div class=\"dot\" data-i=\"5\"></div>\r\n      <div class=\"dot\" data-i=\"6\"></div>\r\n      <div class=\"dot\" data-i=\"7\"></div>\r\n    </div>\r\n    <div class=\"hero-counter\">\r\n      <span class=\"cur\" id=\"slideCur\">01</span>\r\n      <span>/</span>\r\n      <span id=\"slideTotal\">08</span>\r\n    </div>\r\n    <div class=\"hero-progress\"><div class=\"hero-progress-bar\" id=\"heroProgBar\"></div></div>\r\n    <div class=\"hero-trust\">\r\n      <div class=\"trust-icon\"><i data-lucide=\"shield-check\"></i></div>\r\n      <div class=\"trust-text\">\r\n        <strong>Govt. Accredited</strong>\r\n        <span>TVETA | TVET CDACC | NITA | KHPOA</span>\r\n      </div>\r\n    </div>\r\n  </section>\r\n          \r\n  <!-- -- WHY GOCARE PILLARS (Screenshot match) ------------- -->\r\n  <section class=\"pillars-sec\">\r\n    <div class=\"wrap\">\r\n      <div class=\"pillars-header\">\r\n        <div class=\"pillar-line\"></div>\r\n        <h2 class=\"pillars-title\">Why Choose GoCare?</h2>\r\n        <div class=\"pillar-line\"></div>\r\n      </div>\r\n      <div class=\"pillars-grid\">\r\n        <!-- Expert Trainers -->\r\n        <div class=\"pillar-card\">\r\n          <div class=\"pillar-icon-wrapper\">\r\n            <svg class=\"pillar-svg-icon\" viewBox=\"0 0 100 100\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n              <defs>\r\n                <linearGradient id=\"purpleGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n                  <stop offset=\"0%\" stop-color=\"#8e44ad\" />\r\n                  <stop offset=\"100%\" stop-color=\"#642a7e\" />\r\n                </linearGradient>\r\n                <linearGradient id=\"orangeGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n                  <stop offset=\"0%\" stop-color=\"#ff9f43\" />\r\n                  <stop offset=\"100%\" stop-color=\"#ec7424\" />\r\n                </linearGradient>\r\n              </defs>\r\n              <circle cx=\"50\" cy=\"50\" r=\"38\" fill=\"url(#orangeGrad1)\" opacity=\"0.15\" />\r\n              <path d=\"M50 22L18 36L50 50L82 36L50 22Z\" fill=\"url(#purpleGrad1)\" />\r\n              <path d=\"M30 42.5V56C30 63 38.95 68.7 50 68.7C61.05 68.7 70 63 70 56V42.5L50 51.5L30 42.5Z\" fill=\"url(#orangeGrad1)\" />\r\n              <path d=\"M78 38V58H80V38H78Z\" fill=\"url(#purpleGrad1)\" />\r\n              <circle cx=\"79\" cy=\"59\" r=\"3\" fill=\"url(#orangeGrad1)\" />\r\n            </svg>\r\n          </div>\r\n          <h3 class=\"pillar-card-title\">Expert Trainers</h3>\r\n          <div class=\"pillar-card-divider\"></div>\r\n          <p class=\"pillar-card-text\">Learn from highly qualified, experienced industry professionals who provide hands-on practical sessions and clinical mentorship to ensure you master every skill.</p>\r\n        </div>\r\n\r\n        <!-- Accredited Programs -->\r\n        <div class=\"pillar-card\">\r\n          <div class=\"pillar-icon-wrapper\">\r\n            <svg class=\"pillar-svg-icon\" viewBox=\"0 0 100 100\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n              <defs>\r\n                <linearGradient id=\"purpleGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n                  <stop offset=\"0%\" stop-color=\"#8e44ad\" />\r\n                  <stop offset=\"100%\" stop-color=\"#642a7e\" />\r\n                </linearGradient>\r\n                <linearGradient id=\"orangeGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n                  <stop offset=\"0%\" stop-color=\"#ff9f43\" />\r\n                  <stop offset=\"100%\" stop-color=\"#ec7424\" />\r\n                </linearGradient>\r\n              </defs>\r\n              <circle cx=\"50\" cy=\"50\" r=\"38\" fill=\"url(#purpleGrad2)\" opacity=\"0.1\" />\r\n              <rect x=\"28\" y=\"20\" width=\"44\" height=\"60\" rx=\"4\" fill=\"url(#orangeGrad2)\" />\r\n              <line x1=\"36\" y1=\"32\" x2=\"64\" y2=\"32\" stroke=\"white\" stroke-width=\"3\" stroke-linecap=\"round\" />\r\n              <line x1=\"36\" y1=\"42\" x2=\"64\" y2=\"42\" stroke=\"white\" stroke-width=\"3\" stroke-linecap=\"round\" />\r\n              <line x1=\"36\" y1=\"52\" x2=\"52\" y2=\"52\" stroke=\"white\" stroke-width=\"3\" stroke-linecap=\"round\" />\r\n              <circle cx=\"62\" cy=\"62\" r=\"14\" fill=\"#F5F0E8\" stroke=\"url(#purpleGrad2)\" stroke-width=\"4\" />\r\n              <line x1=\"72\" y1=\"72\" x2=\"82\" y2=\"82\" stroke=\"url(#purpleGrad2)\" stroke-width=\"5\" stroke-linecap=\"round\" />\r\n            </svg>\r\n          </div>\r\n          <h3 class=\"pillar-card-title\">Accredited Programs</h3>\r\n          <div class=\"pillar-card-divider\"></div>\r\n          <p class=\"pillar-card-text\">Study with total confidence. Our courses are fully registered, licensed, and accredited by TVETA, TVET CDACC, NITA, KHPOA, and KNEC, ensuring national and global validity.</p>\r\n        </div>\r\n\r\n        <!-- Career Readiness -->\r\n        <div class=\"pillar-card\">\r\n          <div class=\"pillar-icon-wrapper\">\r\n            <svg class=\"pillar-svg-icon\" viewBox=\"0 0 100 100\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n              <defs>\r\n                <linearGradient id=\"purpleGrad3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n                  <stop offset=\"0%\" stop-color=\"#8e44ad\" />\r\n                  <stop offset=\"100%\" stop-color=\"#642a7e\" />\r\n                </linearGradient>\r\n                <linearGradient id=\"orangeGrad3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n                  <stop offset=\"0%\" stop-color=\"#ff9f43\" />\r\n                  <stop offset=\"100%\" stop-color=\"#ec7424\" />\r\n                </linearGradient>\r\n              </defs>\r\n              <circle cx=\"50\" cy=\"50\" r=\"38\" fill=\"url(#orangeGrad3)\" opacity=\"0.15\" />\r\n              <rect x=\"20\" y=\"36\" width=\"60\" height=\"40\" rx=\"6\" fill=\"url(#purpleGrad3)\" />\r\n              <path d=\"M38 36V28C38 25.8 39.8 24 42 24H58C60.2 24 62 25.8 62 28V36\" stroke=\"url(#purpleGrad3)\" stroke-width=\"4\" fill=\"none\" />\r\n              <rect x=\"46\" y=\"50\" width=\"8\" height=\"12\" rx=\"2\" fill=\"url(#orangeGrad3)\" />\r\n              <path d=\"M22 46V40C22 37.8 23.8 36 26 36H30\" stroke=\"url(#orangeGrad3)\" stroke-width=\"2\" fill=\"none\" />\r\n              <path d=\"M78 46V40C78 37.8 76.2 36 74 36H70\" stroke=\"url(#orangeGrad3)\" stroke-width=\"2\" fill=\"none\" />\r\n            </svg>\r\n          </div>\r\n          <h3 class=\"pillar-card-title\">Career Readiness</h3>\r\n          <div class=\"pillar-card-divider\"></div>\r\n          <p class=\"pillar-card-text\">Launch your global career from day one with guaranteed hospital and field attachments, AMCA USA & SDC Canada exam centers, and high employer demand worldwide.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- -- FIND YOUR COURSE ---------------------------------- -->\r\n  <section class=\"fyc-sec\">\r\n    <div class=\"wrap\">\r\n\r\n      <!-- Finder header -->\r\n      <div class=\"fyc-header reveal\">\r\n        <div class=\"fyc-line\"></div>\r\n        <h2 class=\"fyc-title\">Find Your <span class=\"fyc-accent\">Course</span></h2>\r\n        <div class=\"fyc-line\"></div>\r\n      </div>\r\n\r\n      <!-- Filter / search bar -->\r\n      <form class=\"fyc-finder reveal\" id=\"fycFinder\" action=\"courses.html\" method=\"get\">\r\n        <div class=\"fyc-field\">\r\n          <label for=\"fycSchool\">School</label>\r\n          <div class=\"fyc-select-wrap\">\r\n            <select id=\"fycSchool\" name=\"school\">\r\n              <option value=\"\">Any School</option>\r\n              <option value=\"schools/medical-health-sciences.html\">Medical &amp; Health Sciences</option>\r\n              <option value=\"schools/hospitality-management.html\">Hospitality Management</option>\r\n              <option value=\"schools/social-sciences-business.html\">Social Sciences &amp; Business</option>\r\n              <option value=\"schools/international-certifications.html\">International Certifications</option>\r\n            </select>\r\n            <i data-lucide=\"chevron-down\"></i>\r\n          </div>\r\n        </div>\r\n        <div class=\"fyc-field\">\r\n          <label for=\"fycLevel\">Program Level</label>\r\n          <div class=\"fyc-select-wrap\">\r\n            <select id=\"fycLevel\" name=\"level\">\r\n              <option value=\"\">Any Level</option>\r\n              <option value=\"certificate\">Certificate</option>\r\n              <option value=\"diploma\">Diploma</option>\r\n              <option value=\"certification\">International Certification</option>\r\n            </select>\r\n            <i data-lucide=\"chevron-down\"></i>\r\n          </div>\r\n        </div>\r\n        <div class=\"fyc-field\">\r\n          <label for=\"fycDuration\">Duration</label>\r\n          <div class=\"fyc-select-wrap\">\r\n            <select id=\"fycDuration\" name=\"duration\">\r\n              <option value=\"\">Any Duration</option>\r\n              <option value=\"6-months\">6 Months</option>\r\n              <option value=\"1-year\">1 Year</option>\r\n              <option value=\"2-years\">2 Years</option>\r\n            </select>\r\n            <i data-lucide=\"chevron-down\"></i>\r\n          </div>\r\n        </div>\r\n        <button type=\"submit\" class=\"fyc-search-btn\">\r\n          <i data-lucide=\"search\"></i> Search\r\n        </button>\r\n      </form>\r\n\r\n    </div>\r\n  </section>\r\n\r\n  <!-- -- FEATURED SCHOOLS & COURSES ------------------- -->\r\n  <section class=\"schools-sec\" id=\"schools\">\r\n    <div class=\"wrap\">\r\n\r\n      <!-- Header -->\r\n      <div class=\"schools-sec-header reveal\">\r\n        <div class=\"schools-sec-eyebrow\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 10v6M2 10l10-5 10 5-10 5z\"/><path d=\"M6 12v5c3 3 9 3 12 0v-5\"/></svg>\r\n          4 Schools &ndash; 25+ Programmes\r\n        </div>\r\n        <h2 class=\"schools-sec-title\">Explore Our <span class=\"hl-purple\">Schools</span> &amp; <span class=\"hl-orange\">Programmes</span></h2>\r\n        <p class=\"schools-sec-sub\">Four specialist schools, one world-class institution. Find the programme that launches your healthcare or professional career.</p>\r\n      </div>\r\n\r\n      <!-- School Tab Cards -->\r\n      <div class=\"school-tabs reveal\">\r\n        <div class=\"school-tab-card active\" id=\"stab-med\" onclick=\"switchSchool(\'med\')\">\r\n          <div class=\"school-tab-card-bg\" style=\"background-image: url(\'images/Nursing-Assistant.jpg\');\"></div>\r\n          <div class=\"school-tab-card-body\">\r\n            <div class=\"school-tab-icon\">\r\n              <svg viewBox=\"0 0 24 24\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\r\n            </div>\r\n            <div class=\"school-tab-name\">Medical &amp; Health Sciences</div>\r\n            <div class=\"school-tab-count\">14 Programmes</div>\r\n            <div class=\"school-tab-indicator\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"school-tab-card\" id=\"stab-hosp\" onclick=\"switchSchool(\'hosp\')\">\r\n          <div class=\"school-tab-card-bg\" style=\"background-image: url(\'images/Front-office.jpg\');\"></div>\r\n          <div class=\"school-tab-card-body\">\r\n            <div class=\"school-tab-icon\">\r\n              <svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg>\r\n            </div>\r\n            <div class=\"school-tab-name\">Hospitality Management</div>\r\n            <div class=\"school-tab-count\">5 Programmes</div>\r\n            <div class=\"school-tab-indicator\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"school-tab-card\" id=\"stab-social\" onclick=\"switchSchool(\'social\')\">\r\n          <div class=\"school-tab-card-bg\" style=\"background-image: url(\'images/new-images/SOCIAL-WORK-&-COMMUNITY-DEVELOPMENT.jpeg\');\"></div>\r\n          <div class=\"school-tab-card-body\">\r\n            <div class=\"school-tab-icon\">\r\n              <svg viewBox=\"0 0 24 24\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\r\n            </div>\r\n            <div class=\"school-tab-name\">Social Sciences &amp; Business</div>\r\n            <div class=\"school-tab-count\">3 Programmes</div>\r\n            <div class=\"school-tab-indicator\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"school-tab-card\" id=\"stab-intl\" onclick=\"switchSchool(\'intl\')\">\r\n          <div class=\"school-tab-card-bg\" style=\"background-image: url(\'images/slider-four.jpg\');\"></div>\r\n          <div class=\"school-tab-card-body\">\r\n            <div class=\"school-tab-icon\">\r\n              <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\r\n            </div>\r\n            <div class=\"school-tab-name\">International Certifications</div>\r\n            <div class=\"school-tab-count\">3 Programmes</div>\r\n            <div class=\"school-tab-indicator\"></div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- -- PANEL: Medical & Health Sciences -- -->\r\n      <div class=\"school-courses-panel active\" id=\"spanel-med\">\r\n        <div class=\"school-panel-header\">\r\n          <div class=\"school-panel-info\">\r\n            <h3><i data-lucide=\"stethoscope\"></i> School of Medical &amp; Health Sciences</h3>\r\n            <p>From caregiving to theatre technology &middot; our flagship school with 14 nationally accredited programmes.</p>\r\n          </div>\r\n          <a href=\"schools/medical-health-sciences.html\" class=\"school-panel-cta\">\r\n            View All 14 Programmes\r\n            <svg viewBox=\"0 0 24 24\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg>\r\n          </a>\r\n        </div>\r\n        <div class=\"school-featured-grid\">\r\n          <div class=\"school-course-card\">\r\n            <div class=\"sc-card-img\">\r\n              <img loading=\"lazy\" decoding=\"async\" src=\"images/Nursing-Assistant.jpg\" alt=\"CNA Course\">\r\n              <span class=\"sc-card-badge\">Level 5</span>\r\n              <span class=\"sc-card-dur\">1&frac12; Years</span>\r\n            </div>\r\n            <div class=\"sc-card-body\">\r\n              <h4 class=\"sc-card-title\">Certificate in Healthcare Support Services &middot; CNA</h4>\r\n              <p class=\"sc-card-desc\">Become a licensed Healthcare Support Assistant / Certified Nursing Assistant delivering safe, compassionate and professional patient care.</p>\r\n              <div class=\"sc-card-footer\">\r\n                <div class=\"sc-card-accred\">\r\n                  <svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg>\r\n                  Examination Body: TVET CDACC<br>\r\n                  Practice License: KHPOA \r\n                </div>\r\n                <a href=\"courses/certificate-in-healthcare-support-services-level-5-certified-nursing-assistant.html\" class=\"sc-card-link\" aria-label=\"View course\">\r\n                  <svg viewBox=\"0 0 24 24\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg>\r\n                </a>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"school-course-card\">\r\n            <div class=\"sc-card-img\">\r\n              <img loading=\"lazy\" decoding=\"async\" src=\"images/perioperative-level-5.jpg\" alt=\"Theatre Technology\">\r\n              <span class=\"sc-card-badge\">Diploma</span>\r\n              <span class=\"sc-card-dur\">2&frac12; Years</span>\r\n            </div>\r\n            <div class=\"sc-card-body\">\r\n              <h4 class=\"sc-card-title\">Diploma in Perioperative Theatre Technology &middot; Level 6</h4>\r\n              <p class=\"sc-card-desc\">Master the high-stakes operating room environment with advanced clinical expertise required to thrive in specialised surgical teams.</p>\r\n              <div class=\"sc-card-footer\">\r\n                <div class=\"sc-card-accred\">\r\n                  <svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg>\r\n                   Examination Body: TVET CDACC<br><p></p>\r\n                   <svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg>Practice License: KHPOA\r\n                </div>\r\n                <a href=\"courses/diploma-in-perioperative-theatre-technology-level-6.html\" class=\"sc-card-link\" aria-label=\"View course\">\r\n                  <svg viewBox=\"0 0 24 24\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg>\r\n                </a>\r\n              </div>\r\n            </div>